                ? `Tenant A: ${tenantAOrders.length} orders, Tenant B: ${tenantBOrders.length} orders - No overlap`
                : "Cross-tenant data leak detected!",
        };
    });

    // Test carts isolation
    await runTest("Carts: Tenant A cannot see Tenant B carts", async () => {
