"use server";

import { requirePermission } from "../_lib/permissions";
import { db } from "@/infrastructure/db";
import { plans, subscriptions, payments } from "@/db/schema/billing";
import { eq, desc } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { logAdminAction } from "../_lib/audit";

const assignPlanSchema = z.object({
  tenantId: z.string().uuid(),
  planId: z.string().uuid(),
  billingCycle: z.enum(["monthly", "yearly"]),
});

export async function assignPlan(input: z.infer<typeof assignPlanSchema>): Promise<{ error?: string }> {
  const user = await requirePermission("manage_billing");

  const parsed = assignPlanSchema.safeParse(input);
  if (!parsed.success) return { error: "Invalid input" };

  const { tenantId, planId, billingCycle } = parsed.data;
  const now = new Date();
  const periodEnd = new Date(now);
  billingCycle === "yearly" ? periodEnd.setFullYear(periodEnd.getFullYear() + 1) : periodEnd.setMonth(periodEnd.getMonth() + 1);
  const gracePeriodEnd = new Date(periodEnd);
  gracePeriodEnd.setDate(gracePeriodEnd.getDate() + 7);

  try {
    await db.transaction(async (tx) => {
      // Deactivate existing subscriptions
      await tx.update(subscriptions)
        .set({ status: "cancelled", updatedAt: now })
        .where(eq(subscriptions.tenantId, tenantId));

      // Create new subscription
      await tx.insert(subscriptions).values({
        tenantId, planId, billingCycle,
        status: "active",
        currentPeriodStart: now,
        currentPeriodEnd: periodEnd,
        gracePeriodEnd,
      });
    });

    revalidatePath("/admin/billing");
    logAdminAction({
      actorId: user.id, actorEmail: user.email, action: "plan.assign",
      targetType: "tenant", targetId: tenantId, metadata: { planId, billingCycle },
    });
    return {};
  } catch {
    return { error: "Failed to assign plan" };
  }
}

const recordPaymentSchema = z.object({
  tenantId: z.string().uuid(),
  amount: z.string().min(1),
  method: z.enum(["esewa", "khalti", "bank_transfer", "fonepay", "cash", "other"]),
  reference: z.string().optional(),
  notes: z.string().optional(),
});

export async function recordPayment(input: z.infer<typeof recordPaymentSchema>): Promise<{ error?: string }> {
  const user = await requirePermission("manage_billing");

  const parsed = recordPaymentSchema.safeParse(input);
  if (!parsed.success) return { error: "Invalid input" };

  try {
    // Get active subscription
    const [sub] = await db.select({ id: subscriptions.id })
      .from(subscriptions).where(eq(subscriptions.tenantId, parsed.data.tenantId)).limit(1);

    await db.insert(payments).values({
      tenantId: parsed.data.tenantId,
      subscriptionId: sub?.id,
      amount: parsed.data.amount,
      method: parsed.data.method,
      reference: parsed.data.reference || null,
      notes: parsed.data.notes || null,
      recordedBy: user.id,
    });

    // If subscription is in grace/expired, reactivate
    if (sub) {
      const now = new Date();
      const periodEnd = new Date(now);
      periodEnd.setMonth(periodEnd.getMonth() + 1);
      const gracePeriodEnd = new Date(periodEnd);
      gracePeriodEnd.setDate(gracePeriodEnd.getDate() + 7);

      await db.update(subscriptions)
        .set({ status: "active", currentPeriodStart: now, currentPeriodEnd: periodEnd, gracePeriodEnd, updatedAt: now })
        .where(eq(subscriptions.id, sub.id));
    }

    revalidatePath("/admin/billing");
    logAdminAction({
      actorId: user.id, actorEmail: user.email, action: "payment.record",
      targetType: "tenant", targetId: parsed.data.tenantId,
      metadata: { amount: parsed.data.amount, method: parsed.data.method, reference: parsed.data.reference },
    });
    return {};
  } catch {
    return { error: "Failed to record payment" };
  }
}

export async function getPlans() {
  return db.select().from(plans).where(eq(plans.isActive, true)).orderBy(plans.sortOrder);
}

export async function getBillingOverview() {
  const [allSubs, allPayments, allPlans] = await Promise.all([
    db.select().from(subscriptions).orderBy(desc(subscriptions.createdAt)).limit(500),
    db.select().from(payments).orderBy(desc(payments.createdAt)).limit(50),
    db.select().from(plans).where(eq(plans.isActive, true)).orderBy(plans.sortOrder),
  ]);
  return { subscriptions: allSubs, payments: allPayments, plans: allPlans };
}

"use client";

import { useState, useTransition } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import { formatCurrency } from "@/shared/utils";
import { assignPlan, recordPayment } from "./actions";
import { generateMonthlyInvoices, markInvoicePaid, waiveInvoice } from "./invoice-actions";

type Props = {
  merchants: { id: string; name: string; slug: string }[];
  plans: { id: string; name: string; priceMonthly: string }[];
  subscriptions: { id: string; tenantId: string; planId: string; status: string; periodEnd: Date; billingCycle: string }[];
  payments: { id: string; tenantId: string; amount: string; method: string; reference: string | null; merchantName: string; createdAt: string }[];
  invoices: { id: string; tenantId: string; merchantName: string; periodStart: string; orderTotal: string; commissionRate: string; finalAmount: string; status: string }[];
};

export default function BillingClient({ merchants, plans, subscriptions, payments, invoices: invoiceList }: Props) {
  const [isPending, startTransition] = useTransition();

  // Assign plan form
  const [assignTenant, setAssignTenant] = useState("");
  const [assignPlanId, setAssignPlanId] = useState("");
  const [assignCycle, setAssignCycle] = useState<"monthly" | "yearly">("monthly");

  // Record payment form
  const [payTenant, setPayTenant] = useState("");
  const [payAmount, setPayAmount] = useState("");
  const [payMethod, setPayMethod] = useState("");
  const [payRef, setPayRef] = useState("");

  const handleAssign = () => {
    if (!assignTenant || !assignPlanId) return;
    startTransition(async () => {
      const result = await assignPlan({ tenantId: assignTenant, planId: assignPlanId, billingCycle: assignCycle });
      if (result.error) toast.error(result.error);
      else { toast.success("Plan assigned"); setAssignTenant(""); setAssignPlanId(""); }
    });
  };

  const handlePayment = () => {
    if (!payTenant || !payAmount || !payMethod) return;
    startTransition(async () => {
      const result = await recordPayment({ tenantId: payTenant, amount: payAmount, method: payMethod as any, reference: payRef || undefined });
      if (result.error) toast.error(result.error);
      else { toast.success("Payment recorded"); setPayTenant(""); setPayAmount(""); setPayRef(""); }
    });
  };

  const statusColor: Record<string, string> = {
    active: "bg-success/10 text-success",
    grace: "bg-warning/10 text-warning",
    expired: "bg-destructive/10 text-destructive",
    cancelled: "bg-muted text-muted-foreground",
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-lg font-semibold tracking-tight">Billing</h1>
        <p className="text-xs text-muted-foreground">Manage plans, payments, and invoices</p>
      </div>

      <div className="grid lg:grid-cols-2 gap-3">
        {/* Assign Plan */}
        <div className="rounded-lg border p-4 space-y-3">
          <p className="text-sm font-medium">Assign Plan</p>
          <Select value={assignTenant} onValueChange={setAssignTenant}>
            <SelectTrigger><SelectValue placeholder="Select merchant" /></SelectTrigger>
            <SelectContent>
              {merchants.map(m => <SelectItem key={m.id} value={m.id}>{m.name}</SelectItem>)}
            </SelectContent>
          </Select>
          <Select value={assignPlanId} onValueChange={setAssignPlanId}>
            <SelectTrigger><SelectValue placeholder="Select plan" /></SelectTrigger>
            <SelectContent>
              {plans.map(p => <SelectItem key={p.id} value={p.id}>{p.name} — {formatCurrency(Number(p.priceMonthly), "NPR")}/mo</SelectItem>)}
            </SelectContent>
          </Select>
          <Select value={assignCycle} onValueChange={v => setAssignCycle(v as "monthly" | "yearly")}>
            <SelectTrigger><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="yearly">Yearly</SelectItem>
            </SelectContent>
          </Select>
          <Button size="sm" onClick={handleAssign} disabled={isPending || !assignTenant || !assignPlanId}>Assign Plan</Button>
        </div>

        {/* Record Payment */}
        <div className="rounded-lg border p-4 space-y-3">
          <p className="text-sm font-medium">Record Payment</p>
          <Select value={payTenant} onValueChange={setPayTenant}>
            <SelectTrigger><SelectValue placeholder="Select merchant" /></SelectTrigger>
            <SelectContent>
              {merchants.map(m => <SelectItem key={m.id} value={m.id}>{m.name}</SelectItem>)}
            </SelectContent>
          </Select>
          <Input placeholder="Amount (NPR)" value={payAmount} onChange={e => setPayAmount(e.target.value)} type="number" />
          <Select value={payMethod} onValueChange={setPayMethod}>
            <SelectTrigger><SelectValue placeholder="Payment method" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="esewa">eSewa</SelectItem>
              <SelectItem value="khalti">Khalti</SelectItem>
              <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
              <SelectItem value="fonepay">Fonepay</SelectItem>
              <SelectItem value="cash">Cash</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>
          <Input placeholder="Reference / Transaction ID (optional)" value={payRef} onChange={e => setPayRef(e.target.value)} />
          <Button size="sm" onClick={handlePayment} disabled={isPending || !payTenant || !payAmount || !payMethod}>Record Payment</Button>
        </div>
      </div>

      {/* Payment History */}
      <div className="rounded-lg border">
        <div className="p-4 border-b">
          <p className="text-sm font-medium">Recent Payments</p>
        </div>
        {payments.length > 0 ? (
          <div className="divide-y">
            {payments.map(p => (
              <div key={p.id} className="flex items-center justify-between p-3">
                <div>
                  <p className="text-sm font-medium">{p.merchantName}</p>
                  <p className="text-xs text-muted-foreground">
                    {p.method.replace("_", " ")} {p.reference && `· ${p.reference}`} · {new Date(p.createdAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                  </p>
                </div>
                <p className="text-sm font-semibold tabular-nums">{formatCurrency(Number(p.amount), "NPR")}</p>
              </div>
            ))}
          </div>
        ) : (
          <p className="p-4 text-xs text-muted-foreground text-center">No payments recorded yet</p>
        )}
      </div>

      {/* Active Subscriptions */}
      <div className="rounded-lg border">
        <div className="p-4 border-b">
          <p className="text-sm font-medium">Subscriptions</p>
        </div>
        {subscriptions.length > 0 ? (
          <div className="divide-y">
            {subscriptions.map(s => {
              const merchant = merchants.find(m => m.id === s.tenantId);
              const plan = plans.find(p => p.id === s.planId);
              return (
                <div key={s.id} className="flex items-center justify-between p-3">
                  <div>
                    <p className="text-sm font-medium">{merchant?.name ?? "Unknown"}</p>
                    <p className="text-xs text-muted-foreground">{plan?.name} · {s.billingCycle}</p>
                  </div>
                  <Badge className={`text-[10px] ${statusColor[s.status] ?? ""}`}>{s.status}</Badge>
                </div>
              );
            })}
          </div>
        ) : (
          <p className="p-4 text-xs text-muted-foreground text-center">No subscriptions yet</p>
        )}
      </div>

      {/* Invoice Generation */}
      <div className="rounded-lg border">
        <div className="flex items-center justify-between p-4 border-b">
          <p className="text-sm font-medium">Monthly Invoices</p>
          <Button size="sm" onClick={() => {
            const now = new Date();
            startTransition(async () => {
              const result = await generateMonthlyInvoices(now.getFullYear(), now.getMonth() + 1);
              if (result.error) toast.error(result.error);
              else toast.success(`Generated ${result.generated} invoices (${result.skipped} skipped)`);
            });
          }} disabled={isPending}>
            Generate This Month
          </Button>
        </div>
        {invoiceList.length > 0 ? (
          <div className="divide-y">
            {invoiceList.map(inv => (
              <div key={inv.id} className="flex items-center justify-between p-3">
                <div>
                  <p className="text-sm font-medium">{inv.merchantName}</p>
                  <p className="text-xs text-muted-foreground">
                    {new Date(inv.periodStart).toLocaleDateString("en-US", { month: "short", year: "numeric" })} · {inv.commissionRate}% on {formatCurrency(Number(inv.orderTotal), "NPR")}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <p className="text-sm font-semibold tabular-nums">{formatCurrency(Number(inv.finalAmount), "NPR")}</p>
                  {inv.status === "pending" ? (
                    <div className="flex gap-1">
                      <Button variant="outline" size="sm" onClick={() => startTransition(async () => { await markInvoicePaid(inv.id); toast.success("Marked paid"); })} disabled={isPending}>Paid</Button>
                      <Button variant="ghost" size="sm" onClick={() => startTransition(async () => { await waiveInvoice(inv.id); toast.success("Waived"); })} disabled={isPending}>Waive</Button>
                    </div>
                  ) : (
                    <Badge className={`text-[10px] ${inv.status === "paid" ? "bg-success/10 text-success" : inv.status === "waived" ? "bg-muted text-muted-foreground" : "bg-destructive/10 text-destructive"}`}>
                      {inv.status}
                    </Badge>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-xs text-muted-foreground text-center p-4">No invoices generated yet. Click "Generate This Month" to calculate commissions.</p>
        )}
      </div>
    </div>
  );
}

"use server";

import { db } from "@/infrastructure/db";
import { tenants } from "@/db/schema/tenants";
import { orders } from "@/db/schema/orders";
import { plans, subscriptions, invoices } from "@/db/schema/billing";
import { eq, and, gte, lt, sql, isNull } from "drizzle-orm";
import { revalidatePath } from "next/cache";
import { requirePermission } from "../_lib/permissions";
import { logAdminAction } from "../_lib/audit";

/**
 * Calculate commission for a tenant for a given period.
 * Returns MIN(commission_rate × order_total, plan_cap)
 */
async function calculateCommission(tenantId: string, periodStart: Date, periodEnd: Date) {
  // Get tenant's active subscription + plan
  const [sub] = await db.select({
    planId: subscriptions.planId,
    commissionRate: plans.commissionRate,
    cap: plans.priceMonthly,
    planName: plans.name,
  })
    .from(subscriptions)
    .innerJoin(plans, eq(plans.id, subscriptions.planId))
    .where(eq(subscriptions.tenantId, tenantId))
    .orderBy(subscriptions.createdAt)
    .limit(1);

  // No subscription = free tier, no commission
  if (!sub || Number(sub.commissionRate) === 0) {
    return { planId: sub?.planId ?? null, commissionRate: 0, orderTotal: 0, orderCount: 0, commissionAmount: 0, capAmount: 0, finalAmount: 0 };
  }

  // Get paid orders in period
  const [result] = await db.select({
    total: sql<string>`COALESCE(SUM(${orders.total}), 0)`,
    count: sql<number>`COUNT(*)::int`,
  })
    .from(orders)
    .where(and(
      eq(orders.tenantId, tenantId),
      eq(orders.paymentStatus, "paid"),
      gte(orders.createdAt, periodStart),
      lt(orders.createdAt, periodEnd),
    ));

  const orderTotal = Number(result.total);
  const orderCount = result.count;
  const rate = Number(sub.commissionRate);
  const cap = Number(sub.cap);
  const commissionAmount = orderTotal * (rate / 100);
  const finalAmount = Math.min(commissionAmount, cap);

  return {
    planId: sub.planId,
    commissionRate: rate,
    orderTotal,
    orderCount,
    commissionAmount: Math.round(commissionAmount * 100) / 100,
    capAmount: cap,
    finalAmount: Math.round(finalAmount * 100) / 100,
  };
}

/**
 * Generate invoices for all merchants for a given month.
 * Skips free-tier merchants and merchants who already have an invoice for the period.
 */
export async function generateMonthlyInvoices(year: number, month: number): Promise<{ generated: number; skipped: number; error?: string }> {
  const user = await requirePermission("manage_billing");

  const periodStart = new Date(year, month - 1, 1);
  const periodEnd = new Date(year, month, 1);

  // Get all active tenants (not deleted)
  const allTenants = await db.select({ id: tenants.id, name: tenants.name })
    .from(tenants)
    .where(isNull(tenants.deletedAt));

  let generated = 0;
  let skipped = 0;

  for (const tenant of allTenants) {
    // Check if invoice already exists for this period
    const [existing] = await db.select({ id: invoices.id })
      .from(invoices)
      .where(and(
        eq(invoices.tenantId, tenant.id),
        eq(invoices.periodStart, periodStart),
      ))
      .limit(1);

    if (existing) { skipped++; continue; }

    const calc = await calculateCommission(tenant.id, periodStart, periodEnd);

    // Skip free tier (no commission)
    if (calc.finalAmount === 0) { skipped++; continue; }

    await db.insert(invoices).values({
      tenantId: tenant.id,
      planId: calc.planId,
      periodStart,
      periodEnd,
      orderTotal: calc.orderTotal.toString(),
      orderCount: calc.orderCount,
      commissionRate: calc.commissionRate.toString(),
      commissionAmount: calc.commissionAmount.toString(),
      capAmount: calc.capAmount.toString(),
      finalAmount: calc.finalAmount.toString(),
      status: "pending",
    });
    generated++;
  }

  logAdminAction({
    actorId: user.id, actorEmail: user.email, action: "payment.record",
    targetType: "invoices",
    metadata: { year, month, generated, skipped },
  });

  revalidatePath("/admin/billing");
  return { generated, skipped };
}

/**
 * Mark an invoice as paid (link to a payment record).
 */
export async function markInvoicePaid(invoiceId: string, paymentId?: string): Promise<{ error?: string }> {
  const user = await requirePermission("manage_billing");

  await db.update(invoices)
    .set({ status: "paid", paidAt: new Date(), paymentId: paymentId ?? null })
    .where(eq(invoices.id, invoiceId));

  revalidatePath("/admin/billing");
  return {};
}

/**
 * Waive an invoice (e.g., for alpha users, promotions).
 */
export async function waiveInvoice(invoiceId: string): Promise<{ error?: string }> {
  const user = await requirePermission("manage_billing");

  await db.update(invoices)
    .set({ status: "waived" })
    .where(eq(invoices.id, invoiceId));

  revalidatePath("/admin/billing");
  return {};
}

