                  </p>
                </div>
                <div className="text-right">
                  <p className="text-sm font-medium tabular-nums">{formatCurrency(Number(o.total), "NPR")}</p>
                  <p className="text-[10px] text-muted-foreground capitalize">{o.status}</p>
