import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";
import { createClient } from "@/infrastructure/supabase/server";
import { createLogger } from "@/lib/logger";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";
const log = createLogger("api:contact");

const contactSchema = z.object({
  name: z.string().max(200).optional(),
  email: z.string().email(),
  message: z.string().min(1).max(5000),
  tenantId: z.string().uuid().optional(),
});

export const POST = withRateLimit("storefront", async function POST(request: Request) {
  try {
    const raw = await request.json();
    const data = contactSchema.parse(raw);

    const supabase = await createClient();

    const { error } = await supabase
      .from("contact_submissions")
      .insert({
        name: data.name || null,
        email: data.email,
        message: data.message,
        tenant_id: data.tenantId || null,
        submitted_at: new Date().toISOString(),
      });

    if (error) {
      log.error("Contact form error:", error);
      return NextResponse.json({ error: "Failed to send message" }, { status: 500 });
    }

    return NextResponse.json({ message: "Message sent successfully" });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json({ error: error.issues[0].message }, { status: 400 });
    }
    log.error("Contact API error:", error);
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
});

import { NextRequest, NextResponse } from "next/server";
import { getDomainById, removeDomain, getDnsInstructions } from "@/infrastructure/services/domain";
import { createLogger } from "@/lib/logger";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";
const log = createLogger("api:dashboard-domains-id");

interface RouteParams {
  params: Promise<{ id: string }>;
}

/**
 * GET /api/dashboard/domains/[id]
 * Get a specific domain by ID
 * 
 * Requirements: 6.1
 */
export const GET = withRateLimit<{ id: string }>("dashboard", async function GET(
  request: Request,
  { params }: RouteParams
) {
  try {
    const { id } = await params;

    if (!id) {
      return NextResponse.json(
        { error: "Domain ID is required" },
        { status: 400 }
      );
    }

    const domain = await getDomainById(id);

    if (!domain) {
      return NextResponse.json(
        { error: "Domain not found" },
        { status: 404 }
      );
    }

    // Include DNS instructions
    const instructions = getDnsInstructions(
      domain.domain,
      domain.verificationToken,
      domain.verificationMethod as "cname" | "txt"
    );

    return NextResponse.json({
      domain,
      instructions,
    });
  } catch (error) {
    log.error("Failed to fetch domain:", error);

    if (error instanceof Error && error.message === "Unauthorized") {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    return NextResponse.json(
      { error: "Failed to fetch domain" },
      { status: 500 }
    );
  }
})

/**
 * DELETE /api/dashboard/domains/[id]
 * Remove a domain (also removes from Vercel if applicable)
 * 
 * Requirements: 6.1, 8.3
 */
export const DELETE = withRateLimit<{ id: string }>("dashboard", async function DELETE(
  request: Request,
  { params }: RouteParams
) {
  try {
    const { id } = await params;

    if (!id) {
      return NextResponse.json(
        { error: "Domain ID is required" },
        { status: 400 }
      );
    }

    await removeDomain(id);

    return NextResponse.json({ 
      success: true,
      message: "Domain removed successfully"
    });
  } catch (error) {
    log.error("Failed to remove domain:", error);

    if (error instanceof Error) {
      if (error.message === "Unauthorized") {
        return NextResponse.json(
          { error: "Unauthorized" },
          { status: 401 }
        );
      }

      if (error.message === "Domain not found") {
        return NextResponse.json(
          { error: error.message },
          { status: 404 }
        );
      }
    }

    return NextResponse.json(
      { error: "Failed to remove domain" },
      { status: 500 }
    );
  }
})

import { NextRequest, NextResponse } from "next/server";
import { verifyDomain, refreshDomainStatus, getDomainById } from "@/infrastructure/services/domain";
import { createLogger } from "@/lib/logger";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";
const log = createLogger("api:dashboard-domains-id-verify");

interface RouteParams {
  params: Promise<{ id: string }>;
}

/**
 * POST /api/dashboard/domains/[id]/verify
 * Trigger DNS verification for a domain
 * If domain is already verified, refreshes status from Vercel
 * 
 * Requirements: 6.3, 6.6, 8.1, 8.2, 8.5
 */
export const POST = withRateLimit<{ id: string }>("dashboard", async function POST(
  request: Request,
  { params }: RouteParams
) {
  try {
    const { id } = await params;

    if (!id) {
      return NextResponse.json(
        { error: "Domain ID is required" },
        { status: 400 }
      );
    }

    // First check if domain exists and belongs to tenant
    const domain = await getDomainById(id);

    if (!domain) {
      return NextResponse.json(
        { error: "Domain not found" },
        { status: 404 }
      );
    }

    // If domain is already verified, refresh status from Vercel
    // This allows checking if SSL has been provisioned
    let result;
    if (domain.status === "verified" || domain.status === "active") {
      result = await refreshDomainStatus(id);
    } else {
      // Perform full verification (DNS + Vercel API)
      result = await verifyDomain(id);
    }

    if (result.success) {
      // Fetch updated domain record
      const updatedDomain = await getDomainById(id);

      return NextResponse.json({
        success: true,
        domain: updatedDomain,
        message: updatedDomain?.status === "active" 
          ? "Domain is active and SSL is ready"
          : "Domain verified successfully. SSL certificate is being provisioned.",
      });
    }

    // Return verification failure with details
    return NextResponse.json({
      success: false,
      error: result.error,
      errorCode: result.errorCode,
      dnsRecords: result.dnsRecords,
    }, { status: 400 });
  } catch (error) {
    log.error("Failed to verify domain:", error);

    if (error instanceof Error && error.message === "Unauthorized") {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    return NextResponse.json(
      { error: "Failed to verify domain" },
      { status: 500 }
    );
  }
})

