/**
 * Media Upload API Route
 * 
 * Supports both Vercel Blob and AWS S3 storage
 * Storage provider is determined by environment configuration
 * 
 * Features:
 * - Image upload to S3
 * - Auto-tagging for product images
 */

import { NextRequest, NextResponse } from 'next/server';
import { getUser } from '@/lib/auth';
import { createLogger } from "@/lib/logger";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";
const log = createLogger("api:media-upload");

const STORAGE_PROVIDER = process.env.STORAGE_PROVIDER || 'vercel'; // 'vercel' | 's3'
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
const ENABLE_MODERATION = process.env.AWS_REKOGNITION_ENABLED === 'true';

// Image types that can be moderated
const MODERATABLE_TYPES = ['image/jpeg', 'image/png', 'image/webp'];

export const POST = withRateLimit("dashboard", async function POST(request: Request) {
  try {
    // Authenticate
    const user = await getUser();
    if (!user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const tenantId = user.tenantId;
    if (!tenantId) {
      return NextResponse.json({ error: 'No tenant context' }, { status: 400 });
    }

    const formData = await request.formData();
    const file = formData.get('file') as File | null;
    const folder = formData.get('folder') as string | null;
    const skipModeration = formData.get('skipModeration') === 'true';

    if (!file) {
      return NextResponse.json({ error: 'No file provided' }, { status: 400 });
    }

    if (file.size > MAX_FILE_SIZE) {
      return NextResponse.json({ error: 'File too large (max 10MB)' }, { status: 400 });
    }

    const buffer = Buffer.from(await file.arrayBuffer());
    const isImage = MODERATABLE_TYPES.includes(file.type);

    // Moderate image before upload (if enabled and applicable)
    // TODO: Re-add image moderation with a content moderation provider

    const { uploadToS3 } = await import('@/infrastructure/aws/s3');
    const result = await uploadToS3(buffer, {
      tenantId,
      filename: file.name,
      contentType: file.type,
      folder: folder || undefined,
    });

    if (!result.success) {
      return NextResponse.json({ error: result.error || 'Upload failed' }, { status: 500 });
    }

    return NextResponse.json({
      url: result.cdnUrl || result.s3Url,
      key: result.key,
      provider: STORAGE_PROVIDER,
      moderated: ENABLE_MODERATION && isImage,
    });
  } catch (error) {
    log.error('[Upload API] Error:', error);
    return NextResponse.json(
      { error: 'Upload failed' },
      { status: 500 }
    );
  }
});

/**
 * GET: Generate presigned URL for direct client upload to S3
 */
export const GET = withRateLimit("dashboard", async function GET(request: Request) {
  try {
    const user = await getUser();
    if (!user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const tenantId = user.tenantId;
    if (!tenantId) {
      return NextResponse.json({ error: 'No tenant context' }, { status: 400 });
    }

    const { searchParams } = new URL(request.url);
    const filename = searchParams.get('filename');
    const contentType = searchParams.get('contentType');
    const folder = searchParams.get('folder');

    if (!filename || !contentType) {
      return NextResponse.json(
        { error: 'Missing filename or contentType' },
        { status: 400 }
      );
    }

    const { getPresignedUploadUrl, getCdnUrl } = await import('@/infrastructure/aws/s3');

    const result = await getPresignedUploadUrl(
      { tenantId, filename, contentType, folder: folder || undefined },
      3600
    );

    if ('error' in result) {
      return NextResponse.json({ error: result.error }, { status: 500 });
    }

    return NextResponse.json({
      uploadUrl: result.url,
      key: result.key,
      cdnUrl: getCdnUrl(result.key),
    });
  } catch (error) {
    log.error('[Upload API] Presigned URL error:', error);
    return NextResponse.json(
      { error: 'Failed to generate upload URL' },
      { status: 500 }
    );
  }
});

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@/infrastructure/supabase/server";
import { createLogger } from "@/lib/logger";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";
const log = createLogger("api:newsletter-subscribe");

export const POST = withRateLimit("storefront", async function POST(request: Request) {
    try {
        const { email, storeSlug } = await request.json();

        if (!email || !storeSlug) {
            return NextResponse.json(
                { error: "Email and store slug are required" },
                { status: 400 }
            );
        }

        // Validate email format
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
            return NextResponse.json(
                { error: "Invalid email format" },
                { status: 400 }
            );
        }

        const supabase = await createClient();

        // Get tenant by slug
        const { data: tenant, error: tenantError } = await supabase
            .from("tenants")
            .select("id")
            .eq("slug", storeSlug)
            .single();

        if (tenantError || !tenant) {
            return NextResponse.json(
                { error: "Store not found" },
                { status: 404 }
            );
        }

        // Check if already subscribed
        const { data: existing } = await supabase
            .from("newsletter_subscribers")
            .select("id")
            .eq("tenant_id", tenant.id)
            .eq("email", email.toLowerCase())
            .single();

        if (existing) {
            return NextResponse.json(
                { message: "Already subscribed" },
                { status: 200 }
            );
        }

        // Insert new subscriber
        const { error: insertError } = await supabase
            .from("newsletter_subscribers")
            .insert({
                tenant_id: tenant.id,
                email: email.toLowerCase(),
                subscribed_at: new Date().toISOString(),
            });

        if (insertError) {
            log.error("Newsletter subscription error:", insertError);
            return NextResponse.json(
                { error: "Failed to subscribe" },
                { status: 500 }
            );
        }

        return NextResponse.json(
            { message: "Successfully subscribed" },
            { status: 200 }
        );
    } catch (error) {
        log.error("Newsletter API error:", error);
        return NextResponse.json(
            { error: "Internal server error" },
            { status: 500 }
        );
    }
});

import { NextRequest, NextResponse } from "next/server";
import crypto from "crypto";
import { db } from "@/infrastructure/db";
import { orders } from "@/db/schema/orders";
import { tenants } from "@/db/schema/tenants";
import { eq, and } from "drizzle-orm";
import { verifyEsewaPayment } from "@/infrastructure/payments/esewa";
import { createLogger } from "@/lib/logger";

import { withRateLimit } from "@/infrastructure/middleware/rate-limit";

const log = createLogger("api:payment:esewa-callback");

/** Verify HMAC-SHA256 signature on eSewa callback data */
function verifySignature(decoded: Record<string, any>, secret: string): boolean {
  const { signed_field_names, signature } = decoded;
  if (!signed_field_names || !signature) return false;
  const message = signed_field_names
    .split(",")
    .map((field: string) => `${field}=${decoded[field]}`)
    .join(",");
  const expected = crypto.createHmac("sha256", secret).update(message).digest("base64");
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}

/** eSewa redirects here after payment with base64-encoded data in query param */
export const GET = withRateLimit("webhook", async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  const data = (request as NextRequest).nextUrl.searchParams.get("data");

  if (!data) {
    return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=missing_data`, request.url));
  }

  try {
    const decoded = JSON.parse(Buffer.from(data, "base64").toString("utf-8"));
    const orderId = decoded.transaction_uuid;

    if (!orderId) {
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=invalid_data`, request.url));
    }

    // 1. Tenant scoping: look up tenant from slug first
    const [tenant] = await db.select({ id: tenants.id, settings: tenants.settings })
      .from(tenants).where(eq(tenants.slug, slug)).limit(1);

    if (!tenant) {
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=invalid_store`, request.url));
    }

    // Look up order scoped to tenant
    const [order] = await db.select({ id: orders.id, tenantId: orders.tenantId, total: orders.total, paymentStatus: orders.paymentStatus })
      .from(orders).where(and(eq(orders.id, orderId), eq(orders.tenantId, tenant.id))).limit(1);

    if (!order) {
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=order_not_found`, request.url));
    }

    // 2. Idempotency: skip re-verification if already paid
    if (order.paymentStatus === "paid") {
      return NextResponse.redirect(new URL(`/store/${slug}/order-confirmation?order=${orderId}&payment=success`, request.url));
    }

    const paymentSettings = (tenant.settings as Record<string, any>)?.payments;
    const merchantCode = paymentSettings?.esewamerchantCode;
    const merchantSecret = paymentSettings?.esewaSecret;

    if (!merchantCode || !merchantSecret) {
      log.error("eSewa credentials not configured for tenant");
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=config_error`, request.url));
    }

    // 4. HMAC signature verification before trusting callback data
    if (!verifySignature(decoded, merchantSecret)) {
      log.error("eSewa HMAC signature verification failed");
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=verification_failed`, request.url));
    }

    const result = await verifyEsewaPayment({
      encodedData: data,
      merchantCode,
      merchantSecret,
      expectedAmount: Number(order.total),
      expectedTransactionUuid: orderId,
    });

    if (result.success) {
      await db.update(orders)
        .set({ paymentStatus: "paid", status: "confirmed", metadata: { paymentMethod: "esewa", esewaTransactionCode: result.transactionCode }, updatedAt: new Date() })
        .where(and(eq(orders.id, orderId), eq(orders.tenantId, tenant.id)));

      return NextResponse.redirect(new URL(`/store/${slug}/order-confirmation?order=${orderId}&payment=success`, request.url));
    }

    // 3. Sanitize error — don't leak internal details
    log.error("eSewa verification failed:", result.error);
    return NextResponse.redirect(new URL(`/store/${slug}?payment=failed&reason=verification_failed`, request.url));
  } catch (err) {
    log.error("eSewa callback error:", err);
    return NextResponse.redirect(new URL(`/store/${slug}?payment=error`, request.url));
  }
});

import { NextRequest, NextResponse } from "next/server";
import { db } from "@/infrastructure/db";
import { orders } from "@/db/schema/orders";
import { tenants } from "@/db/schema/tenants";
import { eq, and, sql } from "drizzle-orm";
import { verifyKhaltiPayment } from "@/infrastructure/payments/khalti";
import { createLogger } from "@/lib/logger";

import { withRateLimit } from "@/infrastructure/middleware/rate-limit";

const log = createLogger("api:payment:khalti-callback");

/** Khalti redirects here with pidx, transaction_id, amount, purchase_order_id in query */
export const GET = withRateLimit("webhook", async function GET(
  request: Request,
  { params }: { params: Promise<{ slug: string }> }
) {
  const { slug } = await params;
  const url = new URL(request.url);
  const pidx = url.searchParams.get("pidx");
  const purchaseOrderId = url.searchParams.get("purchase_order_id");
  const status = url.searchParams.get("status");

  if (!pidx) {
    return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=missing_params`, request.url));
  }

  // Khalti sends status=Completed on success, User canceled on cancel
  if (status === "User canceled") {
    return NextResponse.redirect(new URL(`/store/${slug}?payment=cancelled`, request.url));
  }

  try {
    // 1. Tenant scoping: look up tenant from slug first
    const [tenant] = await db.select({ id: tenants.id, settings: tenants.settings })
      .from(tenants).where(eq(tenants.slug, slug)).limit(1);

    if (!tenant) {
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=invalid_store`, request.url));
    }

    // 6. Look up order by stored khaltiPidx using JSONB query (no full table scan)
    const [order] = await db.select({ id: orders.id, tenantId: orders.tenantId, total: orders.total, paymentStatus: orders.paymentStatus, metadata: orders.metadata })
      .from(orders)
      .where(and(eq(orders.tenantId, tenant.id), sql`${orders.metadata}->>'khaltiPidx' = ${pidx}`))
      .limit(1);

    if (!order) {
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=order_not_found`, request.url));
    }

    // 7. Verify purchase_order_id matches the looked-up order
    if (purchaseOrderId && purchaseOrderId !== order.id) {
      log.error("purchase_order_id mismatch", null, { query: purchaseOrderId, orderId: order.id });
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=order_mismatch`, request.url));
    }

    // 2. Idempotency: skip re-verification if already paid
    if (order.paymentStatus === "paid") {
      return NextResponse.redirect(new URL(`/store/${slug}/order-confirmation?order=${order.id}&payment=success`, request.url));
    }

    const secretKey = (tenant.settings as Record<string, any>)?.payments?.khaltiSecretKey;
    if (!secretKey) {
      log.error("Khalti secret key not configured");
      return NextResponse.redirect(new URL(`/store/${slug}?payment=error&reason=config_error`, request.url));
    }

    const amountInPaisa = Math.round(Number(order.total) * 100);

    const result = await verifyKhaltiPayment({
      pidx,
      secretKey,
      expectedAmount: amountInPaisa,
      expectedOrderId: order.id,
    });

    if (result.success) {
      await db.update(orders)
        .set({ paymentStatus: "paid", status: "confirmed", metadata: { paymentMethod: "khalti", khaltiTransactionId: result.transactionId, khaltiPidx: pidx }, updatedAt: new Date() })
        .where(and(eq(orders.id, order.id), eq(orders.tenantId, tenant.id)));

      return NextResponse.redirect(new URL(`/store/${slug}/order-confirmation?order=${order.id}&payment=success`, request.url));
    }

    // 3. Sanitize error — don't leak internal details
    log.error("Khalti verification failed:", result.error);
    return NextResponse.redirect(new URL(`/store/${slug}?payment=failed&reason=verification_failed`, request.url));
  } catch (err) {
    log.error("Khalti callback error:", err);
    return NextResponse.redirect(new URL(`/store/${slug}?payment=error`, request.url));
  }
});

import { createClient } from "@/infrastructure/supabase/server";
import { NextResponse } from "next/server";
import { withRateLimit } from "@/infrastructure/middleware/rate-limit";

export const POST = withRateLimit("storefront", async function POST(request: Request) {
  try {
  const formData = await request.formData();
  const productId = formData.get("productId") as string;
  const customerName = formData.get("customerName") as string;
  const customerEmail = formData.get("customerEmail") as string;
  const rating = parseInt(formData.get("rating") as string, 10);
  const title = (formData.get("title") as string) || null;
  const content = formData.get("content") as string;

  if (!productId || !customerName || !customerEmail || !content || !rating) {
    return NextResponse.json({ error: "Missing fields" }, { status: 400 });
  }
  if (isNaN(rating) || rating < 1 || rating > 5) {
    return NextResponse.json({ error: "Invalid rating" }, { status: 400 });
  }

  const supabase = await createClient();

  // Derive tenantId from the product — never trust user input
  const { data: product } = await supabase
    .from("products")
    .select("tenant_id")
    .eq("id", productId)
    .single();

  if (!product) {
    return NextResponse.json({ error: "Product not found" }, { status: 404 });
  }

  const { error } = await supabase.from("reviews").insert({
    tenant_id: product.tenant_id,
    product_id: productId,
    customer_name: customerName,
    customer_email: customerEmail,
    rating,
    title,
    content,
    is_approved: false,
    is_verified: false,
  });

  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
  return NextResponse.json({ success: true });
  } catch (err) {
    return NextResponse.json({ error: "Internal server error" }, { status: 500 });
  }
})

import { type NextRequest, NextResponse } from "next/server"
import { createLogger } from "@/lib/logger"
import { withRateLimit } from "@/infrastructure/middleware/rate-limit"
import { createClient } from "@/infrastructure/supabase/server"
import { createAdminClient } from "@/infrastructure/supabase/admin"

const log = createLogger("api:upload")
const MAX_FILE_SIZE = 10 * 1024 * 1024
const ALLOWED_TYPES = ["image/jpeg", "image/png", "image/gif", "image/webp", "image/avif"]
const BUCKET = "uploads"

export const POST = withRateLimit("dashboard", async function POST(request: Request) {
  try {
    const supabase = await createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const contentType = request.headers.get("content-type")
    if (!contentType?.includes("multipart/form-data")) {
      return NextResponse.json({ error: "Expected multipart/form-data" }, { status: 400 })
    }

    const formData = await request.formData()
    const file = formData.get("file") as File
    if (!file) return NextResponse.json({ error: "No file provided" }, { status: 400 })
    if (file.size > MAX_FILE_SIZE) return NextResponse.json({ error: "File too large (max 10MB)" }, { status: 400 })
    if (!ALLOWED_TYPES.includes(file.type)) return NextResponse.json({ error: "Invalid file type" }, { status: 400 })

    const { data: userData } = await supabase.from("users").select("tenant_id").eq("id", user.id).single()
    if (!userData?.tenant_id) return NextResponse.json({ error: "No tenant" }, { status: 403 })

    // Unique filename: tenant/timestamp-sanitized
    const ext = file.name.split(".").pop()?.toLowerCase() || "png"
    const sanitized = file.name.replace(/\.[^.]+$/, "").replace(/[^a-zA-Z0-9-]/g, "_").toLowerCase()
    const path = `${userData.tenant_id}/${Date.now()}-${sanitized}.${ext}`

    const admin = createAdminClient()
    const { data, error } = await admin.storage.from(BUCKET).upload(path, file, {
      contentType: file.type,
      upsert: false,
    })

    if (error) {
      log.error("Supabase upload error:", error)
      return NextResponse.json({ error: "Upload failed" }, { status: 500 })
    }

    const { data: urlData } = admin.storage.from(BUCKET).getPublicUrl(data.path)

    return NextResponse.json({
      url: urlData.publicUrl,
      filename: sanitized,
      size: file.size,
      type: file.type,
    })
  } catch (error) {
    log.error("Upload error:", error)
    return NextResponse.json({ error: "Upload failed" }, { status: 500 })
  }
})

"use client"

import Image from "next/image"
import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { createClient } from "@/infrastructure/supabase/client"
import { Button } from "@/components/ui/button"
import { Loader2, ArrowRight, Store, LogOut, Camera } from "lucide-react"

function toSlug(name: string) {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")
}

export default function OnboardingPage() {
  const [storeName, setStoreName] = useState("")
  const [currency, setCurrency] = useState("NPR")
  const [logo, setLogo] = useState<File | null>(null)
  const [logoPreview, setLogoPreview] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [isChecking, setIsChecking] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const router = useRouter()
  const supabase = createClient()

  useEffect(() => {
    async function checkUser() {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) { router.push("/login"); return }
      const { data } = await supabase.from("users").select("tenant_id").eq("id", user.id).single()
      if (data?.tenant_id) { router.push("/dashboard"); return }
      setIsChecking(false)
    }
    checkUser()
  }, [router, supabase])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (storeName.length < 3) { setError("At least 3 characters"); return }
    setIsLoading(true)
    setError(null)

    try {
      const formData = new FormData()
      formData.append("storeName", storeName)
      formData.append("currency", currency)
      if (logo) formData.append("logo", logo)

      const res = await fetch("/api/auth/complete-onboarding", {
        method: "POST",
        body: formData,
      })
      const result = await res.json()
      if (!res.ok) { setError(result.error || "Failed to create store"); setIsLoading(false); return }
      // Hard navigation to force server component re-render with new tenant
      window.location.href = "/dashboard"
    } catch {
      setError("Something went wrong. Try again.")
      setIsLoading(false)
    }
  }

  const handleLogout = async () => {
    await supabase.auth.signOut()
    router.push("/login")
  }

  if (isChecking) {
    return (
      <div className="flex min-h-svh items-center justify-center">
        <Loader2 className="size-5 animate-spin text-muted-foreground" />
      </div>
    )
  }

  const slug = toSlug(storeName)
  const isValid = storeName.length >= 3

  return (
    <div className="flex min-h-svh items-center justify-center bg-background p-6">
      <div className="w-full max-w-[340px]">
        {/* Logo */}
        <div className="flex items-center gap-2.5 mb-12">
          <div className="flex size-8 items-center justify-center rounded-md bg-foreground">
            <Store className="size-4 text-background" />
          </div>
          <span className="text-sm font-semibold tracking-tight">Indigo</span>
        </div>

        {/* Header */}
        <div className="mb-8">
          <h1 className="text-2xl font-semibold tracking-tight">Name your store</h1>
          <p className="text-sm text-muted-foreground mt-1">
            You can always change this later.
          </p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Logo upload */}
          <div className="flex items-center gap-4">
            <label className="relative cursor-pointer group">
              <input
                type="file"
                accept="image/*"
                className="hidden"
                onChange={(e) => {
                  const file = e.target.files?.[0]
                  if (file) {
                    setLogo(file)
                    setLogoPreview(URL.createObjectURL(file))
                  }
                }}
              />
              {logoPreview ? (
                <div className="size-14 rounded-xl overflow-hidden ring-1 ring-border">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <Image src={logoPreview} alt="Store logo" fill className="object-cover" />
                </div>
              ) : (
                <div className="size-14 rounded-xl border-2 border-dashed border-muted-foreground/20 flex items-center justify-center group-hover:border-muted-foreground/40 transition-colors">
                  <Camera className="size-5 text-muted-foreground/40 group-hover:text-muted-foreground/60 transition-colors" />
                </div>
              )}
            </label>
            <div>
              <p className="text-xs font-medium">Store logo</p>
              <p className="text-xs text-muted-foreground/50">Optional · Square recommended</p>
            </div>
          </div>

          <div className="space-y-2">
            <input
              id="store-name"
              type="text"
              placeholder="Kathmandu Crafts"
              required
              value={storeName}
              onChange={(e) => { setStoreName(e.target.value); setError(null) }}
              autoFocus
              className="w-full h-11 px-3 rounded-lg border border-input bg-transparent text-base placeholder:text-muted-foreground/40 focus:outline-none focus:ring-2 focus:ring-ring/30 focus:border-ring transition-colors"
            />
            <div className="h-4">
              {error ? (
                <p className="text-xs text-destructive">{error}</p>
              ) : slug ? (
                <p className="text-xs text-muted-foreground">
                  <span className="text-foreground font-medium">{slug}</span><span className="text-muted-foreground/60">.indigo.com</span>
                </p>
              ) : null}
            </div>
          </div>

          {/* Currency */}
          <div className="space-y-1.5">
            <label className="text-xs font-medium text-muted-foreground">Currency</label>
            <div className="flex gap-1.5">
              {[
                { code: "NPR", label: "Rs." },
                { code: "USD", label: "$" },
                { code: "INR", label: "₹" },
                { code: "EUR", label: "€" },
                { code: "GBP", label: "£" },
              ].map((c) => (
                <button
                  key={c.code}
                  type="button"
                  onClick={() => setCurrency(c.code)}
                  className={`h-8 px-3 rounded-md text-xs font-medium transition-colors ${
