// ============================================================================
// Date Range Helpers
// ============================================================================

import type { DashboardPeriod, DashboardStats } from "./types";

function getDateRangeFromPeriod(period: DashboardPeriod): { from: Date; to: Date; previousFrom: Date; previousTo: Date } {
    const now = new Date();
    let from: Date;
    const to = endOfDay(now);

    switch (period) {
        case "7d":
            from = startOfDay(subDays(now, 6));
            break;
        case "30d":
            from = startOfDay(subDays(now, 29));
            break;
        case "90d":
            from = startOfDay(subDays(now, 89));
            break;
        case "1y":
            from = startOfYear(now);
            break;
        default:
            from = startOfDay(subDays(now, 29));
    }

    // Calculate previous period for comparison
    const duration = to.getTime() - from.getTime();
    const previousTo = new Date(from.getTime() - 1);
    const previousFrom = new Date(previousTo.getTime() - duration);

    return { from, to, previousFrom, previousTo };
}

function getGranularity(period: DashboardPeriod): "day" | "week" | "month" {
    switch (period) {
        case "7d":
        case "30d":
            return "day";
        case "90d":
            return "week";
        case "1y":
            return "month";
        default:
            return "day";
    }
}

