/**
 * Get date range from period string
 */
function getDateRangeFromPeriod(
    range: DateRange,
    customFrom?: string,
    customTo?: string
): { from: Date; to: Date } {
    const now = new Date();
    let from: Date;
    let to = endOfDay(now);

    switch (range) {
        case "today":
            from = startOfDay(now);
            break;
        case "7d":
            from = startOfDay(subDays(now, 6));
            break;
        case "30d":
            from = startOfDay(subDays(now, 29));
            break;
        case "90d":
            from = startOfDay(subDays(now, 89));
            break;
        case "12m":
        case "year":
            from = startOfYear(now);
            break;
        case "custom":
            from = customFrom ? startOfDay(new Date(customFrom)) : startOfDay(subDays(now, 29));
            to = customTo ? endOfDay(new Date(customTo)) : endOfDay(now);
            break;
        default:
            from = startOfDay(subDays(now, 29));
    }

    return { from, to };
}

/**
 * Get granularity based on date range
 */
function getGranularityFromRange(range: DateRange): AnalyticsGranularity {
    switch (range) {
        case "today":
            return "hour";
        case "7d":
        case "30d":
            return "day";
        case "90d":
            return "week";
        case "12m":
        case "year":
            return "month";
        default:
            return "day";
    }
}

