export function AnalyticsClient({ data, currency, dateRange, isFreeTier = false, isProTier = false }: AnalyticsClientProps) {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const [isPending, startTransition] = useTransition();

    const handleRangeChange = (range: string) => {
        const params = new URLSearchParams(searchParams.toString());
        params.set("range", range);
        startTransition(() => {
            router.push(`${pathname}?${params.toString()}`);
        });
    };

    const handleExport = async () => {
        const result = await exportAnalyticsReport(dateRange);
        if (result.error) {
            toast.error(result.error);
            return;
        }
        if (result.csv) {
            const blob = new Blob([result.csv], { type: "text/csv" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `analytics-${dateRange}-${format(new Date(), "yyyy-MM-dd")}.csv`;
            a.click();
            URL.revokeObjectURL(url);
            toast.success("Report exported");
        }
    };

    return (
        <AnalyticsDashboardView
            data={data}
            currency={currency}
            dateRange={dateRange}
            isFreeTier={isFreeTier}
            isPending={isPending}
            onRangeChange={handleRangeChange}
            onExport={handleExport}
            onRefresh={() => router.refresh()}
        />
    );
}

