                                        const Icon = inputTypeIcons[attribute.inputType] || Type;

                                        return (
                                            <TableRow
                                                key={attribute.id}
                                                className={cn(
                                                    "group cursor-pointer",
                                                    selectedIds.has(attribute.id) && "bg-muted/50"
