/**
 * Update price for multiple products
 */
export async function bulkUpdatePrice(
    ids: string[],
    priceChange: {
        type: "set" | "increase" | "decrease" | "percentage_increase" | "percentage_decrease";
        value: number;
    }
): Promise<BulkActionResult> {
    const validIds = bulkIdsSchema.parse(ids);
    const validPriceChange = z.object({
        type: z.enum(["set", "increase", "decrease", "percentage_increase", "percentage_decrease"]),
        value: z.number().min(0),
    }).parse(priceChange);
    const { tenantId, userId } = await getAuthenticatedTenant();

    const errors: BulkActionError[] = [];
    let successCount = 0;

    for (const id of validIds) {
        try {
            const product = await productRepository.findById(tenantId, id);
            if (!product) throw new Error("Product not found");

            const currentPrice = parseFloat(product.price || "0");
            let newPrice: number;

            switch (validPriceChange.type) {
                case "set":
                    newPrice = validPriceChange.value;
                    break;
                case "increase":
                    newPrice = currentPrice + validPriceChange.value;
                    break;
                case "decrease":
                    newPrice = Math.max(0, currentPrice - validPriceChange.value);
                    break;
                case "percentage_increase":
                    newPrice = currentPrice * (1 + validPriceChange.value / 100);
                    break;
                case "percentage_decrease":
                    newPrice = currentPrice * (1 - validPriceChange.value / 100);
                    break;
                default:
                    throw new Error("Invalid price change type");
            }

            await productRepository.update(tenantId, id, { price: newPrice.toFixed(2) });
            successCount++;

            try {
                await auditLogger.logUpdate(tenantId, "product", id, { price: currentPrice }, { price: newPrice }, { userId });
            } catch (auditError) {
                log.error(`Audit logging failed for product ${id}:`, auditError);
            }
        } catch (error) {
            log.error("Bulk action failed for item", error, { itemId: id });
            errors.push({
                itemId: id,
                message: error instanceof Error ? error.message : "Unknown error",
                code: "UPDATE_FAILED",
            });
        }
    }

    revalidateEntityPaths("products");

    return {
        success: errors.length === 0,
        successCount,
        failedCount: errors.length,
        totalCount: validIds.length,
        errors: errors.length > 0 ? errors : undefined,
        message: errors.length === 0 
            ? `Successfully updated prices for ${successCount} products` 
            : `Updated ${successCount} of ${validIds.length} products`,
    };
}

/**
 * Add a tag to multiple customers
 */
export async function bulkAddTag(
    ids: string[],
    tag: string
): Promise<BulkActionResult> {
    const validIds = bulkIdsSchema.parse(ids);
    const validTag = z.string().min(1).max(50).parse(tag);
    const { supabase, tenantId, userId } = await getAuthenticatedTenant();

    const errors: BulkActionError[] = [];
    let successCount = 0;

    // Batch fetch all customers
    const { data: customers } = await supabase
        .from("customers")
        .select("id, metadata")
        .eq("tenant_id", tenantId)
        .in("id", validIds);

    const customerMap = new Map((customers || []).map(c => [c.id, c]));

    for (const id of validIds) {
        try {
            const customer = customerMap.get(id);
            if (!customer) throw new Error("Customer not found");

            const currentMetadata = (customer.metadata as Record<string, unknown>) || {};
            const currentTags = (currentMetadata.tags as string[]) || [];

            const { error } = await supabase
                .from("customers")
                .update({ 
                    metadata: { ...currentMetadata, tags: [...currentTags, validTag] },
                    updated_at: new Date().toISOString()
                })
                .eq("id", id)
                .eq("tenant_id", tenantId);

            if (error) throw error;
            successCount++;

            try {
                await auditLogger.logUpdate(tenantId, "customer", id, {}, { tagAdded: validTag }, { userId });
            } catch (auditError) {
                log.error(`Audit logging failed for customer ${id}:`, auditError);
            }
        } catch (error) {
            log.error("Bulk action failed for item", error, { itemId: id });
            errors.push({
                itemId: id,
                message: error instanceof Error ? error.message : "Unknown error",
                code: "UPDATE_FAILED",
            });
        }
    }

    revalidateEntityPaths("customers");

    return {
        success: errors.length === 0,
        successCount,
        failedCount: errors.length,
        totalCount: validIds.length,
        errors: errors.length > 0 ? errors : undefined,
        message: errors.length === 0 
            ? `Successfully added tag "${validTag}" to ${successCount} customers` 
            : `Added tag to ${successCount} of ${validIds.length} customers`,
    };
}

/**
 * Send email to multiple customers
 */
export async function bulkSendEmail(
    ids: string[],
    emailConfig: { subject: string; templateId?: string; body?: string }
): Promise<BulkActionResult> {
    const validIds = bulkIdsSchema.parse(ids);
    const validConfig = z.object({
        subject: z.string().min(1).max(200),
        templateId: z.string().optional(),
        body: z.string().optional(),
    }).parse(emailConfig);
    const { tenantId, userId } = await getAuthenticatedTenant();

    const errors: BulkActionError[] = [];
    let successCount = 0;

    for (const id of validIds) {
        try {
            const customer = await customerRepository.findById(tenantId, id);
            if (!customer) throw new Error("Customer not found");
            if (!customer.email) throw new Error("Customer has no email address");

            // TODO: Integrate with email service (e.g., Resend, SendGrid)
            log.info(`[Bulk Email] Would send email to ${customer.email}:`, {
                subject: validConfig.subject,
                templateId: validConfig.templateId,
            });

            successCount++;

            try {
                await auditLogger.log(tenantId, "email_sent", {
                    entityType: "customer",
                    entityId: id,
                    newValues: { email: customer.email, subject: validConfig.subject },
                    metadata: { userId },
                });
            } catch (auditError) {
                log.error(`Audit logging failed for customer ${id}:`, auditError);
            }
        } catch (error) {
            log.error("Bulk action failed for item", error, { itemId: id });
            errors.push({
                itemId: id,
                message: error instanceof Error ? error.message : "Unknown error",
                code: "EMAIL_FAILED",
            });
        }
    }

    return {
        success: errors.length === 0,
        successCount,
        failedCount: errors.length,
        totalCount: validIds.length,
        errors: errors.length > 0 ? errors : undefined,
        message: errors.length === 0 
            ? `Successfully queued emails for ${successCount} customers` 
            : `Queued ${successCount} of ${validIds.length} emails`,
    };
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import type { Category, CategoryBreadcrumb } from "../types";
import {
    CategoryHeader,
    CategoryInfoCard,
    CategoryImageCard,
    CategorySeoCard,
    CategorySubcategoriesCard,
    CategoryProductsCard,
} from "@/features/categories/components";
import { EntityDetailPage } from "@/components/dashboard/templates";
import { deleteCategoryById } from "../category-actions";

interface CategoryDetailClientProps {
    initialCategory: Category;
    breadcrumbs: CategoryBreadcrumb[];
}

export function CategoryDetailClient({ initialCategory, breadcrumbs }: CategoryDetailClientProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [category, setCategory] = useState<Category>(initialCategory);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [createSubcategoryDialogOpen, setCreateSubcategoryDialogOpen] = useState(false);

    const handleUpdate = (data: Partial<Category>) => {
        setCategory(prev => ({ ...prev, ...data }));
    };

    const handleDelete = () => {
        if (category.subcategoryCount > 0) {
            toast.error("Cannot delete category with subcategories");
            return;
        }

        startTransition(async () => {
            const result = await deleteCategoryById(category.id);
            if (result.success) {
                toast.success("Category deleted");
                router.push(category.parentId ? `/dashboard/categories/${category.parentId}` : "/dashboard/categories");
            } else {
                toast.error(result.error || "Failed to delete category");
            }
        });
    };

    return (
        <>
            <EntityDetailPage
                backHref={category.parentId ? `/dashboard/categories/${category.parentId}` : "/dashboard/categories"}
                backLabel="Categories"
                title={category.name}
                sidebar={
                    <>
                        <CategoryImageCard category={category} onUpdate={handleUpdate} />
                        <CategorySeoCard category={category} onUpdate={handleUpdate} />
                    </>
                }
            >
                {/* Header with breadcrumbs/actions */}
                <CategoryHeader
                    category={category}
                    breadcrumbs={breadcrumbs}
                    onAddSubcategory={() => setCreateSubcategoryDialogOpen(true)}
                    onDelete={() => setDeleteDialogOpen(true)}
                />

                <CategoryInfoCard category={category} onUpdate={handleUpdate} />
                <CategorySubcategoriesCard category={category} onUpdate={handleUpdate} />
                <CategoryProductsCard category={category} onUpdate={handleUpdate} />
            </EntityDetailPage>

            {/* Delete Confirmation */}
            <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Delete category?</AlertDialogTitle>
                        <AlertDialogDescription>
                            This will permanently delete &quot;{category.name}&quot;.
                            {category.productCount > 0 && (
                                <span className="block mt-2 text-info">
                                    {category.productCount} product(s) will become uncategorized.
                                </span>
                            )}
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                            disabled={category.subcategoryCount > 0}
                        >
                            Delete
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    );
}

"use server";

import { createLogger } from "@/lib/logger";
const log = createLogger("actions:categories");

import { z } from "zod";
import { createClient } from "@/infrastructure/supabase/server";
import { getAuthenticatedClient } from "@/lib/auth";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { expireCategoriesCache } from "@/features/store/data";
import type { Category } from "@/infrastructure/supabase/types";
import type { CategoryWithCount } from "./types";

async function getAuthenticatedTenant() {
    const { user, supabase } = await getAuthenticatedClient();
    return { supabase, tenantId: user.tenantId };
}

/**
 * Immediately expire both dashboard and storefront category caches
 * Uses updateTag for read-your-own-writes consistency
 */
async function expireCategoryCaches(tenantId: string) {
    // Dashboard paths
    revalidatePath("/dashboard/categories");
    revalidatePath("/dashboard/products");
    revalidatePath("/dashboard/products/new");

    // Storefront cache - immediate expiration
    await expireCategoriesCache(tenantId);
}

// Get categories with counts

export async function getCategories(): Promise<{ categories: CategoryWithCount[]; error?: string }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        // Get categories with product counts
        const { data: categories, error } = await supabase
            .from("categories")
            .select(`
                *,
                products:products(count)
            `)
            .eq("tenant_id", tenantId)
            .order("sort_order", { ascending: true });

        if (error) {
            return { categories: [], error: error.message };
        }

        // Calculate children count for each category
        const categoriesWithCounts: CategoryWithCount[] = (categories || []).map(cat => {
            const childrenCount = (categories || []).filter(c => c.parent_id === cat.id).length;
            return {
                ...cat,
                products_count: cat.products?.[0]?.count || 0,
                children_count: childrenCount,
            };
        });

        return { categories: categoriesWithCounts };
    } catch (err) {
        log.error("Get categories error:", err);
        return { categories: [], error: err instanceof Error ? err.message : "Failed to fetch categories" };
    }
}

const createCategorySchema = z.object({
  name: z.string().min(1, "Category name is required"),
  slug: z.string().optional().default(""),
  description: z.string().optional().default(""),
  parentId: z.string().optional().default(""),
});

export async function createCategory(formData: FormData): Promise<{ success?: boolean; error?: string; category?: Category }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        const parsed = createCategorySchema.parse({
            name: formData.get("name"),
            slug: formData.get("slug") ?? "",
            description: formData.get("description") ?? "",
            parentId: formData.get("parentId") ?? "",
        });
        const imageUrl = formData.get("imageUrl") as string;

        // Check for duplicate slug
        const { data: existing } = await supabase
            .from("categories")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("slug", parsed.slug)
            .single();

        let finalSlug = parsed.slug;
        if (existing) {
            finalSlug = `${parsed.slug}-${Date.now()}`;
        }

        // Get max sort order
        const { data: maxOrder } = await supabase
            .from("categories")
            .select("sort_order")
            .eq("tenant_id", tenantId)
            .order("sort_order", { ascending: false })
            .limit(1)
            .single();

        const sortOrder = (maxOrder?.sort_order || 0) + 1;

        const { data: category, error } = await supabase
            .from("categories")
            .insert({
                tenant_id: tenantId,
                name: parsed.name,
                slug: finalSlug,
                description: parsed.description || null,
                image_url: imageUrl || null,
                parent_id: parsed.parentId || null,
                sort_order: sortOrder,
            })
            .select()
            .single();

        if (error) {
            log.error("Create category error:", error);
            return { success: false, error: `Failed to create category: ${error.message}` };
        }

        await expireCategoryCaches(tenantId);
        return { category };
    } catch (err) {
        if (err instanceof z.ZodError) {
            return { success: false, error: err.issues[0].message };
        }
        log.error("Create category error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to create category" };
    }
}

export async function updateCategory(formData: FormData): Promise<{ success?: boolean; error?: string; category?: Category }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        const id = formData.get("id") as string;
        const name = formData.get("name") as string;
        const slug = formData.get("slug") as string;
        const description = formData.get("description") as string;
        const imageUrl = formData.get("imageUrl") as string;
        const parentId = formData.get("parentId") as string;

        if (!name?.trim()) {
            return { success: false, error: "Category name is required" };
        }

        // Prevent setting self as parent
        if (parentId === id) {
            return { success: false, error: "Category cannot be its own parent" };
        }

        // Check for duplicate slug (excluding current category)
        const { data: existing } = await supabase
            .from("categories")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("slug", slug)
            .neq("id", id)
            .single();

        let finalSlug = slug;
        if (existing) {
            finalSlug = `${slug}-${Date.now()}`;
        }

        const { data: category, error } = await supabase
            .from("categories")
            .update({
                name,
                slug: finalSlug,
                description: description || null,
                image_url: imageUrl || null,
                parent_id: parentId || null,
                updated_at: new Date().toISOString(),
            })
            .eq("id", id)
            .eq("tenant_id", tenantId)
            .select()
            .single();

        if (error) {
            log.error("Update category error:", error);
            return { success: false, error: `Failed to update category: ${error.message}` };
        }

        await expireCategoryCaches(tenantId);
        return { category };
    } catch (err) {
        log.error("Update category error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to update category" };
    }
}

export async function deleteCategory(id: string): Promise<{ success?: boolean; error?: string }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        // Check if category has children
        const { data: children } = await supabase
            .from("categories")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("parent_id", id)
            .limit(1);

        if (children && children.length > 0) {
            return { success: false, error: "Cannot delete category with subcategories. Delete or move subcategories first." };
        }

        // Unassign products from this category
        await supabase
            .from("products")
            .update({ category_id: null })
            .eq("tenant_id", tenantId)
            .eq("category_id", id);

        // Delete the category
        const { error } = await supabase
            .from("categories")
            .delete()
            .eq("id", id)
            .eq("tenant_id", tenantId);

        if (error) {
            log.error("Delete category error:", error);
            return { success: false, error: `Failed to delete category: ${error.message}` };
        }

        await expireCategoryCaches(tenantId);
        return { success: true };
    } catch (err) {
        log.error("Delete category error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to delete category" };
    }
}

export async function bulkDeleteCategories(ids: string[]): Promise<{ success?: boolean; error?: string; deletedCount: number }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();
        let deletedCount = 0;

        for (const id of ids) {
            // Check if category has children
            const { data: children } = await supabase
                .from("categories")
                .select("id")
                .eq("tenant_id", tenantId)
                .eq("parent_id", id)
                .limit(1);

            if (children && children.length > 0) {
                continue; // Skip categories with children
            }

            // Unassign products
            await supabase
                .from("products")
                .update({ category_id: null })
                .eq("tenant_id", tenantId)
                .eq("category_id", id);

            // Delete category
            const { error } = await supabase
                .from("categories")
                .delete()
                .eq("id", id)
                .eq("tenant_id", tenantId);

            if (!error) {
                deletedCount++;
            }
        }

        await expireCategoryCaches(tenantId);
        return { deletedCount };
    } catch (err) {
        log.error("Bulk delete categories error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to delete categories", deletedCount: 0 };
    }
}

export async function updateCategoryOrder(updates: { id: string; sort_order: number; parent_id: string | null }[]): Promise<{ success?: boolean; error?: string }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        for (const update of updates) {
            const { error } = await supabase
                .from("categories")
                .update({ 
                    sort_order: update.sort_order,
                    parent_id: update.parent_id,
                    updated_at: new Date().toISOString(),
                })
                .eq("id", update.id)
                .eq("tenant_id", tenantId);

            if (error) {
                log.error("Update category order error:", error);
                return { success: false, error: `Failed to update order: ${error.message}` };
            }
        }

        await expireCategoryCaches(tenantId);
        return { success: true };
    } catch (err) {
        log.error("Update category order error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to update order" };
    }
}

export async function moveCategory(id: string, newParentId: string | null): Promise<{ success?: boolean; error?: string }> {
    try {
        const { supabase, tenantId } = await getAuthenticatedTenant();

        // Prevent circular reference
        if (newParentId) {
            // Check if newParentId is a descendant of id
            let currentId: string | null = newParentId;
            while (currentId) {
                if (currentId === id) {
                    return { success: false, error: "Cannot move category to its own descendant" };
                }
                const result = await supabase
                    .from("categories")
                    .select("parent_id")
                    .eq("id", currentId)
                    .single();
                const parentData = result.data as { parent_id: string | null } | null;
                currentId = parentData?.parent_id || null;
            }
        }

        const { error } = await supabase
            .from("categories")
            .update({ 
                parent_id: newParentId,
                updated_at: new Date().toISOString(),
            })
            .eq("id", id)
            .eq("tenant_id", tenantId);

        if (error) {
            log.error("Move category error:", error);
            return { success: false, error: `Failed to move category: ${error.message}` };
        }

        await expireCategoryCaches(tenantId);
        return { success: true };
    } catch (err) {
        log.error("Move category error:", err);
        return { success: false, error: err instanceof Error ? err.message : "Failed to move category" };
    }
}

"use client";

import { useState, useTransition, useMemo } from "react";
import { useRouter } from "next/navigation";
