export async function deleteCategoryById(categoryId: string) {
    const { supabase, tenantId } = await getAuthenticatedTenant();

    try {
        validateId(categoryId, "Category ID");
        // Check if category has children
        const { data: children } = await supabase
            .from("categories")
            .select("id")
            .eq("parent_id", categoryId)
            .eq("tenant_id", tenantId)
            .limit(1);

        if (children && children.length > 0) {
            return { success: false, error: "Cannot delete category with subcategories" };
        }

        // Unassign products from this category
        await supabase
            .from("products")
            .update({ category_id: null })
            .eq("category_id", categoryId)
            .eq("tenant_id", tenantId);

        // Delete category
        const { error } = await supabase
            .from("categories")
            .delete()
            .eq("id", categoryId)
            .eq("tenant_id", tenantId);

        if (error) {
            return { success: false, error: "Failed to delete category" };
        }

        revalidatePath("/dashboard/categories");
        return { success: true };
    } catch (error) {
        log.error("Failed to delete category:", error);
        return { success: false, error: "Failed to delete category" };
    }
}

