export async function createSubcategory(
    parentId: string,
    data: { name: string; slug: string; description?: string }
) {
    const { supabase, tenantId } = await getAuthenticatedTenant();

    try {
        validateId(parentId, "Parent ID");
        // Check for duplicate slug
        const { data: existing } = await supabase
            .from("categories")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("slug", data.slug)
            .single();

        let finalSlug = data.slug;
        if (existing) {
            finalSlug = `${data.slug}-${Date.now()}`;
        }

        // Get max sort order
        const { data: maxOrder } = await supabase
            .from("categories")
            .select("sort_order")
            .eq("parent_id", parentId)
            .eq("tenant_id", tenantId)
            .order("sort_order", { ascending: false })
            .limit(1)
            .single();

        const sortOrder = (maxOrder?.sort_order || 0) + 1;

        const { data: category, error } = await supabase
            .from("categories")
            .insert({
                tenant_id: tenantId,
                parent_id: parentId,
                name: data.name,
                slug: finalSlug,
                description: data.description || null,
                sort_order: sortOrder,
            })
            .select()
            .single();

        if (error) {
            return { success: false, error: "Failed to create subcategory" };
        }

        revalidatePath(`/dashboard/categories/${parentId}`);
        revalidatePath("/dashboard/categories");
        return { success: true, data: category };
    } catch (error) {
        log.error("Failed to create subcategory:", error);
        return { success: false, error: "Failed to create subcategory" };
    }
}

export async function deleteSubcategory(subcategoryId: string, parentId: string) {
    const result = await deleteCategoryById(subcategoryId);
    if (result.success) {
        revalidatePath(`/dashboard/categories/${parentId}`);
    }
    return result;
}

