    Loader2,
    Grid3x3,
    ChevronRight,
    ChevronLeft,
    CheckCircle,
    FolderOpen,
    Layers,
    Info,
    Search,
    Package,
} from "lucide-react";
import { Button } from "@/components/ui/button";
