export async function getAvailableProducts(collectionId: string, search?: string) {
    const { supabase, tenantId } = await getAuthenticatedTenant();

    try {
        // Get products already in collection
        const { data: existingProducts } = await supabase
            .from("collection_products")
            .select("product_id")
            .eq("collection_id", collectionId);

        const existingIds = (existingProducts || []).map(p => p.product_id);

        // Get available products
        let query = supabase
            .from("products")
            .select("id, name, slug, sku, price, images, status")
            .eq("tenant_id", tenantId)
            .eq("status", "active")
            .order("name", { ascending: true })
            .limit(50);

        if (existingIds.length > 0) {
            query = query.not("id", "in", `(${existingIds.join(",")})`);
        }

        if (search) {
            query = query.or(`name.ilike.%${sanitizeSearch(search)}%,sku.ilike.%${sanitizeSearch(search)}%`);
        }

        const { data: products, error } = await query;

        if (error) {
            return { success: false, error: "Failed to fetch products", data: [] };
        }

        return {
            success: true,
            data: (products || []).map(p => ({
                id: p.id,
                name: p.name,
                slug: p.slug,
                sku: p.sku,
                price: parseFloat(p.price || "0"),
                image: (p.images as string[])?.[0] || null,
                status: p.status,
            })),
        };
    } catch (error) {
        log.error("Failed to fetch products:", error);
        return { success: false, error: "Failed to fetch products", data: [] };
    }
}

"use client";

import { useState, useCallback, useTransition, useEffect } from "react";
import Image from "next/image";
import { toast } from "sonner";
import {
    Image as ImageIcon,
    X,
    Loader2,
    FolderOpen,
    ChevronRight,
    ChevronLeft,
    CheckCircle,
    Info,
    Type,
    Settings,
    Check,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/shared/utils";
import { createCollection, updateCollection } from "./actions";
import type { Collection } from "@/infrastructure/supabase/types";

interface CollectionDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    collection: Collection | null;
    onSuccess: (collection: Collection, isNew: boolean) => void;
}

function generateSlug(name: string): string {
    return name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
}

const STEPS = [
    { id: 1, title: "Basic Info", description: "Name and type" },
    { id: 2, title: "Details", description: "Image and settings" },
];

const COLLECTION_TYPES = [
    {
        value: "manual" as const,
        label: "Manual Collection",
        description: "Add products manually to this collection",
        icon: Check,
    },
    {
        value: "automatic" as const,
        label: "Automatic Collection",
        description: "Products are added based on conditions",
        icon: Settings,
    },
];

export function CollectionDialog({ open, onOpenChange, collection, onSuccess }: CollectionDialogProps) {
    const [isPending, startTransition] = useTransition();
    const [isUploading, setIsUploading] = useState(false);
    const [step, setStep] = useState(1);

    // Form state
    const [name, setName] = useState("");
    const [slug, setSlug] = useState("");
    const [description, setDescription] = useState("");
    const [imageUrl, setImageUrl] = useState("");
    const [isActive, setIsActive] = useState(true);
    const [type, setType] = useState<"manual" | "automatic">("manual");
    const [errors, setErrors] = useState<Record<string, string>>({});

    // Initialize form when dialog opens
    useEffect(() => {
        if (open) {
            if (collection) {
                setName(collection.name);
                setSlug(collection.slug);
                setDescription(collection.description || "");
                setImageUrl(collection.image_url || "");
                setIsActive(collection.is_active ?? true);
                setType(collection.type || "manual");
            } else {
                resetForm();
            }
        }
    }, [open, collection]);

    const resetForm = useCallback(() => {
        setStep(1);
        setName("");
        setSlug("");
        setDescription("");
        setImageUrl("");
        setIsActive(true);
        setType("manual");
        setErrors({});
    }, []);

    const handleClose = useCallback(() => {
        resetForm();
        onOpenChange(false);
    }, [resetForm, onOpenChange]);

    const handleNameChange = (value: string) => {
        setName(value);
        if (!collection && !slug) {
            setSlug(generateSlug(value));
        }
        if (errors.name) {
            setErrors(prev => ({ ...prev, name: "" }));
        }
    };

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsUploading(true);
        try {
            const formData = new FormData();
            formData.append("file", file);

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formData,
            });

            if (!response.ok) throw new Error("Upload failed");

            const data = await response.json();
            setImageUrl(data.url);
            toast.success("Image uploaded");
        } catch {
            toast.error("Failed to upload image");
        } finally {
            setIsUploading(false);
        }
    };

    const validate = (): boolean => {
        const newErrors: Record<string, string> = {};

        if (!name.trim()) {
            newErrors.name = "Collection name is required";
        }

        if (!slug.trim()) {
            newErrors.slug = "URL slug is required";
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async () => {
        if (!validate()) {
            setStep(1);
            return;
        }

        const formData = new FormData();
        formData.set("name", name);
        formData.set("slug", slug);
        formData.set("description", description);
        formData.set("imageUrl", imageUrl);
        formData.set("isActive", String(isActive));
        formData.set("type", type);

        startTransition(async () => {
            try {
                if (collection) {
                    formData.set("id", collection.id);
                    const result = await updateCollection(formData);
                    if (result.error) {
                        toast.error(result.error);
                        return;
                    }
                    onSuccess(result.collection!, false);
                    toast.success("Collection updated");
                } else {
                    const result = await createCollection(formData);
                    if (result.error) {
                        toast.error(result.error);
                        return;
                    }
                    onSuccess(result.collection!, true);
                    toast.success("Collection created");
                }
                handleClose();
            } catch {
                toast.error("Something went wrong");
            }
        });
    };

    const canProceed = step === 1 ? name.trim() && slug.trim() : true;
    const selectedType = COLLECTION_TYPES.find(t => t.value === type);

    if (!open) return null;

    return (
        <>
            {/* Backdrop */}
            <div 
                className="fixed inset-0 bg-foreground/50 z-50 animate-in fade-in duration-200"
                onClick={handleClose}
            />

            {/* Slide-over Panel */}
            <div className="fixed inset-y-0 right-0 z-50 w-full max-w-xl animate-in slide-in-from-right duration-300">
                <div className="flex h-full flex-col bg-background">
                    {/* Header */}
                    <div className="border-b px-4 py-4">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="flex size-9 items-center justify-center rounded-lg bg-primary/10">
                                    <FolderOpen className="size-4 text-primary" />
                                </div>
                                <div>
                                    <h2 className="text-sm font-semibold">
                                        {collection ? "Edit Collection" : "Create Collection"}
                                    </h2>
                                    <p className="text-sm text-muted-foreground">
                                        Step {step} of {STEPS.length}: {STEPS[step - 1].description}
                                    </p>
                                </div>
                            </div>
                            <Button variant="ghost" size="icon" aria-label="Close" onClick={handleClose}>
                                <X className="size-4" />
                            </Button>
                        </div>

                        {/* Progress Steps */}
                        <div className="mt-4 flex items-center gap-2">
                            {STEPS.map((s, i) => (
                                <div key={s.id} className="flex items-center">
                                    <button
                                        type="button"
                                        onClick={() => s.id < step && setStep(s.id)}
                                        disabled={s.id > step}
                                        className={cn(
                                            "flex size-8 items-center justify-center rounded-full text-sm font-medium transition-colors",
                                            step > s.id
                                                ? "bg-primary text-primary-foreground cursor-pointer hover:bg-primary/90"
                                                : step === s.id
                                                ? "bg-primary text-primary-foreground"
                                                : "bg-muted text-muted-foreground cursor-not-allowed"
                                        )}
                                    >
                                        {step > s.id ? (
                                            <CheckCircle className="size-4" />
                                        ) : (
                                            s.id
                                        )}
                                    </button>
                                    {i < STEPS.length - 1 && (
                                        <div
                                            className={cn(
                                                "mx-2 h-0.5 w-12 transition-colors",
                                                step > s.id ? "bg-primary" : "bg-muted"
                                            )}
                                        />
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Content */}
                    <div className="flex-1 overflow-y-auto p-4">
                        {/* Step 1: Basic Info */}
                        {step === 1 && (
                            <div className="space-y-4">
                                {/* Name */}
                                <div className="space-y-2">
                                    <Label htmlFor="name">
                                        Collection Name <span className="text-destructive">*</span>
                                    </Label>
                                    <Input
                                        id="name"
                                        value={name}
                                        onChange={(e) => handleNameChange(e.target.value)}
                                        placeholder="e.g., Summer Sale, New Arrivals, Best Sellers"
                                        className={cn( errors.name && "border-destructive")}
                                        autoFocus
                                    />
                                    {errors.name && <p className="text-xs text-destructive">{errors.name}</p>}
                                    <p className="text-xs text-muted-foreground">
                                        This will be displayed to customers in your store
                                    </p>
                                </div>

                                {/* Slug */}
                                <div className="space-y-2">
                                    <Label htmlFor="slug">
                                        URL Slug <span className="text-destructive">*</span>
                                    </Label>
                                    <div className="flex items-center gap-2">
                                        <span className="text-sm text-muted-foreground shrink-0">/collections/</span>
                                        <Input
                                            id="slug"
                                            value={slug}
                                            onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, "-"))}
                                            placeholder="summer-sale"
                                            className={cn("font-mono", errors.slug && "border-destructive")}
                                        />
                                    </div>
                                    {errors.slug && <p className="text-xs text-destructive">{errors.slug}</p>}
                                </div>

                                {/* Collection Type */}
                                <div className="space-y-3">
                                    <Label>Collection Type</Label>
                                    <div className="grid gap-3">
                                        {COLLECTION_TYPES.map((t) => (
                                            <button
                                                key={t.value}
                                                type="button"
                                                onClick={() => setType(t.value)}
                                                className={cn(
                                                    "flex items-center gap-3 p-4 rounded-lg border text-left transition-colors",
                                                    "hover:border-primary/50 hover:bg-accent/50",
                                                    type === t.value
                                                        ? "border-primary bg-primary/5 ring-1 ring-primary"
                                                        : "border-border"
                                                )}
                                            >
                                                <div
                                                    className={cn(
                                                        "flex size-9 shrink-0 items-center justify-center rounded-lg transition-colors",
                                                        type === t.value ? "bg-primary text-primary-foreground" : "bg-muted"
                                                    )}
                                                >
                                                    <t.icon className="size-4" />
                                                </div>
                                                <div className="min-w-0 flex-1">
                                                    <p className={cn("font-medium", type === t.value && "text-primary")}>
                                                        {t.label}
                                                    </p>
                                                    <p className="text-sm text-muted-foreground">{t.description}</p>
                                                </div>
                                                {type === t.value && (
                                                    <CheckCircle className="size-4 text-primary shrink-0" />
                                                )}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        )}

                        {/* Step 2: Details */}
                        {step === 2 && (
                            <div className="space-y-4">
                                {/* Summary */}
                                <div className="rounded-lg border p-4 space-y-3">
                                                    <h3 className="font-medium flex items-center gap-2">
                                        <Info className="size-4 text-muted-foreground" />
                                        Summary
                                    </h3>
                                    <div className="grid grid-cols-2 gap-3 text-sm">
                                        <div>
                                            <p className="text-muted-foreground">Name</p>
                                            <p className="font-medium">{name}</p>
                                        </div>
                                        <div>
                                            <p className="text-muted-foreground">Type</p>
                                            <p className="font-medium">{selectedType?.label}</p>
                                        </div>
                                        <div className="col-span-2">
                                            <p className="text-muted-foreground">Slug</p>
                                            <p className="font-mono text-xs">/collections/{slug}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Image Upload */}
                                <div className="space-y-3">
                                    <Label>Collection Image</Label>
                                    <div className="flex items-start gap-4">
                                        <div className="size-32 rounded-lg border-2 border-dashed overflow-hidden shrink-0 bg-muted/30">
                                            {imageUrl ? (
                                                <div className="relative w-full h-full group">
                                                    <Image
                                                        src={imageUrl}
                                                        alt="Collection"
                                                        fill
                                                        className="object-cover"
                                                    />
                                                    <div className="absolute inset-0 bg-foreground/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                                        <Button
                                                            variant="destructive"

                                                            onClick={() => setImageUrl("")}
                                                        >
                                                            <X className="size-4" />
                                                            Remove
                                                        </Button>
                                                    </div>
                                                </div>
                                            ) : (
                                                <label className="w-full h-full flex flex-col items-center justify-center cursor-pointer hover:bg-muted/50 transition-colors">
                                                    <input
                                                        type="file"
                                                        accept="image/*"
                                                        onChange={handleImageUpload}
                                                        className="hidden"
                                                        disabled={isUploading}
                                                    />
                                                    {isUploading ? (
                                                        <Loader2 className="size-8 animate-spin text-muted-foreground" />
                                                    ) : (
                                                        <>
                                                            <ImageIcon className="size-8 text-muted-foreground" />
                                                            <span className="text-sm text-muted-foreground mt-2">Upload image</span>
                                                        </>
                                                    )}
                                                </label>
                                            )}
                                        </div>
                                        <div className="text-sm text-muted-foreground space-y-1">
                                            <p>Recommended: 800x800px</p>
                                            <p>Max size: 5MB</p>
                                            <p>Formats: JPG, PNG, WebP</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Description */}
                                <div className="space-y-2">
                                    <Label htmlFor="description">Description</Label>
                                    <Textarea
                                        id="description"
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                        placeholder="Describe this collection to help customers understand what products they'll find here..."
                                        className="resize-none min-h-[100px]"
                                        rows={4}
                                    />
                                    <p className="text-xs text-muted-foreground">
                                        This description may be shown on collection pages in your store
                                    </p>
                                </div>

                                {/* Settings */}
                                <div className="space-y-4 pt-4 border-t">
                                    <h3 className="font-medium">Settings</h3>

                                    <div className="flex items-center justify-between gap-4 p-3 rounded-lg border">
                                        <div className="space-y-0.5">
                                            <Label className="text-sm font-medium">Active</Label>
                                            <p className="text-xs text-muted-foreground">
                                                Show this collection on your store
                                            </p>
                                        </div>
                                        <Switch checked={isActive} onCheckedChange={setIsActive} />
                                    </div>
                                </div>

                                {/* Info about next steps */}
                                <div className="rounded-lg bg-muted/50 p-4 text-sm">
                                    <p className="font-medium mb-1">Next Steps</p>
                                    <p className="text-muted-foreground">
                                        After creating this collection, you&apos;ll be able to add products
                                        {type === "automatic" && " and set up automatic rules"}.
                                    </p>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Footer */}
                    <div className="border-t px-4 py-4">
                        <div className="flex items-center justify-between">
                            <Button
                                variant="ghost"
                                onClick={() => step > 1 ? setStep(step - 1) : handleClose()}
                            >
                                <ChevronLeft className="size-3.5" />
                                {step > 1 ? "Back" : "Cancel"}
                            </Button>

                            {step < 2 ? (
                                <Button
                                    onClick={() => setStep(step + 1)}
                                    disabled={!canProceed}
                                >
                                    Continue
                                    <ChevronRight className="size-4 ml-2" />
                                </Button>
                            ) : (
                                <Button
                                    onClick={handleSubmit}
                                    disabled={isPending || !name.trim()}
                                >
                                    {isPending ? (
                                        <>
                                            <Loader2 className="size-3.5 animate-spin" />
                                            {collection ? "Updating..." : "Creating..."}
                                        </>
                                    ) : (
                                        <>
                                            <CheckCircle className="size-3.5" />
                                            {collection ? "Update Collection" : "Create Collection"}
                                        </>
                                    )}
                                </Button>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { EntityListPage } from "@/components/dashboard/templates";
import { toast } from "sonner";
import {
    Plus,
    Trash2,
    Pencil,
    Search,
    FolderOpen,
    MoreHorizontal,
    CheckCircle,
    X,
    GripVertical,
    Eye,
    Copy,
    ChevronUp,
    ChevronDown,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { cn } from "@/shared/utils";
import { EmptyState } from "@/components/ui/empty-state";
import { StickyBulkActionsBar } from "@/components/dashboard/bulk-actions-bar";
import { DataTablePagination } from "@/components/dashboard/data-table/pagination";
import { CollectionDialog } from "./collection-dialog";
import { deleteCollection, updateCollectionOrder, toggleCollectionStatus } from "./actions";
import type { Collection } from "@/infrastructure/supabase/types";


interface CollectionsClientProps {
    collections: Collection[];
}

export function CollectionsClient({ collections: initialCollections }: CollectionsClientProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [collections, setCollections] = useState(initialCollections);
    const [searchQuery, setSearchQuery] = useState("");
    const [dialogOpen, setDialogOpen] = useState(false);
    const [editingCollection, setEditingCollection] = useState<Collection | null>(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [collectionToDelete, setCollectionToDelete] = useState<Collection | null>(null);
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [pageIndex, setPageIndex] = useState(0);
    const [pageSize, setPageSize] = useState(10);

    // Filter collections
    const filteredCollections = collections.filter(c =>
        c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        c.description?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    // Pagination
    const pageCount = Math.ceil(filteredCollections.length / pageSize);
    const paginatedCollections = filteredCollections.slice(
        pageIndex * pageSize,
        (pageIndex + 1) * pageSize
    );

    // Stats
    const activeCount = collections.filter(c => c.is_active).length;
    const totalProducts = collections.reduce((sum, c) => sum + (c.products_count || 0), 0);

    // Selection helpers
    const toggleAll = () => {
        if (selectedIds.size === filteredCollections.length && filteredCollections.length > 0) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(filteredCollections.map(c => c.id)));
        }
    };

    const toggleRow = (id: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev);
            if (next.has(id)) {
                next.delete(id);
            } else {
                next.add(id);
            }
            return next;
        });
    };

    // Bulk actions
    const handleBulkActivate = () => {
        startTransition(async () => {
            try {
            const ids = Array.from(selectedIds);
            const results = await Promise.all(ids.map(id => toggleCollectionStatus(id, true)));
            const failed = results.filter(r => r.error);
            if (failed.length > 0) {
                toast.error(`Failed to activate ${failed.length} collection(s)`);
            } else {
                setCollections(prev => prev.map(c => selectedIds.has(c.id) ? { ...c, is_active: true } : c));
                toast.success(`${ids.length} collection(s) activated`);
            }
            setSelectedIds(new Set());
            } catch {
                toast.error("Failed to activate collections");
            }
        });
    };

    const handleBulkDeactivate = () => {
        startTransition(async () => {
            try {
            const ids = Array.from(selectedIds);
            const results = await Promise.all(ids.map(id => toggleCollectionStatus(id, false)));
            const failed = results.filter(r => r.error);
            if (failed.length > 0) {
                toast.error(`Failed to deactivate ${failed.length} collection(s)`);
            } else {
                setCollections(prev => prev.map(c => selectedIds.has(c.id) ? { ...c, is_active: false } : c));
                toast.success(`${ids.length} collection(s) deactivated`);
            }
            setSelectedIds(new Set());
            } catch {
                toast.error("Failed to deactivate collections");
            }
        });
    };

    const handleBulkDelete = () => {
        startTransition(async () => {
            try {
            const ids = Array.from(selectedIds);
            const results = await Promise.all(ids.map(id => deleteCollection(id)));
            const failed = results.filter(r => r.error);
            if (failed.length > 0) {
                toast.error(`Failed to delete ${failed.length} collection(s)`);
            } else {
                setCollections(prev => prev.filter(c => !selectedIds.has(c.id)));
                toast.success(`${ids.length} collection(s) deleted`);
            }
            setSelectedIds(new Set());
            } catch {
                toast.error("Failed to delete collections");
            }
        });
    };

    const handleEdit = (collection: Collection) => {
        setEditingCollection(collection);
        setDialogOpen(true);
    };

    const handleCreate = () => {
        setEditingCollection(null);
        setDialogOpen(true);
    };

    const handleDelete = async () => {
        if (!collectionToDelete) return;

        startTransition(async () => {
            const result = await deleteCollection(collectionToDelete.id);
            if (result.error) {
                toast.error(result.error);
            } else {
                setCollections(prev => prev.filter(c => c.id !== collectionToDelete.id));
                toast.success("Collection deleted");
            }
            setDeleteDialogOpen(false);
            setCollectionToDelete(null);
        });
    };

    const handleToggleStatus = async (collection: Collection) => {
        startTransition(async () => {
            const result = await toggleCollectionStatus(collection.id, !collection.is_active);
            if (result.error) {
                toast.error(result.error);
            } else {
                setCollections(prev => prev.map(c =>
                    c.id === collection.id ? { ...c, is_active: !c.is_active } : c
                ));
                toast.success(collection.is_active ? "Collection deactivated" : "Collection activated");
            }
        });
    };

    const handleMoveUp = async (index: number) => {
        if (index === 0) return;
        const newCollections = [...collections];
        [newCollections[index - 1], newCollections[index]] = [newCollections[index], newCollections[index - 1]];

        // Update sort orders
        const updates = newCollections.map((c, i) => ({ id: c.id, sort_order: i }));

        setCollections(newCollections);
        startTransition(async () => {
            const result = await updateCollectionOrder(updates);
            if (result.error) {
                toast.error(result.error);
                setCollections(initialCollections);
            }
        });
    };

    const handleMoveDown = async (index: number) => {
        if (index === collections.length - 1) return;
        const newCollections = [...collections];
        [newCollections[index], newCollections[index + 1]] = [newCollections[index + 1], newCollections[index]];

        const updates = newCollections.map((c, i) => ({ id: c.id, sort_order: i }));

        setCollections(newCollections);
        startTransition(async () => {
            const result = await updateCollectionOrder(updates);
            if (result.error) {
                toast.error(result.error);
                setCollections(initialCollections);
            }
        });
    };

    const handleDialogSuccess = (collection: Collection, isNew: boolean) => {
        if (isNew) {
            setCollections(prev => [...prev, collection]);
        } else {
            setCollections(prev => prev.map(c => c.id === collection.id ? collection : c));
        }
        setDialogOpen(false);
        setEditingCollection(null);
        router.refresh();
    };

    // Reset page when search changes
    const handleSearchChange = (value: string) => {
        setSearchQuery(value);
        setPageIndex(0);
        setSelectedIds(new Set());
    };

    return (
        <EntityListPage
            title="Collections"
            actions={
                <Button onClick={handleCreate}>
                    <Plus className="size-3.5" />
                    Create Collection
                </Button>
            }
            stats={[
                { label: "Total", value: collections.length, icon: <div className="size-9 rounded-lg bg-primary/10 flex items-center justify-center"><FolderOpen className="size-4 text-primary" /></div> },
                { label: "Active", value: activeCount, icon: <div className="size-9 rounded-lg bg-success/10 flex items-center justify-center"><CheckCircle className="size-4 text-success" /></div> },
                { label: "Inactive", value: collections.length - activeCount, icon: <div className="size-9 rounded-lg bg-shipping/10 flex items-center justify-center"><X className="size-4 text-shipping" /></div> },
                { label: "Products", value: totalProducts, icon: <div className="size-9 rounded-lg bg-primary/10 flex items-center justify-center"><Eye className="size-4 text-primary" /></div> },
            ]}
            filters={
                <div className="flex items-center gap-4">
                    <div className="relative flex-1 w-full sm:max-w-sm">
                        <Search
                            className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground"
                        />
                        <Input
                            aria-label="Search collections" placeholder="Search collections..."
                            value={searchQuery}
                            onChange={(e) => handleSearchChange(e.target.value)}
                            className="pl-9"
                        />
                    </div>
                </div>
            }
        >
            {/* Collections Table */}
            <Table>
                    <TableHeader>
                        <TableRow className="hover:bg-transparent">
                            <TableHead className="w-12">
                                <Checkbox
                                    checked={selectedIds.size === filteredCollections.length && filteredCollections.length > 0}
                                    onCheckedChange={toggleAll}
                                    aria-label="Select all"
                                />
                            </TableHead>
                            <TableHead className="w-12"></TableHead>
                            <TableHead>Collection</TableHead>
                            <TableHead className="hidden md:table-cell">Products</TableHead>
                            <TableHead className="hidden md:table-cell">Type</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead className="w-12"></TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {paginatedCollections.length === 0 ? (
                            <TableRow className="hover:bg-transparent">
                                <TableCell colSpan={7} className="h-[300px]">
                                    <EmptyState
                                        icon={FolderOpen}
                                        title={searchQuery ? "No collections match your search" : "No collections yet"}
                                        description={searchQuery
                                            ? "Try adjusting your search"
                                            : "Create your first collection to organize products"}
                                        action={!searchQuery ? {
                                            label: "Create Collection",
                                            onClick: handleCreate,
                                        } : undefined}
                                    />
                                </TableCell>
                            </TableRow>
                        ) : (
                            paginatedCollections.map((collection, index) => (
                                <TableRow key={collection.id} className="group">
                                    <TableCell>
                                        <Checkbox
                                            checked={selectedIds.has(collection.id)}
                                            onCheckedChange={() => toggleRow(collection.id)}
                                            aria-label={`Select ${collection.name}`}
                                        />
                                    </TableCell>
                                    <TableCell>
                                        <div className="flex flex-col gap-1">
                                            <button
                                                onClick={() => handleMoveUp(index)}
                                                disabled={index === 0 || isPending}
                                                className="p-1 rounded hover:bg-muted disabled:opacity-30 disabled:cursor-not-allowed"
                                            >
                                                <ChevronUp className="size-3.5" />
                                            </button>
                                            <button
                                                onClick={() => handleMoveDown(index)}
                                                disabled={index === paginatedCollections.length - 1 || isPending}
                                                className="p-1 rounded hover:bg-muted disabled:opacity-30 disabled:cursor-not-allowed"
                                            >
                                                <ChevronDown className="size-3.5" />
                                            </button>
                                        </div>
                                    </TableCell>
                                    <TableCell>
                                        <div
                                            className="flex items-center gap-3 cursor-pointer"
                                            onClick={() => router.push(`/dashboard/collections/${collection.id}`)}
                                        >
                                            <div className="size-9 rounded-lg bg-muted overflow-hidden shrink-0">
                                                {collection.image_url ? (
                                                    <Image
                                                        src={collection.image_url}
                                                        alt={collection.name}
                                                        width={48}
                                                        height={48}
                                                        className="w-full h-full object-cover"
                                                    />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center">
                                                        <FolderOpen className="size-4 text-muted-foreground" />
                                                    </div>
                                                )}
                                            </div>
                                            <div className="min-w-0">
                                                <p className="font-medium truncate hover:underline">{collection.name}</p>
                                                {collection.description && (
