// Get initials from name
export function CustomersClient({
    customers,
    stats,
    totalCount,
    currentPage,
    pageSize,
    currency,
    filters,
}: CustomersClientProps) {
    const router = useRouter();

    // Use URL filters hook for state management
    const {
        searchValue,
        setSearchValue,
        setFilter,
        clearAll,
        hasActiveFilters,
        page,
        pageSize: urlPageSize,
        setPage,
        setPageSize,
        isPending,
        getFilter,
        sort,
        sortDir,
        setSort,
