interface CustomerGroup {
  id: string
  name: string
  description: string | null
  discount_percentage: number
  members_count: number
  created_at: string
}

interface CustomerGroupsClientProps {
  groups: CustomerGroup[]
  tenantId: string
}

export function CustomerGroupsClient({ groups: initialGroups, tenantId }: CustomerGroupsClientProps) {
  const router = useRouter()
  const [isPending, startTransition] = useTransition()
  const [groups, setGroups] = useState(initialGroups)
  const confirmDelete = useConfirmDelete()

  // Dialog state
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingGroup, setEditingGroup] = useState<CustomerGroup | null>(null)
  const [formData, setFormData] = useState({
    name: "",
    description: "",
    discountPercentage: "",
  })

  const resetForm = () => {
    setFormData({ name: "", description: "", discountPercentage: "" })
    setEditingGroup(null)
  }

  const openCreateDialog = () => {
    resetForm()
    setDialogOpen(true)
  }

  const openEditDialog = (group: CustomerGroup) => {
    setEditingGroup(group)
    setFormData({
      name: group.name,
      description: group.description || "",
      discountPercentage: group.discount_percentage?.toString() || "",
    })
    setDialogOpen(true)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    const data = new FormData()
    data.set("tenantId", tenantId)
    data.set("name", formData.name)
    data.set("description", formData.description)
    data.set("discountPercentage", formData.discountPercentage)

    startTransition(async () => {
      if (editingGroup) {
        data.set("groupId", editingGroup.id)
        const result = await updateCustomerGroup(data)
        if (result.error) {
          toast.error(result.error)
        } else {
          toast.success("Group updated")
          setDialogOpen(false)
          router.refresh()
        }
      } else {
        const result = await createCustomerGroup(data)
        if (result.error) {
          toast.error(result.error)
        } else {
          toast.success("Group created")
          setDialogOpen(false)
          router.refresh()
        }
      }
    })
  }

  const handleDelete = async (group: CustomerGroup) => {
    if (!(await confirmDelete(group.name, "group"))) return;
    startTransition(async () => {
      const result = await deleteCustomerGroup(group.id)
      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success("Group deleted")
        router.refresh()
      }
    })
  }

  return (
    <div className="space-y-3">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" aria-label="Go back" asChild>
            <Link href="/dashboard/customers">
              <ArrowLeft className="size-4" />
            </Link>
          </Button>
          <div>
            <h1 className="text-lg font-semibold tracking-tight">Customer Groups</h1>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button onClick={openCreateDialog}>
            <Plus className="size-3.5" />
            Create Group
          </Button>
        </div>
      </div>

      {/* Groups Grid */}
      {groups.length === 0 ? (
        <Card>
          <CardContent className="py-16">
            <EmptyState
              icon={Users}
              title="No customer groups"
              description="Create groups to segment customers and offer special discounts"
              action={{
                label: "Create Group",
                onClick: openCreateDialog,
              }}
            />
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {groups.map((group) => (
            <Card key={group.id} className="relative">
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex size-9 items-center justify-center rounded-lg bg-primary/10">
                      <Users className="size-4 text-primary" />
                    </div>
                    <div>
                      <CardTitle className="text-sm">{group.name}</CardTitle>
                      <p className="text-xs text-muted-foreground">
                        {group.members_count} member{group.members_count !== 1 ? "s" : ""}
                      </p>
                    </div>
                  </div>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon-sm" aria-label="More actions">
                        <MoreHorizontal className="size-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      <DropdownMenuItem onClick={() => openEditDialog(group)}>
                        <Edit className="size-3.5" />
                        Edit
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        className="text-destructive focus:text-destructive"
                        onClick={() => handleDelete(group)}
                      >
                        <Trash2 className="size-3.5" />
                        Delete
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                {group.description && (
                  <p className="text-sm text-muted-foreground line-clamp-2">
                    {group.description}
                  </p>
                )}
                <div className="flex items-center justify-between pt-2 border-t">
                  <div className="flex items-center gap-2">
                    <Percent className="size-4 text-muted-foreground" />
                    <span className="text-sm">
                      {group.discount_percentage > 0 ? (
                        <Badge className="bg-success/10 text-success">
                          {group.discount_percentage}% off
                        </Badge>
                      ) : (
                        <span className="text-muted-foreground">No discount</span>
                      )}
                    </span>
                  </div>
                  <span className="text-xs text-muted-foreground">
                    {format(new Date(group.created_at), "MMM d, yyyy")}
                  </span>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="sm:max-w-[425px]">
          <DialogHeader>
            <DialogTitle>{editingGroup ? "Edit Group" : "Create Customer Group"}</DialogTitle>
            <DialogDescription>
