/**
 * Update asset metadata (filename, alt text)
 */
export async function updateAsset(
  assetId: string,
  updates: { filename?: string; altText?: string }
): Promise<{ success: boolean; error?: string }> {
  try {
    const validAssetId = z.string().uuid().parse(assetId);
    const validUpdates = z.object({
      filename: z.string().min(1).max(255).optional(),
      altText: z.string().max(500).optional(),
    }).parse(updates);
    const { supabase, tenantId } = await getAuthenticatedTenant();

    const updateData: Record<string, unknown> = {};
    if (validUpdates.filename !== undefined) {
      updateData.filename = validUpdates.filename;
    }
    if (validUpdates.altText !== undefined) {
      updateData.alt_text = validUpdates.altText;
    }

    const { error } = await supabase
      .from("media_assets")
      .update(updateData)
      .eq("id", validAssetId)
      .eq("tenant_id", tenantId);

    if (error) {
      return { success: false, error: error.message };
    }

    revalidatePath("/dashboard/media");
    return { success: true };
  } catch (error) {
    log.error("Media action failed", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to update asset",
    };
  }
}

/**
 * Soft delete an asset
 */
export async function deleteAsset(
  assetId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const validAssetId = z.string().uuid().parse(assetId);
    const { supabase, tenantId } = await getAuthenticatedTenant();

    // Get asset to delete from blob storage
    const { data: asset, error: fetchError } = await supabase
      .from("media_assets")
      .select("blob_url")
      .eq("id", validAssetId)
      .eq("tenant_id", tenantId)
      .single();

    if (fetchError || !asset) {
      return { success: false, error: "Asset not found" };
    }

    // Delete from Vercel Blob
    try {
      await del(asset.blob_url);
    } catch (blobError) {
      console.warn("Failed to delete blob:", blobError);
      // Continue with soft delete even if blob deletion fails
    }

    // Soft delete in database
    const { error } = await supabase
      .from("media_assets")
      .update({ deleted_at: new Date().toISOString() })
      .eq("id", validAssetId)
      .eq("tenant_id", tenantId);

    if (error) {
      return { success: false, error: error.message };
    }

    revalidatePath("/dashboard/media");
    return { success: true };
  } catch (error) {
    log.error("Media action failed", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to delete asset",
    };
  }
}

/**
 * Get storage usage for the current tenant
 */
export async function getStorageUsage(): Promise<StorageUsage> {
  const { supabase, tenantId } = await getAuthenticatedTenant();

  const { data, error } = await supabase
    .from("media_assets")
    .select("size_bytes")
    .eq("tenant_id", tenantId)
    .is("deleted_at", null);

  if (error) {
    log.error("Get storage usage error:", error);
    return {
      usedBytes: 0,
      quotaBytes: DEFAULT_STORAGE_QUOTA,
      assetCount: 0,
      percentUsed: 0,
    };
  }

  const usedBytes = data?.reduce((sum, asset) => sum + (asset.size_bytes || 0), 0) || 0;
  const assetCount = data?.length || 0;

  return {
    usedBytes,
    quotaBytes: DEFAULT_STORAGE_QUOTA,
    assetCount,
    percentUsed: Math.round((usedBytes / DEFAULT_STORAGE_QUOTA) * 100),
  };
}

