/**
 * Create a new folder
 */
export async function createFolder(
  name: string,
  parentFolderId?: string | null
): Promise<{ success: boolean; folder?: MediaFolder; error?: string }> {
  try {
    const validName = z.string().min(1).max(100).parse(name);
    const validParentId = z.string().uuid().nullable().optional().parse(parentFolderId);
    const { supabase, tenantId } = await getAuthenticatedTenant();

    const { data: folder, error } = await supabase
      .from("media_folders")
      .insert({
        tenant_id: tenantId,
        name: validName,
        parent_folder_id: validParentId || null,
      })
      .select()
      .single();

    if (error) {
      if (error.code === "23505") {
        return { success: false, error: "A folder with this name already exists" };
      }
      return { success: false, error: error.message };
    }

    revalidatePath("/dashboard/media");
    return { success: true, folder: transformFolder(folder) };
  } catch (error) {
    log.error("Media action failed", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to create folder",
    };
  }
}

