/**
 * Delete a folder (moves contents to parent or root)
 */
export async function deleteFolder(
  folderId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const validFolderId = z.string().uuid().parse(folderId);
    const { supabase, tenantId } = await getAuthenticatedTenant();

    // Get folder to find parent
    const { data: folder, error: fetchError } = await supabase
      .from("media_folders")
      .select("parent_folder_id")
      .eq("id", validFolderId)
      .eq("tenant_id", tenantId)
      .single();

    if (fetchError || !folder) {
      return { success: false, error: "Folder not found" };
    }

    // Move assets to parent folder (or root)
    await supabase
      .from("media_assets")
      .update({ folder_id: folder.parent_folder_id })
      .eq("folder_id", validFolderId)
      .eq("tenant_id", tenantId);

    // Move child folders to parent
    await supabase
      .from("media_folders")
      .update({ parent_folder_id: folder.parent_folder_id })
      .eq("parent_folder_id", validFolderId)
      .eq("tenant_id", tenantId);

    // Delete the folder
    const { error } = await supabase
      .from("media_folders")
      .delete()
      .eq("id", validFolderId)
      .eq("tenant_id", tenantId);

    if (error) {
      return { success: false, error: error.message };
    }

    revalidatePath("/dashboard/media");
    return { success: true };
  } catch (error) {
    log.error("Media action failed", error);
    return {
      success: false,
      error: error instanceof Error ? error.message : "Failed to delete folder",
    };
  }
}

