/**
 * Bulk delete assets
 */
export async function bulkDeleteAssets(
  assetIds: string[]
): Promise<BulkOperationResult> {
  const validIds = z.array(z.string().uuid()).min(1).parse(assetIds);
  const { supabase, tenantId } = await getAuthenticatedTenant();

  const success: string[] = [];
  const failed: Array<{ id: string; error: string }> = [];

  // Batch fetch all assets
  const { data: assets } = await supabase
    .from("media_assets")
    .select("id, blob_url")
    .eq("tenant_id", tenantId)
    .in("id", validIds);

  const assetMap = new Map((assets || []).map(a => [a.id, a]));

  for (const assetId of validIds) {
    try {
      const asset = assetMap.get(assetId);

      if (asset) {
        // Delete from blob storage
        try {
          await del(asset.blob_url);
        } catch (e) {
          log.error("[deleteMediaAsset] blob deletion failed", e);
        }

        // Soft delete in database
        const { error } = await supabase
          .from("media_assets")
          .update({ deleted_at: new Date().toISOString() })
          .eq("id", assetId)
          .eq("tenant_id", tenantId);

        if (error) {
          failed.push({ id: assetId, error: error.message });
        } else {
          success.push(assetId);
        }
      } else {
        failed.push({ id: assetId, error: "Asset not found" });
      }
    } catch (error) {
      log.error("Bulk media delete failed", error, { assetId });
      failed.push({
        id: assetId,
        error: error instanceof Error ? error.message : "Unknown error",
      });
    }
  }

  revalidatePath("/dashboard/media");
  return { success, failed };
}

/**
 * Bulk move assets to folder
 */
export async function bulkMoveAssets(
  assetIds: string[],
  targetFolderId: string | null
): Promise<BulkOperationResult> {
  const validIds = z.array(z.string().uuid()).min(1).parse(assetIds);
  const validTargetId = z.string().uuid().nullable().parse(targetFolderId);
  const { supabase, tenantId } = await getAuthenticatedTenant();

  const { error } = await supabase
    .from("media_assets")
    .update({ folder_id: validTargetId })
    .in("id", validIds)
    .eq("tenant_id", tenantId);

  if (error) {
    return {
      success: [],
      failed: validIds.map((id) => ({ id, error: error.message })),
    };
  }

  revalidatePath("/dashboard/media");
  return { success: validIds, failed: [] };
}

/**
 * Get a presigned URL for direct browser-to-S3 upload.
 * Client uploads directly — no server proxy, no memory pressure.
 */
export async function getUploadUrl(
  filename: string,
  contentType: string,
  folder?: string
): Promise<{ success?: boolean; uploadUrl?: string; key?: string; cdnUrl?: string; error?: string }> {
  const { tenantId } = await getAuthenticatedTenant();

  const { getPresignedUploadUrl, getCdnUrl } = await import("@/infrastructure/aws/s3");
  const result = await getPresignedUploadUrl(
    { tenantId, filename, contentType, folder },
    3600
  );

  if ("error" in result) return { success: false, error: result.error };
  return { uploadUrl: result.url, key: result.key, cdnUrl: getCdnUrl(result.key) };
}

/**
 * Register an uploaded asset in the database after direct S3 upload completes.
 */
export async function registerUploadedAsset(
  key: string,
  cdnUrl: string,
  filename: string,
  contentType: string,
  size: number,
  folderId?: string
): Promise<{ success: boolean; asset?: MediaAsset; error?: string }> {
  const validKey = z.string().min(1).parse(key);
  const validCdnUrl = z.string().url().parse(cdnUrl);
  const validFilename = z.string().min(1).max(255).parse(filename);
  const validContentType = z.string().min(1).parse(contentType);
  const validSize = z.number().int().min(0).parse(size);
  const validFolderId = z.string().uuid().optional().parse(folderId);
  const { supabase, tenantId } = await getAuthenticatedTenant();

  const displayName = validFilename.replace(/\.[^/.]+$/, "");
  const thumbnailUrl = validContentType.startsWith("image/")
    ? `${validCdnUrl}?w=150&h=150&fit=cover`
    : null;

  const { data: asset, error } = await supabase
    .from("media_assets")
    .insert({
      tenant_id: tenantId,
      filename: displayName,
      original_filename: validFilename,
      url: validCdnUrl,
      thumbnail_url: thumbnailUrl,
      mime_type: validContentType,
      size: validSize,
      storage_key: validKey,
      folder_id: validFolderId || null,
    })
    .select()
    .single();

  if (error) return { success: false, error: error.message };

  revalidatePath("/dashboard/media");
  return { success: true, asset: asset as MediaAsset };
}

