function OrderTableRow({
  order,
  isSelected,
  onSelect,
  currency,
}: {
  order: OrderRow;
  isSelected: boolean;
  onSelect: (checked: boolean) => void;
  currency: string;
}) {
  const [isPending, startTransition] = useTransition();
  const router = useRouter();

  const handleStatusChange = (newStatus: string) => {
    startTransition(async () => {
      try {
        const formData = new FormData();
        formData.set("orderId", order.id);
        formData.set("status", newStatus);
        await updateOrderStatus(formData);
        toast.success(`Order ${order.order_number} updated to ${newStatus}`);
        router.refresh();
      } catch (error) {
        toast.error("Failed to update order status");
      }
    });
  };

  const customerInitials = order.customer_name
    ? order.customer_name.split(" ").map((n) => n[0]).join("").toUpperCase()
    : order.customer_email?.charAt(0).toUpperCase() || "?";

  return (
    <TableRow 
      className={cn(
        "group transition-colors duration-150",
        isSelected && "bg-primary/5",
        isPending && "opacity-50"
      )}
    >
      <TableCell className="w-12">
        <Checkbox
          checked={isSelected}
          onCheckedChange={onSelect}
          aria-label={`Select order ${order.order_number}`}
        />
      </TableCell>

      <TableCell>
        <div className="flex items-center gap-2">
          <Link
            href={`/dashboard/orders/${order.id}`}
            className="font-medium text-foreground hover:text-info transition-colors"
          >
            #{order.order_number}
          </Link>
          {(() => {
            const action = needsAction(order);
            if (!action) return null;
            const config: Record<string, { label: string; className: string }> = {
              verify: { label: "Verify", className: "bg-warning/10 text-warning" },
              collect: { label: "Collect", className: "bg-info/10 text-info" },
              fulfill: { label: "Fulfill", className: "bg-primary/10 text-primary" },
            };
            const c = config[action];
            return c ? <Badge className={cn("text-[10px] px-1.5 py-0", c.className)}>{c.label}</Badge> : null;
          })()}
        </div>
        <p className="text-xs text-muted-foreground mt-0.5">
          {formatDistanceToNow(new Date(order.created_at), { addSuffix: true })}
        </p>
      </TableCell>

      <TableCell>
        <div className="flex items-center gap-2">
          <Avatar className="size-8">
