        </div>
      </TableCell>

      <TableCell>
        <div className="flex items-center gap-1.5">
          <Package className="size-3.5 text-muted-foreground" />
          <span className="text-sm text-muted-foreground tabular-nums">
            {order.items_count} {order.items_count === 1 ? "item" : "items"}
