  filters,
  onFilterChange,
  dateRange,
  onDateRangeChange,
  onClearFilters,
  isFilterPending,
  sort,
  sortDir,
  onSort,
  selectedIds,
  isAllSelected,
  onToggleSelection,
  onToggleAll,
