                                                        <SelectItem value="g">g</SelectItem><SelectItem value="kg">kg</SelectItem>
                                                        <SelectItem value="lb">lb</SelectItem><SelectItem value="oz">oz</SelectItem>
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                        </div>
