    try {
        validateId(productId, "Product ID");
        const [product] = await db.select({ images: products.images })
            .from(products)
            .where(and(eq(products.id, productId), eq(products.tenantId, tenantId)))
            .limit(1);

        if (!product) {
            return { success: false, error: "Product not found" };
