"use client";
import { useSaveShortcut } from "@/hooks/use-save-shortcut";
import { useUnsavedChanges, useFormDirty } from "@/hooks/use-unsaved-changes";

import { useState, useTransition, useCallback } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Bell, ShoppingCart, AlertCircle, Settings, AtSign, Mail, Loader2, CheckCircle, Moon, Smartphone, Volume2, VolumeX } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { updateNotificationPreferences, updateQuietHours } from "./actions";
import type { NotificationCategory, NotificationChannel, NotificationFrequency, NotificationPreferenceInput, UserNotificationPreferences } from "@/features/notifications/repositories";

const CATEGORIES: { id: NotificationCategory; label: string; desc: string; icon: LucideIcon; color: string }[] = [
  { id: "orders", label: "Orders", desc: "New orders, status updates, cancellations", icon: ShoppingCart, color: "text-blue-500" },
  { id: "inventory", label: "Inventory", desc: "Low stock alerts and restock reminders", icon: AlertCircle, color: "text-warning" },
  { id: "system", label: "System", desc: "Platform updates, security, and maintenance", icon: Settings, color: "text-muted-foreground" },
  { id: "mentions", label: "Mentions", desc: "When someone mentions you or assigns a task", icon: AtSign, color: "text-violet-500" },
];

const CHANNELS: { id: NotificationChannel; label: string; icon: LucideIcon }[] = [
  { id: "in_app", label: "In-App", icon: Bell },
  { id: "email", label: "Email", icon: Mail },
];

export function NotificationsSettingsClient({ initialPreferences, userRole }: {
  initialPreferences: UserNotificationPreferences; userRole: "owner" | "admin" | "staff";
}) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();

  const buildMap = useCallback(() => {
    const map: Record<string, boolean> = {};
    for (const p of initialPreferences.preferences) map[`${p.category}-${p.channel}`] = p.enabled;
    for (const c of CATEGORIES) for (const ch of CHANNELS) {
      const k = `${c.id}-${ch.id}`;
      if (!(k in map)) map[k] = true;
    }
    return map;
  }, [initialPreferences.preferences]);

  const [prefs, setPrefs] = useState(buildMap);
  const [quietHours, setQuietHours] = useState({
    enabled: initialPreferences.quietHours?.enabled ?? false,
    startTime: initialPreferences.quietHours?.startTime ?? "22:00",
    endTime: initialPreferences.quietHours?.endTime ?? "08:00",
    timezone: initialPreferences.quietHours?.timezone ?? "Asia/Kathmandu",
  });

  const toggle = (cat: NotificationCategory, ch: NotificationChannel) =>
    setPrefs(p => ({ ...p, [`${cat}-${ch}`]: !p[`${cat}-${ch}`] }));

  const toggleAll = (enabled: boolean) => {
    const map: Record<string, boolean> = {};
    for (const c of CATEGORIES) for (const ch of CHANNELS) map[`${c.id}-${ch.id}`] = enabled;
    setPrefs(map);
  };

  const { isDirty: prefsDirty } = useFormDirty(prefs, buildMap());
  const { isDirty: quietDirty } = useFormDirty(quietHours, {
    enabled: initialPreferences.quietHours?.enabled ?? false,
    startTime: initialPreferences.quietHours?.startTime ?? "22:00",
    endTime: initialPreferences.quietHours?.endTime ?? "08:00",
    timezone: initialPreferences.quietHours?.timezone ?? "Asia/Kathmandu",
  });
  const isDirty = prefsDirty || quietDirty;
  useUnsavedChanges(isDirty);

  const handleSave = () => startTransition(async () => {
    const inputs: NotificationPreferenceInput[] = [];
    for (const c of CATEGORIES) for (const ch of CHANNELS) {
      inputs.push({ category: c.id, channel: ch.id, enabled: prefs[`${c.id}-${ch.id}`] ?? true, frequency: "realtime" as NotificationFrequency });
    }
    const [prefRes, quietRes] = await Promise.all([
      updateNotificationPreferences(inputs),
      updateQuietHours(quietHours),
    ]);
    const err = prefRes.error || quietRes.error;
    if (err) { toast.error(err); return; }
    toast.success("Notification preferences saved");
    router.refresh();
  });

  const enabledCount = Object.values(prefs).filter(Boolean).length;
  const totalCount = CATEGORIES.length * CHANNELS.length;
  const allEnabled = enabledCount === totalCount;
  const noneEnabled = enabledCount === 0;

  useSaveShortcut(handleSave);

  return (
    <div className="max-w-2xl space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold tracking-tight">Notifications</h1>
          <p className="text-xs text-muted-foreground">
            {enabledCount} of {totalCount} enabled
            {quietHours.enabled && <> · Quiet hours active</>}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isDirty && <span className="text-[10px] text-muted-foreground">Unsaved changes</span>}
          <Button onClick={handleSave} disabled={isPending || !isDirty} size="sm">
            {isPending ? <Loader2 className="size-3.5 animate-spin" /> : <CheckCircle className="size-3.5" />}
            {isPending ? "Saving…" : "Save"}
          </Button>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => toggleAll(true)} disabled={allEnabled} className="text-xs">
          <Volume2 className="size-3.5" /> Enable All
        </Button>
        <Button variant="outline" size="sm" onClick={() => toggleAll(false)} disabled={noneEnabled} className="text-xs">
          <VolumeX className="size-3.5" /> Mute All
        </Button>
      </div>

      {/* Notification Grid */}
      <div>
        <div className="flex items-center gap-2 mb-3">
          <h2 className="text-sm font-medium flex-1">Channels</h2>
          {CHANNELS.map(ch => (
            <div key={ch.id} className="w-16 text-center">
              <div className="flex items-center justify-center gap-1 text-[10px] text-muted-foreground">
                <ch.icon className="size-3.5" />
                {ch.label}
              </div>
            </div>
          ))}
        </div>
        <div className="rounded-lg border divide-y">
          {CATEGORIES.map(cat => {
            const catEnabled = CHANNELS.some(ch => prefs[`${cat.id}-${ch.id}`]);
            return (
              <div key={cat.id} className="flex items-center gap-3 p-4">
                <div className="size-8 rounded-lg bg-muted flex items-center justify-center shrink-0">
                  <cat.icon className={`size-4 ${cat.color}`} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium">{cat.label}</p>
                    {!catEnabled && <span className="text-[10px] text-muted-foreground/50">Muted</span>}
                  </div>
                  <p className="text-xs text-muted-foreground">{cat.desc}</p>
                </div>
                {CHANNELS.map(ch => (
                  <div key={ch.id} className="w-16 flex justify-center shrink-0">
                    <Switch
                      checked={prefs[`${cat.id}-${ch.id}`] ?? true}
                      onCheckedChange={() => toggle(cat.id, ch.id)}
                    />
                  </div>
                ))}
              </div>
            );
          })}
        </div>
      </div>

      {/* Quiet Hours */}
      <div>
        <h2 className="text-sm font-medium mb-3">Quiet Hours</h2>
        <div className="rounded-lg border divide-y">
          <div className="p-4 flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="size-8 rounded-lg bg-muted flex items-center justify-center shrink-0">
                <Moon className="size-4 text-muted-foreground" />
              </div>
              <div className="space-y-0.5">
                <p className="text-sm font-medium">Pause Notifications</p>
                <p className="text-xs text-muted-foreground">
                  {quietHours.enabled
                    ? `${quietHours.startTime} – ${quietHours.endTime} (${quietHours.timezone.split("/").pop()})`
                    : "Hold non-urgent notifications during specific hours"}
                </p>
              </div>
            </div>
            <Switch checked={quietHours.enabled} onCheckedChange={v => setQuietHours(p => ({ ...p, enabled: v }))} />
          </div>
          {quietHours.enabled && (
            <div className="p-4 flex flex-wrap items-center gap-3">
              <div className="space-y-1.5">
                <Label className="text-xs">From</Label>
                <Select value={quietHours.startTime} onValueChange={v => setQuietHours(p => ({ ...p, startTime: v }))}>
                  <SelectTrigger className="w-24"><SelectValue /></SelectTrigger>
                  <SelectContent>{Array.from({ length: 24 }, (_, i) => { const h = `${String(i).padStart(2, "0")}:00`; return <SelectItem key={h} value={h}>{h}</SelectItem>; })}</SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">To</Label>
                <Select value={quietHours.endTime} onValueChange={v => setQuietHours(p => ({ ...p, endTime: v }))}>
                  <SelectTrigger className="w-24"><SelectValue /></SelectTrigger>
                  <SelectContent>{Array.from({ length: 24 }, (_, i) => { const h = `${String(i).padStart(2, "0")}:00`; return <SelectItem key={h} value={h}>{h}</SelectItem>; })}</SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">Timezone</Label>
                <Select value={quietHours.timezone} onValueChange={v => setQuietHours(p => ({ ...p, timezone: v }))}>
                  <SelectTrigger className="w-44"><SelectValue /></SelectTrigger>
                  <SelectContent>
                    {[["Asia/Kathmandu", "Kathmandu (NPT)"], ["Asia/Kolkata", "India (IST)"], ["UTC", "UTC"], ["America/New_York", "Eastern (ET)"], ["Europe/London", "London (GMT)"]].map(([v, l]) => (
                      <SelectItem key={v} value={v}>{l}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Mobile Push (future) */}
      <div>
        <h2 className="text-sm font-medium mb-3">Mobile</h2>
        <div className="rounded-lg border p-4 flex items-center gap-3">
          <div className="size-8 rounded-lg bg-muted flex items-center justify-center shrink-0">
            <Smartphone className="size-4 text-muted-foreground" />
          </div>
          <div className="flex-1">
            <p className="text-sm font-medium">Push Notifications</p>
            <p className="text-xs text-muted-foreground">Get notified on your phone when orders come in</p>
          </div>
          <span className="text-[10px] font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-full">Coming soon</span>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useSaveShortcut } from "@/hooks/use-save-shortcut";
import { useUnsavedChanges } from "@/hooks/use-unsaved-changes";

import { useState, useTransition } from "react";
import { toast } from "sonner";
import Image from "next/image";
import { Banknote, Building2, CheckCircle, Loader2, ExternalLink, Eye, EyeOff } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/shared/utils";
import { type PaymentSettings, updatePaymentSettings } from "./actions";
import { HelpTooltip } from "@/components/dashboard";

// ─── Logos ────────────────────────────────────────────────
const ESEWA_LOGO = "https://cdn.esewa.com.np/ui/images/esewa_og.png";
const KHALTI_LOGO = "https://upload.wikimedia.org/wikipedia/commons/e/ee/Khalti_Digital_Wallet_Logo.png.jpg";

// ─── Secret Input ─────────────────────────────────────────
function SecretInput({ value, onChange, placeholder, id }: { value: string; onChange: (v: string) => void; placeholder: string; id: string }) {
  const [show, setShow] = useState(false);

  return (
    <div className="relative">
      <Input id={id} type={show ? "text" : "password"} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} className="pr-9" />
      <button type="button" onClick={() => setShow(!show)} className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
        {show ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}
      </button>
    </div>
  );
}

// ─── Payment Method Row ───────────────────────────────────
function MethodHeader({ icon, name, description, active, onToggle, badge }: {
  icon: React.ReactNode; name: string; description: string; active: boolean; onToggle: (v: boolean) => void; badge?: string;
}) {
  return (
    <div className="flex items-center gap-3 p-4">
      <div className="size-10 rounded-lg border bg-background flex items-center justify-center shrink-0 overflow-hidden">
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <p className="text-sm font-medium">{name}</p>
          {badge && <Badge className="text-[10px] px-1.5 py-0 bg-muted text-muted-foreground">{badge}</Badge>}
          <Badge className={cn("text-[10px] px-1.5 py-0", active ? "bg-success/10 text-success" : "bg-muted text-muted-foreground")}>
            {active ? "Active" : "Inactive"}
          </Badge>
        </div>
        <p className="text-xs text-muted-foreground">{description}</p>
      </div>
      <Switch checked={active} onCheckedChange={onToggle} />
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────
export function PaymentsSettingsClient({ initialSettings, isFreeTier = false }: { initialSettings: PaymentSettings; isFreeTier?: boolean }) {
  const [s, setS] = useState(initialSettings);
  const [isPending, startTransition] = useTransition();
  const set = <K extends keyof PaymentSettings>(k: K, v: PaymentSettings[K]) => setS(prev => ({ ...prev, [k]: v }));
  const hasChanges = JSON.stringify(s) !== JSON.stringify(initialSettings);
  useUnsavedChanges(hasChanges);

  const handleSave = () => {
    // Validate required fields for active methods
    const errors: string[] = [];
    if (s.bankTransfer) {
      if (!s.bankName.trim()) errors.push("Bank name is required when bank transfer is enabled");
      if (!s.accountNumber.trim()) errors.push("Account number is required when bank transfer is enabled");
    }
    if (s.esewa && !s.esewamerchantCode.trim()) errors.push("Merchant code is required when eSewa is enabled");
    if (s.khalti && !s.khaltiSecretKey.trim()) errors.push("Secret key is required when Khalti is enabled");
    if (errors.length) {
      errors.forEach(e => toast.error(e));
      return;
    }
    startTransition(async () => {
      const result = await updatePaymentSettings(s);
      result.success ? toast.success("Payment settings saved") : toast.error(result.error ?? "Failed to save");
    });
  };

  const activeCount = [s.cashOnDelivery, s.bankTransfer, s.esewa, s.khalti].filter(Boolean).length;

  useSaveShortcut(handleSave);
  return (
    <div className="max-w-2xl space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold tracking-tight">Payments</h1>
          <p className="text-xs text-muted-foreground">Configure payment providers and methods</p>
          <p className="text-xs text-muted-foreground">
            {activeCount} payment method{activeCount !== 1 ? "s" : ""} active
          </p>
        </div>
        <Button onClick={handleSave} disabled={isPending || !hasChanges} size="sm">
          {isPending ? <Loader2 className="size-3.5 animate-spin" /> : <CheckCircle className="size-3.5" />}
          {isPending ? "Saving…" : "Save"}
        </Button>
      </div>

      <div className="rounded-lg border divide-y">
        {/* COD */}
        <MethodHeader
          icon={<Banknote className="size-5 text-success" />}
          name="Cash on Delivery"
          description="Customers pay when they receive their order"
          active={s.cashOnDelivery}
          onToggle={v => set("cashOnDelivery", v)}
          badge="Recommended"
        />

        {/* Bank Transfer, eSewa, Khalti — paid plans only */}
        {!isFreeTier && (<>
        <div>
          <MethodHeader
            icon={<Building2 className="size-5 text-info" />}
            name="Bank Transfer"
            description="Customers transfer directly to your bank account"
            active={s.bankTransfer}
            onToggle={v => set("bankTransfer", v)}
          />
          {s.bankTransfer && (
            <div className="px-4 pb-4 pt-0 ml-[52px] space-y-3">
              <div className="grid gap-3 sm:grid-cols-2">
                <div className="space-y-1.5">
                  <Label className="text-xs">Bank Name</Label>
                  <Input value={s.bankName} onChange={e => set("bankName", e.target.value)} placeholder="e.g. Nepal Bank Ltd" />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs">Account Holder</Label>
                  <Input value={s.accountHolderName} onChange={e => set("accountHolderName", e.target.value)} placeholder="Full name on account" />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs">Account Number <HelpTooltip content="Your bank account number. Customers will transfer payments to this account." /></Label>
                  <Input value={s.accountNumber} onChange={e => set("accountNumber", e.target.value)} placeholder="Account number" />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs">Branch</Label>
                  <Input value={s.branch} onChange={e => set("branch", e.target.value)} placeholder="Branch name" />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* eSewa */}
        <div>
          <MethodHeader
            icon={<Image src={ESEWA_LOGO} alt="eSewa" width={20} height={20} className="rounded" unoptimized />}
            name="eSewa"
            description="Nepal's leading digital wallet"
            active={s.esewa}
            onToggle={v => set("esewa", v)}
          />
          {s.esewa && (
            <div className="px-4 pb-4 pt-0 ml-[52px] space-y-3">
              <div className="grid gap-3 sm:grid-cols-2">
                <div className="space-y-1.5">
                  <Label className="text-xs">Merchant Code <HelpTooltip content="Your unique eSewa merchant code. Find it at developer.esewa.com.np after signing up as a merchant." /></Label>
                  <Input value={s.esewamerchantCode} onChange={e => set("esewamerchantCode", e.target.value)} placeholder="e.g. EPAYTEST" />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs">Secret Key <HelpTooltip content="Your eSewa API secret key. Keep this private — never share it publicly." /></Label>
                  <SecretInput id="esewaSecret" value={s.esewaSecret} onChange={v => set("esewaSecret", v)} placeholder="Your eSewa secret key" />
                </div>
              </div>
              <p className="text-xs text-muted-foreground">
                Get credentials from <a href="https://developer.esewa.com.np" target="_blank" rel="noopener noreferrer" className="text-info hover:underline">eSewa Developer Portal <ExternalLink className="size-3" /></a>
              </p>
            </div>
          )}
        </div>

        {/* Khalti */}
        <div>
          <MethodHeader
            icon={<Image src={KHALTI_LOGO} alt="Khalti" width={20} height={20} className="rounded" unoptimized />}
            name="Khalti"
            description="Nepal's unified payment platform"
            active={s.khalti}
            onToggle={v => set("khalti", v)}
          />
          {s.khalti && (
            <div className="px-4 pb-4 pt-0 ml-[52px] space-y-3">
              <div className="space-y-1.5">
                <Label className="text-xs">Secret Key <HelpTooltip content="Your Khalti API secret key from the merchant dashboard at khalti.com." /></Label>
                <SecretInput id="khaltiSecret" value={s.khaltiSecretKey} onChange={v => set("khaltiSecretKey", v)} placeholder="Your Khalti secret key" />
              </div>
              <p className="text-xs text-muted-foreground">
                Get credentials from <a href="https://admin.khalti.com" target="_blank" rel="noopener noreferrer" className="text-info hover:underline">Khalti Merchant Portal <ExternalLink className="size-3" /></a>
              </p>
            </div>
          )}
        </div>
        </>)}
      </div>

      <p className="text-[10px] text-muted-foreground text-center">
        Payment credentials are encrypted at rest. Test mode available for eSewa and Khalti.
      </p>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Plus, Trash2, MoreHorizontal, MapPin, Clock, Package, Edit, Loader2, CheckCircle, Truck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { formatCurrency } from "@/shared/utils";
import { toast } from "sonner";
import { ZoneDialog, RateDialog } from "./_components/helpers";
import { createShippingZone, updateShippingZone, deleteShippingZone, createShippingRate, updateShippingRate, deleteShippingRate } from "./actions";

interface ShippingRate {
  id: string; name: string; price: number; min_days: number; max_days: number;
  condition_type?: "weight" | "price" | "none"; condition_min?: number; condition_max?: number;
}

interface ShippingZone {
  id: string; name: string; regions: string[]; rates: ShippingRate[];
}

interface ShippingData {
  zones: ShippingZone[];
  freeShippingThreshold: number | null;
  defaultHandlingTime: number;
  carriers: unknown[];
  packages: unknown[];
}

export function ShippingSettingsClient({ data, currency }: { data: ShippingData; currency: string }) {
  const [zones, setZones] = useState(data.zones);
  const [freeShipping, setFreeShipping] = useState(!!data.freeShippingThreshold);
  const [threshold, setThreshold] = useState(data.freeShippingThreshold?.toString() || "2500");
  const [handlingTime, setHandlingTime] = useState(data.defaultHandlingTime.toString());
  const [isPending, startTransition] = useTransition();
  const router = useRouter();

  const [zoneDialogOpen, setZoneDialogOpen] = useState(false);
  const [selectedZone, setSelectedZone] = useState<ShippingZone | null>(null);
  const [rateDialogOpen, setRateDialogOpen] = useState(false);
  const [selectedRate, setSelectedRate] = useState<ShippingRate | null>(null);
  const [selectedZoneForRate, setSelectedZoneForRate] = useState<string | null>(null);

  const handleSaveZone = (zoneData: Partial<ShippingZone>) => {
    startTransition(async () => {
      const fd = new FormData();
      fd.set("name", zoneData.name || "");
      fd.set("description", "");
      fd.set("isActive", "true");
      if (selectedZone) {
        fd.set("zoneId", selectedZone.id);
        const res = await updateShippingZone(fd);
        if (res.error) { toast.error(res.error); return; }
        toast.success("Zone updated");
      } else {
        const res = await createShippingZone(fd);
        if (res.error) { toast.error(res.error); return; }
        toast.success("Zone created");
      }
      setSelectedZone(null);
      router.refresh();
    });
  };

  const handleSaveRate = (rateData: Partial<ShippingRate>) => {
    if (!selectedZoneForRate) return;
    startTransition(async () => {
      const fd = new FormData();
      fd.set("name", rateData.name || "");
      fd.set("price", String(rateData.price || 0));
      fd.set("isActive", "true");
      fd.set("position", "0");
      if (selectedRate) {
        fd.set("rateId", selectedRate.id);
        const res = await updateShippingRate(fd);
        if (res.error) { toast.error(res.error); return; }
        toast.success("Rate updated");
      } else {
        fd.set("zoneId", selectedZoneForRate);
        const res = await createShippingRate(fd);
        if (res.error) { toast.error(res.error); return; }
        toast.success("Rate created");
      }
      setSelectedRate(null);
      setSelectedZoneForRate(null);
      router.refresh();
    });
  };

  const totalRates = zones.reduce((sum, z) => sum + z.rates.length, 0);

  return (
    <div className="max-w-2xl space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold tracking-tight">Shipping</h1>
          <p className="text-xs text-muted-foreground">Manage shipping zones and delivery rates</p>
          <p className="text-xs text-muted-foreground">{zones.length} zone{zones.length !== 1 ? "s" : ""} · {totalRates} rate{totalRates !== 1 ? "s" : ""}</p>
        </div>
        <Button onClick={() => { setSelectedZone(null); setZoneDialogOpen(true); }} size="sm">
          <Plus className="size-3.5" />
          Add Zone
        </Button>
      </div>

      {/* General Settings */}
      <div>
        <h2 className="text-sm font-medium mb-3">General</h2>
        <div className="rounded-lg border divide-y">
          <div className="p-4 flex items-center justify-between gap-4">
            <div className="space-y-0.5">
              <p className="text-sm font-medium">Free Shipping Threshold</p>
              <p className="text-xs text-muted-foreground">Offer free shipping on orders above this amount</p>
            </div>
            <div className="flex items-center gap-2">
              {freeShipping && (
                <Input type="number" min={0} value={threshold} onChange={e => setThreshold(e.target.value)} className="w-28 text-right tabular-nums" />
              )}
              <Switch checked={freeShipping} onCheckedChange={setFreeShipping} />
            </div>
          </div>
          <div className="p-4 flex items-center justify-between gap-4">
            <div className="space-y-0.5">
              <p className="text-sm font-medium">Handling Time</p>
              <p className="text-xs text-muted-foreground">Days to prepare an order before shipping</p>
            </div>
            <div className="flex items-center gap-1.5">
              <Input type="number" min={0} max={14} value={handlingTime} onChange={e => setHandlingTime(e.target.value)} className="w-16 text-right tabular-nums" />
              <span className="text-xs text-muted-foreground">days</span>
            </div>
          </div>
        </div>
      </div>

      {/* Shipping Zones */}
      <div>
        <h2 className="text-sm font-medium mb-3">Zones & Rates</h2>
        {zones.length === 0 ? (
          <div className="rounded-lg border p-10 text-center">
            <div className="mx-auto size-10 rounded-full bg-muted flex items-center justify-center mb-3">
              <Truck className="size-4 text-muted-foreground" />
            </div>
            <p className="text-sm font-medium mb-1">No shipping zones</p>
            <p className="text-xs text-muted-foreground mb-4 max-w-xs mx-auto">Create zones to define delivery areas and set rates for each</p>
            <Button onClick={() => { setSelectedZone(null); setZoneDialogOpen(true); }} size="sm">
              <Plus className="size-3.5" /> Add Zone
            </Button>
          </div>
        ) : (
          <div className="space-y-3">
            {zones.map(zone => (
              <div key={zone.id} className="rounded-lg border">
                {/* Zone header */}
                <div className="p-4 flex items-center gap-3">
                  <div className="size-9 rounded-full bg-muted flex items-center justify-center shrink-0">
                    <MapPin className="size-4 text-muted-foreground" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium">{zone.name}</p>
                    <p className="text-xs text-muted-foreground truncate">{zone.regions.join(", ")}</p>
                  </div>
                  <Badge className="text-[10px] px-1.5 py-0 bg-muted text-muted-foreground">{zone.rates.length} rate{zone.rates.length !== 1 ? "s" : ""}</Badge>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button variant="ghost" size="icon"><MoreHorizontal className="size-3.5" /></Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-40">
                      <DropdownMenuItem onClick={() => { setSelectedZone(zone); setZoneDialogOpen(true); }} className="text-xs gap-2">
                        <Edit className="size-3.5" /> Edit Zone
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => { setSelectedZoneForRate(zone.id); setSelectedRate(null); setRateDialogOpen(true); }} className="text-xs gap-2">
                        <Plus className="size-3.5" /> Add Rate
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem onClick={() => { startTransition(async () => { const res = await deleteShippingZone(zone.id); if (res.error) toast.error(res.error); else { toast.success("Zone deleted"); router.refresh(); } }); }} className="text-xs gap-2 text-destructive focus:text-destructive">
                        <Trash2 className="size-3.5" /> Delete Zone
                      </DropdownMenuItem>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>

                {/* Rates */}
                {zone.rates.length > 0 && (
                  <div className="border-t divide-y">
                    {zone.rates.map(rate => (
                      <div key={rate.id} className="px-4 py-2.5 flex items-center gap-3 ml-[52px]">
                        <Package className="size-3.5 text-muted-foreground shrink-0" />
                        <span className="text-sm flex-1">{rate.name}</span>
                        <span className="text-xs text-muted-foreground flex items-center gap-1">
                          <Clock className="size-3.5" />
                          {rate.min_days === rate.max_days ? `${rate.min_days}d` : `${rate.min_days}-${rate.max_days}d`}
                        </span>
                        <span className="text-sm font-medium tabular-nums w-20 text-right">
                          {rate.price === 0 ? "Free" : formatCurrency(rate.price, currency)}
                        </span>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon-sm"><MoreHorizontal className="size-3.5" /></Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" className="w-32">
                            <DropdownMenuItem onClick={() => { setSelectedZoneForRate(zone.id); setSelectedRate(rate); setRateDialogOpen(true); }} className="text-xs gap-2">
                              <Edit className="size-3.5" /> Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => { startTransition(async () => { const res = await deleteShippingRate(rate.id); if (res.error) toast.error(res.error); else { toast.success("Rate deleted"); router.refresh(); } }); }} className="text-xs gap-2 text-destructive focus:text-destructive">
                              <Trash2 className="size-3.5" /> Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    ))}
                  </div>
                )}

                {/* Add rate shortcut */}
                {zone.rates.length === 0 && (
                  <div className="border-t px-4 py-3 ml-[52px]">
                    <button onClick={() => { setSelectedZoneForRate(zone.id); setSelectedRate(null); setRateDialogOpen(true); }} className="text-xs text-muted-foreground hover:text-foreground transition-colors">
                      + Add a shipping rate
                    </button>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <p className="text-[10px] text-muted-foreground text-center">
        Customers see available shipping options based on their delivery address and your zone configuration.
      </p>

      <ZoneDialog open={zoneDialogOpen} onOpenChange={setZoneDialogOpen} zone={selectedZone} onSave={handleSaveZone} />
      <RateDialog open={rateDialogOpen} onOpenChange={setRateDialogOpen} rate={selectedRate} currency={currency} onSave={handleSaveRate} />
    </div>
  );
}

"use client";
import { useSaveShortcut } from "@/hooks/use-save-shortcut";
import { useUnsavedChanges } from "@/hooks/use-unsaved-changes";

import { useState, useTransition } from "react";
import { toast } from "sonner";
import { Loader2, CheckCircle } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { type TaxSettings, updateTaxSettings } from "./actions";

import { ToggleRow } from "@/components/dashboard/toggle-row";

export function TaxSettingsClient({ initialSettings }: { initialSettings: TaxSettings }) {
  const [s, setS] = useState(initialSettings);
  const [isPending, startTransition] = useTransition();
  const hasChanges = JSON.stringify(s) !== JSON.stringify(initialSettings);
  useUnsavedChanges(hasChanges);
  const set = <K extends keyof TaxSettings>(k: K, v: TaxSettings[K]) => setS(prev => ({ ...prev, [k]: v }));

  const handleSave = () => startTransition(async () => {
    const result = await updateTaxSettings(s);
    result.success ? toast.success("Tax settings saved") : toast.error(result.error ?? "Failed to save");
  });

  useSaveShortcut(handleSave);

  return (
    <div className="max-w-2xl space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-lg font-semibold tracking-tight">Tax</h1>
          <p className="text-xs text-muted-foreground">Configure tax rates and collection</p>
          <p className="text-xs text-muted-foreground">
            {s.defaultRate > 0 ? `${s.taxName || "Tax"} at ${s.defaultRate}%` : "No tax configured"} · Prices {s.priceIncludesTax ? "include" : "exclude"} tax
          </p>
        </div>
        <Button onClick={handleSave} disabled={isPending || !hasChanges} size="sm">
          {isPending ? <Loader2 className="size-3.5 animate-spin" /> : <CheckCircle className="size-3.5" />}
          {isPending ? "Saving…" : "Save"}
        </Button>
      </div>

      {/* Tax Rate */}
      <div>
        <h2 className="text-sm font-medium mb-3">Tax Rate</h2>
        <div className="rounded-lg border">
          <div className="p-4 space-y-3">
            <div className="grid gap-3 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label className="text-xs">Tax Name</Label>
                <Input value={s.taxName} onChange={e => set("taxName", e.target.value)} placeholder="e.g. VAT, GST" />
              </div>
              <div className="space-y-1.5">
                <Label className="text-xs">Default Rate (%)</Label>
                <Input type="number" min={0} max={100} step={0.01} value={s.defaultRate} onChange={e => set("defaultRate", parseFloat(e.target.value) || 0)} className="tabular-nums" />
              </div>
            </div>
            <div className="space-y-1.5">
              <Label className="text-xs">PAN / VAT Registration Number</Label>
              <Input value={s.registrationNumber} onChange={e => set("registrationNumber", e.target.value)} placeholder="e.g. 123456789" />
              <p className="text-[10px] text-muted-foreground">9-digit PAN number. Displayed on invoices and required for VAT billing in Nepal.</p>
            </div>
          </div>
        </div>
      </div>

      {/* Behavior */}
      <div>
        <h2 className="text-sm font-medium mb-3">Behavior</h2>
        <div className="rounded-lg border divide-y">
          <ToggleRow label="Prices Include Tax" description="Product prices already include tax (tax-inclusive pricing)" checked={s.priceIncludesTax} onChange={v => set("priceIncludesTax", v)} badge="Common in Nepal" />
