import type { MetadataRoute } from "next";
import { createClient } from "@/infrastructure/supabase/server";

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "https://indigo.com.np";

  try {
    const supabase = await createClient();

    const { data: tenants } = await supabase
      .from("tenants")
      .select("slug, updated_at")
      .limit(1000);

    if (!tenants?.length) return [{ url: baseUrl, lastModified: new Date(), priority: 1 }];

    const { data: pages } = await supabase
      .from("store_layouts")
      .select("tenant_id, slug, updated_at, is_homepage, tenants!inner(slug)")
      .not("blocks", "is", null)
      .eq("status", "published")
      .limit(5000);

    const tenantMap = new Map(tenants.map((t) => [t.slug, t.updated_at]));

    const entries: MetadataRoute.Sitemap = [
      { url: baseUrl, lastModified: new Date(), changeFrequency: "weekly", priority: 1 },
    ];

    for (const t of tenants) {
      entries.push(
        { url: `${baseUrl}/store/${t.slug}`, lastModified: t.updated_at, changeFrequency: "daily", priority: 1.0 },
        { url: `${baseUrl}/store/${t.slug}/products`, lastModified: t.updated_at, changeFrequency: "daily", priority: 0.7 },
      );
    }

    for (const p of pages ?? []) {
      if (p.is_homepage) continue;
      const tenantSlug = (p.tenants as unknown as { slug: string })?.slug;
      if (!tenantSlug || !p.slug) continue;
      const pageSlug = p.slug.startsWith("/") ? p.slug.slice(1) : p.slug;
      entries.push({
        url: `${baseUrl}/store/${tenantSlug}/${pageSlug}`,
        lastModified: p.updated_at,
        changeFrequency: "weekly",
        priority: 0.8,
      });
    }

    return entries;
  } catch {
    return [{ url: baseUrl, lastModified: new Date(), priority: 1 }];
  }
}

import { createClient } from "@/infrastructure/supabase/server"
import { db } from "@/infrastructure/db"
import { editorProjects } from "@/db/schema/editor-projects"
import { editorPages } from "@/db/schema/editor-pages"
import { tenants } from "@/db/schema/tenants"
import { eq, and, sql } from "drizzle-orm"
import { redirect, notFound } from "next/navigation"
import DOMPurify from "isomorphic-dompurify"
import { loadPublishedStorefront } from "@/features/editor/renderer/load-publication"
import { StorefrontRenderer } from "@/features/editor/renderer/storefront-renderer"

export default async function CatchAllPage({
  params,
}: {
  params: Promise<{ slug: string; catchAll: string[] }>
}) {
  const { slug, catchAll } = await params
  const pageSlug = catchAll[0]
  const path = "/" + catchAll.join("/")

  // Resolve tenant
  const [tenant] = await db.select({ id: tenants.id })
    .from(tenants).where(eq(tenants.slug, slug)).limit(1)
  if (!tenant) notFound()

  const structuredPublication = await loadPublishedStorefront(tenant.id, pageSlug)
  if (structuredPublication) {
    return <StorefrontRenderer document={structuredPublication.page.document} context={structuredPublication.context} mode="live" />
  }

  // Try to resolve as an editor page
  const [project] = await db.select({ id: editorProjects.id })
    .from(editorProjects)
    .where(and(eq(editorProjects.tenantId, tenant.id), eq(editorProjects.published, true)))
    .limit(1)

  if (project) {
    const [page] = await db.select({
      id: editorPages.id,
      publishedHtml: editorPages.publishedHtml,
    }).from(editorPages)
      .where(and(
        eq(editorPages.projectId, project.id),
        eq(editorPages.slug, pageSlug),
        eq(editorPages.published, true),
      ))
      .limit(1)

    if (page?.publishedHtml) {
      // Increment views (fire-and-forget)
      db.update(editorPages)
        .set({ views: sql`COALESCE(${editorPages.views}, 0) + 1` })
        .where(eq(editorPages.id, page.id))
        .then(() => {}).catch(() => {})

      // Extract body content — render inside store layout, not raw <html>
      const bodyMatch = page.publishedHtml.match(/<body[^>]*>([\s\S]*?)<\/body>/i)
      const bodyContent = DOMPurify.sanitize(bodyMatch ? bodyMatch[1] : page.publishedHtml, { ADD_TAGS: ['style'], ADD_ATTR: ['target'] })
      const headMatch = page.publishedHtml.match(/<head[^>]*>([\s\S]*?)<\/head>/i)
      const styles = headMatch ? headMatch[1].match(/<style[^>]*>[\s\S]*?<\/style>/gi) : null
      const headStyles = styles ? styles.map(s => s.replace(/<\/?style[^>]*>/gi, '')).join('\n') : null

      return (
        <>
          {headStyles && <style dangerouslySetInnerHTML={{ __html: headStyles }} />}
          <div dangerouslySetInnerHTML={{ __html: bodyContent }} />
        </>
      )
    }
  }

  // Check for redirects
  const supabase = await createClient()
  const { data: layout } = await supabase
    .from("store_layouts")
    .select("theme_overrides")
    .eq("tenant_id", tenant.id)
    .eq("is_homepage", true)
    .maybeSingle()

  const redirects = (layout?.theme_overrides as Record<string, unknown>)
    ?.redirects as string | undefined

  if (redirects) {
    for (const line of redirects.split("\n")) {
      const parts = line.split("->").map((s) => s.trim())
      if (parts[0] === path && parts[1]) {
        redirect(`/store/${slug}${parts[1]}`)
      }
    }
  }

  notFound()
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string; catchAll: string[] }>
}) {
  const { slug, catchAll } = await params
  const pageSlug = catchAll[0]

  const [tenant] = await db.select({ id: tenants.id, name: tenants.name, description: tenants.description })
    .from(tenants).where(eq(tenants.slug, slug)).limit(1)

  if (!tenant) return { title: "Page Not Found" }

  const structuredPublication = await loadPublishedStorefront(tenant.id, pageSlug)
  if (structuredPublication) {
    const page = structuredPublication.page.document.page
    const title = page.seoTitle || page.name
    const description = page.seoDescription || tenant.description || undefined
    const ogImage = page.ogImage || undefined

    return {
      title,
      description,
      openGraph: {
        title,
        description,
        type: "website" as const,
        ...(ogImage ? { images: [{ url: ogImage }] } : {}),
      },
      twitter: {
        card: "summary_large_image",
        title,
        description,
        ...(ogImage ? { images: [ogImage] } : {}),
      },
    }
  }

  return { title: "Page Not Found" }
}

import { createClient } from "@/infrastructure/supabase/server"
import { notFound, redirect } from "next/navigation"
import Link from "next/link"
