export default function SearchPage() {
  const params = useParams()
  const searchParams = useSearchParams()
  const router = useRouter()
  const slug = params.slug as string

  const [isPending, startTransition] = useTransition()
  const [isLoading, setIsLoading] = useState(true)
  const [products, setProducts] = useState<Product[]>([])
  const [categories, setCategories] = useState<Category[]>([])
  const [tenantId, setTenantId] = useState<string | null>(null)
  const [maxProductPrice, setMaxProductPrice] = useState(1000)
  const [showFilters, setShowFilters] = useState(false)

  // Initialize filters from URL
  const [filters, setFilters] = useState<SearchFilters>({
    query: searchParams.get("q") || "",
    categoryId: searchParams.get("category") || null,
    minPrice: Number(searchParams.get("minPrice")) || 0,
    maxPrice: Number(searchParams.get("maxPrice")) || 0,
    sort: (searchParams.get("sort") as SortOption) || "newest",
  })

  // Fetch tenant and categories on mount
  useEffect(() => {
    async function fetchInitialData() {
      try {
      const supabase = createClient()

      // Fetch tenant
      const { data: tenant } = await supabase
        .from("tenants")
        .select("id")
        .eq("slug", slug)
        .single()

      if (!tenant) return

      setTenantId(tenant.id)

      // Fetch categories for filter
      const { data: cats } = await supabase
        .from("categories")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("name")

      setCategories(cats || [])

      // Get max price for slider
      const { data: priceData } = await supabase
        .from("products")
        .select("price")
        .eq("tenant_id", tenant.id)
        .eq("status", "active")
        .order("price", { ascending: false })
        .limit(1)
        .single()

      if (priceData) {
        const maxPrice = Math.ceil(Number(priceData.price) / 100) * 100
        setMaxProductPrice(maxPrice)
        if (filters.maxPrice === 0) {
          setFilters((prev) => ({ ...prev, maxPrice }))
        }
      }
      } catch (err) {
        console.error("Failed to fetch initial data:", err)
      }
    }

    fetchInitialData()
  }, [slug])

  // Search products when filters change
  const searchProducts = useCallback(async () => {
    if (!tenantId) return

    setIsLoading(true)
    try {
    const supabase = createClient()

    let query = supabase
      .from("products")
      .select("*, category:categories(id, name, slug)")
      .eq("tenant_id", tenantId)
      .eq("status", "active")

    // Apply search query — full-text search with ILIKE fallback for short queries
    if (filters.query.trim()) {
      const q = filters.query.trim().replace(/[%_'"\\,().!|&:*]/g, '')
      if (!q) { /* skip empty after sanitize */ }
      else if (q.length <= 2) {
        query = query.or(
          `name.ilike.%${q}%,description.ilike.%${q}%`
        )
      } else {
        const tsQuery = q.split(/\s+/).filter(Boolean).map((w) => `${w}:*`).join(" & ")
        query = query.textSearch("search_vector", tsQuery)
      }
    }

    // Apply category filter
    if (filters.categoryId) {
      query = query.eq("category_id", filters.categoryId)
    }

    // Apply price range
    if (filters.minPrice > 0) {
      query = query.gte("price", filters.minPrice)
    }
    if (filters.maxPrice > 0 && filters.maxPrice < maxProductPrice) {
      query = query.lte("price", filters.maxPrice)
    }

    // Apply sorting
    switch (filters.sort) {
      case "newest":
        query = query.order("created_at", { ascending: false })
        break
      case "oldest":
        query = query.order("created_at", { ascending: true })
        break
      case "price-asc":
        query = query.order("price", { ascending: true })
        break
      case "price-desc":
        query = query.order("price", { ascending: false })
        break
      case "name-asc":
        query = query.order("name", { ascending: true })
        break
      case "name-desc":
        query = query.order("name", { ascending: false })
        break
    }

    const { data } = await query

    setProducts(data || [])
    } catch (err) {
      console.error("Search failed:", err)
    } finally {
      setIsLoading(false)
    }
  }, [tenantId, filters, maxProductPrice])

  // Trigger search when filters or tenantId changes
  useEffect(() => {
    if (tenantId) {
      searchProducts()
    }
  }, [tenantId, searchProducts])

  // Update URL when filters change
  const updateURL = useCallback(
    (newFilters: SearchFilters) => {
      startTransition(() => {
        const params = new URLSearchParams()
        if (newFilters.query) params.set("q", newFilters.query)
        if (newFilters.categoryId) params.set("category", newFilters.categoryId)
        if (newFilters.minPrice > 0) params.set("minPrice", String(newFilters.minPrice))
        if (newFilters.maxPrice > 0 && newFilters.maxPrice < maxProductPrice) {
          params.set("maxPrice", String(newFilters.maxPrice))
        }
        if (newFilters.sort !== "newest") params.set("sort", newFilters.sort)

        const queryString = params.toString()
        router.push(`/store/${slug}/search${queryString ? `?${queryString}` : ""}`, {
          scroll: false,
        })
      })
    },
    [router, slug, maxProductPrice]
  )

  const handleFilterChange = (updates: Partial<SearchFilters>) => {
    const newFilters = { ...filters, ...updates }
    setFilters(newFilters)
    updateURL(newFilters)
  }

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    updateURL(filters)
  }

  const clearFilters = () => {
    const defaultFilters: SearchFilters = {
      query: "",
      categoryId: null,
      minPrice: 0,
      maxPrice: maxProductPrice,
      sort: "newest",
    }
    setFilters(defaultFilters)
    router.push(`/store/${slug}/search`)
  }

  const hasActiveFilters =
    filters.query ||
    filters.categoryId ||
    filters.minPrice > 0 ||
    (filters.maxPrice > 0 && filters.maxPrice < maxProductPrice) ||
    filters.sort !== "newest"

  return (
    <div className="py-12">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h1 className="text-3xl font-semibold">Search Products</h1>
            {filters.query && (
              <p className="mt-1 text-muted-foreground">
                {isLoading ? "Searching..." : `${products.length} results for "${filters.query}"`}
              </p>
            )}
          </div>

          {/* Mobile filter toggle */}
          <Button
            variant="outline"
            className="sm:hidden"
            onClick={() => setShowFilters(!showFilters)}
          >
            <Filter className="size-4" />
            Filters
          </Button>
        </div>

        <div className="mt-8 grid gap-8 lg:grid-cols-4">
          {/* Filters Sidebar */}
          <aside
            className={`space-y-6 ${showFilters ? "block" : "hidden"} lg:block`}
          >
            {/* Search Input */}
            <form onSubmit={handleSearchSubmit}>
              <Label htmlFor="search" className="text-sm font-medium">
                Search
              </Label>
              <div className="relative mt-2">
                <Search
                  className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground"
                />
                <Input
                  id="search"
                  type="search"
                  placeholder="Search products..."
                  value={filters.query}
                  onChange={(e) => setFilters({ ...filters, query: e.target.value })}
                  className="pl-9"
                />
              </div>
            </form>

            {/* Category Filter */}
            <div>
              <Label className="text-sm font-medium">Category</Label>
              <Select
                value={filters.categoryId || "all"}
                onValueChange={(value) =>
                  handleFilterChange({ categoryId: value === "all" ? null : value })
                }
              >
                <SelectTrigger className="mt-2 w-full">
                  <SelectValue placeholder="All categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All categories</SelectItem>
                  {categories.map((category) => (
                    <SelectItem key={category.id} value={category.id}>
                      {category.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Price Range */}
            <div>
              <Label className="text-sm font-medium">Price Range</Label>
              <div className="mt-4 px-2">
                <Slider
                  value={[filters.minPrice, filters.maxPrice || maxProductPrice]}
                  min={0}
                  max={maxProductPrice}
                  step={10}
                  onValueChange={([min, max]) =>
                    setFilters({ ...filters, minPrice: min, maxPrice: max })
                  }
                  onValueCommit={([min, max]) =>
                    handleFilterChange({ minPrice: min, maxPrice: max })
                  }
                />
              </div>
              <div className="mt-2 flex items-center justify-between text-sm text-muted-foreground">
                <span>${filters.minPrice}</span>
                <span>${filters.maxPrice || maxProductPrice}</span>
              </div>
            </div>

            {/* Sort */}
            <div>
              <Label className="text-sm font-medium">Sort By</Label>
              <Select
                value={filters.sort}
                onValueChange={(value) => handleFilterChange({ sort: value as SortOption })}
              >
                <SelectTrigger className="mt-2 w-full">
                  <ArrowDownAZ className="size-4" />
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="newest">Newest First</SelectItem>
                  <SelectItem value="oldest">Oldest First</SelectItem>
                  <SelectItem value="price-asc">Price: Low to High</SelectItem>
                  <SelectItem value="price-desc">Price: High to Low</SelectItem>
                  <SelectItem value="name-asc">Name: A to Z</SelectItem>
                  <SelectItem value="name-desc">Name: Z to A</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Clear Filters */}
            {hasActiveFilters && (
              <Button variant="outline" className="w-full" onClick={clearFilters}>
                <X className="size-4" />
                Clear Filters
              </Button>
            )}
          </aside>

          {/* Product Grid */}
          <div className="lg:col-span-3">
            {isLoading ? (
              <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {Array.from({ length: 6 }).map((_, i) => (
                  <ProductCardSkeleton key={i} />
                ))}
              </div>
            ) : products.length > 0 ? (
              <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {products.map((product) => (
                  <ProductCard key={product.id} product={product} storeSlug={slug} />
                ))}
              </div>
            ) : (
              <NoResults
                title="No products found"
                message={
                  filters.query
                    ? `No products match "${filters.query}". Try adjusting your search or filters.`
                    : "Try adjusting your filters to find what you're looking for."
                }
                onClear={hasActiveFilters ? clearFilters : undefined}
              />
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

"use client";

import { useState, useTransition } from "react";
import { useParams } from "next/navigation";
import { createClient } from "@/infrastructure/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Package, Truck, CheckCircle, Clock, ExternalLink } from "lucide-react";
import { cn } from "@/shared/utils";

interface OrderResult {
  id: string;
  order_number: string;
  status: string;
  total: string;
  currency: string;
  created_at: string;
  items: { id: string; product_name: string; quantity: number; unit_price: string }[];
  fulfillments: { id: string; status: string; tracking_number: string | null; tracking_url: string | null; shipped_at: string | null }[];
}

const steps = [
  { key: "confirmed", label: "Confirmed", icon: CheckCircle },
  { key: "processing", label: "Processing", icon: Package },
  { key: "shipped", label: "Shipped", icon: Truck },
  { key: "delivered", label: "Delivered", icon: CheckCircle },
] as const;

function getStepIndex(status: string, fulfillments: OrderResult["fulfillments"]): number {
  if (fulfillments.some((f) => f.status === "delivered")) return 3;
  if (fulfillments.some((f) => f.status === "shipped")) return 2;
  if (status === "processing" || status === "confirmed") return 1;
  return 0;
}

export default function TrackPage() {
  const { slug } = useParams<{ slug: string }>();
  const [order, setOrder] = useState<OrderResult | null>(null);
  const [error, setError] = useState("");
  const [isPending, startTransition] = useTransition();

  const handleSubmit = (formData: FormData) => {
    const orderNumber = formData.get("orderNumber") as string;
    const email = formData.get("email") as string;
    if (!orderNumber || !email) { setError("Both fields are required"); return; }

    startTransition(async () => {
      setError("");
      const supabase = createClient();
      const { data: tenant } = await supabase.from("tenants").select("id").eq("slug", slug).single();
      if (!tenant) { setError("Store not found"); return; }

      const { data } = await supabase
        .from("orders")
        .select("id, order_number, status, total, currency, created_at, customer_email, order_items(id, product_name, quantity, unit_price), fulfillments(id, status, tracking_number, tracking_url, shipped_at)")
        .eq("tenant_id", tenant.id)
        .eq("order_number", orderNumber)
        .single();

      if (!data || data.customer_email?.toLowerCase() !== email.toLowerCase()) {
        setError("Order not found. Check your order number and email.");
        return;
      }
      setOrder({
        id: data.id,
        order_number: data.order_number,
        status: data.status,
        total: data.total,
        currency: data.currency || "USD",
        created_at: data.created_at,
        items: data.order_items ?? [],
        fulfillments: data.fulfillments ?? [],
      });
    });
  };

  return (
    <div className="min-h-screen bg-background">
      <div className="mx-auto max-w-xl px-4 py-16">
        <h1 className="text-xl font-semibold text-center mb-8">Track Your Order</h1>

        {!order ? (
          <Card>
            <CardContent className="p-6">
              <form action={handleSubmit} className="space-y-4">
                {error && <p className="text-xs text-destructive">{error}</p>}
                <div>
                  <label className="text-xs font-medium mb-1 block">Order Number</label>
                  <Input name="orderNumber" placeholder="e.g. ORD-1234" required />
                </div>
                <div>
                  <label className="text-xs font-medium mb-1 block">Email Address</label>
                  <Input name="email" type="email" placeholder="The email used for the order" required />
                </div>
                <Button type="submit" className="w-full" disabled={isPending}>
                  {isPending ? "Looking up..." : "Track Order"}
                </Button>
              </form>
            </CardContent>
          </Card>
        ) : (
          <div className="space-y-6">
            <Card>
              <CardContent className="p-6">
                <div className="flex justify-between items-start mb-6">
                  <div>
                    <p className="text-sm font-semibold">{order.order_number}</p>
                    <p className="text-xs text-muted-foreground">Placed {new Date(order.created_at).toLocaleDateString()}</p>
                  </div>
                  <p className="text-sm font-semibold">{new Intl.NumberFormat("en-US", { style: "currency", currency: order.currency }).format(parseFloat(order.total))}</p>
                </div>

                {/* Timeline */}
                <div className="flex items-center justify-between mb-6">
                  {steps.map((step, i) => {
                    const current = getStepIndex(order.status, order.fulfillments);
                    const done = i <= current;
                    return (
                      <div key={step.key} className="flex flex-col items-center gap-1 flex-1">
                        <div className={cn("flex items-center justify-center size-8 rounded-full border-2", done ? "border-primary bg-primary text-primary-foreground" : "border-muted-foreground/20 text-muted-foreground/30")}>
                          <step.icon className="size-4" />
                        </div>
                        <span className={cn("text-[10px]", done ? "text-foreground font-medium" : "text-muted-foreground")}>{step.label}</span>
                        {i < steps.length - 1 && <div className={cn("absolute h-0.5 w-full", done ? "bg-primary" : "bg-muted")} style={{ display: "none" }} />}
                      </div>
                    );
                  })}
                </div>

                {/* Tracking */}
                {order.fulfillments.filter((f) => f.tracking_number).map((f) => (
                  <div key={f.id} className="rounded-lg bg-muted p-3 flex items-center justify-between">
                    <div>
                      <p className="text-xs font-medium">Tracking: {f.tracking_number}</p>
                      {f.shipped_at && <p className="text-[10px] text-muted-foreground">Shipped {new Date(f.shipped_at).toLocaleDateString()}</p>}
                    </div>
                    {f.tracking_url && (
                      <a href={f.tracking_url} target="_blank" rel="noopener noreferrer" className="text-xs text-primary flex items-center gap-1 hover:underline">
                        Track <ExternalLink className="size-3" />
                      </a>
                    )}
                  </div>
                ))}
              </CardContent>
            </Card>

            {/* Items */}
            <Card>
              <CardContent className="p-6">
                <h3 className="text-sm font-semibold mb-3">Items</h3>
                {order.items.map((item) => (
                  <div key={item.id} className="flex justify-between py-2 border-b last:border-0 text-sm">
                    <span>{item.product_name} × {item.quantity}</span>
                    <span className="text-muted-foreground">{new Intl.NumberFormat("en-US", { style: "currency", currency: order.currency }).format(parseFloat(item.unit_price) * item.quantity)}</span>
                  </div>
                ))}
              </CardContent>
            </Card>

            <Button variant="outline" className="w-full" onClick={() => setOrder(null)}>Track Another Order</Button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { useParams } from "next/navigation"
import Image from "next/image"
import Link from "next/link"
import { createClient } from "@/infrastructure/supabase/client"
import { useCart } from "@/features/store/cart-provider"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"
import { Price } from "@/components/ui/price"
import {
  Heart,
  ShoppingCart,
  Trash2,
  ImageIcon,
  Loader2,
  ArrowRight,
} from "lucide-react"
import { toast } from "sonner"
import type { Product } from "@/infrastructure/supabase/types"

// Wishlist storage key per store
function getWishlistKey(storeSlug: string) {
  return `wishlist_${storeSlug}`
}

// Get wishlist from localStorage
function getWishlist(storeSlug: string): string[] {
  if (typeof window === "undefined") return []
  try {
    const stored = localStorage.getItem(getWishlistKey(storeSlug))
    return stored ? JSON.parse(stored) : []
  } catch {
    return []
  }
}

// Save wishlist to localStorage
function saveWishlist(storeSlug: string, productIds: string[]) {
  if (typeof window === "undefined") return
  localStorage.setItem(getWishlistKey(storeSlug), JSON.stringify(productIds))
}

// Add to wishlist
export function addToWishlist(storeSlug: string, productId: string) {
  const wishlist = getWishlist(storeSlug)
  if (!wishlist.includes(productId)) {
    saveWishlist(storeSlug, [...wishlist, productId])
    window.dispatchEvent(new CustomEvent("wishlist-updated", { detail: { storeSlug } }))
  }
}

// Remove from wishlist
export function removeFromWishlist(storeSlug: string, productId: string) {
  const wishlist = getWishlist(storeSlug)
  saveWishlist(storeSlug, wishlist.filter((id) => id !== productId))
  window.dispatchEvent(new CustomEvent("wishlist-updated", { detail: { storeSlug } }))
}

// Check if product is in wishlist
export function isInWishlist(storeSlug: string, productId: string): boolean {
  return getWishlist(storeSlug).includes(productId)
}

function WishlistItemSkeleton() {
  return (
    <Card className="overflow-hidden">
      <div className="flex flex-col sm:flex-row">
        <Skeleton className="aspect-square w-full sm:w-40" />
        <div className="flex-1 p-4 space-y-3">
          <Skeleton className="h-5 w-3/4" />
          <Skeleton className="h-4 w-1/2" />
          <div className="flex gap-2 pt-2">
            <Skeleton className="h-9 w-28" />
            <Skeleton className="size-9" />
          </div>
        </div>
      </div>
    </Card>
  )
}

interface WishlistItemProps {
  product: Product
  storeSlug: string
  currency?: string
  onRemove: (productId: string) => void
}

function WishlistItem({ product, storeSlug, currency = "NPR", onRemove }: WishlistItemProps) {
  const { addItem, isPending } = useCart()
  const [isAdding, setIsAdding] = useState(false)
  const [isRemoving, setIsRemoving] = useState(false)

  const productUrl = `/store/${storeSlug}/products/${product.slug}`
  const hasDiscount = product.compare_at_price && product.compare_at_price > product.price

  const handleAddToCart = async () => {
    setIsAdding(true)
    try {
      const images = product.images || []
      await addItem(product.id, 1, {
        name: product.name,
        sku: product.sku || undefined,
        image: images[0]?.url || undefined,
        price: Number(product.price),
        compareAtPrice: product.compare_at_price ? Number(product.compare_at_price) : undefined,
      })
      toast.success(`${product.name} added to cart`)
    } catch {
      toast.error("Failed to add to cart")
    } finally {
      setIsAdding(false)
    }
  }

  const handleRemove = () => {
    setIsRemoving(true)
    onRemove(product.id)
    toast.success(`${product.name} removed from wishlist`)
  }

  return (
    <Card className="group overflow-hidden transition-shadow hover:shadow-md">
      <div className="flex flex-col sm:flex-row">
        {/* Product Image */}
        <Link href={productUrl} className="relative aspect-square w-full sm:w-40 shrink-0">
          <div className="relative h-full w-full overflow-hidden bg-muted">
            {product.images && product.images.length > 0 ? (
              <Image
                src={product.images[0].url || "/placeholder.svg"}
                alt={product.images[0].alt || product.name}
                fill
                sizes="(max-width: 640px) 100vw, 160px"
                className="object-cover transition-transform duration-300 group-hover:scale-105"
              />
            ) : (
              <div className="flex h-full w-full items-center justify-center">
                <ImageIcon className="size-10 text-muted-foreground" />
              </div>
            )}
            {hasDiscount && (
              <span className="absolute left-2 top-2 rounded-full bg-destructive px-2 py-0.5 text-xs font-medium text-destructive-foreground">
                Sale
              </span>
            )}
          </div>
        </Link>

        {/* Product Details */}
        <CardContent className="flex flex-1 flex-col justify-between p-4">
          <div>
            <Link href={productUrl}>
              <h3 className="font-medium hover:text-primary transition-colors">
                {product.name}
              </h3>
            </Link>
            {product.category && (
              <p className="mt-1 text-sm text-muted-foreground">{product.category.name}</p>
            )}
            <div className="mt-2 flex items-center gap-2">
              <Price 
                amount={product.price} 
                currency={currency}
                originalAmount={hasDiscount && product.compare_at_price ? product.compare_at_price : undefined}
              />
            </div>
          </div>

          {/* Actions */}
          <div className="mt-4 flex flex-wrap items-center gap-2">
            <Button

              onClick={handleAddToCart}
              disabled={isAdding || isPending}
            >
              {isAdding ? (
                <Loader2 className="size-4 animate-spin" />
              ) : (
                <ShoppingCart className="size-4" />
              )}
              {isAdding ? "Adding..." : "Add to Cart"}
            </Button>
            <Button
              variant="outline"

              onClick={handleRemove}
              disabled={isRemoving}
              className="text-destructive hover:text-destructive hover:bg-destructive/10"
            >
              <Trash2 className="size-4" />
              <span className="sr-only">Remove from wishlist</span>
            </Button>
            <Button variant="ghost" asChild className="ml-auto">
              <Link href={productUrl}>
                View Details
                <ArrowRight className="ml-1 size-4" />
              </Link>
            </Button>
          </div>
        </CardContent>
      </div>
    </Card>
  )
}

export default function WishlistPage() {
  const params = useParams()
  const slug = params.slug as string

  const [isLoading, setIsLoading] = useState(true)
  const [products, setProducts] = useState<Product[]>([])
  const [wishlistIds, setWishlistIds] = useState<string[]>([])

  // Fetch wishlist products
  const fetchWishlistProducts = useCallback(async () => {
    const ids = getWishlist(slug)
    setWishlistIds(ids)

    if (ids.length === 0) {
      setProducts([])
      setIsLoading(false)
      return
    }

    try {
    const supabase = createClient()

    const { data } = await supabase
      .from("products")
      .select("*, category:categories(id, name, slug)")
      .in("id", ids)
      .eq("status", "active")

    // Maintain wishlist order
    const productMap = new Map((data || []).map((p) => [p.id, p]))
    const orderedProducts = ids
      .map((id) => productMap.get(id))
      .filter((p): p is Product => p !== undefined)

    setProducts(orderedProducts)
    } catch (err) {
      console.error("Failed to fetch wishlist:", err)
    } finally {
      setIsLoading(false)
    }
  }, [slug])

  // Initial fetch
  useEffect(() => {
    fetchWishlistProducts()
  }, [fetchWishlistProducts])

  // Listen for wishlist updates from other components
  useEffect(() => {
    const handleWishlistUpdate = (e: CustomEvent<{ storeSlug: string }>) => {
      if (e.detail.storeSlug === slug) {
        fetchWishlistProducts()
      }
    }

    window.addEventListener("wishlist-updated", handleWishlistUpdate as EventListener)
    return () => {
      window.removeEventListener("wishlist-updated", handleWishlistUpdate as EventListener)
    }
  }, [slug, fetchWishlistProducts])

  const handleRemoveItem = (productId: string) => {
    removeFromWishlist(slug, productId)
    setProducts((prev) => prev.filter((p) => p.id !== productId))
    setWishlistIds((prev) => prev.filter((id) => id !== productId))
  }

  const handleClearWishlist = () => {
    saveWishlist(slug, [])
    setProducts([])
    setWishlistIds([])
    toast.success("Wishlist cleared")
    window.dispatchEvent(new CustomEvent("wishlist-updated", { detail: { storeSlug: slug } }))
  }

  return (
    <div className="py-12">
      <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-semibold">My Wishlist</h1>
            <p className="mt-1 text-muted-foreground">
              {isLoading
                ? "Loading..."
                : products.length === 0
                  ? "No saved items"
                  : `${products.length} saved item${products.length !== 1 ? "s" : ""}`}
            </p>
          </div>
          {products.length > 0 && (
            <Button variant="outline" onClick={handleClearWishlist}>
              Clear All
            </Button>
          )}
        </div>

        {/* Content */}
        <div className="mt-8">
          {isLoading ? (
            <div className="space-y-4">
              {Array.from({ length: 3 }).map((_, i) => (
                <WishlistItemSkeleton key={i} />
              ))}
            </div>
          ) : products.length > 0 ? (
            <div className="space-y-4">
              {products.map((product) => (
                <WishlistItem
                  key={product.id}
                  product={product}
                  storeSlug={slug}
                  onRemove={handleRemoveItem}
                />
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center text-center py-20">
              <div className="rounded-full bg-muted flex items-center justify-center mb-4 size-16">
                <Heart className="w-8 h-8 text-muted-foreground" />
              </div>
              <h3 className="font-semibold text-foreground text-lg">
                Your wishlist is empty
              </h3>
              <p className="text-muted-foreground mt-1 max-w-sm text-base">
                Save items you love by clicking the heart icon on any product.
              </p>
              <div className="flex items-center gap-2 mt-4">
                <Button onClick={() => {
                  window.location.href = `/store/${slug}/products`
                }}>
                  Browse Products
                </Button>
              </div>
            </div>
          )}
        </div>

        {/* Continue Shopping */}
        {products.length > 0 && (
          <div className="mt-8 text-center">
            <Button variant="outline" asChild>
              <Link href={`/store/${slug}/products`}>
                Continue Shopping
                <ArrowRight className="ml-2 size-4" />
              </Link>
            </Button>
          </div>
        )}
      </div>
    </div>
  )
}

