                                <div className="flex items-center gap-2">
                                    <Skeleton className="size-3 rounded-full" />
                                    <Skeleton className="h-4 w-20" />
                                </div>
                                <Skeleton className="h-4 w-16" />
                            </div>
                        ))}
                    </div>
                </div>
            </CardContent>
        </Card>
