import { ChartToolbar } from "./chart-toolbar";
import { ChartExport } from "./chart-export";
import { DrillDownModal } from "./drill-down-modal";
import type {
  ChartDataPoint,
  DrillDownDataPoint,
  ChartType,
  TimeRange,
  ComparisonMode,
  ExportFormat,
  ChartSeries,
} from "./chart-types";

// ============================================================================
// Props
// ============================================================================

interface InteractiveChartProps {
  /** Chart data */
  data: ChartDataPoint[];
  /** Chart title */
  title: string;
  /** Chart description */
  description?: string;
  /** Series configuration */
  series?: ChartSeries[];
  /** Initial chart type */
  chartType?: ChartType;
  /** Chart height */
  height?: number;
  /** Show toolbar */
  showToolbar?: boolean;
  /** Enable fullscreen mode */
  enableFullscreen?: boolean;
  /** Enable zoom controls */
  enableZoom?: boolean;
  /** Enable legend toggle */
  enableLegendToggle?: boolean;
  /** Enable drill-down */
  enableDrillDown?: boolean;
  /** Drill-down data provider */
  getDrillDownData?: (point: DrillDownDataPoint) => DrillDownDataPoint[] | Promise<DrillDownDataPoint[]>;
  /** Time range */
  timeRange?: TimeRange;
  /** Time range change handler */
  onTimeRangeChange?: (range: TimeRange, customFrom?: Date, customTo?: Date) => void;
  /** Comparison mode */
  comparisonMode?: ComparisonMode;
  /** Comparison mode change handler */
  onComparisonModeChange?: (mode: ComparisonMode) => void;
  /** Refresh handler */
  onRefresh?: () => void;
  /** Is refreshing */
  isRefreshing?: boolean;
  /** Click handler */
  onClick?: (point: ChartDataPoint) => void;
  /** Format value for display */
  formatValue?: (value: number) => string;
  /** Loading state */
  isLoading?: boolean;
  /** Additional class names */
  className?: string;
}

// ============================================================================
// Default Config
// ============================================================================

const defaultChartConfig: ChartConfig = {
  value: {
    label: "Value",
    color: "var(--chart-1)",
  },
};

// ============================================================================
// Component
// ============================================================================

export function InteractiveChart({
  data,
  title,
  description,
  series,
  chartType: initialChartType = "area",
  height = 300,
  showToolbar = true,
  enableFullscreen = true,
  enableZoom = true,
  enableLegendToggle = true,
  enableDrillDown = false,
  getDrillDownData,
  timeRange = "30d",
  onTimeRangeChange,
  comparisonMode = "none",
  onComparisonModeChange,
  onRefresh,
  isRefreshing = false,
  onClick,
  formatValue,
  isLoading = false,
  className,
}: InteractiveChartProps) {
  const chartRef = useRef<HTMLDivElement>(null);
  const [isFullscreenOpen, setIsFullscreenOpen] = useState(false);
  const [isDrillDownOpen, setIsDrillDownOpen] = useState(false);
  const [zoomLeft, setZoomLeft] = useState<string | null>(null);
  const [zoomRight, setZoomRight] = useState<string | null>(null);
  const [isZooming, setIsZooming] = useState(false);

  // Use chart interaction hook
  const {
    state,
    zoomIn,
    zoomOut,
    resetZoom,
    toggleSeries,
    setChartType,
    drillDown,
    navigateDown,
    navigateUp,
    navigateToLevel,
  } = useChartInteraction({
    initialChartType,
    initialVisibleSeries: series?.map((s) => s.key) || ["value"],
  });

  // Build chart config from series
  const chartConfig = useMemo<ChartConfig>(() => {
    if (!series || series.length === 0) {
      return defaultChartConfig;
    }
    return series.reduce((config, s) => {
      config[s.key] = {
        label: s.name,
        color: s.color,
      };
      return config;
    }, {} as ChartConfig);
  }, [series]);

  // Transform data for chart
  const chartData = useMemo(() => {
    return data.map((point) => ({
      name: point.label || String(point.x),
      value: point.y,
      ...point,
    }));
  }, [data]);

  // Filter data based on zoom
  const filteredData = useMemo(() => {
    if (state.zoom.scale <= 1) return chartData;
    const startIndex = Math.floor(chartData.length * state.zoom.left);
    const endIndex = Math.ceil(chartData.length * state.zoom.right);
    return chartData.slice(startIndex, endIndex);
  }, [chartData, state.zoom]);

  // Handle chart click - receives data from Recharts event
  const handleChartClick = useCallback(
    (data: unknown) => {
      // Recharts passes the active payload in the event
      const activePayload = (data as { activePayload?: Array<{ payload: ChartDataPoint }> })?.activePayload;
      if (!activePayload || activePayload.length === 0) return;

      const point = activePayload[0].payload;

      if (enableDrillDown && getDrillDownData) {
        const drillDownPoint: DrillDownDataPoint = {
          ...point,
          id: String(point.x),
          level: drillDown.currentLevel,
        };

        Promise.resolve(getDrillDownData(drillDownPoint)).then((childData) => {
          if (childData.length > 0) {
            navigateDown(drillDownPoint, childData);
            setIsDrillDownOpen(true);
          }
        });
      } else if (onClick) {
        onClick(point);
      }
    },
    [enableDrillDown, getDrillDownData, drillDown.currentLevel, navigateDown, onClick]
  );

  // Handle zoom selection
  const handleMouseDown = useCallback(
    (e: { activeLabel?: string }) => {
      if (!enableZoom || !e.activeLabel) return;
      setIsZooming(true);
      setZoomLeft(e.activeLabel);
    },
    [enableZoom]
  );

  const handleMouseMove = useCallback(
    (e: { activeLabel?: string }) => {
      if (!isZooming || !e.activeLabel) return;
      setZoomRight(e.activeLabel);
    },
    [isZooming]
  );

  const handleMouseUp = useCallback(() => {
    if (!isZooming || !zoomLeft || !zoomRight) {
      setIsZooming(false);
      setZoomLeft(null);
      setZoomRight(null);
      return;
    }

    const leftIndex = chartData.findIndex((d) => d.name === zoomLeft);
    const rightIndex = chartData.findIndex((d) => d.name === zoomRight);

    if (leftIndex !== -1 && rightIndex !== -1 && leftIndex !== rightIndex) {
      zoomIn();
    }

    setIsZooming(false);
    setZoomLeft(null);
    setZoomRight(null);
  }, [isZooming, zoomLeft, zoomRight, chartData, zoomIn]);

  // Loading state
  if (isLoading) {
    return (
      <Card className={className}>
        <CardHeader>
          <Skeleton className="h-5 w-40" />
          <Skeleton className="h-4 w-60" />
        </CardHeader>
        <CardContent>
          <Skeleton className="w-full" style={{ height }} />
        </CardContent>
      </Card>
    );
  }

  // Empty state
  if (data.length === 0) {
    return (
      <Card className={className}>
        <CardHeader>
          <CardTitle>{title}</CardTitle>
          {description && <CardDescription>{description}</CardDescription>}
        </CardHeader>
        <CardContent>
          <div
            className="flex flex-col items-center justify-center text-muted-foreground"
            style={{ height }}
          >
            <p>No data available</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  const commonChartProps = {
    data: filteredData,
    margin: { top: 10, right: 10, left: 0, bottom: 0 },
    onMouseDown: handleMouseDown,
    onMouseMove: handleMouseMove,
    onMouseUp: handleMouseUp,
    onClick: handleChartClick,
  };

  const renderChart = (chartHeight: number) => (
    <ChartContainer config={chartConfig} className="w-full" style={{ height: chartHeight }}>
      {state.chartType === "area" ? (
        <AreaChart {...commonChartProps}>
          <defs>
            <linearGradient id="interactiveFill" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="var(--color-value)" stopOpacity={0.3} />
              <stop offset="95%" stopColor="var(--color-value)" stopOpacity={0.05} />
            </linearGradient>
          </defs>
          <CartesianGrid vertical={false} className="stroke-muted" />
          <XAxis
            dataKey="name"
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            className="text-muted-foreground text-xs"
          />
          <YAxis
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            tickFormatter={formatValue}
            className="text-muted-foreground text-xs"
          />
          <ChartTooltip
            content={
              <ChartTooltipContent
                formatter={(value) =>
                  formatValue ? formatValue(value as number) : (value as number).toLocaleString()
                }
              />
            }
          />
          {state.visibleSeries.has("value") && (
            <Area
              dataKey="value"
              type="monotone"
              fill="url(#interactiveFill)"
              stroke="var(--color-value)"
              strokeWidth={2}
              className={cn(enableDrillDown && "cursor-pointer")}
            />
          )}
          {zoomLeft && zoomRight && (
            <ReferenceArea
              x1={zoomLeft}
              x2={zoomRight}
              strokeOpacity={0.3}
              fill="var(--chart-1)"
              fillOpacity={0.1}
            />
          )}
          {enableLegendToggle && <ChartLegend content={<ChartLegendContent />} />}
        </AreaChart>
      ) : state.chartType === "bar" ? (
        <BarChart {...commonChartProps}>
          <CartesianGrid vertical={false} className="stroke-muted" />
          <XAxis
            dataKey="name"
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            className="text-muted-foreground text-xs"
          />
          <YAxis
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            tickFormatter={formatValue}
            className="text-muted-foreground text-xs"
          />
          <ChartTooltip content={<ChartTooltipContent />} />
          {state.visibleSeries.has("value") && (
            <Bar
              dataKey="value"
              fill="var(--color-value)"
              radius={[4, 4, 0, 0]}
              className={cn(enableDrillDown && "cursor-pointer")}
            />
          )}
          {enableLegendToggle && <ChartLegend content={<ChartLegendContent />} />}
        </BarChart>
      ) : (
        <LineChart {...commonChartProps}>
          <CartesianGrid vertical={false} className="stroke-muted" />
          <XAxis
            dataKey="name"
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            className="text-muted-foreground text-xs"
          />
          <YAxis
            tickLine={false}
            axisLine={false}
            tickMargin={8}
            tickFormatter={formatValue}
            className="text-muted-foreground text-xs"
          />
          <ChartTooltip content={<ChartTooltipContent />} />
          {state.visibleSeries.has("value") && (
            <Line
              dataKey="value"
              type="monotone"
              stroke="var(--color-value)"
              strokeWidth={2}
              dot={{ r: 3, cursor: enableDrillDown ? "pointer" : "default" }}
              activeDot={{ r: 5 }}
            />
          )}
          {enableLegendToggle && <ChartLegend content={<ChartLegendContent />} />}
        </LineChart>
      )}
    </ChartContainer>
  );

  return (
    <>
      <Card className={className}>
        <CardHeader className="flex flex-row items-start justify-between space-y-0 pb-2">
          <div>
            <CardTitle>{title}</CardTitle>
            {description && <CardDescription>{description}</CardDescription>}
          </div>
          <div className="flex items-center gap-1">
            {enableZoom && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon-sm" onClick={zoomIn} aria-label="Zoom in">
                      <ZoomIn className="size-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Zoom In</TooltipContent>
                </Tooltip>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon-sm" onClick={zoomOut} aria-label="Zoom out">
                      <ZoomOut className="size-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Zoom Out</TooltipContent>
                </Tooltip>
                {state.zoom.scale > 1 && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button variant="ghost" size="icon-sm" onClick={resetZoom} aria-label="Reset zoom">
                        <RefreshCw className="size-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Reset Zoom</TooltipContent>
                  </Tooltip>
                )}
              </TooltipProvider>
            )}

            {enableLegendToggle && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon-sm" aria-label="View"
                      onClick={() => toggleSeries("value")}
                    >
                      {state.visibleSeries.has("value") ? (
                        <Eye className="size-4" />
                      ) : (
                        <EyeOff className="size-4" />
                      )}
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>
                    {state.visibleSeries.has("value") ? "Hide" : "Show"} Series
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}

            {enableFullscreen && (
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost"
                      size="icon-sm" aria-label="View fullscreen"
                      onClick={() => setIsFullscreenOpen(true)}
                    >
                      <Maximize className="size-4" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Fullscreen</TooltipContent>
                </Tooltip>
              </TooltipProvider>
            )}

            <ChartExport
              chartRef={chartRef}
              data={data}
              defaultFilename={title.toLowerCase().replace(/\s+/g, "-")}
              title={title}
            />
          </div>
        </CardHeader>

        {showToolbar && onTimeRangeChange && (
          <div className="px-6 pb-2">
            <ChartToolbar
              timeRange={timeRange}
              onTimeRangeChange={onTimeRangeChange}
              chartType={state.chartType}
              onChartTypeChange={setChartType}
              comparisonMode={comparisonMode}
              onComparisonModeChange={onComparisonModeChange}
              onRefresh={onRefresh}
              isRefreshing={isRefreshing}
              showComparison={!!onComparisonModeChange}
              showExport={false}
            />
          </div>
        )}

        <CardContent>
          <div ref={chartRef}>{renderChart(height)}</div>
        </CardContent>
      </Card>

      {enableFullscreen && (
        <Dialog open={isFullscreenOpen} onOpenChange={setIsFullscreenOpen}>
          <DialogContent className="max-w-[90vw] max-h-[90vh]">
            <DialogHeader>
              <DialogTitle>{title}</DialogTitle>
              <DialogDescription className="sr-only">Expanded chart view</DialogDescription>
            </DialogHeader>
            <div className="mt-4">{renderChart(500)}</div>
          </DialogContent>
        </Dialog>
      )}

      {enableDrillDown && (
        <DrillDownModal
          open={isDrillDownOpen}
          onOpenChange={setIsDrillDownOpen}
          levelStack={drillDown.levelStack}
          currentLevel={drillDown.currentLevel}
          selectedPoint={drillDown.selectedPoint}
          onNavigateToLevel={navigateToLevel}
          onNavigateUp={navigateUp}
          onNavigateDown={(point) => {
            if (getDrillDownData) {
              Promise.resolve(getDrillDownData(point)).then((childData) => {
                if (childData.length > 0) {
                  navigateDown(point, childData);
                }
              });
            }
          }}
          chartType={state.chartType}
          formatValue={formatValue}
        />
      )}
    </>
  );
}

export function InteractiveChartSkeleton({ height = 300 }: { height?: number }) {
  return (
    <Card>
      <CardHeader>
        <Skeleton className="h-5 w-40" />
        <Skeleton className="h-4 w-60" />
      </CardHeader>
      <CardContent>
        <Skeleton className="w-full" style={{ height }} />
      </CardContent>
    </Card>
  );
}

"use client";

import * as React from "react";
import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { format } from "date-fns";
import { VList } from "virtua";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import {
  Search,
  Settings,
  ArrowUp,
  ArrowDown,
  RefreshCw,
  Calendar as CalendarIcon,
  X,
} from "lucide-react";
import { cn } from "@/shared/utils";
import { DataTablePagination } from "./pagination";
import { EmptyState } from "@/components/ui/empty-state";

// Types
export interface DataTableColumn<TData> {
  id: string;
  header: string;
  accessorKey?: keyof TData;
  cell?: (row: TData) => React.ReactNode;
  enableSorting?: boolean;
  enableHiding?: boolean;
  className?: string;
}

export interface DataTableFilterOption {
  label: string;
  value: string;
  count?: number;
  color?: string; // e.g., "bg-success" for status dots
}

export interface DataTableFilter {
  id: string;
  label: string;
  type?: "select" | "date-range";
  options?: DataTableFilterOption[];
}

export interface DataTableAction {
  label: string;
  onClick?: () => void;
  href?: string;
  variant?: "default" | "outline" | "ghost";
  icon?: React.ReactNode;
}

// Import LucideIcon type for EmptyState compatibility
import { type LucideIcon, Inbox } from "lucide-react";

export interface DataTableEmptyState {
  icon?: LucideIcon;
  title: string;
  description?: string;
  action?: {
    label: string;
    onClick: () => void;
  };
}

interface ActiveFilterChip {
  key: string;
  label: string;
  value: string;
  displayValue: string;
}

interface DataTableProps<TData> {
  data: TData[];
  columns: DataTableColumn<TData>[];
  filters?: DataTableFilter[];
  actions?: DataTableAction[];
  getRowId: (row: TData) => string;
  rowHref?: (row: TData) => string;
  onRowClick?: (row: TData) => void;
  totalCount: number;
  pageSize?: number;
  enableSearch?: boolean;
  enablePagination?: boolean;
  enableRowSelection?: boolean;
  enableColumnVisibility?: boolean;
  enableSorting?: boolean;
  enableFilterChips?: boolean;
  searchPlaceholder?: string;
  emptyState?: DataTableEmptyState;
  isLoading?: boolean;
  onBulkAction?: (selectedIds: string[], action: string) => void;
  bulkActions?: { label: string; value: string; variant?: "default" | "destructive" }[];
  prefix?: string;
  className?: string;
  // Date range support (opt-in)
  dateRange?: { from?: Date; to?: Date };
  onDateRangeChange?: (range: { from?: Date; to?: Date }) => void;
  // Virtualization for large datasets (opt-in, renders visible rows only)
  enableVirtualization?: boolean;
  virtualRowHeight?: number;
}


// URL state helpers
function getQueryParamKey(key: string, prefix?: string) {
  return prefix ? `${prefix}_${key}` : key;
}

function parseSearchParams(searchParams: URLSearchParams, prefix?: string) {
  const get = (key: string) => searchParams.get(getQueryParamKey(key, prefix));

  return {
    page: parseInt(get("page") || "1", 10),
    pageSize: parseInt(get("pageSize") || "10", 10),
    search: get("q") || "",
    sort: get("sort") || "",
    sortDir: (get("sortDir") as "asc" | "desc") || "asc",
    filters: {} as Record<string, string>,
  };
}

export function DataTable<TData>({
  data,
  columns,
  filters = [],
  actions = [],
  getRowId,
  rowHref,
  onRowClick,
  totalCount,
  pageSize: defaultPageSize = 10,
  enableSearch = true,
  enablePagination = true,
  enableRowSelection = false,
  enableColumnVisibility = false,
  enableSorting = false,
  enableFilterChips = true,
  searchPlaceholder = "Search...",
  emptyState,
  isLoading = false,
  onBulkAction,
  bulkActions = [],
  prefix,
  className,
  dateRange,
  onDateRangeChange,
  enableVirtualization = false,
  virtualRowHeight = 52,
}: DataTableProps<TData>) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = React.useTransition();

  // Parse URL state
  const urlState = React.useMemo(
    () => parseSearchParams(searchParams, prefix),
    [searchParams, prefix]
  );

  // Local state
  const [searchValue, setSearchValue] = React.useState(urlState.search);
  const [selectedRows, setSelectedRows] = React.useState<Set<string>>(new Set());
  const [columnVisibility, setColumnVisibility] = React.useState<Record<string, boolean>>(() =>
    columns.reduce((acc, col) => ({ ...acc, [col.id]: true }), {})
  );

  // Calculate active filter chips
  const activeFilterChips = React.useMemo(() => {
    const chips: ActiveFilterChip[] = [];

    // Add select filter chips
    filters.forEach((filter) => {
      if (filter.type !== "date-range") {
        const value = searchParams.get(getQueryParamKey(filter.id, prefix));
        if (value) {
          const option = filter.options?.find(o => o.value === value);
          chips.push({
            key: filter.id,
            label: filter.label,
            value,
            displayValue: option?.label || value,
          });
        }
      }
    });

    // Add date range chip if present
    if (dateRange?.from) {
      const dateLabel = dateRange.to
        ? `${format(dateRange.from, "MMM d")} - ${format(dateRange.to, "MMM d")}`
        : format(dateRange.from, "MMM d, yyyy");
      chips.push({
        key: "dateRange",
        label: "Date",
        value: "dateRange",
        displayValue: dateLabel,
      });
    }

    return chips;
  }, [filters, searchParams, prefix, dateRange]);

  // Check if date range filter is configured
  const hasDateRangeFilter = filters.some(f => f.type === "date-range");

  // Update URL with new params
  const updateUrl = React.useCallback(
    (updates: Record<string, string | undefined>) => {
      const params = new URLSearchParams(searchParams.toString());

      Object.entries(updates).forEach(([key, value]) => {
        const paramKey = getQueryParamKey(key, prefix);
        if (value) {
          params.set(paramKey, value);
        } else {
          params.delete(paramKey);
        }
      });

      // Reset to page 1 when filters change (except for page changes)
      if (!("page" in updates)) {
        params.delete(getQueryParamKey("page", prefix));
      }

      startTransition(() => {
        router.push(`${pathname}?${params.toString()}`);
      });
    },
    [pathname, router, searchParams, prefix]
  );

  // Debounced search
  React.useEffect(() => {
    const timeout = setTimeout(() => {
      if (searchValue !== urlState.search) {
        updateUrl({ q: searchValue || undefined });
      }
    }, 300);
    return () => clearTimeout(timeout);
  }, [searchValue, urlState.search, updateUrl]);

  // Handle sorting
  const handleSort = (columnId: string) => {
    if (!enableSorting) return;
    const newDir = urlState.sort === columnId && urlState.sortDir === "asc" ? "desc" : "asc";
    updateUrl({ sort: columnId, sortDir: newDir });
  };

  // Handle row selection
  const toggleSelectAll = () => {
    if (selectedRows.size === data.length) {
      setSelectedRows(new Set());
    } else {
      setSelectedRows(new Set(data.map(getRowId)));
    }
  };

  const toggleSelect = (id: string) => {
    const newSelected = new Set(selectedRows);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedRows(newSelected);
  };

  // Handle removing a filter chip
  const removeFilterChip = (key: string) => {
    if (key === "dateRange" && onDateRangeChange) {
      onDateRangeChange({});
    } else {
      updateUrl({ [key]: undefined });
    }
  };

  // Clear all filters
  const clearAllFilters = () => {
    setSearchValue("");
    if (onDateRangeChange) {
      onDateRangeChange({});
    }
    router.push(pathname);
  };

  // Visible columns
  const visibleColumns = columns.filter(
    (col) => columnVisibility[col.id] !== false
  );

  const pageCount = Math.ceil(totalCount / urlState.pageSize);
  const hasFilters = urlState.search || activeFilterChips.length > 0;

  return (
    <div className={cn("space-y-3", className)}>
      {/* Toolbar */}
      <div className="flex flex-col gap-3">
        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
          {/* Search */}
          {enableSearch && (
            <div className="relative flex-1 w-full sm:max-w-sm">
              <Search
                className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground"
              />
              <Input
                placeholder={searchPlaceholder}
                value={searchValue}
                onChange={(e) => setSearchValue(e.target.value)}
                className="pl-9 bg-background"
              />
            </div>
          )}

          {/* Filters */}
          <div className="flex items-center gap-2 flex-wrap">
            {filters.filter(f => f.type !== "date-range").map((filter) => (
              <Select
                key={filter.id}
                value={searchParams.get(getQueryParamKey(filter.id, prefix)) || "all"}
                onValueChange={(value) =>
                  updateUrl({ [filter.id]: value === "all" ? undefined : value })
                }
              >
                <SelectTrigger className="w-[140px] bg-background">
                  <SelectValue placeholder={filter.label} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All {filter.label}</SelectItem>
                  {filter.options?.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      <span className="flex items-center gap-2">
                        {opt.color && (
                          <span className={cn("size-2 rounded-full", opt.color)} />
                        )}
                        {opt.label}
                        {opt.count !== undefined && (
                          <span className="text-muted-foreground">({opt.count})</span>
                        )}
                      </span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            ))}

            {/* Date Range Filter */}
            {hasDateRangeFilter && onDateRangeChange && (
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className={cn(
                      "w-[200px] justify-start text-left font-normal",
                      !dateRange?.from && "text-muted-foreground"
                    )}
                  >
                    <CalendarIcon className="size-4" />
                    {dateRange?.from ? (
                      dateRange.to ? (
                        <>
                          {format(dateRange.from, "MMM d")} - {format(dateRange.to, "MMM d")}
                        </>
                      ) : (
                        format(dateRange.from, "MMM d, yyyy")
                      )
                    ) : (
                      <span>Pick date range</span>
                    )}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="range"
                    selected={{ from: dateRange?.from, to: dateRange?.to }}
                    onSelect={(range) => {
                      onDateRangeChange({ from: range?.from, to: range?.to });
                    }}
                    numberOfMonths={2}
                  />
                </PopoverContent>
              </Popover>
            )}

            {/* Clear Filters */}
            {hasFilters && (
              <Button
                variant="ghost"
                onClick={clearAllFilters}
              >
                Clear
              </Button>
            )}
          </div>

          {/* Actions */}
          <div className="flex items-center gap-2 ml-auto">
            {/* Column Visibility */}
            {enableColumnVisibility && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="outline">
                    <Settings className="size-4" />
                    <span className="hidden sm:inline">Columns</span>
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  {columns
                    .filter((col) => col.enableHiding !== false)
                    .map((col) => (
                      <DropdownMenuCheckboxItem
                        key={col.id}
                        checked={columnVisibility[col.id] !== false}
                        onCheckedChange={(checked) =>
                          setColumnVisibility((prev) => ({ ...prev, [col.id]: checked }))
                        }
                      >
                        {col.header}
                      </DropdownMenuCheckboxItem>
                    ))}
                </DropdownMenuContent>
              </DropdownMenu>
            )}

            {/* Refresh */}
            <Button
              variant="outline"
              size="icon" aria-label="Refresh"
              onClick={() => router.refresh()}
              disabled={isPending}
            >
              <RefreshCw
                className={cn("size-4", isPending && "animate-spin")}
              />
            </Button>

            {/* Custom Actions */}
            {actions.map((action, i) => (
              <Button
                key={i}
                variant={action.variant || "default"}
                onClick={action.onClick}
                asChild={!!action.href}
                className="gap-2"
              >
                {action.href ? (
                  <a href={action.href}>
                    {action.icon}
                    {action.label}
                  </a>
                ) : (
                  <>
                    {action.icon}
                    {action.label}
                  </>
                )}
              </Button>
            ))}
          </div>
        </div>

        {/* Bulk Actions */}
        {enableRowSelection && selectedRows.size > 0 && (
          <div className="flex items-center gap-3 p-2 bg-muted rounded-lg">
            <span className="text-sm font-medium">{selectedRows.size} selected</span>
            <div className="flex items-center gap-2">
              {bulkActions.map((action) => (
                <Button
                  key={action.value}

                  variant={action.variant === "destructive" ? "outline" : "outline"}
                  className={action.variant === "destructive" ? "text-destructive hover:text-destructive" : ""}
                  onClick={() => onBulkAction?.(Array.from(selectedRows), action.value)}
                >
                  {action.label}
                </Button>
              ))}
              <Button variant="ghost" onClick={() => setSelectedRows(new Set())}>
                Clear
              </Button>
            </div>
          </div>
        )}

        {/* Active Filter Chips */}
        {enableFilterChips && activeFilterChips.length > 0 && (
          <div className="flex items-center gap-[8px] flex-wrap">
            {activeFilterChips.map((chip) => (
              <Badge
                key={chip.key}
                variant="secondary"
                className="gap-1.5 pr-1 font-normal"
              >
                <span className="text-muted-foreground">{chip.label}:</span>
                <span>{chip.displayValue}</span>
                <Button
                  variant="ghost"
                  size="icon-sm" aria-label="Remove filter"
                  className="size-4 p-0 hover:bg-transparent"
                  onClick={() => removeFilterChip(chip.key)}
                >
                  <X className="size-3" />
                </Button>
              </Badge>
            ))}
            <Button
              variant="ghost"

              className="h-6 px-2 text-xs text-muted-foreground"
              onClick={clearAllFilters}
            >
              Clear all
            </Button>
          </div>
        )}
      </div>

      {/* Table */}
      <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              {enableRowSelection && (
                <TableHead className="w-12">
                  <Checkbox
                    checked={selectedRows.size === data.length && data.length > 0}
                    onCheckedChange={toggleSelectAll}
                    aria-label="Select all"
                  />
                </TableHead>
              )}
              {visibleColumns.map((col) => {
                // Determine aria-sort value for sortable columns
                const getAriaSortValue = (): "ascending" | "descending" | "none" | undefined => {
                  if (!col.enableSorting || !enableSorting) return undefined;
                  if (urlState.sort !== col.id) return "none";
                  return urlState.sortDir === "asc" ? "ascending" : "descending";
                };

                return (
                  <TableHead
                    key={col.id}
                    className={cn(
                      col.enableSorting && enableSorting && "cursor-pointer select-none",
                      col.className
                    )}
                    onClick={() => col.enableSorting && handleSort(col.id)}
                    aria-sort={getAriaSortValue()}
                  >
                    <div className="flex items-center gap-1">
                      {col.header}
                      {col.enableSorting && enableSorting && urlState.sort === col.id && (
                        urlState.sortDir === "asc" ? (
                          <ArrowUp className="size-3" />
                        ) : (
                          <ArrowDown className="size-3" />
                        )
                      )}
                    </div>
                  </TableHead>
                );
              })}
            </TableRow>
          </TableHeader>
          <TableBody>
            {data.length === 0 ? (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={visibleColumns.length + (enableRowSelection ? 1 : 0)}
                  className="h-[388px]"
                >
                  <EmptyState
                    icon={emptyState?.icon}
                    title={emptyState?.title || (hasFilters ? "No results found" : "No data")}
                    description={
                      emptyState?.description ||
                      (hasFilters ? "Try adjusting your search or filters" : undefined)
                    }
                    action={
                      hasFilters
                        ? { label: "Clear Filters", onClick: () => router.push(pathname) }
                        : emptyState?.action
                    }
                  />
                </TableCell>
              </TableRow>
            ) : enableVirtualization && data.length > 50 ? (
              <tr>
                <td colSpan={visibleColumns.length + (enableRowSelection ? 1 : 0)}>
                  <VList style={{ height: Math.min(data.length * virtualRowHeight, 600) }}>
                    {data.map((row) => {
                      const rowId = getRowId(row);
                      const isSelected = selectedRows.has(rowId);
                      return (
                        <div
                          key={rowId}
                          role="row"
                          className={cn(
                            "group flex items-center border-b",
                            isSelected && "bg-muted",
                            (rowHref || onRowClick) && "cursor-pointer hover:bg-muted/50"
                          )}
                          onClick={() => {
                            if (onRowClick) onRowClick(row);
                            else if (rowHref) router.push(rowHref(row));
                          }}
                        >
                          {enableRowSelection && (
                            <div role="cell" className="py-2 px-4" onClick={(e) => e.stopPropagation()}>
                              <Checkbox
                                checked={isSelected}
                                onCheckedChange={() => toggleSelect(rowId)}
                                aria-label={`Select row ${rowId}`}
                              />
                            </div>
                          )}
                          {visibleColumns.map((col) => (
                            <div role="cell" key={col.id} className={cn("py-2 px-4 flex-1", col.className)}>
                              {col.cell
                                ? col.cell(row)
                                : col.accessorKey
                                ? String((row as Record<string, unknown>)[col.accessorKey as string] ?? "")
                                : null}
                            </div>
                          ))}
                        </div>
                      );
                    })}
                  </VList>
                </td>
              </tr>
            ) : (
              data.map((row) => {
                const rowId = getRowId(row);
                const isSelected = selectedRows.has(rowId);

                return (
                  <TableRow
                    key={rowId}
                    className={cn(
                      "group",
                      isSelected && "bg-muted",
                      (rowHref || onRowClick) && "cursor-pointer"
                    )}
                    onClick={() => {
                      if (onRowClick) onRowClick(row);
                      else if (rowHref) router.push(rowHref(row));
                    }}
                  >
                    {enableRowSelection && (
                      <TableCell className="py-2" onClick={(e) => e.stopPropagation()}>
                        <Checkbox
                          checked={isSelected}
                          onCheckedChange={() => toggleSelect(rowId)}
                          aria-label={`Select row ${rowId}`}
                        />
                      </TableCell>
                    )}
                    {visibleColumns.map((col) => (
                      <TableCell key={col.id} className={cn("py-2", col.className)}>
                        {col.cell
                          ? col.cell(row)
                          : col.accessorKey
                          ? String((row as Record<string, unknown>)[col.accessorKey as string] ?? "")
                          : null}
                      </TableCell>
                    ))}
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>

      {/* Pagination */}
      {enablePagination && totalCount > 0 && (
        <DataTablePagination
          pageIndex={urlState.page - 1}
          pageSize={urlState.pageSize}
          pageCount={pageCount}
          totalItems={totalCount}
          selectedCount={selectedRows.size}
          onPageChange={(page) => updateUrl({ page: String(page + 1) })}
          onPageSizeChange={(size) => updateUrl({ pageSize: String(size) })}
        />
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { 
  Globe, 
  Info,
  Loader2,
  CheckCircle,
} from "lucide-react";

interface DomainRecord {
  id: string;
  tenantId: string;
  domain: string;
  verificationToken: string;
  verificationMethod: string;
  status: string;
  vercelDomainId: string | null;
  errorMessage: string | null;
  createdAt: string;
  verifiedAt: string | null;
}

interface DnsInstructions {
  method: string;
  records: Array<{ type: string; name: string; value: string }>;
  instructions: string;
}

interface AddDomainDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDomainAdded: (domain: DomainRecord, instructions: DnsInstructions) => void;
}

export function AddDomainDialog({
  open,
  onOpenChange,
  onDomainAdded,
}: AddDomainDialogProps) {
  const [domain, setDomain] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);
  const [instructions, setInstructions] = useState<DnsInstructions | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!domain.trim()) {
      setError("Please enter a domain");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/dashboard/domains", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ domain: domain.trim().toLowerCase() }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Failed to add domain");
      }

      setSuccess(true);
      setInstructions(data.instructions);
      onDomainAdded(data.domain, data.instructions);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to add domain");
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setDomain("");
    setError(null);
    setSuccess(false);
    setInstructions(null);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Globe className="size-5" />
            Add Custom Domain
          </DialogTitle>
          <DialogDescription>
            Connect your own domain to your storefront. You&apos;ll need to configure DNS records with your domain provider.
          </DialogDescription>
        </DialogHeader>

        {!success ? (
          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="domain">Domain</Label>
                <Input
                  id="domain"
                  placeholder="store.yourdomain.com"
                  value={domain}
                  onChange={(e) => setDomain(e.target.value)}
                  disabled={loading}
                />
                <p className="text-xs text-muted-foreground">
                  Enter your domain without http:// or https://
                </p>
              </div>

              {error && (
                <Alert variant="destructive">
                  <Info className="size-4" />
                  <AlertTitle>Error</AlertTitle>
                  <AlertDescription>{error}</AlertDescription>
                </Alert>
              )}

              <Alert>
                <Info className="size-4" />
                <AlertTitle>DNS Configuration Required</AlertTitle>
                <AlertDescription>
                  After adding your domain, you&apos;ll need to configure DNS records. We support both CNAME and A record configurations.
                </AlertDescription>
              </Alert>
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={handleClose} disabled={loading}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading || !domain.trim()}>
                {loading ? (
                  <>
                    <Loader2 className="size-4 animate-spin" />
                    Adding...
                  </>
                ) : (
                  "Add Domain"
                )}
              </Button>
            </DialogFooter>
          </form>
        ) : (
          <div className="space-y-4 py-4">
            <Alert className="border-success/20 bg-success/10">
              <CheckCircle className="size-4 text-success" />
              <AlertTitle className="text-success">Domain Added Successfully</AlertTitle>
              <AlertDescription>
                Your domain has been added. Now configure your DNS records to complete the setup.
              </AlertDescription>
            </Alert>

            {instructions && (
              <DnsInstructionsDisplay instructions={instructions} domain={domain} />
            )}

            <DialogFooter>
              <Button onClick={handleClose}>Done</Button>
            </DialogFooter>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

interface DnsInstructionsDisplayProps {
  instructions: DnsInstructions;
  domain: string;
}

function DnsInstructionsDisplay({ instructions, domain }: DnsInstructionsDisplayProps) {
  return (
    <div className="space-y-4">
