  /** Callback to rename a preset */
  onRename: (id: string, name: string) => void;
  /** Callback to clear filters */
  onClear: () => void;
  /** Default label when no preset is active */
  defaultLabel?: string;
  /** Additional class names */
  className?: string;
}

/**
 * Dropdown for managing saved filter presets
 * Inspired by Saleor's FilterPresetsSelect
 * 
 * @example
 * ```tsx
 * const { filters } = useUrlFilters();
 * const {
 *   presets,
 *   activePreset,
 *   hasUnsavedChanges,
 *   savePreset,
 *   applyPreset,
 *   deletePreset,
 *   renamePreset,
 *   clearFilters,
 *   updatePreset,
 * } = useFilterPresets({ 
 *   pageKey: 'orders',
 *   currentFilters: filters 
 * });
 * 
 * <FilterPresetsSelect
 *   presets={presets}
 *   activePreset={activePreset}
 *   hasUnsavedChanges={hasUnsavedChanges}
 *   onApply={applyPreset}
 *   onSave={savePreset}
 *   onUpdate={(id) => updatePreset(id)}
 *   onDelete={deletePreset}
 *   onRename={renamePreset}
 *   onClear={clearFilters}
 * />
 * ```
 */
export function FilterPresetsSelect({
  presets,
  activePreset,
  hasUnsavedChanges,
  onApply,
  onSave,
  onUpdate,
  onDelete,
  onRename,
  onClear,
  defaultLabel = "All items",
  className,
}: FilterPresetsSelectProps) {
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [renameDialogOpen, setRenameDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedPresetId, setSelectedPresetId] = useState<string | null>(null);
  const [newName, setNewName] = useState("");

  const handleSave = () => {
    if (newName.trim()) {
      onSave(newName.trim());
      setNewName("");
      setSaveDialogOpen(false);
    }
  };

  const handleRename = () => {
    if (selectedPresetId && newName.trim()) {
      onRename(selectedPresetId, newName.trim());
      setNewName("");
      setSelectedPresetId(null);
      setRenameDialogOpen(false);
    }
  };

  const handleDelete = () => {
    if (selectedPresetId) {
      onDelete(selectedPresetId);
      setSelectedPresetId(null);
      setDeleteDialogOpen(false);
    }
  };

  const openRenameDialog = (preset: FilterPreset) => {
    setSelectedPresetId(preset.id);
    setNewName(preset.name);
    setRenameDialogOpen(true);
  };

  const openDeleteDialog = (preset: FilterPreset) => {
    setSelectedPresetId(preset.id);
    setDeleteDialogOpen(true);
  };

  return (
    <>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="outline" className={cn("gap-2", className)}>
            <Filter className="size-4" />
            <span className="max-w-[150px] truncate">
              {activePreset?.name || defaultLabel}
            </span>
            {hasUnsavedChanges && (
              <Badge variant="secondary" className="ml-1 px-1.5 py-0 text-[10px]">
                Modified
              </Badge>
            )}
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" className="w-64">
          {/* Default option */}
          <DropdownMenuItem onClick={onClear}>
            <span className="flex-1">{defaultLabel}</span>
            {!activePreset && !hasUnsavedChanges && (
              <CheckCircle className="size-4 text-primary" />
            )}
          </DropdownMenuItem>

          {presets.length > 0 && <DropdownMenuSeparator />}

          {/* Saved presets */}
          {presets.map((preset) => (
            <DropdownMenuItem
              key={preset.id}
              className="group flex items-center justify-between"
            >
              <button
                className="flex-1 text-left"
                onClick={() => onApply(preset.id)}
              >
                <span className="flex items-center gap-2">
                  <Bookmark className="w-3.5 h-3.5 text-muted-foreground" />
                  <span className="truncate max-w-[120px]">{preset.name}</span>
                </span>
              </button>
              <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <Button
                  variant="ghost"
                  size="icon-sm" aria-label="Rename preset"
                  className="size-6"
                  onClick={(e) => {
                    e.stopPropagation();
                    openRenameDialog(preset);
                  }}
                >
                  <Pencil className="size-3" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon-sm" aria-label="Delete preset"
                  className="size-6 text-destructive hover:text-destructive"
                  onClick={(e) => {
                    e.stopPropagation();
                    openDeleteDialog(preset);
                  }}
                >
                  <Trash2 className="size-3" />
                </Button>
              </div>
              {activePreset?.id === preset.id && !hasUnsavedChanges && (
                <CheckCircle className="size-4 text-primary ml-2" />
              )}
            </DropdownMenuItem>
          ))}

          <DropdownMenuSeparator />

          {/* Save current filters */}
          {hasUnsavedChanges && (
            <DropdownMenuItem onClick={() => setSaveDialogOpen(true)}>
              <Plus className="size-4" />
              Save current filters
            </DropdownMenuItem>
          )}

          {/* Update active preset */}
          {activePreset && hasUnsavedChanges && (
            <DropdownMenuItem onClick={() => onUpdate(activePreset.id)}>
              <CheckCircle className="size-4" />
              Update "{activePreset.name}"
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Save Dialog */}
      <Dialog open={saveDialogOpen} onOpenChange={setSaveDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Save Filter Preset</DialogTitle><DialogDescription className="sr-only">Save current filters as a reusable preset</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <Input
              placeholder="Preset name"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSave()}
              autoFocus
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setSaveDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={!newName.trim()}>
              Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Rename Dialog */}
      <Dialog open={renameDialogOpen} onOpenChange={setRenameDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Rename Preset</DialogTitle><DialogDescription className="sr-only">Rename the selected filter preset</DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <Input
              placeholder="New name"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleRename()}
              autoFocus
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRenameDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleRename} disabled={!newName.trim()}>
              Rename
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Delete Preset</DialogTitle><DialogDescription className="sr-only">Confirm deletion of this filter preset</DialogDescription>
          </DialogHeader>
          <p className="text-sm text-muted-foreground">
            Are you sure you want to delete this filter preset? This action cannot be undone.
          </p>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteDialogOpen(false)}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={handleDelete}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

FilterPresetsSelect.displayName = "FilterPresetsSelect";

"use client";

import * as React from "react";
import { useForm, FieldValues, DefaultValues, Path, UseFormReturn } from "react-hook-form";
import { Form } from "@/components/ui/form";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import { useRouter } from "next/navigation";
import { cn } from "@/shared/utils";

// Reusable form field components
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
} from "@/components/ui/form";

interface FormInputProps<TFieldValues extends FieldValues> {
  form: UseFormReturn<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
  placeholder?: string;
  description?: string;
  type?: "text" | "email" | "password" | "number" | "url";
  disabled?: boolean;
  className?: string;
}

export function FormInput<TFieldValues extends FieldValues>({
  form,
  name,
  label,
  placeholder,
  description,
  type = "text",
  disabled,
  className,
}: FormInputProps<TFieldValues>) {
  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem className={className}>
          <FormLabel>{label}</FormLabel>
          <FormControl>
            <Input
              type={type}
              placeholder={placeholder}
              disabled={disabled}
              {...field}
              value={field.value ?? ""}
              onChange={(e) => {
                const value = type === "number" ? parseFloat(e.target.value) || 0 : e.target.value;
                field.onChange(value);
              }}
            />
          </FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

interface FormTextareaProps<TFieldValues extends FieldValues> {
  form: UseFormReturn<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
  placeholder?: string;
  description?: string;
  rows?: number;
  maxLength?: number;
  disabled?: boolean;
  className?: string;
}

export function FormTextarea<TFieldValues extends FieldValues>({
  form,
  name,
  label,
  placeholder,
  description,
  rows = 4,
  maxLength,
  disabled,
  className,
}: FormTextareaProps<TFieldValues>) {
  const value = form.watch(name) as string;
  const charCount = value?.length || 0;

  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem className={className}>
          <div className="flex items-center justify-between">
            <FormLabel>{label}</FormLabel>
            {maxLength && (
              <span
                className={cn(
                  "text-xs",
                  charCount > maxLength * 0.9 ? "text-warning" : "text-muted-foreground",
                  charCount >= maxLength && "text-destructive"
                )}
              >
                {charCount}/{maxLength}
              </span>
            )}
          </div>
          <FormControl>
            <Textarea
              placeholder={placeholder}
              rows={rows}
              maxLength={maxLength}
              disabled={disabled}
              {...field}
              value={field.value ?? ""}
            />
          </FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

interface FormSwitchProps<TFieldValues extends FieldValues> {
  form: UseFormReturn<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
  description?: string;
  disabled?: boolean;
  className?: string;
}

export function FormSwitch<TFieldValues extends FieldValues>({
  form,
  name,
  label,
  description,
  disabled,
  className,
}: FormSwitchProps<TFieldValues>) {
  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem
          className={cn(
            "flex items-center justify-between rounded-lg border p-4",
            className
          )}
        >
          <div className="space-y-0.5">
            <FormLabel className="text-sm">{label}</FormLabel>
            {description && (
              <FormDescription>{description}</FormDescription>
            )}
          </div>
          <FormControl>
            <Switch
              checked={field.value}
              onCheckedChange={field.onChange}
              disabled={disabled}
            />
          </FormControl>
        </FormItem>
      )}
    />
  );
}

interface FormSelectProps<TFieldValues extends FieldValues> {
  form: UseFormReturn<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
  placeholder?: string;
  description?: string;
  options: { label: string; value: string }[];
  disabled?: boolean;
  className?: string;
}

export function FormSelect<TFieldValues extends FieldValues>({
  form,
  name,
  label,
  placeholder = "Select...",
  description,
  options,
  disabled,
  className,
}: FormSelectProps<TFieldValues>) {
  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem className={className}>
          <FormLabel>{label}</FormLabel>
          <Select
            onValueChange={field.onChange}
            defaultValue={field.value}
            disabled={disabled}
          >
            <FormControl>
              <SelectTrigger>
                <SelectValue placeholder={placeholder} />
              </SelectTrigger>
            </FormControl>
            <SelectContent>
              {options.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

interface FormPriceInputProps<TFieldValues extends FieldValues> {
  form: UseFormReturn<TFieldValues>;
  name: Path<TFieldValues>;
  label: string;
  currency?: string;
  description?: string;
  disabled?: boolean;
  className?: string;
}

export function FormPriceInput<TFieldValues extends FieldValues>({
  form,
  name,
  label,
  currency = "$",
  description,
  disabled,
  className,
}: FormPriceInputProps<TFieldValues>) {
  return (
    <FormField
      control={form.control}
      name={name}
      render={({ field }) => (
        <FormItem className={className}>
          <FormLabel>{label}</FormLabel>
          <FormControl>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                {currency}
              </span>
              <Input
                type="number"
                step="0.01"
                min="0"
                placeholder="0.00"
                disabled={disabled}
                className="pl-7"
                {...field}
                value={field.value ?? ""}
                onChange={(e) => field.onChange(parseFloat(e.target.value) || 0)}
              />
            </div>
          </FormControl>
          {description && <FormDescription>{description}</FormDescription>}
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

