export function LowStockProducts({ products, currency }: LowStockProductsProps) {
  if (products.length === 0) {
    return null; // Don't show the card at all if no low stock products
  }

  return (
    <Card className="border-warning/30 bg-warning/5">
      <CardHeader className="py-3">
        <div className="flex items-center gap-2">
          <AlertTriangle className="size-4 text-warning" />
          <CardTitle className="text-sm font-semibold tracking-tight text-warning">
            Low Stock Alert
          </CardTitle>
          <Badge
            variant="secondary"
            className="ml-auto bg-warning/10 text-warning border-0 text-xs"
          >
            {products.length} {products.length === 1 ? "item" : "items"}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="pt-0">
        <div className="space-y-3">
          {products.slice(0, 5).map((product) => (
            <Link
              key={product.id}
              href={`/dashboard/products/${product.id}`}
              className="flex items-center gap-3 p-2.5 rounded-lg hover:bg-muted/50 transition-colors group"
            >
              {/* Product Image */}
              <div className="size-9 rounded-lg bg-muted overflow-hidden shrink-0 border">
                {product.images && product.images.length > 0 ? (
                  <Image
                    src={product.images[0]}
                    alt={product.name}
                    width={48}
                    height={48}
                    className="object-cover w-full h-full"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <Package className="size-5 text-muted-foreground" />
                  </div>
                )}
              </div>

              {/* Product Info */}
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate group-hover:text-brand/80 transition-colors">
                  {product.name}
                </p>
                <div className="flex items-center gap-2 mt-0.5">
                  <p className="text-xs text-muted-foreground">
                    {formatCurrency(product.price, currency)}
                  </p>
                  <span className="text-xs text-muted-foreground">•</span>
                  <Badge
                    variant="secondary"
                    className="bg-warning/10 text-warning border-0 text-[10px] px-1.5 py-0"
                  >
                    {product.quantity} left
                  </Badge>
                </div>
              </div>

              {/* Arrow Icon */}
              <ArrowRight className="size-4 text-muted-foreground group-hover:text-brand/80 transition-colors shrink-0" />
            </Link>
          ))}
        </div>

        {products.length > 5 && (
          <Button
            variant="outline"

            className="w-full mt-3 border-warning/30 hover:bg-muted/50"
            asChild
          >
            <Link href="/dashboard/products?filter=low-stock">
              View all {products.length} low stock items
              <ArrowRight className="size-4 ml-2" />
            </Link>
          </Button>
        )}

        {products.length <= 5 && (
          <Button
            variant="outline"

            className="w-full mt-3 border-warning/30 hover:bg-muted/50"
            asChild
          >
            <Link href="/dashboard/products?filter=low-stock">
              Manage Inventory
              <ArrowRight className="size-4 ml-2" />
            </Link>
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { useState } from "react";
import {
  Plus,
  Trash2,
  Lock,
  Info,
} from "lucide-react";
import { cn } from "@/shared/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Badge } from "@/components/ui/badge";

export interface MetadataItem {
  key: string;
  value: string;
}

interface MetadataCardProps {
  /** Metadata items */
  data: MetadataItem[];
  /** Whether this is private metadata */
  isPrivate?: boolean;
  /** Whether the metadata is read-only */
  readonly?: boolean;
  /** Callback when metadata changes */
  onChange?: (data: MetadataItem[]) => void;
  /** Custom title */
  title?: string;
  /** Custom description */
  description?: string;
}

/**
 * Card for displaying and editing metadata key-value pairs
 * Inspired by Saleor's Metadata component
 */
export function MetadataCard({
  data,
  isPrivate = false,
  readonly = false,
  onChange,
  title,
  description,
}: MetadataCardProps) {
  const defaultTitle = isPrivate ? "Private Metadata" : "Metadata";
  const defaultDescription = isPrivate
    ? "Private metadata is only visible to staff users and apps"
    : "Metadata can be used to store additional information";

  const handleAdd = () => {
    onChange?.([...data, { key: "", value: "" }]);
  };

  const handleRemove = (index: number) => {
    const newData = data.filter((_, i) => i !== index);
    onChange?.(newData);
  };

  const handleChange = (
    index: number,
    field: "key" | "value",
    value: string
  ) => {
    const newData = data.map((item, i) =>
      i === index ? { ...item, [field]: value } : item
    );
    onChange?.(newData);
  };

  return (
    <Accordion type="single" collapsible className="w-full">
      <AccordionItem value="metadata" className="border rounded-lg">
        <AccordionTrigger className="px-4 hover:no-underline">
          <div className="flex items-center gap-2">
            {isPrivate && (
              <Lock className="size-4 text-muted-foreground" />
            )}
            <span className="font-medium">{title || defaultTitle}</span>
            {data.length > 0 && (
              <Badge variant="secondary" className="ml-2">
                {data.length}
              </Badge>
            )}
          </div>
        </AccordionTrigger>
        <AccordionContent className="px-4 pb-4">
          <p className="text-sm text-muted-foreground mb-4">
            {description || defaultDescription}
          </p>

          {data.length === 0 ? (
            <div className="text-center py-6 text-muted-foreground">
              <p className="text-sm">No metadata entries</p>
            </div>
          ) : (
            <div className="space-y-2">
              {/* Header */}
              <div className="grid grid-cols-[1fr_1fr_40px] gap-2 text-xs font-medium text-muted-foreground px-1">
                <span>Key</span>
                <span>Value</span>
                <span></span>
              </div>

              {/* Rows */}
              {data.map((item, index) => (
                <div
                  key={index}
                  className="grid grid-cols-[1fr_1fr_40px] gap-2 items-center"
                >
                  <Input
                    value={item.key}
                    onChange={(e) => handleChange(index, "key", e.target.value)}
                    placeholder="Key"
                    disabled={readonly}
                    className="h-9 text-sm"
                  />
                  <Input
                    value={item.value}
                    onChange={(e) => handleChange(index, "value", e.target.value)}
                    placeholder="Value"
                    disabled={readonly}
                    className="h-9 text-sm"
                  />
                  {!readonly && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon-sm" aria-label="Delete"
                      className="size-9"
                      onClick={() => handleRemove(index)}
                    >
                      <Trash2 className="size-4" />
                    </Button>
                  )}
                </div>
              ))}
            </div>
          )}

          {!readonly && (
            <Button
              type="button"
              variant="outline"

              className="mt-4"
              onClick={handleAdd}
            >
              <Plus className="size-4" />
              Add Entry
            </Button>
          )}
        </AccordionContent>
      </AccordionItem>
    </Accordion>
  );
}

interface MetadataProps {
  /** Public metadata */
  metadata: MetadataItem[];
  /** Private metadata (optional) */
  privateMetadata?: MetadataItem[];
  /** Whether to hide private metadata section */
  hidePrivateMetadata?: boolean;
  /** Whether metadata is read-only */
  readonly?: boolean;
  /** Whether metadata is loading */
  isLoading?: boolean;
  /** Callback when public metadata changes */
  onMetadataChange?: (data: MetadataItem[]) => void;
  /** Callback when private metadata changes */
  onPrivateMetadataChange?: (data: MetadataItem[]) => void;
  /** Additional class names */
  className?: string;
}

/**
 * Combined metadata component with public and private sections
 * Inspired by Saleor's Metadata pattern
 * 
 * @example
 * ```tsx
 * const [metadata, setMetadata] = useState<MetadataItem[]>([]);
 * const [privateMetadata, setPrivateMetadata] = useState<MetadataItem[]>([]);
 * 
 * return (
 *   <Metadata
 *     metadata={metadata}
 *     privateMetadata={privateMetadata}
 *     onMetadataChange={setMetadata}
 *     onPrivateMetadataChange={setPrivateMetadata}
 *   />
 * );
 * ```
 */
export function Metadata({
  metadata,
  privateMetadata,
  hidePrivateMetadata = false,
  readonly = false,
  isLoading = false,
  onMetadataChange,
  onPrivateMetadataChange,
  className,
}: MetadataProps) {
  if (isLoading) {
    return (
      <div className={cn("space-y-4", className)}>
        <MetadataLoadingCard />
        {!hidePrivateMetadata && <MetadataLoadingCard isPrivate />}
      </div>
    );
  }

  return (
    <div className={cn("space-y-4", className)}>
      <MetadataCard
        data={metadata}
        isPrivate={false}
        readonly={readonly}
        onChange={onMetadataChange}
      />
      {!hidePrivateMetadata && privateMetadata && (
        <MetadataCard
          data={privateMetadata}
          isPrivate={true}
          readonly={readonly}
          onChange={onPrivateMetadataChange}
        />
      )}
    </div>
  );
}

/**
 * Loading skeleton for metadata card
 */
function MetadataLoadingCard({ isPrivate = false }: { isPrivate?: boolean }) {
  return (
    <div className="border rounded-lg p-4">
      <div className="flex items-center gap-2 mb-4">
        {isPrivate && (
          <div className="size-4 bg-muted rounded animate-pulse" />
        )}
        <div className="h-5 w-32 bg-muted rounded animate-pulse" />
      </div>
      <div className="space-y-2">
        {[1, 2].map((i) => (
          <div key={i} className="grid grid-cols-[1fr_1fr_40px] gap-2">
            <div className="h-9 bg-muted rounded animate-pulse" />
            <div className="h-9 bg-muted rounded animate-pulse" />
            <div className="size-9 bg-muted rounded animate-pulse" />
          </div>
        ))}
      </div>
    </div>
  );
}

Metadata.displayName = "Metadata";
MetadataCard.displayName = "MetadataCard";

"use client";

import { useMemo } from "react";
import { usePathname } from "next/navigation";
import Link from "next/link";
import { ExternalLink } from "lucide-react";
import {
    Sheet,
    SheetContent,
    SheetHeader,
    SheetTitle,
} from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/shared/utils";
import { createNavigation } from "../sidebar/navigation";
import type { NavGroup, NavItem } from "../sidebar/types";

export interface MobileNavSheetProps {
    /** Whether the sheet is open */
    open: boolean;
    /** Callback when open state changes */
    onOpenChange: (open: boolean) => void;
    /** Number of low stock items */
    lowStockCount?: number;
    /** Number of pending returns */
    pendingReturnsCount?: number;
}

export function MobileNavSheet({
    open,
    onOpenChange,
    lowStockCount = 0,
    pendingReturnsCount = 0,
}: MobileNavSheetProps) {
    const pathname = usePathname();

    const navGroups: NavGroup[] = useMemo(
        () => createNavigation({}),
        []
    );

    const isActive = (href: string) => {
        const basePath = href.split("?")[0];
        return pathname === basePath || pathname.startsWith(basePath + "/");
    };

    const handleNavClick = () => {
        onOpenChange(false);
    };

    const renderItem = (item: NavItem) => {
        const active = isActive(item.href);
        return (
            <Link
                key={item.id}
                href={item.href}
                target={item.external ? "_blank" : undefined}
                rel={item.external ? "noopener noreferrer" : undefined}
                onClick={handleNavClick}
                className={cn(
                    "flex items-center gap-[13px] p-[13px] rounded-lg transition-colors",
                    "active:scale-[0.98]",
                    active
                        ? "bg-primary/10 text-primary"
                        : "hover:bg-muted/50"
                )}
                aria-current={active ? "page" : undefined}
            >
                <div
                    className={cn(
                        "flex items-center justify-center w-[42px] h-[42px] rounded-lg",
                        active ? "bg-primary/20" : "bg-muted"
                    )}
                >
                    <item.icon
                        strokeWidth={active ? 2 : 1.5}
                        className={cn(
                            "w-[26px] h-[26px]",
                            active ? "text-primary" : "text-muted-foreground"
                        )}
                    />
                </div>
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-[8px]">
                        <span
                            className={cn(
                                "text-sm font-medium",
                                active && "text-primary"
                            )}
                        >
                            {item.title}
                        </span>
                        {item.external && (
                            <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
                        )}
                        {item.badge && (
                            <Badge
                                className={cn(
                                    "text-[10px] py-0 px-1.5 h-5",
                                    item.badgeVariant === "warning" &&
                                        "bg-warning text-primary-foreground",
                                    item.badgeVariant === "success" &&
                                        "bg-success text-primary-foreground",
                                    item.badgeVariant === "destructive" &&
                                        "bg-destructive text-destructive-foreground",
                                    !item.badgeVariant &&
                                        "bg-muted text-muted-foreground"
                                )}
                            >
                                {item.badge}
                            </Badge>
                        )}
                    </div>
                </div>
            </Link>
        );
    };

    return (
        <Sheet open={open} onOpenChange={onOpenChange}>
            <SheetContent
                side="bottom"
                className={cn(
                    "h-[85vh] rounded-t-3xl",
                    "pb-[env(safe-area-inset-bottom)]"
                )}
            >
                <SheetHeader className="pb-[13px]">
                    <SheetTitle className="text-left">More</SheetTitle>
                </SheetHeader>

                <div className="overflow-y-auto h-[calc(100%-60px)] -mx-[13px] px-[13px]">
                    {navGroups.map((group, groupIndex) => (
                        <div key={group.id}>
                            {groupIndex > 0 && <Separator className="my-[13px]" />}
                            {group.label && (
                                <div className="mb-[8px]">
                                    <h3 className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
                                        {group.label}
                                    </h3>
                                </div>
                            )}
                            <div className="space-y-[8px]">
                                {group.items.map((item) => renderItem(item))}
                            </div>
                        </div>
                    ))}

                    {/* Bottom spacing for safe area */}
                    <div className="h-[26px]" />
                </div>
            </SheetContent>
        </Sheet>
    );
}

