  { value: "unread", label: "Unread" },
  { value: "orders", label: "Orders" },
  { value: "inventory", label: "Inventory" },
  { value: "system", label: "System" },
];

function ConnectionIndicator({ status }: { status: ConnectionStatus }) {
  const statusConfig: Record<ConnectionStatus, { icon: LucideIcon; color: string; label: string }> = {
    connected: {
      icon: Wifi,
      color: "text-success",
      label: "Connected - Real-time updates active",
    },
    connecting: {
      icon: Loader2,
      color: "text-warning animate-spin",
      label: "Connecting...",
    },
    reconnecting: {
      icon: Loader2,
      color: "text-warning animate-spin",
      label: "Reconnecting...",
    },
    disconnected: {
      icon: WifiOff,
      color: "text-muted-foreground",
      label: "Disconnected - Updates paused",
    },
    error: {
      icon: WifiOff,
      color: "text-destructive",
      label: "Connection error - Retrying...",
    },
  };

  const config = statusConfig[status];
  const Icon = config.icon;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div className="flex items-center">
          <Icon className={cn("size-3.5", config.color)} />
        </div>
      </TooltipTrigger>
      <TooltipContent side="bottom" className="text-xs">
        {config.label}
      </TooltipContent>
    </Tooltip>
  );
}

export function NotificationCenter({
  className,
  viewAllHref = "/dashboard/notifications",
  maxItems = 20,
  tenantId,
  userId,
  enableRealtime = true,
}: NotificationCenterProps) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<NotificationCategory>("all");
  const [hasNewNotification, setHasNewNotification] = useState(false);
  const prevUnreadCountRef = useRef<number>(0);

  const {
    unreadCount,
    hasUnread,
    getByCategory,
    markAsRead,
    markAllAsRead,
  } = useNotifications();

  const { status: connectionStatus, reconnect } = useRealtimeNotifications({
    tenantId: tenantId || "default",
    userId,
    autoConnect: enableRealtime && !!tenantId,
    onNotification: () => {
      setHasNewNotification(true);
      setTimeout(() => setHasNewNotification(false), 3000);
    },
  });

  useEffect(() => {
    if (unreadCount > prevUnreadCountRef.current) {
      setHasNewNotification(true);
      setTimeout(() => setHasNewNotification(false), 3000);
    }
    prevUnreadCountRef.current = unreadCount;
  }, [unreadCount]);

  useEffect(() => {
    if (open) {
      setHasNewNotification(false);
    }
  }, [open]);

  const filteredNotifications = getByCategory(activeTab).slice(0, maxItems);

  const handleNotificationClick = useCallback(
    (notification: Notification) => {
      markAsRead(notification.id);
      if (notification.href) {
        setOpen(false);
        router.push(notification.href);
      }
    },
    [markAsRead, router]
  );

  const handleMarkAllAsRead = useCallback(() => {
    markAllAsRead();
  }, [markAllAsRead]);

  const handleViewAll = useCallback(() => {
    setOpen(false);
    router.push(viewAllHref);
  }, [router, viewAllHref]);

  const handleReconnect = useCallback(() => {
    reconnect();
  }, [reconnect]);

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          className={cn(
            "relative size-8 p-0",
            hasNewNotification && "animate-pulse",
            className
          )}
          aria-label={hasUnread ? `Notifications (${unreadCount} unread)` : "Notifications"}
        >
          <Bell 
            className={cn(
              "size-3.5 transition-transform",
              hasNewNotification && "animate-bounce"
            )} 
          />
          {hasUnread && (
            <Badge
              variant="destructive"
              className="absolute -top-1 -right-1 h-4 min-w-4 px-1 text-[10px] font-semibold"
            >
              {unreadCount > 99 ? "99+" : unreadCount}
            </Badge>
          )}
          {hasNewNotification && !hasUnread && (
            <span className="absolute -top-0.5 -right-0.5 flex size-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75" />
              <span className="relative inline-flex rounded-full size-2 bg-primary" />
            </span>
          )}
        </Button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-[calc(100vw-2rem)] sm:w-[380px] p-0" sideOffset={8}>
        <div className="flex items-center justify-between border-b px-4 py-3">
          <div className="flex items-center gap-2">
            <h2 className="text-sm font-semibold tracking-tight">Notifications</h2>
            {hasUnread && (
              <Badge variant="secondary" className="text-[10px] tabular-nums">
                {unreadCount} new
              </Badge>
            )}
            {enableRealtime && (
              <ConnectionIndicator status={connectionStatus} />
            )}
          </div>
          <div className="flex items-center gap-1">
            {connectionStatus === "error" && (
              <Button
                variant="ghost"
                size="xs"
                onClick={handleReconnect}
                className="text-xs text-muted-foreground hover:text-foreground"
              >
                Retry
              </Button>
            )}
            {hasUnread && (
              <Button
                variant="ghost"
                size="xs"
                onClick={handleMarkAllAsRead}
                className="text-xs text-muted-foreground hover:text-foreground"
              >
                <CheckCircle className="size-3.5" />
                Mark all read
              </Button>
            )}
          </div>
        </div>

        <Tabs
          value={activeTab}
          onValueChange={(value) => setActiveTab(value as NotificationCategory)}
          className="w-full"
        >
          <div className="border-b px-2">
            <TabsList variant="line" className="h-9 w-full justify-start gap-0">
              {TABS.map((tab) => (
                <TabsTrigger key={tab.value} value={tab.value} className="text-xs px-3">
                  {tab.label}
                </TabsTrigger>
              ))}
            </TabsList>
          </div>

          {TABS.map((tab) => (
            <TabsContent key={tab.value} value={tab.value} className="mt-0">
              <ScrollArea className="h-[320px]">
                {filteredNotifications.length > 0 ? (
                  <div className="p-2 space-y-1">
                    {filteredNotifications.map((notification) => (
                      <NotificationItem
                        key={notification.id}
                        notification={notification}
                        onClick={handleNotificationClick}
                      />
                    ))}
                  </div>
                ) : (
                  <NotificationEmptyState category={activeTab} />
                )}
              </ScrollArea>
            </TabsContent>
          ))}
        </Tabs>

        <div className="border-t p-2">
          <Button
            variant="ghost"

            className="w-full justify-center text-xs"
            onClick={handleViewAll}
          >
            View all notifications
            <ArrowRight className="size-3.5 ml-1" />
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

function NotificationEmptyState({ category }: { category: NotificationCategory }) {
  const messages: Record<NotificationCategory, { title: string; description: string }> = {
    all: {
      title: "No notifications",
      description: "You're all caught up! New notifications will appear here.",
    },
    unread: {
      title: "No unread notifications",
      description: "You've read all your notifications.",
    },
    orders: {
      title: "No order notifications",
      description: "Order updates will appear here.",
    },
    inventory: {
      title: "No inventory alerts",
      description: "Stock alerts will appear here.",
    },
    system: {
      title: "No system notifications",
      description: "System updates will appear here.",
    },
  };

  const { title, description } = messages[category];

  return (
    <EmptyState
      icon={Bell}
      title={title}
      description={description}

      className="h-[320px]"
    />
  );
}

export { NotificationEmptyState };

