"use client";

import { useState, useEffect, useCallback } from "react";
import { usePathname } from "next/navigation";
import { WifiOff, X, Info } from "lucide-react";
import { cn } from "@/shared/utils";
import { Button } from "@/components/ui/button";
import { useOnlineStatus } from "@/hooks/use-online-status";
import { useSyncQueue } from "@/hooks/use-sync-queue";

export interface OfflineBannerProps {
  className?: string;
  dismissible?: boolean;
  showPendingCount?: boolean;
}


/**
 * Full-width banner shown when the user is offline
 * Dismissible but reappears on navigation
 */
export function OfflineBanner({
  className,
  dismissible = true,
  showPendingCount = true,
}: OfflineBannerProps) {
  const pathname = usePathname();
  const { isOnline } = useOnlineStatus();
  const { pendingCount } = useSyncQueue();
  const [isDismissed, setIsDismissed] = useState(false);

  // Reset dismissed state on navigation
  useEffect(() => {
    setIsDismissed(false);
  }, [pathname]);

  // Reset dismissed state when going back online
  useEffect(() => {
    if (isOnline) {
      setIsDismissed(false);
    }
  }, [isOnline]);

  const handleDismiss = useCallback(() => {
    setIsDismissed(true);
  }, []);

  // Don't show if online or dismissed
  if (isOnline || isDismissed) {
    return null;
  }

  return (
    <div
      role="alert"
      aria-live="polite"
      className={cn(
        "relative flex items-center justify-center gap-3 bg-destructive/10 px-4 py-2.5",
        "border-b border-destructive/20",
        "animate-in slide-in-from-top duration-300",
        className
      )}
    >
      <WifiOff className="size-4 text-destructive shrink-0" />
      <div className="flex items-center gap-2 text-sm">
        <span className="font-medium text-destructive">You&apos;re offline</span>
        <span className="text-destructive">—</span>
        <span className="text-destructive">
          Changes will sync when you&apos;re back online
        </span>
        {showPendingCount && pendingCount > 0 && (
          <>
            <span className="text-destructive">·</span>
            <span className="text-destructive">
              {pendingCount} pending {pendingCount === 1 ? "change" : "changes"}
            </span>
          </>
        )}
      </div>
      {dismissible && (
        <Button
          variant="ghost"
          size="icon-xs"
          onClick={handleDismiss}
          className="absolute right-2 text-destructive hover:text-destructive hover:bg-destructive/20"
          aria-label="Dismiss offline banner"
        >
          <X className="h-3.5 w-3.5" />
        </Button>
      )}
    </div>
  );
}


/**
 * Compact offline banner for tight spaces
 */
export function OfflineBannerCompact({ className }: { className?: string }) {
  const { isOnline } = useOnlineStatus();

  if (isOnline) {
    return null;
  }

  return (
    <div
      role="alert"
      className={cn(
        "flex items-center gap-2 rounded-md bg-destructive/10 px-3 py-1.5 text-xs",
        "animate-in fade-in duration-200",
        className
      )}
    >
      <WifiOff className="h-3.5 w-3.5 text-destructive" />
      <span className="text-destructive font-medium">Offline mode</span>
    </div>
  );
}

/**
 * Reconnected banner shown briefly when coming back online
 */
export function ReconnectedBanner({ className }: { className?: string }) {
  const { isOnline, wasOffline, resetWasOffline } = useOnlineStatus();
  const { pendingCount, isSyncing } = useSyncQueue();
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (isOnline && wasOffline) {
      setShow(true);
      // Auto-hide after 5 seconds if no pending items
      if (pendingCount === 0 && !isSyncing) {
        const timer = setTimeout(() => {
          setShow(false);
          resetWasOffline();
        }, 5000);
        return () => clearTimeout(timer);
      }
    } else {
      setShow(false);
    }
  }, [isOnline, wasOffline, pendingCount, isSyncing, resetWasOffline]);

  if (!show) {
    return null;
  }

  return (
    <div
      role="status"
      aria-live="polite"
      className={cn(
        "flex items-center justify-center gap-3 bg-success/10 px-4 py-2.5",
        "border-b border-success/20",
        "animate-in slide-in-from-top duration-300",
        className
      )}
    >
      <Info className="size-4 text-success shrink-0" />
      <div className="flex items-center gap-2 text-sm">
        <span className="font-medium text-success">Back online</span>
        {pendingCount > 0 && (
          <>
            <span className="text-success">—</span>
            <span className="text-success">
              {isSyncing
                ? "Syncing your changes..."
                : `${pendingCount} ${pendingCount === 1 ? "change" : "changes"} ready to sync`}
            </span>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useCallback } from "react";
import { RotateCw, CheckCircle, Clock, AlertCircle, Trash2, RefreshCw } from "lucide-react";
import { cn } from "@/shared/utils";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { useOnlineStatus } from "@/hooks/use-online-status";
import { useSyncQueue } from "@/hooks/use-sync-queue";
import type { SyncQueueItem, SyncStatus as SyncStatusType } from "./offline-types";

export interface SyncStatusProps {
  className?: string;
  onSync?: () => void;
  onClose?: () => void;
}


export function SyncStatus({ className, onSync, onClose }: SyncStatusProps) {
  const { isOnline } = useOnlineStatus();
  const {
    pendingItems,
    failedItems,
    pendingCount,
    failedCount,
    isSyncing,
    syncProgress,
    lastSyncAt,
    processQueue,
    retryOperation,
    retryAllFailed,
    clearCompleted,
    removeOperation,
  } = useSyncQueue();

  const handleSync = useCallback(async () => {
    if (onSync) {
      onSync();
    } else {
      await processQueue();
    }
  }, [onSync, processQueue]);

  const formatLastSync = (date: Date | null) => {
    if (!date) return "Never";
    const now = new Date();
    const diff = now.getTime() - date.getTime();
    const minutes = Math.floor(diff / 60000);
    const hours = Math.floor(diff / 3600000);
    if (minutes < 1) return "Just now";
    if (minutes < 60) return `${minutes}m ago`;
    if (hours < 24) return `${hours}h ago`;
    return date.toLocaleDateString();
  };

  const allItems = [...pendingItems, ...failedItems];
  const hasItems = allItems.length > 0;

  return (
    <div className={cn("flex flex-col", className)}>
      <div className="flex items-center justify-between border-b px-4 py-3">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-semibold tracking-tight">Sync Status</h2>
          <StatusBadge isOnline={isOnline} isSyncing={isSyncing} />
        </div>
        {lastSyncAt && (
          <span className="text-xs text-muted-foreground">
            Last sync: {formatLastSync(lastSyncAt)}
          </span>
        )}
      </div>

      {isSyncing && (
        <div className="px-4 py-3 border-b">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs text-muted-foreground">Syncing changes...</span>
            <span className="text-xs font-medium">{syncProgress}%</span>
          </div>
          <Progress value={syncProgress} className="h-1.5" />
        </div>
      )}

      <ScrollArea className="h-[240px]">
        {hasItems ? (
          <div className="p-2 space-y-1">
            {allItems.map((item) => (
              <SyncQueueItemRow
                key={item.id}
                item={item}
                onRetry={() => retryOperation(item.id)}
                onRemove={() => removeOperation(item.id)}
              />
            ))}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full py-8 text-center">
            <CheckCircle className="size-8 text-success mb-2" />
            <p className="text-sm font-medium">All synced</p>
            <p className="text-xs text-muted-foreground">
              No pending changes to sync
            </p>
          </div>
        )}
      </ScrollArea>

      <Separator />
      <div className="p-3 flex items-center justify-between gap-2">
        {failedCount > 0 && (
          <Button
            variant="ghost"
            size="xs"
            onClick={retryAllFailed}
            className="text-xs"
          >
            <RefreshCw className="size-3" />
            Retry failed ({failedCount})
          </Button>
        )}
        <div className="flex-1" />
        <Button
          variant="default"

          onClick={handleSync}
          disabled={!isOnline || isSyncing || pendingCount === 0}
          className="text-xs"
        >
          {isSyncing ? (
            <>
              <RotateCw className="size-3 animate-spin" />
              Syncing...
            </>
          ) : (
            <>
              <RotateCw className="size-3" />
              Sync now
            </>
          )}
        </Button>
      </div>
    </div>
  );
}


function StatusBadge({ isOnline, isSyncing }: { isOnline: boolean; isSyncing: boolean }) {
  if (isSyncing) {
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-2 py-0.5 text-[10px] font-medium text-primary">
        <span className="h-1.5 w-1.5 rounded-full bg-primary animate-pulse" />
        Syncing
      </span>
    );
  }
  if (!isOnline) {
    return (
      <span className="inline-flex items-center gap-1 rounded-full bg-destructive/10 px-2 py-0.5 text-[10px] font-medium text-destructive">
        <span className="h-1.5 w-1.5 rounded-full bg-destructive" />
        Offline
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1 rounded-full bg-success/10 px-2 py-0.5 text-[10px] font-medium text-success">
      <span className="h-1.5 w-1.5 rounded-full bg-success" />
      Online
    </span>
  );
}


interface SyncQueueItemRowProps {
  item: SyncQueueItem;
  onRetry: () => void;
  onRemove: () => void;
}

function SyncQueueItemRow({ item, onRetry, onRemove }: SyncQueueItemRowProps) {
  const getStatusIcon = (status: SyncStatusType) => {
    switch (status) {
      case "pending":
        return <Clock className="h-3.5 w-3.5 text-muted-foreground" />;
      case "syncing":
        return <RotateCw className="h-3.5 w-3.5 text-primary animate-spin" />;
      case "completed":
        return <CheckCircle className="h-3.5 w-3.5 text-success" />;
      case "failed":
        return <AlertCircle className="h-3.5 w-3.5 text-destructive" />;
      case "conflict":
        return <AlertCircle className="h-3.5 w-3.5 text-warning" />;
      default:
        return null;
    }
  };

  const getOperationLabel = () => {
    const typeLabels = { create: "Create", update: "Update", delete: "Delete", batch: "Batch" };
    return typeLabels[item.type] || item.type;
  };

  return (
    <div className={cn(
      "flex items-center gap-2 rounded-md px-2 py-1.5 text-xs",
      item.status === "failed" && "bg-destructive/10",
      item.status === "syncing" && "bg-primary/5"
    )}>
      {getStatusIcon(item.status)}
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1">
          <span className="font-medium truncate">{item.entityName || item.entityId}</span>
          <span className="text-muted-foreground">·</span>
          <span className="text-muted-foreground capitalize">{item.entityType}</span>
        </div>
        <div className="flex items-center gap-1 text-[10px] text-muted-foreground">
          <span>{getOperationLabel()}</span>
          {item.error && <span className="text-destructive truncate">· {item.error}</span>}
        </div>
      </div>
      {item.status === "failed" && (
        <Button variant="ghost" size="icon-xs" onClick={onRetry} title="Retry">
          <RefreshCw className="size-3" />
        </Button>
      )}
      <Button variant="ghost" size="icon-xs" onClick={onRemove} title="Remove">
        <Trash2 className="size-3" />
      </Button>
    </div>
  );
}

"use client";

import {
  ShoppingCart,
  CheckCircle,
  Package,
  Truck,
  Home,
  type LucideIcon,
} from "lucide-react";
import { cn } from "@/shared/utils";

export type OrderStatus = 
  | "pending" 
  | "confirmed" 
  | "processing" 
  | "shipped" 
  | "delivered" 
  | "completed" 
  | "cancelled";

interface OrderStepperProps {
  currentStatus: OrderStatus;
  className?: string;
}

const steps = [
  { status: "pending", label: "Placed", icon: ShoppingCart },
  { status: "confirmed", label: "Confirmed", icon: CheckCircle },
  { status: "processing", label: "Processing", icon: Package },
  { status: "shipped", label: "Shipped", icon: Truck },
  { status: "delivered", label: "Delivered", icon: Home },
];

const statusToStep: Record<OrderStatus, number> = {
  pending: 1,
  confirmed: 2,
  processing: 3,
  shipped: 4,
  delivered: 5,
  completed: 5,
  cancelled: 0,
};

export function OrderStepper({ currentStatus, className }: OrderStepperProps) {
  const currentStep = statusToStep[currentStatus];

  if (currentStatus === "cancelled") {
    return (
      <div className={cn("flex items-center justify-center py-4", className)}>
        <div className="flex items-center gap-2 px-4 py-2 rounded-lg bg-destructive/10 text-destructive">
          <span className="text-sm font-medium">Order Cancelled</span>
        </div>
      </div>
    );
  }

  return (
    <div className={cn("w-full", className)}>
      <div className="flex items-center w-full">
        {steps.map((step, index) => {
          const stepNumber = index + 1;
          const isCompleted = stepNumber < currentStep;
          const isActive = stepNumber === currentStep;
          const Icon = step.icon;

          return (
            <div key={step.status} className="flex items-center flex-1 last:flex-none">
              <div className="flex flex-col items-center gap-2">
                <div
                  className={cn(
                    "size-10 rounded-lg flex items-center justify-center transition-colors",
                    isCompleted && "bg-success text-success-foreground",
                    isActive && "bg-primary text-primary-foreground ring-4 ring-primary/20",
                    !isCompleted && !isActive && "bg-muted text-muted-foreground"
                  )}
                >
                  <Icon className="size-5" />
                </div>
                <span
                  className={cn(
                    "text-xs font-medium whitespace-nowrap",
                    isCompleted && "text-success",
                    isActive && "text-primary",
                    !isCompleted && !isActive && "text-muted-foreground"
                  )}
                >
                  {step.label}
                </span>
              </div>

              {index < steps.length - 1 && (
                <div
                  className={cn(
                    "h-0.5 flex-1 mx-2 transition-colors",
                    isCompleted ? "bg-success" : "bg-muted"
                  )}
                />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client"

import { format, formatDistanceToNow } from "date-fns"
import {
    CheckCircle,
    Clock,
    Truck,
    Package,
    X,
    ShoppingCart,
    CreditCard,
    Mail,
    type LucideIcon,
} from "lucide-react"
import { cn } from "@/shared/utils"

export interface TimelineEvent {
    id: string
    type: "created" | "confirmed" | "processing" | "shipped" | "delivered" | "completed" | "cancelled" | "payment" | "note"
    title: string
    description?: string
    timestamp: string
    user?: string
}

interface OrderTimelineProps {
    events: TimelineEvent[]
}

const eventConfig: Record<string, { icon: LucideIcon; color: string; bgColor: string }> = {
    created: {
        icon: ShoppingCart,
        color: "text-primary",
        bgColor: "bg-info/10",
    },
    confirmed: {
        icon: CheckCircle,
        color: "text-success",
        bgColor: "bg-success/10",
    },
    processing: {
        icon: Package,
        color: "text-info",
        bgColor: "bg-info/10",
    },
    shipped: {
        icon: Truck,
        color: "text-primary",
        bgColor: "bg-info/10",
    },
    delivered: {
        icon: CheckCircle,
        color: "text-success",
        bgColor: "bg-success/10",
    },
    completed: {
        icon: CheckCircle,
        color: "text-success",
        bgColor: "bg-success/10",
    },
    cancelled: {
        icon: X,
        color: "text-destructive",
        bgColor: "bg-destructive/10",
    },
    payment: {
        icon: CreditCard,
        color: "text-warning",
        bgColor: "bg-warning/10",
    },
    note: {
        icon: Mail,
        color: "text-muted-foreground",
        bgColor: "bg-muted",
    },
}

export function OrderTimeline({ events }: OrderTimelineProps) {
    if (events.length === 0) {
        return (
            <p className="text-sm text-muted-foreground text-center py-4">
                No activity recorded
            </p>
        )
    }

    return (
        <div className="relative">
            {/* Timeline line */}
            <div className="absolute left-4 top-0 bottom-0 w-px bg-border" />

            <div className="space-y-4">
                {events.map((event, index) => {
                    const config = eventConfig[event.type] || eventConfig.note
                    const isFirst = index === 0

                    return (
                        <div key={event.id} className="relative flex gap-3 pl-0">
                            {/* Icon */}
                            <div
                                className={cn(
                                    "relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full",
                                    config.bgColor,
                                    isFirst && "ring-2 ring-background"
                                )}
                            >
                                <config.icon
                                    className={cn("size-4", config.color)}
                                />
                            </div>

                            {/* Content */}
                            <div className="flex-1 min-w-0 pb-4">
                                <div className="flex items-start justify-between gap-2">
                                    <div>
                                        <p className="text-sm font-medium">{event.title}</p>
                                        {event.description && (
                                            <p className="text-xs text-muted-foreground mt-0.5">
                                                {event.description}
                                            </p>
                                        )}
                                    </div>
                                    <time
                                        className="text-xs text-muted-foreground whitespace-nowrap"
                                        title={format(new Date(event.timestamp), "PPP 'at' p")}
                                    >
                                        {formatDistanceToNow(new Date(event.timestamp), { addSuffix: true })}
                                    </time>
                                </div>
                                {event.user && (
                                    <p className="text-xs text-muted-foreground mt-1">
                                        by {event.user}
                                    </p>
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
    )
}

// Helper to generate timeline events from order data
export function generateOrderTimeline(order: {
    created_at: string
    updated_at?: string
    status: string
    payment_status?: string
    notes?: string
}): TimelineEvent[] {
    const events: TimelineEvent[] = []

    // Order created
    events.push({
        id: "created",
        type: "created",
        title: "Order placed",
        description: "Customer completed checkout",
        timestamp: order.created_at,
    })

    // Payment received (if paid)
    if (order.payment_status === "paid") {
        events.push({
            id: "payment",
            type: "payment",
            title: "Payment received",
            description: "Payment confirmed",
            timestamp: order.created_at, // Assume same time as order for now
        })
    }

    // Current status (if not pending)
    if (order.status !== "pending") {
        const statusTitles: Record<string, string> = {
            confirmed: "Order confirmed",
            processing: "Processing started",
            shipped: "Order shipped",
            delivered: "Order delivered",
            completed: "Order completed",
            cancelled: "Order cancelled",
        }

        const statusDescriptions: Record<string, string> = {
            confirmed: "Order has been confirmed and is being prepared",
            processing: "Order is being processed",
            shipped: "Package is on its way",
            delivered: "Package has been delivered",
            completed: "Order has been completed",
            cancelled: "Order has been cancelled",
        }

        events.push({
            id: `status-${order.status}`,
            type: order.status as TimelineEvent["type"],
            title: statusTitles[order.status] || `Status: ${order.status}`,
            description: statusDescriptions[order.status],
            timestamp: order.updated_at || order.created_at,
        })
    }

    // Sort by timestamp descending (newest first)
    return events.sort((a, b) => 
        new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
    )
}

"use client";

import type { ReactNode } from "react";
