// ============================================================================
// TableRowSkeleton - For data table rows
// ============================================================================

interface TableRowSkeletonProps {
  columns?: number;
  showCheckbox?: boolean;
  showImage?: boolean;
  columnWidths?: string[];
  className?: string;
}

export function TableRowSkeleton({
  columns = 5,
  showCheckbox = true,
  showImage = true,
  columnWidths,
  className,
}: TableRowSkeletonProps) {
  const effectiveColumns = columns - (showCheckbox ? 1 : 0) - (showImage ? 1 : 0);

  return (
    <div className={cn("flex items-center gap-4 p-4 border-b last:border-0", className)}>
      {showCheckbox && <Skeleton className="size-4 rounded shrink-0" />}
      {showImage && <Skeleton className="size-10 rounded-lg shrink-0" />}
      {Array.from({ length: effectiveColumns }).map((_, i) => (
        <Skeleton
          key={i}
          className={cn(
            "h-4 flex-1",
            columnWidths?.[i] || (i === 0 ? "max-w-[200px]" : i === effectiveColumns - 1 ? "max-w-[80px]" : "")
          )}
        />
      ))}
    </div>
  );
}

