interface TimelineAddNoteProps {
  disabled?: boolean;
  message: string;
  placeholder?: string;
  buttonLabel?: ReactNode;
  label?: string;
  onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
  onSubmit: () => void;
  reset: () => void;
}

export function TimelineAddNote({
  disabled,
  message,
  placeholder = "Leave your note here...",
  buttonLabel = "Send",
  label,
  onChange,
  onSubmit,
  reset,
}: TimelineAddNoteProps) {
  const [isFocused, setIsFocused] = useState(false);
  const isMessageEmpty = message.trim().length === 0;
  const canSubmit = !disabled && !isMessageEmpty;

  const handleSubmit = () => {
    if (canSubmit) {
      reset();
      onSubmit();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
      e.preventDefault();
      handleSubmit();
    }
  };

  return (
    <div className="mb-6">
      <div className="relative">
        <Textarea
          disabled={disabled}
          placeholder={placeholder}
          onChange={onChange}
          onKeyDown={handleKeyDown}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          value={message}
          name="message"
          rows={3}
          className="resize-none pr-20"
        />
        {isFocused && (
          <div className="absolute bottom-2 right-2 text-xs text-muted-foreground">
            <kbd className="px-1.5 py-0.5 bg-muted rounded font-mono text-[0.6875rem] tabular-nums">⌘</kbd>
            <span className="mx-0.5">+</span>
            <kbd className="px-1.5 py-0.5 bg-muted rounded font-mono text-[0.6875rem] tabular-nums">↵</kbd>
          </div>
        )}
      </div>
      <div className="flex justify-end mt-2">
        <Button
          disabled={!canSubmit}
          onClick={handleSubmit}
          variant="secondary"

          className="gap-2"
        >
          <Send className="size-4" />
          {buttonLabel}
        </Button>
      </div>
    </div>
  );
}

