// Timeline Note
// ============================================================================

interface TimelineNoteProps {
  id: string;
  message: string;
  date: Date | string;
  actor?: TimelineActor;
  isLastInGroup?: boolean;
  onEdit?: (id: string, message: string) => Promise<void>;
  isEditing?: boolean;
}

export function TimelineNote({
  id,
  message,
  date,
  actor,
  isLastInGroup = false,
  onEdit,
  isEditing = false,
}: TimelineNoteProps) {
  const [isEditMode, setIsEditMode] = useState(false);
  const [editMessage, setEditMessage] = useState(message);
  const [isSaving, setIsSaving] = useState(false);
  const dateObj = typeof date === "string" ? parseISO(date) : date;

  const handleSave = async () => {
    if (!onEdit || editMessage.trim() === message) {
      setIsEditMode(false);
      return;
    }

    setIsSaving(true);
    try {
      await onEdit(id, editMessage);
      setIsEditMode(false);
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancel = () => {
    setEditMessage(message);
    setIsEditMode(false);
  };

  return (
    <div className="relative flex gap-4 pb-6">
      {/* Timeline line */}
      {!isLastInGroup && (
        <div className="absolute left-[15px] top-8 bottom-0 w-px bg-border" />
      )}

      {/* Avatar */}
      <Avatar className="relative z-10 size-8 shrink-0">
        {actor?.avatar && <AvatarImage src={actor.avatar} alt={actor.name} />}
        <AvatarFallback className="text-xs">
          {actor?.name?.[0]?.toUpperCase() || "U"}
        </AvatarFallback>
      </Avatar>

      {/* Content */}
      <div className="flex-1 min-w-0">
        <div className="rounded-lg border bg-muted/30 p-3">
          <div className="flex items-start justify-between gap-2 mb-2">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium">{actor?.name || "User"}</span>
              <Badge variant="secondary" className="text-[10px] px-1.5 py-0">
                Note
              </Badge>
            </div>
            <div className="flex items-center gap-2">
              <time
                className="text-xs text-muted-foreground"
                title={format(dateObj, "PPpp")}
              >
                {formatEventTime(date)}
              </time>
              {onEdit && !isEditMode && (
                <Button
                  variant="ghost"
                  size="icon-sm" aria-label="Edit note"
                  className="size-6"
                  onClick={() => setIsEditMode(true)}
                >
                  <MessageSquare className="w-3.5 h-3.5" />
                </Button>
              )}
            </div>
          </div>

          {isEditMode ? (
            <div className="space-y-2">
              <Textarea
                value={editMessage}
                onChange={(e) => setEditMessage(e.target.value)}
                rows={3}
                className="resize-none"
                disabled={isSaving}
              />
              <div className="flex justify-end gap-2">
                <Button
                  variant="ghost"

                  onClick={handleCancel}
                  disabled={isSaving}
                >
                  Cancel
                </Button>
                <Button

                  onClick={handleSave}
                  disabled={isSaving || editMessage.trim() === message}
                >
                  {isSaving ? "Saving..." : "Save"}
                </Button>
              </div>
            </div>
          ) : (
            <p className="text-sm whitespace-pre-wrap">{message}</p>
          )}
        </div>
      </div>
    </div>
  );
}

