                      <stop offset="100%" stopColor="var(--lv2-accent)" stopOpacity="0" />
                    </linearGradient>
                  </defs>
                  {[0.25, 0.5, 0.75].map((f) => (
                    <line key={f} x1={PAD} x2={W - PAD} y1={H * f} y2={H * f} stroke="var(--lv2-border)" strokeDasharray="3 5" strokeWidth="1" />
