                    </div>
                    <strong>{row.value}%</strong>
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="lv2-dash-panel">
            <div className="lv2-dash-panel__head">
              <strong>Recent events</strong>
              <span className="lv2-live-badge"><span className="lv2-dot lv2-dot--pulse" /> Streaming</span>
