const NODE_ACTIVE_RADIUS = 3.2;

// ─── Helpers ──────────────────────────────────────────────────────────────────

function lerpN(a: number, b: number, t: number) {
  return a + (b - a) * t;
}

function lerpColor(
  base: { r: number; g: number; b: number; a: number },
  active: { r: number; g: number; b: number; a: number },
  t: number,
): string {
  const r = Math.round(lerpN(base.r, active.r, t));
  const g = Math.round(lerpN(base.g, active.g, t));
  const b = Math.round(lerpN(base.b, active.b, t));
  const a = lerpN(base.a, active.a, t);
  return `rgba(${r},${g},${b},${a.toFixed(3)})`;
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function KineticGrid({
  children,
  className,
  globalColor = "default",
}: {
  children?: ReactNode;
  className?: string;
  globalColor?: "default" | "monochrome";
}) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const mouseRef = useRef<Point>({ x: -9999, y: -9999 });
  const targetMouseRef = useRef<Point>({ x: -9999, y: -9999 });
  const ripplesRef = useRef<Ripple[]>([]);
  const rafRef = useRef<number>(0);
  const isAnimatingRef = useRef<boolean>(true);
  const sizeRef = useRef<{ w: number; h: number }>({ w: 0, h: 0 });

  // ── Warp ────────────────────────────────────────────────────────────────────

  const getWarpedPoint = useCallback(
    (
      gx: number,
      gy: number,
      col: number,
      row: number,
      mouse: Point,
      ripples: Ripple[],
      cols: number,
      rows: number,
    ): { pt: Point; proximity: number } => {
      const edgeMargin = 1.5;
      const colPin = Math.min(
        col / edgeMargin,
        (cols - 1 - col) / edgeMargin,
        1,
      );
      const rowPin = Math.min(
        row / edgeMargin,
        (rows - 1 - row) / edgeMargin,
        1,
      );
      const pinFactor = colPin * colPin * rowPin * rowPin;

      const dx = gx - mouse.x;
      const dy = gy - mouse.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      const proximity =
        Math.max(0, 1 - dist / INFLUENCE_RADIUS) * pinFactor;

      // Ripple displacement
      let rx = 0,
        ry = 0;
      for (const r of ripples) {
        const rdx = gx - r.x;
        const rdy = gy - r.y;
        const rdist = Math.sqrt(rdx * rdx + rdy * rdy);
        const waveWidth = 55;
        const diff = rdist - r.radius;
        if (Math.abs(diff) < waveWidth) {
          const strength =
            (1 - Math.abs(diff) / waveWidth) * r.opacity * 18 * pinFactor;
          const angle = Math.atan2(rdy, rdx);
          const sign = diff < 0 ? -1 : 1;
          rx += Math.cos(angle) * strength * sign * -1;
          ry += Math.sin(angle) * strength * sign * -1;
        }
      }

      // Cursor warp with bell falloff
      if (dist < INFLUENCE_RADIUS && dist > 0 && pinFactor > 0) {
        const t = dist / INFLUENCE_RADIUS;
        const eased =
          t < 0.01 ? 0 : (1 - t) * (1 - t) * Math.min(1, dist / 60);
        const warpAmt = eased * MAX_WARP * pinFactor;
        const angle = Math.atan2(dy, dx);
        return {
          pt: {
            x: gx - Math.cos(angle) * warpAmt + rx,
            y: gy - Math.sin(angle) * warpAmt + ry,
          },
          proximity,
        };
      }

      return { pt: { x: gx + rx, y: gy + ry }, proximity };
    },
    [],
  );

  const [themeMode, setThemeMode] = useState<"light" | "dark">("dark");


  // ── Draw ────────────────────────────────────────────────────────────────────

  const draw = useCallback(
    (now: number) => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;

      const { w: W, h: H } = sizeRef.current;
      const mouse = mouseRef.current;
      const ripples = ripplesRef.current;

      const isLight = themeMode === "light";
      const lineBase = isLight ? { r: 0, g: 0, b: 0, a: 0.06 } : { r: 255, g: 255, b: 255, a: 0.13 };

      const theme = {
        default: {
          lineActive: { r: 123, g: 97, b: 255, a: 0.9 },
          nodeActive: { r: 123, g: 97, b: 255, a: 1.0 },
          glow: "123,97,255",
          ripple: "140,120,255",
        },
        monochrome: {
          lineActive: isLight ? { r: 0, g: 0, b: 0, a: 0.9 } : { r: 255, g: 255, b: 255, a: 0.9 },
          nodeActive: isLight ? { r: 0, g: 0, b: 0, a: 1.0 } : { r: 255, g: 255, b: 255, a: 1.0 },
          glow: isLight ? "0,0,0" : "255,255,255",
          ripple: isLight ? "0,0,0" : "255,255,255",
        },
      }[globalColor ?? "default"];

      // Truly transparent background
      ctx.clearRect(0, 0, W, H);

      // Static background dot texture
      ctx.fillStyle = isLight ? "rgba(0,0,0,0.04)" : "rgba(255,255,255,0.04)";
      for (let x = DOT_SPACING / 2; x < W; x += DOT_SPACING) {
        for (let y = DOT_SPACING / 2; y < H; y += DOT_SPACING) {
          ctx.beginPath();
          ctx.arc(x, y, 0.7, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      // Update ripples
      for (let i = ripples.length - 1; i >= 0; i--) {
        const r = ripples[i];
        const age = (now - r.born) / 1000;
        r.radius = Math.max(0, age * 400);
        r.opacity = Math.max(0, 1 - age * 1.2);
        if (r.opacity <= 0) ripples.splice(i, 1);
      }

      // ── Build warped grid ─────────────────────────────────────────────────
      const cols = Math.max(2, Math.ceil(W / CELL_SIZE)) + 1;
      const rows = Math.max(2, Math.ceil(H / CELL_SIZE)) + 1;
      const cellW = W / (cols - 1);
      const cellH = H / (rows - 1);

      const pts: Point[][] = [];
      const prox: number[][] = [];

      for (let row = 0; row < rows; row++) {
        pts[row] = [];
        prox[row] = [];
        for (let col = 0; col < cols; col++) {
          const { pt, proximity } = getWarpedPoint(
            col * cellW,
            row * cellH,
            col,
            row,
            mouse,
            ripples,
            cols,
            rows,
          );
          pts[row][col] = pt;
          prox[row][col] = proximity;
        }
      }

      // ── Grid lines ────────────────────────────────────────────────────────
      const drawSeg = (p1: Point, p2: Point, pr1: number, pr2: number) => {
        const avg = (pr1 + pr2) / 2;
        const t = avg * avg * (3 - 2 * avg);
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = lerpColor(lineBase, theme.lineActive, t);
        ctx.lineWidth = lerpN(0.8, 1.5, t);
        ctx.stroke();
      };

      ctx.lineCap = "butt";

      for (let row = 0; row < rows; row++)
        for (let col = 0; col < cols - 1; col++)
          drawSeg(
            pts[row][col],
            pts[row][col + 1],
            prox[row][col],
            prox[row][col + 1],
          );

      for (let col = 0; col < cols; col++)
        for (let row = 0; row < rows - 1; row++)
          drawSeg(
            pts[row][col],
            pts[row + 1][col],
            prox[row][col],
            prox[row + 1][col],
          );

      // ── Intersection nodes ────────────────────────────────────────────────
      for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
          const p = pts[row][col];
          const pr = prox[row][col];
          const t = pr * pr * (3 - 2 * pr);
          const r = lerpN(NODE_BASE_RADIUS, NODE_ACTIVE_RADIUS, t);

          // Outer glow ring for active nodes
          if (t > 0.3) {
            const glowR = r + lerpN(0, 6, (t - 0.3) / 0.7);
            const grd = ctx.createRadialGradient(
              p.x,
              p.y,
              r * 0.5,
              p.x,
              p.y,
              glowR,
            );
            grd.addColorStop(
              0,
              `rgba(${theme.glow},${(t * 0.3).toFixed(3)})`,
            );
            grd.addColorStop(1, `rgba(${theme.glow},0)`);
            ctx.beginPath();
            ctx.arc(p.x, p.y, glowR, 0, Math.PI * 2);
            ctx.fillStyle = grd;
            ctx.fill();
          }

          // Node fill
          ctx.beginPath();
          ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
          const nodeBase = isLight ? { r: 0, g: 0, b: 0, a: 0.15 } : { r: 255, g: 255, b: 255, a: 0.2 };
          ctx.fillStyle = lerpColor(nodeBase, theme.nodeActive, t);
          ctx.fill();
        }
      }

      // ── Ripple rings ──────────────────────────────────────────────────────
      for (const r of ripples) {
        const safeRadius = Math.max(0, r.radius);
        ctx.beginPath();
        ctx.arc(r.x, r.y, safeRadius, 0, Math.PI * 2);
        ctx.strokeStyle = `rgba(${theme.ripple},${(r.opacity * 0.28).toFixed(3)})`;
        ctx.lineWidth = 1.5;
        ctx.stroke();
      }
    },
    [getWarpedPoint, globalColor, themeMode],
  );

  // ── Animation loop ──────────────────────────────────────────────────────────

  const animate = useCallback(
    (now: number) => {
      const m = mouseRef.current;
      const t = targetMouseRef.current;

      m.x = lerpN(m.x, t.x, LERP_SPEED);
      m.y = lerpN(m.y, t.y, LERP_SPEED);

      draw(now);

      const dx = Math.abs(m.x - t.x);
      const dy = Math.abs(m.y - t.y);
      if (dx < 0.1 && dy < 0.1 && ripplesRef.current.length === 0) {
        isAnimatingRef.current = false;
        return;
      }

      rafRef.current = requestAnimationFrame(animate);
    },
    [draw],
  );

  useEffect(() => {
    const root = document.documentElement;
    const observer = new MutationObserver(() => {
      setThemeMode(root.dataset.theme === "light" ? "light" : "dark");
      // Wake up loop to redraw in new theme
      if (!isAnimatingRef.current) {
        isAnimatingRef.current = true;
        rafRef.current = requestAnimationFrame(animate);
      }
    });
    setThemeMode(root.dataset.theme === "light" ? "light" : "dark");
    observer.observe(root, { attributes: true, attributeFilter: ["data-theme"] });
    return () => observer.disconnect();
  }, [animate]);

  // ── Setup ───────────────────────────────────────────────────────────────────

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const wakeUp = () => {
      if (!isAnimatingRef.current) {
        isAnimatingRef.current = true;
        rafRef.current = requestAnimationFrame(animate);
      }
    };

    const setSize = () => {
      const w = window.innerWidth;
      const h = window.innerHeight;
      canvas.width = w;
      canvas.height = h;
      sizeRef.current = { w, h };
      if (mouseRef.current.x === -9999) {
        mouseRef.current = { x: -9999, y: -9999 };
        targetMouseRef.current = { x: -9999, y: -9999 };
      }
      wakeUp();
    };

    setSize();
    window.addEventListener("resize", setSize);

    const onMouseMove = (e: MouseEvent) => {
      targetMouseRef.current = { x: e.clientX, y: e.clientY };
      wakeUp();
    };

    const onTouchMove = (e: TouchEvent) => {
      targetMouseRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      wakeUp();
    };

    const onClick = (e: MouseEvent) => {
      ripplesRef.current.push({
        x: e.clientX,
        y: e.clientY,
        radius: 0,
        opacity: 1,
        born: performance.now(),
      });
      wakeUp();
    };

    const onTouchStart = (e: TouchEvent) => {
      // Don't duplicate click ripples on touch devices (which also fire clicks)
      targetMouseRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      wakeUp();
    };

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("click", onClick);
    window.addEventListener("touchmove", onTouchMove, { passive: true });
    window.addEventListener("touchstart", onTouchStart, { passive: true });
    isAnimatingRef.current = true;
    rafRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener("resize", setSize);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("click", onClick);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("touchstart", onTouchStart);
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [animate]);

  // ── Render ──────────────────────────────────────────────────────────────────

  return (
    <div
      className={cn(
        "relative w-full min-h-screen overflow-hidden",
        className,
      )}
    >
      <canvas
        ref={canvasRef}
        className="fixed inset-0 h-full w-full pointer-events-none"
        style={{ zIndex: 0 }}
      />

      <div className="relative z-10 w-full h-full">{children}</div>
    </div>
  );
}

"use client"

import { useEffect, useState, useTransition } from "react"
import { usePathname, useSearchParams } from "next/navigation"
import { cn } from "@/shared/utils"

interface NavigationProgressProps {
  /**
   * Color of the progress bar
   * @default "var(--primary)"
   */
  color?: string
  /**
   * Height of the progress bar in pixels
   * @default 3
   */
  height?: number
  /**
   * Delay before showing the progress bar (ms)
   * @default 100
   */
  delay?: number
  /**
   * Z-index of the progress bar
   * @default 9999
   */
  zIndex?: number
}

/**
 * Global navigation progress bar that shows during route transitions.
 * Add this to your root layout for app-wide navigation feedback.
 * 
 * @example
 * ```tsx
 * // In layout.tsx
 * <NavigationProgress />
 * ```
 */
export function NavigationProgress({
  color = "var(--primary)",
  height = 3,
  delay = 100,
  zIndex = 9999,
}: NavigationProgressProps) {
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [isNavigating, setIsNavigating] = useState(false)
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    // Reset on route change
    setIsNavigating(false)
    setProgress(0)
  }, [pathname, searchParams])

  useEffect(() => {
    if (!isNavigating) return

    // Simulate progress
    const timer1 = setTimeout(() => setProgress(30), 100)
    const timer2 = setTimeout(() => setProgress(60), 300)
    const timer3 = setTimeout(() => setProgress(80), 600)

    return () => {
      clearTimeout(timer1)
      clearTimeout(timer2)
      clearTimeout(timer3)
    }
  }, [isNavigating])

  // Listen for navigation start via click events on links
  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      const link = target.closest("a")

      if (!link) return

      const href = link.getAttribute("href")
      if (!href) return

      // Skip external links, hash links, and same-page links
      if (
        href.startsWith("http") ||
        href.startsWith("#") ||
        href.startsWith("mailto:") ||
        href.startsWith("tel:") ||
        link.target === "_blank"
      ) {
        return
      }

      // Check if it's a different route
      const url = new URL(href, window.location.origin)
      if (url.pathname !== pathname || url.search !== searchParams.toString()) {
        // Delay showing progress to avoid flash for fast navigations
        const timer = setTimeout(() => {
          setIsNavigating(true)
          setProgress(10)
        }, delay)

        // Clean up if navigation completes quickly
        return () => clearTimeout(timer)
      }
    }

    document.addEventListener("click", handleClick)
    return () => document.removeEventListener("click", handleClick)
  }, [pathname, searchParams, delay])

  if (!isNavigating || progress === 0) return null

  return (
    <div
      className="fixed top-0 left-0 right-0 pointer-events-none"
      style={{ zIndex }}
    >
      <div
        className={cn(
          "h-full transition-[width] duration-300 ease-out",
          progress === 100 && "opacity-0"
        )}
        style={{
          height,
          width: `${progress}%`,
          backgroundColor: color,
          boxShadow: `0 0 10px ${color}, 0 0 5px ${color}`,
        }}
      />
    </div>
  )
}

"use client"

import Link, { LinkProps } from "next/link"
import { useRouter } from "next/navigation"
import { useState, forwardRef, type ComponentProps } from "react"
import { cn } from "@/shared/utils"

/**
 * HoverPrefetchLink - Only prefetches on hover
 * 
 * Use for large lists (product grids, infinite scroll tables) where
 * prefetching all links in viewport would be wasteful.
 * 
 * @example
 * ```tsx
 * // Product grid with many items
 * {products.map(product => (
 *   <HoverPrefetchLink key={product.id} href={`/products/${product.slug}`}>
 *     {product.name}
 *   </HoverPrefetchLink>
 * ))}
 * ```
 */
export const HoverPrefetchLink = forwardRef<
  HTMLAnchorElement,
  ComponentProps<typeof Link>
>(({ children, className, ...props }, ref) => {
  const [active, setActive] = useState(false)

  return (
    <Link
      ref={ref}
      {...props}
      prefetch={active ? undefined : false}
      onMouseEnter={() => setActive(true)}
      className={className}
    >
      {children}
    </Link>
  )
})

HoverPrefetchLink.displayName = "HoverPrefetchLink"

/**
 * NoPrefetchLink - Never prefetches
 * 
 * Use for low-priority links like footer navigation where
 * prefetching is unnecessary.
 * 
 * @example
 * ```tsx
 * // Footer links
 * <NoPrefetchLink href="/privacy">Privacy Policy</NoPrefetchLink>
 * <NoPrefetchLink href="/terms">Terms of Service</NoPrefetchLink>
 * ```
 */
export const NoPrefetchLink = forwardRef<
  HTMLAnchorElement,
  Omit<ComponentProps<typeof Link>, "prefetch">
>(({ children, className, ...props }, ref) => {
  return (
    <Link ref={ref} {...props} prefetch={false} className={className}>
      {children}
    </Link>
  )
})

NoPrefetchLink.displayName = "NoPrefetchLink"

/**
 * ManualPrefetchLink - Prefetches on mount
 * 
 * Use when you need to ensure a route is prefetched immediately
 * when the component mounts, regardless of viewport visibility.
 * 
 * @example
 * ```tsx
 * // Critical navigation that should always be ready
 * <ManualPrefetchLink href="/dashboard">Dashboard</ManualPrefetchLink>
 * ```
 */
export function ManualPrefetchLink({
  href,
  children,
  className,
  ...props
}: Omit<ComponentProps<"a">, "href"> & { href: string }) {
  const router = useRouter()
  const [hasPrefetched, setHasPrefetched] = useState(false)

  // Prefetch on mount
  if (!hasPrefetched && typeof window !== "undefined") {
    router.prefetch(href)
    setHasPrefetched(true)
  }

  return (
    <a
      href={href}
      onClick={(event) => {
        event.preventDefault()
        router.push(href)
      }}
      className={className}
      {...props}
    >
      {children}
    </a>
  )
}

/**
 * PrefetchOnVisible - Prefetches when element enters viewport
 * 
 * Use for below-the-fold content that should prefetch when scrolled into view.
 * 
 * @example
 * ```tsx
 * <PrefetchOnVisible href="/features">
 *   Learn about features
 * </PrefetchOnVisible>
 * ```
 */
export const PrefetchOnVisible = forwardRef<
  HTMLAnchorElement,
  ComponentProps<typeof Link> & { rootMargin?: string }
>(({ children, className, href, rootMargin = "100px", ...props }, ref) => {
  const router = useRouter()
  const [hasPrefetched, setHasPrefetched] = useState(false)

  return (
    <Link
      ref={(node) => {
        // Handle forwarded ref
        if (typeof ref === "function") ref(node)
        else if (ref) ref.current = node

        // Set up intersection observer
        if (node && !hasPrefetched && typeof IntersectionObserver !== "undefined") {
          const observer = new IntersectionObserver(
            (entries) => {
              if (entries[0]?.isIntersecting) {
                router.prefetch(typeof href === "string" ? href : href.pathname || "")
                setHasPrefetched(true)
                observer.disconnect()
              }
            },
            { rootMargin }
          )
          observer.observe(node)
        }
      }}
      href={href}
      prefetch={false}
      className={className}
      {...props}
    >
      {children}
    </Link>
  )
})

PrefetchOnVisible.displayName = "PrefetchOnVisible"

/**
 * CardPrefetchLink - Prefetches when hovering anywhere on parent card
 * 
 * Use for product cards where the entire card should trigger prefetch.
 * 
 * @example
 * ```tsx
 * <div onMouseEnter={() => prefetch("/product/123")}>
 *   <CardPrefetchLink href="/product/123">
 *     <ProductCard />
 *   </CardPrefetchLink>
 * </div>
 * ```
 */
export function useCardPrefetch(href: string) {
  const router = useRouter()
  const [hasPrefetched, setHasPrefetched] = useState(false)

  const prefetch = () => {
    if (!hasPrefetched) {
      router.prefetch(href)
      setHasPrefetched(true)
    }
  }

  return { prefetch, hasPrefetched }
}

/**
 * Price Component
 * 
 * Displays formatted prices with currency support.
 * Uses tenant currency from context by default.
 * 
 * @see SYSTEM-ARCHITECTURE.md Section 5.2.1
 */

import { cn } from "@/shared/utils";
import { formatPrice, type CurrencyCode, type FormatPriceOptions } from "@/shared/currency";

export interface PriceProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Price amount (number or decimal string) */
  amount: number | string;
  /** Currency code (uses tenant currency from context if not provided) */
  currency?: string;
  /** Show currency symbol (default: true) */
  showSymbol?: boolean;
  /** Show currency code instead of symbol */
  showCode?: boolean;
  /** Override decimal places */
  decimals?: number;
  /** Use compact notation for large numbers */
  compact?: boolean;
  /** Original price for showing discounts */
  originalAmount?: number | string;
  /** Show discount percentage badge */
  showDiscountBadge?: boolean;
  /** Size variant */
  size?: "xs" | "sm" | "default" | "lg" | "xl";
}

const sizeClasses = {
  xs: "text-xs",
  sm: "text-sm",
  default: "text-base",
  lg: "text-lg",
  xl: "text-2xl font-semibold",
};

/**
 * Price display component
 * 
 * @example
 * ```tsx
 * // Basic usage
 * <Price amount={99.99} />
 * 
 * // With specific currency
 * <Price amount={99.99} currency="EUR" />
 * 
 * // With discount
 * <Price amount={79.99} originalAmount={99.99} showDiscountBadge />
 * 
 * // Compact for large numbers
 * <Price amount={1500000} compact />
 * 
 * // Different sizes
 * <Price amount={99.99} size="xl" />
 * ```
 */
export function Price({
  amount,
  currency = "NPR",
  showSymbol = true,
  showCode = false,
  decimals,
  compact = false,
  originalAmount,
  showDiscountBadge = false,
  size = "default",
  className,
  ...props
}: PriceProps) {
  const numAmount = typeof amount === "string" ? parseFloat(amount) : amount;
  const numOriginal = originalAmount
    ? typeof originalAmount === "string"
      ? parseFloat(originalAmount)
      : originalAmount
    : null;

  const hasDiscount = numOriginal !== null && numOriginal > numAmount;
  const discountPercentage = hasDiscount
    ? Math.round(((numOriginal - numAmount) / numOriginal) * 100)
    : 0;

  const formatOptions: FormatPriceOptions = {
    showSymbol,
    showCode,
    compact,
    ...(decimals !== undefined && { decimals }),
  };

  const formattedPrice = formatPrice(numAmount, currency, formatOptions);
  const formattedOriginal = numOriginal
    ? formatPrice(numOriginal, currency, formatOptions)
    : null;

  if (hasDiscount) {
    return (
      <span
        data-slot="price"
        className={cn("inline-flex items-center gap-2", className)}
        {...props}
      >
        <span className={cn(sizeClasses[size], "font-semibold text-foreground")}>
          {formattedPrice}
        </span>
        <span
          className={cn(
            sizeClasses[size === "xl" ? "lg" : size === "lg" ? "default" : "sm"],
            "text-muted-foreground line-through"
          )}
        >
          {formattedOriginal}
        </span>
        {showDiscountBadge && discountPercentage > 0 && (
          <span className="inline-flex items-center rounded-full bg-destructive/10 px-2 py-0.5 text-xs font-medium text-destructive">
            -{discountPercentage}%
          </span>
        )}
      </span>
    );
  }

  return (
    <span
      data-slot="price"
      className={cn(sizeClasses[size], "font-semibold", className)}
      {...props}
    >
      {formattedPrice}
    </span>
  );
}

/**
 * Price range component
 * 
 * @example
 * ```tsx
 * <PriceRange min={10} max={50} currency="USD" />
 * ```
 */
export interface PriceRangeProps extends Omit<PriceProps, "amount" | "originalAmount"> {
  /** Minimum price */
  min: number | string;
  /** Maximum price */
  max: number | string;
  /** Separator between prices */
  separator?: string;
}

export function PriceRange({
  min,
  max,
  currency = "NPR",
  separator = " - ",
  showSymbol = true,
  size = "default",
  className,
  ...props
}: PriceRangeProps) {
  const numMin = typeof min === "string" ? parseFloat(min) : min;
  const numMax = typeof max === "string" ? parseFloat(max) : max;

  // If min and max are the same, just show one price
  if (numMin === numMax) {
    return (
      <Price
        amount={numMin}
        currency={currency}
        showSymbol={showSymbol}
        size={size}
        className={className}
        {...props}
      />
    );
  }

  const formatOptions: FormatPriceOptions = { showSymbol };
  const formattedMin = formatPrice(numMin, currency, formatOptions);
  const formattedMax = formatPrice(numMax, currency, { ...formatOptions, showSymbol: false });

  return (
    <span
      data-slot="price-range"
      className={cn(sizeClasses[size], "font-semibold", className)}
      {...props}
    >
      {formattedMin}
      {separator}
      {showSymbol ? formatPrice(numMax, currency, formatOptions) : formattedMax}
    </span>
  );
}

/**
 * Free price badge
 * 
 * @example
 * ```tsx
 * {price === 0 ? <FreePrice /> : <Price amount={price} />}
 * ```
 */
export interface FreePriceProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Text to display (default: "Free") */
  text?: string;
  /** Size variant */
  size?: "xs" | "sm" | "default" | "lg" | "xl";
}

export function FreePrice({
  text = "Free",
  size = "default",
  className,
  ...props
}: FreePriceProps) {
  return (
    <span
      data-slot="free-price"
      className={cn(
        sizeClasses[size],
        "font-semibold text-primary",
        className
      )}
      {...props}
    >
      {text}
    </span>
  );
}

/**
 * Smart price component that handles zero prices
 * 
 * @example
 * ```tsx
 * <SmartPrice amount={product.price} currency={tenant.currency} />
 * ```
 */
export interface SmartPriceProps extends PriceProps {
  /** Text to show for free items */
  freeText?: string;
}

export function SmartPrice({
  amount,
  freeText = "Free",
  ...props
}: SmartPriceProps) {
  const numAmount = typeof amount === "string" ? parseFloat(amount) : amount;

  if (numAmount === 0 || isNaN(numAmount)) {
    return <FreePrice text={freeText} size={props.size} className={props.className} />;
  }

  return <Price amount={amount} {...props} />;
}

import { pgTable, uuid, text, timestamp, integer, decimal, boolean, index, check, jsonb } from "drizzle-orm/pg-core";
import { relations, sql } from "drizzle-orm";
import { tenants } from "./tenants";
import { products, productVariants } from "./products";

/**
 * Carts table - Tenant-scoped
 * 
 * @see SYSTEM-ARCHITECTURE.md Section 9.2 (F006)
 * @see IMPLEMENTATION-PLAN.md Section 3.2
 * 
 * RLS Policy: tenant_id = current_setting('app.current_tenant')::uuid
 */
export const carts = pgTable("carts", {
    id: uuid("id").defaultRandom().primaryKey(),
    tenantId: uuid("tenant_id").references(() => tenants.id, { onDelete: "cascade" }).notNull(),
    customerId: text("customer_id"), // Can be null for guest carts

    // Customer Info (for checkout)
    email: text("email"),
    customerName: text("customer_name"),
    customerPhone: text("customer_phone"),

    currency: text("currency").default("USD").notNull(),

    // Status: active, completed, abandoned
    status: text("status").default("active").notNull(),

    // Shipping Address
    shippingAddress: text("shipping_address"),
    shippingCity: text("shipping_city"),
    shippingArea: text("shipping_area"),
    shippingPostalCode: text("shipping_postal_code"),
    shippingCountry: text("shipping_country"),

    // Billing Address
    billingAddress: text("billing_address"),

    // Totals (calculated)
    subtotal: decimal("subtotal").default("0").notNull(),
    discountTotal: decimal("discount_total").default("0").notNull(),
    shippingTotal: decimal("shipping_total").default("0").notNull(),
    taxTotal: decimal("tax_total").default("0").notNull(),
    total: decimal("total").default("0").notNull(),

    // Voucher/Discount
    discountId: uuid("discount_id"),
    voucherCodeId: uuid("voucher_code_id"),
    voucherCode: text("voucher_code"),

    // Metadata (JSONB for flexible flags like recovery_email_sent)
    metadata: jsonb("metadata").$type<Record<string, unknown>>(),

    // Timestamps
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
    tenantCustomerIdx: index("carts_tenant_customer_idx").on(table.tenantId, table.customerId),
    statusIdx: index("carts_status_idx").on(table.status),
    activeCartIdx: index("carts_active_idx").on(table.tenantId).where(sql`status = 'active'`),
}));

/**
 * Cart items table
 */
export const cartItems = pgTable("cart_items", {
    id: uuid("id").defaultRandom().primaryKey(),
    tenantId: uuid("tenant_id").references(() => tenants.id, { onDelete: "cascade" }).notNull(),
    cartId: uuid("cart_id").references(() => carts.id, { onDelete: 'cascade' }).notNull(),

    // Product Link
    productId: uuid("product_id").references(() => products.id, { onDelete: "set null" }),
    variantId: uuid("variant_id").references(() => productVariants.id, { onDelete: "set null" }),

    // Snapshot of product data at time of addition (to prevent price change issues)
    productName: text("product_name").notNull(),
    productSku: text("product_sku"),
    productImage: text("product_image"),

    quantity: integer("quantity").default(1).notNull(),

    // Pricing (stored as decimal for precision)
    unitPrice: decimal("unit_price").notNull(),
    compareAtPrice: decimal("compare_at_price"),

    // Timestamps
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
    tenantIdx: index("cart_items_tenant_idx").on(table.tenantId),
    cartIdx: index("cart_items_cart_idx").on(table.cartId),
    quantityPositive: check("cart_items_quantity_positive", sql`quantity > 0`),
}));

/**
 * Cart relations for Drizzle query builder
 */
export const cartsRelations = relations(carts, ({ many }) => ({
    items: many(cartItems),
}));

export const cartItemsRelations = relations(cartItems, ({ one }) => ({
    cart: one(carts, {
        fields: [cartItems.cartId],
        references: [carts.id],
    }),
    product: one(products, {
        fields: [cartItems.productId],
        references: [products.id],
    }),
    variant: one(productVariants, {
        fields: [cartItems.variantId],
        references: [productVariants.id],
    }),
}));

import { pgTable, uuid, text, timestamp, boolean, integer, index, unique } from "drizzle-orm/pg-core";
import { tenants } from "./tenants";
import { users } from "./users";

/**
 * Notification Categories
 * 
 * @see IMPLEMENTATION-PLAN.md Section 4.1
 */
export type NotificationCategory = 
  | "orders"      // New orders, order updates, cancellations
  | "inventory"   // Low stock alerts, restock notifications
  | "system"      // Platform updates, maintenance, security
  | "mentions";   // Team mentions, comments, assignments

/**
 * Notification Channels
 */
export type NotificationChannel = 
  | "in_app"      // In-app notification center
  | "email"       // Email notifications
  | "push"        // Push notifications (future)
  | "whatsapp"    // WhatsApp via Business API
  | "sms";        // SMS via Sparrow SMS

/**
 * Notification Frequency
 */
export type NotificationFrequency = 
  | "realtime"    // Immediate delivery
  | "daily"       // Daily digest
  | "weekly";     // Weekly digest

/**
 * Notification Preferences Table - User-scoped within tenant
 * 
 * Stores per-user notification preferences for each category/channel combination.
 * 
 * RLS Policy: tenant_id = current_setting('app.current_tenant')::uuid
 */
export const notificationPreferences = pgTable("notification_preferences", {
  id: uuid("id").defaultRandom().primaryKey(),
  tenantId: uuid("tenant_id").references(() => tenants.id).notNull(),
  userId: uuid("user_id").references(() => users.id).notNull(),

  // Preference configuration
  category: text("category").notNull().$type<NotificationCategory>(),
  channel: text("channel").notNull().$type<NotificationChannel>(),
  enabled: boolean("enabled").default(true).notNull(),
  frequency: text("frequency").default("realtime").$type<NotificationFrequency>(),

  // Timestamps
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
  // Index for efficient lookups
  tenantUserIdx: index("notification_prefs_tenant_user_idx").on(table.tenantId, table.userId),
  // Unique constraint: one preference per user/category/channel combination
  uniquePreference: unique("notification_prefs_unique").on(table.userId, table.category, table.channel),
}));

/**
 * Quiet Hours Settings Table - User-scoped within tenant
 * 
 * Stores quiet hours configuration per user.
 * During quiet hours, non-urgent notifications are held for later delivery.
 */
export const quietHoursSettings = pgTable("quiet_hours_settings", {
  id: uuid("id").defaultRandom().primaryKey(),
  tenantId: uuid("tenant_id").references(() => tenants.id).notNull(),
  userId: uuid("user_id").references(() => users.id).notNull(),

  // Quiet hours configuration
  enabled: boolean("enabled").default(false).notNull(),
  startTime: text("start_time").default("22:00"), // HH:MM format
  endTime: text("end_time").default("08:00"),     // HH:MM format
  timezone: text("timezone").default("UTC"),

  // Timestamps
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
  // Index for efficient lookups
  tenantUserIdx: index("quiet_hours_tenant_user_idx").on(table.tenantId, table.userId),
  // Unique constraint: one quiet hours setting per user
  uniqueUser: unique("quiet_hours_unique_user").on(table.userId),
}));

/**
 * Type exports for use in repositories and actions
 */
export type NotificationPreference = typeof notificationPreferences.$inferSelect;
export type NotificationPreferenceInsert = typeof notificationPreferences.$inferInsert;
export type QuietHoursSetting = typeof quietHoursSettings.$inferSelect;
export type QuietHoursSettingInsert = typeof quietHoursSettings.$inferInsert;

