"use client";

import { useMemo } from "react";
import { cn, formatCurrency } from "@/shared/utils";

interface CategoryData {
    id: string;
    name: string;
    revenue: number;
    percentage: number;
}

interface DonutChartProps {
    data: CategoryData[];
    currency: string;
}

export function DonutChart({ data, currency }: DonutChartProps) {
    const total = useMemo(() => data.reduce((sum, d) => sum + d.revenue, 0), [data]);

    const colors = [
        "stroke-chart-1",
        "stroke-chart-2", 
        "stroke-chart-3",
        "stroke-chart-4",
        "stroke-chart-5",
    ];

    // Calculate segments
    const segments = useMemo(() => {
        let currentAngle = 0;
        return data.map((item, index) => {
            const angle = (item.percentage / 100) * 360;
            const segment = {
                ...item,
                startAngle: currentAngle,
                endAngle: currentAngle + angle,
                color: colors[index % colors.length],
            };
            currentAngle += angle;
            return segment;
        });
    }, [data]);

    if (data.length === 0) {
        return (
            <div className="flex items-center justify-center h-[160px]">
                <p className="text-sm text-muted-foreground">No data</p>
            </div>
        );
    }

    // SVG donut chart
    const size = 160;
    const strokeWidth = 24;
    const radius = (size - strokeWidth) / 2;
    const circumference = 2 * Math.PI * radius;
    const center = size / 2;

    return (
        <div className="flex items-center justify-center">
            <div className="relative">
                <svg width={size} height={size} className="-rotate-90">
                    {segments.map((segment, index) => {
                        const dashArray = (segment.percentage / 100) * circumference;
                        const dashOffset = segments
                            .slice(0, index)
                            .reduce((sum, s) => sum + (s.percentage / 100) * circumference, 0);

                        return (
                            <circle
                                key={segment.id}
                                cx={center}
                                cy={center}
                                r={radius}
                                fill="none"
                                strokeWidth={strokeWidth}
                                className={cn(segment.color, "transition-colors duration-300")}
                                strokeDasharray={`${dashArray} ${circumference}`}
                                strokeDashoffset={-dashOffset}
                                strokeLinecap="round"
                            />
                        );
                    })}
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-2xl font-semibold">{formatCurrency(total, currency)}</span>
                    <span className="text-xs text-muted-foreground">Total</span>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useMemo } from "react";
import { format } from "date-fns";
import { cn, formatCurrency } from "@/shared/utils";
import {
    Tooltip,
    TooltipContent,
    TooltipTrigger,
} from "@/components/ui/tooltip";

interface RevenueDataPoint {
    date: string;
    revenue: number;
    orders: number;
}

interface RevenueChartProps {
    data: RevenueDataPoint[];
    currency: string;
}

export function RevenueChart({ data, currency }: RevenueChartProps) {
    const { maxRevenue, totalRevenue, totalOrders } = useMemo(() => {
        const max = Math.max(...data.map(d => d.revenue), 1);
        const total = data.reduce((sum, d) => sum + d.revenue, 0);
        const orders = data.reduce((sum, d) => sum + d.orders, 0);
        return { maxRevenue: max, totalRevenue: total, totalOrders: orders };
    }, [data]);

    if (data.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center h-[200px]">
                <p className="text-sm text-muted-foreground">No data available</p>
            </div>
        );
    }

    // Limit bars for readability
    const displayData = data.length > 31 ? data.filter((_, i) => i % Math.ceil(data.length / 31) === 0) : data;

    return (
        <div className="space-y-4">
            {/* Summary */}
            <div className="flex items-center gap-6 text-sm">
                <div>
                    <span className="text-muted-foreground">Total: </span>
                    <span className="font-semibold">{formatCurrency(totalRevenue, currency)}</span>
                </div>
                <div>
                    <span className="text-muted-foreground">Orders: </span>
                    <span className="font-semibold">{totalOrders}</span>
                </div>
                <div>
                    <span className="text-muted-foreground">Avg/day: </span>
                    <span className="font-semibold">{formatCurrency(totalRevenue / data.length, currency)}</span>
                </div>
            </div>

            {/* Chart */}
            <div className="h-[200px] flex items-end gap-1">
                {displayData.map((point, index) => {
                    const height = maxRevenue > 0 ? (point.revenue / maxRevenue) * 100 : 0;
                    const isWeekend = new Date(point.date).getDay() === 0 || new Date(point.date).getDay() === 6;

                    return (
                        <Tooltip key={point.date}>
                            <TooltipTrigger asChild>
                                <div
                                    className="flex-1 min-w-[4px] max-w-[24px] group cursor-pointer"
                                    style={{ height: "100%" }}
                                >
                                    <div
                                        className={cn(
                                            "w-full rounded-t transition-colors duration-200",
                                            "bg-chart-1 group-hover:bg-chart-1/80",
                                            isWeekend && "bg-chart-1/60"
                                        )}
                                        style={{ 
                                            height: `${Math.max(height, 2)}%`,
                                            marginTop: `${100 - Math.max(height, 2)}%`
                                        }}
                                    />
                                </div>
                            </TooltipTrigger>
                            <TooltipContent>
                                <div className="text-xs space-y-1">
                                    <p className="font-medium">{format(new Date(point.date), "MMM d, yyyy")}</p>
                                    <p>Revenue: {formatCurrency(point.revenue, currency)}</p>
                                    <p>Orders: {point.orders}</p>
                                </div>
                            </TooltipContent>
                        </Tooltip>
                    );
                })}
            </div>

            {/* X-axis labels */}
            <div className="flex justify-between text-xs text-muted-foreground">
                <span>{format(new Date(data[0].date), "MMM d")}</span>
                {data.length > 7 && (
                    <span>{format(new Date(data[Math.floor(data.length / 2)].date), "MMM d")}</span>
                )}
                <span>{format(new Date(data[data.length - 1].date), "MMM d")}</span>
            </div>
        </div>
    );
}

import "server-only";
import { orders, orderItems } from "@/db/schema/orders";
import { products, categories } from "@/db/schema/products";
import { customers } from "@/db/schema/customers";
import { eq, and, gte, lte, desc, count, sum, sql, isNotNull } from "drizzle-orm";
import { withTenant } from "@/infrastructure/db";
import type {
    AnalyticsGranularity,
    RevenueByPeriod,
    RevenueDataPoint as AdvancedRevenueDataPoint,
    TopProductsResponse,
    TopProductData,
    CustomerMetrics,
    CustomerSegmentData,
    CustomerSegmentType,
    ConversionFunnelData,
    FunnelStageData,
    SalesByCategoryResponse,
    CategorySalesData,
    OrdersByStatusResponse,
    OrdersByStatusData,
    OrderStatusType,
} from "./analytics-types";

/**
 * Analytics Overview - Summary metrics for dashboard
 */
export interface AnalyticsOverview {
    revenue: number;
    ordersCount: number;
    avgOrderValue: number;
    customersCount: number;
    revenueChange: number;
    ordersChange: number;
    avgOrderValueChange: number;
    customersChange: number;
}

/**
 * Revenue Data Point - For chart visualization (legacy interface)
 */
export interface RevenueDataPoint {
    date: string;
    revenue: number;
    orders: number;
}

/**
 * Top Product - Best selling products by revenue
 */
export interface TopProduct {
    id: string;
    name: string;
    sku: string | null;
    revenue: number;
    quantity: number;
    imageUrl: string | null;
}

/**
 * Top Category - Best performing categories by revenue
 */
export interface TopCategory {
    id: string;
    name: string;
    revenue: number;
    ordersCount: number;
    productCount: number;
}

/**
 * Orders By Status - Order distribution by status
 */
export interface OrdersByStatus {
    status: string;
    count: number;
    percentage: number;
}

/**
 * Customer Segment - Customer segmentation data
 */
export interface CustomerSegment {
    segment: "new" | "returning" | "vip";
    count: number;
    percentage: number;
    revenue: number;
}

/**
 * Recent Order - Simplified order for dashboard display
 */
export interface RecentOrder {
    id: string;
    orderNumber: string;
    customerName: string | null;
    customerEmail: string | null;
    total: string;
    status: string;
    createdAt: Date;
}

/**
 * Analytics Repository
 *
 * Provides analytics and reporting data for the dashboard.
 * All methods use withTenant() wrapper to ensure RLS context is set.
 *
 * @see IMPLEMENTATION-PLAN.md Section 4.1
 */
export class AnalyticsRepository {
    /**
     * Get overview metrics for the dashboard
     */
    async getOverview(
        tenantId: string,
        startDate: Date,
        endDate: Date
    ): Promise<AnalyticsOverview> {
        return withTenant(tenantId, async (tx) => {
            // Current period metrics
            const [currentMetrics] = await tx
                .select({
                    revenue: sum(orders.total),
                    ordersCount: count(orders.id),
                })
                .from(orders)
                .where(
                    and(
                        eq(orders.tenantId, tenantId),
                        gte(orders.createdAt, startDate),
                        lte(orders.createdAt, endDate),
                        eq(orders.paymentStatus, "paid")
                    )
                );

            // Customer count for current period
            const [customerMetrics] = await tx
                .select({
                    customersCount: count(customers.id),
                })
                .from(customers)
                .where(
                    and(
                        eq(customers.tenantId, tenantId),
                        gte(customers.createdAt, startDate),
                        lte(customers.createdAt, endDate)
                    )
                );

            // Calculate previous period for comparison
            const periodLength = endDate.getTime() - startDate.getTime();
            const prevStartDate = new Date(startDate.getTime() - periodLength);
            const prevEndDate = new Date(startDate.getTime() - 1);

            // Previous period metrics
            const [prevMetrics] = await tx
                .select({
                    revenue: sum(orders.total),
                    ordersCount: count(orders.id),
                })
                .from(orders)
                .where(
                    and(
                        eq(orders.tenantId, tenantId),
                        gte(orders.createdAt, prevStartDate),
                        lte(orders.createdAt, prevEndDate),
                        eq(orders.paymentStatus, "paid")
                    )
                );

            const [prevCustomerMetrics] = await tx
                .select({
                    customersCount: count(customers.id),
                })
                .from(customers)
                .where(
                    and(
                        eq(customers.tenantId, tenantId),
                        gte(customers.createdAt, prevStartDate),
                        lte(customers.createdAt, prevEndDate)
                    )
                );

            const revenue = Number(currentMetrics?.revenue || 0);
            const ordersCount = Number(currentMetrics?.ordersCount || 0);
            const customersCount = Number(customerMetrics?.customersCount || 0);
            const avgOrderValue = ordersCount > 0 ? revenue / ordersCount : 0;

            const prevRevenue = Number(prevMetrics?.revenue || 0);
            const prevOrdersCount = Number(prevMetrics?.ordersCount || 0);
            const prevCustomersCount = Number(prevCustomerMetrics?.customersCount || 0);
            const prevAvgOrderValue = prevOrdersCount > 0 ? prevRevenue / prevOrdersCount : 0;

            // Calculate percentage changes
            const calcChange = (current: number, previous: number): number => {
                if (previous === 0) return current > 0 ? 100 : 0;
                return ((current - previous) / previous) * 100;
            };

            return {
                revenue,
                ordersCount,
                avgOrderValue,
                customersCount,
                revenueChange: calcChange(revenue, prevRevenue),
                ordersChange: calcChange(ordersCount, prevOrdersCount),
                avgOrderValueChange: calcChange(avgOrderValue, prevAvgOrderValue),
                customersChange: calcChange(customersCount, prevCustomersCount),
            };
        });
    }

    /**
     * Get revenue chart data points
     */
    async getRevenueChart(
        tenantId: string,
        startDate: Date,
        endDate: Date
    ): Promise<RevenueDataPoint[]> {
        return withTenant(tenantId, async (tx) => {
            const result = await tx
                .select({
                    date: sql<string>`DATE(${orders.createdAt})`,
                    revenue: sum(orders.total),
                    orders: count(orders.id),
                })
                .from(orders)
                .where(
                    and(
                        eq(orders.tenantId, tenantId),
                        gte(orders.createdAt, startDate),
                        lte(orders.createdAt, endDate),
                        eq(orders.paymentStatus, "paid")
                    )
                )
                .groupBy(sql`DATE(${orders.createdAt})`)
                .orderBy(sql`DATE(${orders.createdAt})`);

            return result.map((row) => ({
