                    <BreadcrumbList>
                        <BreadcrumbItem>
                            <BreadcrumbLink href="/dashboard/categories">Categories</BreadcrumbLink>
                        </BreadcrumbItem>
                        {breadcrumbs.slice(0, -1).map((crumb) => (
                            <BreadcrumbItem key={crumb.id}>
                                <BreadcrumbSeparator>
                                    <ArrowRight className="size-3.5" />
                                </BreadcrumbSeparator>
                                <BreadcrumbLink href={`/dashboard/categories/${crumb.id}`}>
                                    {crumb.name}
                                </BreadcrumbLink>
                            </BreadcrumbItem>
                        ))}
                        <BreadcrumbItem>
                            <BreadcrumbSeparator>
                                <ArrowRight className="size-3.5" />
                            </BreadcrumbSeparator>
                            <BreadcrumbPage>{category.name}</BreadcrumbPage>
                        </BreadcrumbItem>
                    </BreadcrumbList>
                </Breadcrumb>
            )}

            {/* Header */}
            <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex items-center gap-4">
                    <Button variant="ghost" size="icon" asChild>
                        <Link href={category.parentId ? `/dashboard/categories/${category.parentId}` : "/dashboard/categories"}>
                            <ArrowLeft className="size-4" />
                        </Link>
                    </Button>
                    <div>
                        <div className="flex items-center gap-2">
                            <h1 className="text-lg font-semibold tracking-tight">
                                {category.name}
                            </h1>
                            <Button
                                variant="ghost"
                                size="icon"
                                className="size-5"
                                onClick={copyId}
                            >
                                <Copy className="size-3.5" />
                            </Button>
                        </div>
                        <p className="text-sm text-muted-foreground">
                            Created {format(new Date(category.createdAt), "PPP")}
                            {` · ${category.productCount} product${category.productCount !== 1 ? "s" : ""}`}
                            {category.subcategoryCount > 0 && ` · ${category.subcategoryCount} subcategor${category.subcategoryCount !== 1 ? "ies" : "y"}`}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3">
                    {/* Level Badge */}
                    {category.level > 0 && (
                        <Badge variant="outline">
                            Level {category.level + 1}
                        </Badge>
                    )}

                    {/* Add Subcategory */}
                    <Button variant="outline" onClick={onAddSubcategory}>
                        <Plus className="size-4" />
                        Add Subcategory
                    </Button>

                    {/* View in Store */}
                    <Button variant="outline" onClick={handleViewStorefront}>
                        <Eye className="size-4" />
                        View
                    </Button>

                    {/* Actions Menu */}
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button variant="outline" size="icon">
                                <MoreHorizontal className="size-4" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                            <DropdownMenuItem
                                className="text-destructive focus:text-destructive"
                                onClick={onDelete}
                                disabled={category.subcategoryCount > 0}
                            >
                                <Trash className="size-4" />
                                Delete Category
                                {category.subcategoryCount > 0 && (
                                    <span className="ml-auto text-xs">(has children)</span>
                                )}
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import {
    Package,
    Search,
    MoreHorizontal,
    Trash2,
    ChevronRight,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { toast } from "sonner";
import { cn } from "@/shared/utils";
import type { Category, CategoryProduct } from "@/app/dashboard/categories/types";
import { removeProductFromCategory } from "@/app/dashboard/categories/category-actions";

interface CategoryProductsCardProps {
    category: Category;
    onUpdate?: (data: Partial<Category>) => void;
}

export function CategoryProductsCard({ category, onUpdate }: CategoryProductsCardProps) {
    const [isPending, startTransition] = useTransition();
    const [searchQuery, setSearchQuery] = useState("");
    const [products, setProducts] = useState<CategoryProduct[]>(category.products || []);

    const filteredProducts = products.filter(p =>
        p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.sku?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const handleRemoveProduct = (productId: string) => {
        startTransition(async () => {
            const result = await removeProductFromCategory(productId, category.id);
            if (result.success) {
                setProducts(prev => prev.filter(p => p.id !== productId));
                toast.success("Product removed from category");
                onUpdate?.({ productCount: products.length - 1 });
            } else {
                toast.error(result.error || "Failed to remove product");
            }
        });
    };

    const formatPrice = (price: number) => {
        return new Intl.NumberFormat("en-US", {
            style: "currency",
            currency: "USD",
        }).format(price);
    };

    const statusColors: Record<string, string> = {
        active: "bg-success/10 text-success",
        draft: "bg-muted text-muted-foreground",
        archived: "bg-warning/10 text-warning",
    };

    return (
        <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
                <CardTitle className="text-base font-medium flex items-center gap-2">
                    <Package className="size-4" />
                    Products ({category.productCount})
                </CardTitle>
                <Button variant="outline" asChild>
                    <Link href={`/dashboard/products?category=${category.id}`}>
                        View All
                        <ChevronRight className="size-4 ml-2" />
                    </Link>
                </Button>
            </CardHeader>
            <CardContent className="space-y-4">
                {/* Search */}
                {products.length > 0 && (
                    <div className="relative">
                        <Search
                            className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground"
                        />
                        <Input
                            placeholder="Search products..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-9"
                        />
                    </div>
                )}

                {/* Products List */}
                {filteredProducts.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-12 text-center">
                        <Package className="size-12 text-muted-foreground mb-4" />
                        <p className="text-muted-foreground">
                            {searchQuery ? "No products match your search" : "No products in this category"}
                        </p>
                        {!searchQuery && (
                            <Button variant="outline" className="mt-4" asChild>
                                <Link href="/dashboard/products/new">Add Product</Link>
                            </Button>
                        )}
                    </div>
                ) : (
                    <div className="border rounded-lg divide-y">
                        {filteredProducts.map((product) => (
                            <div
                                key={product.id}
                                className="flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors"
                            >
                                {/* Product Image */}
                                <div className="size-10 rounded-lg bg-muted overflow-hidden shrink-0">
                                    {product.image ? (
                                        <Image
                                            src={product.image}
                                            alt={product.name}
                                            width={40}
                                            height={40}
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center">
                                            <Package className="size-4 text-muted-foreground" />
                                        </div>
                                    )}
                                </div>

                                {/* Product Info */}
                                <Link
                                    href={`/dashboard/products/${product.id}`}
                                    className="flex-1 min-w-0 hover:underline"
                                >
                                    <p className="font-medium truncate">{product.name}</p>
                                    {product.sku && (
                                        <p className="text-xs text-muted-foreground">SKU: {product.sku}</p>
                                    )}
                                </Link>

                                {/* Price */}
                                <span className="text-sm font-medium hidden sm:block">
                                    {formatPrice(product.price)}
                                </span>

                                {/* Status */}
                                <Badge
                                    className={cn(
                                        "border-0 capitalize hidden sm:inline-flex",
                                        statusColors[product.status]
                                    )}
                                >
                                    {product.status}
                                </Badge>

                                {/* Actions */}
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" size="icon-sm">
                                            <MoreHorizontal className="size-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end">
                                        <DropdownMenuItem asChild>
                                            <Link href={`/dashboard/products/${product.id}`}>
                                                <ChevronRight className="size-4" />
                                                View Product
                                            </Link>
                                        </DropdownMenuItem>
                                        <DropdownMenuItem
                                            className="text-destructive focus:text-destructive"
                                            onClick={() => handleRemoveProduct(product.id)}
                                        >
                                            <Trash2 className="size-4" />
                                            Remove from Category
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>
                        ))}
                    </div>
                )}

                {/* Show more link if there are more products */}
                {category.productCount > products.length && (
                    <div className="text-center">
                        <Button variant="link" asChild>
                            <Link href={`/dashboard/products?category=${category.id}`}>
                                View all {category.productCount} products
                            </Link>
                        </Button>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

"use client";

import { useState, useTransition } from "react";
import Image from "next/image";
import Link from "next/link";
import { Plus, Trash, Grid3X3, MoreHorizontal, ArrowRight, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/components/ui/dialog";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import type { Category, Subcategory } from "@/app/dashboard/categories/types";
import { createSubcategory, deleteSubcategory } from "@/app/dashboard/categories/category-actions";

interface CategorySubcategoriesCardProps {
    category: Category;
    onUpdate?: (data: Partial<Category>) => void;
}

function generateSlug(name: string): string {
    return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export function CategorySubcategoriesCard({ category, onUpdate }: CategorySubcategoriesCardProps) {
    const [isPending, startTransition] = useTransition();
    const [subcategories, setSubcategories] = useState<Subcategory[]>(category.subcategories || []);
    const [createDialogOpen, setCreateDialogOpen] = useState(false);
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [subcategoryToDelete, setSubcategoryToDelete] = useState<Subcategory | null>(null);

    // Form state
    const [name, setName] = useState("");
    const [slug, setSlug] = useState("");
    const [description, setDescription] = useState("");

    const handleNameChange = (value: string) => {
        setName(value);
        setSlug(generateSlug(value));
    };

    const handleCreate = () => {
        if (!name.trim()) {
            toast.error("Name is required");
            return;
        }

        startTransition(async () => {
            const result = await createSubcategory(category.id, { name, slug, description });
            if (result.success && result.data) {
                const newSub: Subcategory = {
                    id: result.data.id,
                    name: result.data.name,
                    slug: result.data.slug,
                    description: result.data.description,
                    imageUrl: result.data.image_url,
                    productCount: 0,
                    subcategoryCount: 0,
                    sortOrder: result.data.sort_order || 0,
                    createdAt: result.data.created_at,
                };
                setSubcategories(prev => [...prev, newSub]);
                toast.success("Subcategory created");
                onUpdate?.({ subcategoryCount: subcategories.length + 1 });
                setCreateDialogOpen(false);
                setName("");
                setSlug("");
                setDescription("");
            } else {
                toast.error(result.error || "Failed to create");
            }
        });
    };

    const handleDelete = () => {
        if (!subcategoryToDelete) return;

        startTransition(async () => {
            const result = await deleteSubcategory(subcategoryToDelete.id, category.id);
            if (result.success) {
                setSubcategories(prev => prev.filter(s => s.id !== subcategoryToDelete.id));
                toast.success("Subcategory deleted");
                onUpdate?.({ subcategoryCount: subcategories.length - 1 });
            } else {
                toast.error(result.error || "Failed to delete");
            }
            setDeleteDialogOpen(false);
            setSubcategoryToDelete(null);
        });
    };

    return (
        <>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
                    <CardTitle className="text-base font-medium flex items-center gap-2">
                        <Grid3X3 className="size-4" />
                        Subcategories ({subcategories.length})
                    </CardTitle>
                    <Button onClick={() => setCreateDialogOpen(true)}>
                        <Plus className="size-4" />
                        Add
                    </Button>
                </CardHeader>
                <CardContent>
                    {subcategories.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-8 text-center">
                            <Grid3X3 className="size-10 text-muted-foreground mb-3" />
                            <p className="text-sm text-muted-foreground">No subcategories</p>
                            <Button
                                variant="outline"

                                className="mt-3"
                                onClick={() => setCreateDialogOpen(true)}
                            >
                                Add Subcategory
                            </Button>
                        </div>
                    ) : (
                        <div className="divide-y border rounded-lg">
                            {subcategories.map((sub) => (
                                <div
                                    key={sub.id}
                                    className="flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors"
                                >
                                    <div className="size-10 rounded-lg bg-muted overflow-hidden shrink-0">
                                        {sub.imageUrl ? (
                                            <Image
                                                src={sub.imageUrl}
                                                alt={sub.name}
                                                width={40}
                                                height={40}
                                                className="w-full h-full object-cover"
                                            />
                                        ) : (
                                            <div className="w-full h-full flex items-center justify-center">
                                                <Grid3X3 className="size-4 text-muted-foreground" />
                                            </div>
                                        )}
                                    </div>

                                    <Link
                                        href={`/dashboard/categories/${sub.id}`}
                                        className="flex-1 min-w-0 hover:underline"
                                    >
                                        <p className="font-medium truncate">{sub.name}</p>
                                        <p className="text-xs text-muted-foreground">
                                            {sub.productCount} product{sub.productCount !== 1 ? "s" : ""}
                                            {sub.subcategoryCount > 0 && ` · ${sub.subcategoryCount} sub`}
                                        </p>
                                    </Link>

                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <Button variant="ghost" size="icon-sm">
                                                <MoreHorizontal className="size-4" />
                                            </Button>
                                        </DropdownMenuTrigger>
                                        <DropdownMenuContent align="end">
                                            <DropdownMenuItem asChild>
                                                <Link href={`/dashboard/categories/${sub.id}`}>
                                                    <ArrowRight className="size-4" />
                                                    View
                                                </Link>
                                            </DropdownMenuItem>
                                            <DropdownMenuItem
                                                className="text-destructive focus:text-destructive"
                                                onClick={() => {
                                                    setSubcategoryToDelete(sub);
                                                    setDeleteDialogOpen(true);
                                                }}
                                                disabled={sub.subcategoryCount > 0}
                                            >
                                                <Trash className="size-4" />
                                                Delete
                                            </DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Create Dialog */}
            <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Add Subcategory</DialogTitle>
                        <DialogDescription>
                            Create a new subcategory under {category.name}
                        </DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                        <div className="space-y-2">
                            <Label htmlFor="subName">Name</Label>
                            <Input
                                id="subName"
                                value={name}
                                onChange={(e) => handleNameChange(e.target.value)}
                                placeholder="Subcategory name"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="subSlug">URL Slug</Label>
                            <Input
                                id="subSlug"
                                value={slug}
                                onChange={(e) => setSlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, "-"))}
                                placeholder="subcategory-slug"
                                className="font-mono"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="subDesc">Description (optional)</Label>
                            <Input
                                id="subDesc"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                placeholder="Brief description"
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>
                            Cancel
                        </Button>
                        <Button onClick={handleCreate} disabled={isPending || !name.trim()}>
                            {isPending ? (
                                <Loader2 className="size-4 animate-spin" />
                            ) : (
                                <Plus className="size-4" />
                            )}
                            Create
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>

            {/* Delete Confirmation */}
            <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Delete subcategory?</AlertDialogTitle>
                        <AlertDialogDescription>
                            This will permanently delete &quot;{subcategoryToDelete?.name}&quot;.
                            Products in this subcategory will become uncategorized.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={handleDelete}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            Delete
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </>
    );
}

