                {/* Selected Count */}
                {selectedIds.size > 0 && (
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                        <Badge variant="secondary">{selectedIds.size} selected</Badge>
                    </div>
                )}

                <DialogFooter>
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        Cancel
                    </Button>
                    <Button onClick={handleAssign} disabled={selectedIds.size === 0 || isPending}>
                        {isPending ? (
                            <>
                                <Loader className="size-4 animate-spin" />
                                Adding...
                            </>
                        ) : (
                            <>
                                <Plus className="size-4" />
                                Add {selectedIds.size > 0 ? `(${selectedIds.size})` : ""}
                            </>
                        )}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useTransition } from "react";
import Image from "next/image";
import { Plus, Trash, Package, Search, MoreHorizontal, ArrowUp, ArrowDown, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { toast } from "sonner";
import { cn } from "@/shared/utils";
import type { Collection, CollectionProduct } from "@/app/dashboard/collections/types";
import { unassignProductFromCollection, bulkUnassignProducts, reorderCollectionProducts } from "@/app/dashboard/collections/collection-actions";
import { AssignProductsDialog } from "./assign-products-dialog";

interface CollectionProductsCardProps {
    collection: Collection;
    onUpdate?: (data: Partial<Collection>) => void;
}

export function CollectionProductsCard({ collection, onUpdate }: CollectionProductsCardProps) {
    const [isPending, startTransition] = useTransition();
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [assignDialogOpen, setAssignDialogOpen] = useState(false);
    const [products, setProducts] = useState<CollectionProduct[]>(collection.products || []);

    const filteredProducts = products.filter(p =>
        p.productName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        p.productSku?.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const toggleSelect = (productId: string) => {
        setSelectedIds(prev => {
            const next = new Set(prev);
            if (next.has(productId)) {
                next.delete(productId);
            } else {
                next.add(productId);
            }
            return next;
        });
    };

    const toggleSelectAll = () => {
        if (selectedIds.size === filteredProducts.length) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(filteredProducts.map(p => p.productId)));
        }
    };

    const handleRemoveProduct = (productId: string) => {
        startTransition(async () => {
            const result = await unassignProductFromCollection(collection.id, productId);
            if (result.success) {
                setProducts(prev => prev.filter(p => p.productId !== productId));
                toast.success("Product removed");
                onUpdate?.({ productCount: products.length - 1 });
            } else {
                toast.error(result.error || "Failed to remove product");
            }
        });
    };

    const handleBulkRemove = () => {
        startTransition(async () => {
            const result = await bulkUnassignProducts(collection.id, Array.from(selectedIds));
            if (result.success) {
                setProducts(prev => prev.filter(p => !selectedIds.has(p.productId)));
                toast.success(`Removed ${selectedIds.size} products`);
                setSelectedIds(new Set());
                onUpdate?.({ productCount: products.length - selectedIds.size });
            } else {
                toast.error(result.error || "Failed to remove products");
            }
        });
    };

    const handleMoveUp = (index: number) => {
        if (index === 0) return;
        const newProducts = [...products];
        [newProducts[index - 1], newProducts[index]] = [newProducts[index], newProducts[index - 1]];
        setProducts(newProducts);

        startTransition(async () => {
            const result = await reorderCollectionProducts(
                collection.id,
                newProducts.map(p => p.productId)
            );
            if (!result.success) {
                toast.error("Failed to reorder");
                setProducts(products);
            }
        });
    };

    const handleMoveDown = (index: number) => {
        if (index === products.length - 1) return;
        const newProducts = [...products];
        [newProducts[index], newProducts[index + 1]] = [newProducts[index + 1], newProducts[index]];
        setProducts(newProducts);

        startTransition(async () => {
            const result = await reorderCollectionProducts(
                collection.id,
                newProducts.map(p => p.productId)
            );
            if (!result.success) {
                toast.error("Failed to reorder");
                setProducts(products);
            }
        });
    };

    const handleProductsAssigned = (newProducts: CollectionProduct[]) => {
        setProducts(prev => [...prev, ...newProducts]);
        onUpdate?.({ productCount: products.length + newProducts.length });
    };

    const formatPrice = (price: number) => {
        return new Intl.NumberFormat("en-US", {
            style: "currency",
            currency: "USD",
        }).format(price);
    };

    return (
        <>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4">
                    <CardTitle className="text-base font-medium flex items-center gap-2">
                        <Package className="size-4" />
                        Products ({products.length})
                    </CardTitle>
                    <Button onClick={() => setAssignDialogOpen(true)}>
                        <Plus className="size-4" />
                        Add Products
                    </Button>
                </CardHeader>
                <CardContent className="space-y-4">
                    {/* Search & Bulk Actions */}
                    <div className="flex items-center gap-4">
                        <div className="relative flex-1">
                            <Search
                                className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground"
                            />
                            <Input
                                placeholder="Search products..."
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                className="pl-9"
                            />
                        </div>
                        {selectedIds.size > 0 && (
                            <Button
                                variant="destructive"

                                onClick={handleBulkRemove}
                                disabled={isPending}
                            >
                                {isPending ? (
                                    <Loader2 className="size-4 animate-spin" />
                                ) : (
                                    <Trash className="size-4" />
                                )}
                                Remove ({selectedIds.size})
                            </Button>
                        )}
                    </div>

                    {/* Products List */}
                    {filteredProducts.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-center">
                            <Package className="size-12 text-muted-foreground mb-4" />
                            <p className="text-muted-foreground">
                                {searchQuery ? "No products match your search" : "No products in this collection"}
                            </p>
                            {!searchQuery && (
                                <Button
                                    variant="outline"
                                    className="mt-4"
                                    onClick={() => setAssignDialogOpen(true)}
                                >
                                    Add Products
                                </Button>
                            )}
                        </div>
                    ) : (
                        <div className="border rounded-lg divide-y">
                            {/* Header */}
                            <div className="flex items-center gap-3 px-4 py-2 bg-muted/30">
                                <Checkbox
                                    checked={selectedIds.size === filteredProducts.length && filteredProducts.length > 0}
                                    onCheckedChange={toggleSelectAll}
                                />
                                <span className="text-sm font-medium flex-1">Product</span>
                                <span className="text-sm font-medium w-20 text-right hidden sm:block">Price</span>
                                <span className="text-sm font-medium w-20 text-center hidden sm:block">Order</span>
                                <span className="w-8"></span>
                            </div>

                            {/* Rows */}
                            {filteredProducts.map((product, index) => (
                                <div
                                    key={product.id}
                                    className={cn(
                                        "flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors",
                                        selectedIds.has(product.productId) && "bg-muted/50"
                                    )}
                                >
                                    <Checkbox
                                        checked={selectedIds.has(product.productId)}
                                        onCheckedChange={() => toggleSelect(product.productId)}
                                    />

                                    {/* Product Info */}
                                    <div className="flex items-center gap-3 flex-1 min-w-0">
                                        <div className="size-10 rounded-lg bg-muted overflow-hidden shrink-0">
                                            {product.productImage ? (
                                                <Image
                                                    src={product.productImage}
                                                    alt={product.productName}
                                                    width={40}
                                                    height={40}
                                                    className="w-full h-full object-cover"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center">
                                                    <Package className="size-4 text-muted-foreground" />
                                                </div>
                                            )}
                                        </div>
                                        <div className="min-w-0">
                                            <p className="font-medium truncate">{product.productName}</p>
                                            {product.productSku && (
                                                <p className="text-xs text-muted-foreground">SKU: {product.productSku}</p>
                                            )}
                                        </div>
                                    </div>

                                    {/* Price */}
                                    <div className="w-20 text-right hidden sm:block">
                                        <span className="text-sm">{formatPrice(product.productPrice)}</span>
                                    </div>

                                    {/* Reorder */}
                                    <div className="w-20 items-center justify-center gap-1 hidden sm:flex">
                                        <button
                                            onClick={() => handleMoveUp(index)}
                                            disabled={index === 0 || isPending}
                                            className="p-1 rounded hover:bg-muted disabled:opacity-30"
                                        >
                                            <ArrowUp className="size-4" />
                                        </button>
                                        <button
                                            onClick={() => handleMoveDown(index)}
                                            disabled={index === filteredProducts.length - 1 || isPending}
                                            className="p-1 rounded hover:bg-muted disabled:opacity-30"
                                        >
                                            <ArrowDown className="size-4" />
                                        </button>
                                    </div>

                                    {/* Actions */}
                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <Button variant="ghost" size="icon-sm">
                                                <MoreHorizontal className="size-4" />
                                            </Button>
                                        </DropdownMenuTrigger>
                                        <DropdownMenuContent align="end">
                                            <DropdownMenuItem
                                                className="text-destructive focus:text-destructive"
                                                onClick={() => handleRemoveProduct(product.productId)}
                                            >
                                                <Trash className="size-4" />
                                                Remove from Collection
                                            </DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>

            <AssignProductsDialog
                open={assignDialogOpen}
                onOpenChange={setAssignDialogOpen}
                collectionId={collection.id}
                onProductsAssigned={handleProductsAssigned}
            />
        </>
    );
}

import "server-only";
import { 
    collections, 
    collectionProducts,
    CollectionType,
} from "@/db/schema/collections";
import { products } from "@/db/schema/products";
import { eq, desc, ilike, or, count, and } from "drizzle-orm";
import { withTenant } from "@/infrastructure/db";
import { QueryOptions } from "@/infrastructure/repositories/base";

export type CollectionCreateInput = {
    name: string;
    slug: string;
    description?: string;
    imageUrl?: string;
    imageAlt?: string;
    metaTitle?: string;
    metaDescription?: string;
    isActive?: boolean;
    sortOrder?: number;
    type?: CollectionType;
    conditions?: Record<string, unknown>;
};

export type CollectionUpdateInput = Partial<CollectionCreateInput>;

export interface CollectionWithProductCount {
    id: string;
    name: string;
    slug: string;
    description: string | null;
    imageUrl: string | null;
    isActive: boolean | null;
    type: CollectionType | null;
    productCount: number;
}

export interface CollectionStats {
    total: number;
    active: number;
    manual: number;
    automatic: number;
    empty: number;
}

export class CollectionRepository {
    async findAll(tenantId: string, options?: QueryOptions) {
        return withTenant(tenantId, async (tx) => {
            let query = tx
                .select()
                .from(collections)
                .where(eq(collections.tenantId, tenantId))
                .orderBy(collections.sortOrder, desc(collections.createdAt));

            if (options?.limit) {
                query = query.limit(options.limit) as typeof query;
            }

            if (options?.offset) {
                query = query.offset(options.offset) as typeof query;
            }

            return query;
        });
    }

    async findById(tenantId: string, id: string) {
        return withTenant(tenantId, async (tx) => {
            const [result] = await tx
                .select()
                .from(collections)
                .where(and(eq(collections.tenantId, tenantId), eq(collections.id, id)))
                .limit(1);

            return result || null;
        });
    }

    async findBySlug(tenantId: string, slug: string) {
        return withTenant(tenantId, async (tx) => {
            const [result] = await tx
                .select()
                .from(collections)
                .where(and(eq(collections.tenantId, tenantId), eq(collections.slug, slug)))
                .limit(1);

            return result || null;
        });
    }

    async findActive(tenantId: string, options?: QueryOptions) {
        return withTenant(tenantId, async (tx) => {
            let query = tx
                .select()
                .from(collections)
                .where(and(eq(collections.tenantId, tenantId), eq(collections.isActive, true)))
                .orderBy(collections.sortOrder);

            if (options?.limit) {
                query = query.limit(options.limit) as typeof query;
            }

            if (options?.offset) {
                query = query.offset(options.offset) as typeof query;
            }

            return query;
        });
    }

    async search(tenantId: string, query: string, options?: QueryOptions) {
        return withTenant(tenantId, async (tx) => {
            const searchPattern = `%${query}%`;
            let dbQuery = tx
                .select()
                .from(collections)
                .where(
                    and(
                        eq(collections.tenantId, tenantId),
                        or(
                            ilike(collections.name, searchPattern),
                            ilike(collections.description, searchPattern)
                        )
                    )
                )
                .orderBy(desc(collections.createdAt));

            if (options?.limit) {
                dbQuery = dbQuery.limit(options.limit) as typeof dbQuery;
            }

            if (options?.offset) {
                dbQuery = dbQuery.offset(options.offset) as typeof dbQuery;
            }

            return dbQuery;
        });
    }

    async getStats(tenantId: string): Promise<CollectionStats> {
        return withTenant(tenantId, async (tx) => {
            const allCollections = await tx.select().from(collections).where(eq(collections.tenantId, tenantId));

            const productCounts = await tx
                .select({
                    collectionId: collectionProducts.collectionId,
                    count: count(collectionProducts.productId),
                })
                .from(collectionProducts)
                .where(eq(collectionProducts.tenantId, tenantId))
                .groupBy(collectionProducts.collectionId);

            const countMap = new Map(productCounts.map(pc => [pc.collectionId, Number(pc.count)]));
            const emptyCount = allCollections.filter(c => !countMap.has(c.id) || countMap.get(c.id) === 0).length;

            return {
                total: allCollections.length,
                active: allCollections.filter(c => c.isActive).length,
                manual: allCollections.filter(c => c.type === "manual").length,
                automatic: allCollections.filter(c => c.type === "automatic").length,
                empty: emptyCount,
            };
        });
    }

    async create(tenantId: string, data: CollectionCreateInput) {
        return withTenant(tenantId, async (tx) => {
            const [result] = await tx
                .insert(collections)
                .values({
                    tenantId,
                    name: data.name,
                    slug: data.slug,
                    description: data.description,
                    imageUrl: data.imageUrl,
                    imageAlt: data.imageAlt,
                    metaTitle: data.metaTitle,
                    metaDescription: data.metaDescription,
                    isActive: data.isActive ?? true,
                    sortOrder: data.sortOrder ?? 0,
                    type: data.type || "manual",
                    conditions: data.conditions,
                })
                .returning();

            return result;
        });
    }

    async update(tenantId: string, id: string, data: CollectionUpdateInput) {
        return withTenant(tenantId, async (tx) => {
            const [result] = await tx
                .update(collections)
                .set({
                    ...data,
                    updatedAt: new Date(),
                })
                .where(and(eq(collections.tenantId, tenantId), eq(collections.id, id)))
                .returning();

            return result || null;
        });
    }

    async delete(tenantId: string, id: string) {
        return withTenant(tenantId, async (tx) => {
            await tx.delete(collections).where(and(eq(collections.tenantId, tenantId), eq(collections.id, id)));
        });
    }

    async getProducts(tenantId: string, collectionId: string, options?: QueryOptions) {
        return withTenant(tenantId, async (tx) => {
            let query = tx
                .select({
                    product: products,
                    position: collectionProducts.position,
                })
                .from(collectionProducts)
                .innerJoin(products, eq(collectionProducts.productId, products.id))
                .where(and(eq(collectionProducts.tenantId, tenantId), eq(collectionProducts.collectionId, collectionId)))
                .orderBy(collectionProducts.position);

            if (options?.limit) {
                query = query.limit(options.limit) as typeof query;
            }

            if (options?.offset) {
                query = query.offset(options.offset) as typeof query;
            }

            const results = await query;
            return results.map(r => ({ ...r.product, position: r.position }));
        });
    }

    async addProduct(tenantId: string, collectionId: string, productId: string, position?: number) {
        return withTenant(tenantId, async (tx) => {
            const [existing] = await tx
                .select()
                .from(collectionProducts)
                .where(
                    and(
                        eq(collectionProducts.tenantId, tenantId),
                        eq(collectionProducts.collectionId, collectionId),
                        eq(collectionProducts.productId, productId)
                    )
                )
                .limit(1);

            if (existing) {
                if (position !== undefined) {
                    await tx
                        .update(collectionProducts)
                        .set({ position })
                        .where(eq(collectionProducts.id, existing.id));
                }
                return existing;
            }

            const [result] = await tx
                .insert(collectionProducts)
                .values({
                    tenantId,
                    collectionId,
                    productId,
                    position: position ?? 0,
                })
                .returning();

            return result;
        });
    }

    async removeProduct(tenantId: string, collectionId: string, productId: string) {
        return withTenant(tenantId, async (tx) => {
            await tx
                .delete(collectionProducts)
                .where(
                    and(
                        eq(collectionProducts.tenantId, tenantId),
                        eq(collectionProducts.collectionId, collectionId),
                        eq(collectionProducts.productId, productId)
                    )
                );
        });
    }

    async reorderProducts(tenantId: string, collectionId: string, productIds: string[]) {
        return withTenant(tenantId, async (tx) => {
            for (let i = 0; i < productIds.length; i++) {
                await tx
                    .update(collectionProducts)
                    .set({ position: i })
                    .where(
                        and(
                            eq(collectionProducts.tenantId, tenantId),
                            eq(collectionProducts.collectionId, collectionId),
                            eq(collectionProducts.productId, productIds[i])
                        )
                    );
            }
        });
    }

    async findWithProductCount(tenantId: string, id: string): Promise<CollectionWithProductCount | null> {
        return withTenant(tenantId, async (tx) => {
            const [collection] = await tx
                .select()
                .from(collections)
                .where(and(eq(collections.tenantId, tenantId), eq(collections.id, id)))
                .limit(1);

            if (!collection) return null;

            const [countResult] = await tx
                .select({ count: count() })
                .from(collectionProducts)
                .where(and(eq(collectionProducts.tenantId, tenantId), eq(collectionProducts.collectionId, id)));

            return {
                id: collection.id,
                name: collection.name,
                slug: collection.slug,
                description: collection.description,
                imageUrl: collection.imageUrl,
                isActive: collection.isActive,
                type: collection.type,
                productCount: Number(countResult?.count || 0),
            };
        });
    }

    async getCollectionsForProduct(tenantId: string, productId: string) {
        return withTenant(tenantId, async (tx) => {
            const results = await tx
                .select({ collection: collections })
                .from(collectionProducts)
                .innerJoin(collections, eq(collectionProducts.collectionId, collections.id))
                .where(and(eq(collectionProducts.tenantId, tenantId), eq(collectionProducts.productId, productId)));

            return results.map(r => r.collection);
        });
    }
}

export const collectionRepository = new CollectionRepository();

