                </CardTitle>
                {recentOrders.length > 0 && (
                    <Button variant="outline" asChild>
                        <Link href={`/dashboard/orders?customer=${customer.email}`}>
                            View all orders
                            <ArrowRight className="size-4 ml-1" />
                        </Link>
                    </Button>
                )}
            </CardHeader>
            <CardContent>
                {recentOrders.length === 0 ? (
                    <div className="text-center py-8">
                        <div className="size-12 rounded-2xl bg-muted/50 flex items-center justify-center mx-auto">
                            <ShoppingCart className="size-5 text-muted-foreground/50" />
                        </div>
                        <p className="mt-3 text-sm text-muted-foreground">No orders found</p>
                    </div>
                ) : (
                    <Table>
                        <TableHeader>
                            <TableRow className="hover:bg-transparent">
                                <TableHead>Order</TableHead>
                                <TableHead>Date</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead className="text-right">Total</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {recentOrders.map((order) => {
                                const statusStyle = paymentStatusConfig[order.paymentStatus] || paymentStatusConfig.pending;
                                return (
                                    <TableRow
                                        key={order.id}
                                        className="cursor-pointer"
                                        onClick={() => window.location.href = `/dashboard/orders/${order.id}`}
                                    >
                                        <TableCell className="font-medium">
                                            #{order.orderNumber}
                                        </TableCell>
                                        <TableCell className="text-muted-foreground">
                                            {format(new Date(order.createdAt), "MMM d, yyyy")}
                                        </TableCell>
                                        <TableCell>
                                            <Badge
                                                variant="secondary"
                                                className={cn(
                                                    "border-0 capitalize",
