                                        </TableCell>
                                        <TableCell className="text-right font-medium">
                                            {formatCurrency(order.total, order.currency || currency)}
                                        </TableCell>
                                    </TableRow>
                                );
                            })}
                        </TableBody>
                    </Table>
                )}
            </CardContent>
        </Card>
    );
}

