"use client";

import { useState, useEffect, useTransition } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Search, Grid3X3, Loader2 } from "lucide-react";
import { getCategoriesForDiscount } from "@/app/dashboard/marketing/actions";

interface Category {
    id: string;
    name: string;
    parent_name: string | null;
    product_count: number;
}

interface AssignCategoryDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    excludeIds: string[];
    onAssign: (categoryIds: string[]) => void;
}

export function AssignCategoryDialog({
    open,
    onOpenChange,
    excludeIds,
    onAssign,
}: AssignCategoryDialogProps) {
    const [isPending, startTransition] = useTransition();
    const [categories, setCategories] = useState<Category[]>([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedIds, setSelectedIds] = useState<string[]>([]);
    const [isLoading, setIsLoading] = useState(false);

    // Fetch categories when dialog opens
    useEffect(() => {
        if (open) {
            setIsLoading(true);
            startTransition(async () => {
                const result = await getCategoriesForDiscount();
                if (result.categories) {
                    setCategories(result.categories);
                }
                setIsLoading(false);
            });
        }
    }, [open]);

    const availableCategories = categories.filter(
        (c) => !excludeIds.includes(c.id)
    );

    const filteredCategories = availableCategories.filter((category) =>
        category.name.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const toggleSelect = (id: string) => {
        setSelectedIds((prev) =>
            prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
        );
    };

    const handleSubmit = () => {
        onAssign(selectedIds);
        setSelectedIds([]);
        setSearchQuery("");
    };

    const handleClose = () => {
        onOpenChange(false);
        setSelectedIds([]);
        setSearchQuery("");
    };

    return (
        <Dialog open={open} onOpenChange={handleClose}>
            <DialogContent className="sm:max-w-lg">
                <DialogHeader>
                    <DialogTitle>Assign Categories</DialogTitle>
                    <DialogDescription>
                        Select categories to apply this discount to all their products
                    </DialogDescription>
                </DialogHeader>

                <div className="space-y-4">
                    <div className="relative">
                        <Search
                            className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground size-4"
                        />
                        <Input
                            placeholder="Search categories..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-9"
                        />
                    </div>

                    <ScrollArea className="h-[300px] border rounded-lg">
                        {isLoading ? (
                            <div className="flex items-center justify-center h-full">
                                <Loader2 className="size-5 animate-spin text-muted-foreground" />
                            </div>
                        ) : filteredCategories.length === 0 ? (
                            <div className="p-4 text-center text-muted-foreground">
                                {availableCategories.length === 0 ? "No categories available" : "No categories found"}
                            </div>
                        ) : (
                            <div className="divide-y">
                                {filteredCategories.map((category) => (
                                    <label
                                        key={category.id}
                                        className="flex items-center gap-3 p-3 hover:bg-muted cursor-pointer"
                                    >
                                        <Checkbox
                                            checked={selectedIds.includes(category.id)}
                                            onCheckedChange={() => toggleSelect(category.id)}
                                        />
                                        <div className="size-10 rounded bg-muted flex items-center justify-center flex-shrink-0">
                                            <Grid3X3
                                                className="size-4 text-muted-foreground"
                                            />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="font-medium truncate">{category.name}</div>
                                            <div className="text-sm text-muted-foreground">
                                                {category.parent_name ? `${category.parent_name} › ` : ""}
                                                {category.product_count} products
                                            </div>
                                        </div>
                                    </label>
                                ))}
                            </div>
                        )}
                    </ScrollArea>

                    {selectedIds.length > 0 && (
                        <div className="text-sm text-muted-foreground">
                            {selectedIds.length} categories selected
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button type="button" variant="outline" onClick={handleClose}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} disabled={selectedIds.length === 0 || isPending}>
                        Assign {selectedIds.length > 0 ? `${selectedIds.length} ` : ""}Categories
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

