                                            checked={selectedIds.includes(product.id)}
                                            onCheckedChange={() => toggleSelect(product.id)}
                                        />
                                        <div className="size-10 rounded bg-muted flex items-center justify-center overflow-hidden flex-shrink-0 relative">
                                            {product.image_url ? (
                                                <Image
                                                    src={product.image_url}
                                                    alt={product.name}
                                                    fill
                                                    className="object-cover"
                                                />
                                            ) : (
                                                <ImageIcon
                                                    className="size-4 text-muted-foreground"
                                                />
                                            )}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="font-medium truncate">{product.name}</div>
                                            <div className="text-sm text-muted-foreground">
                                                {product.sku || "No SKU"} · ${product.price.toFixed(2)}
                                            </div>
                                        </div>
                                    </label>
                                ))}
                            </div>
                        )}
                    </ScrollArea>

                    {selectedIds.length > 0 && (
                        <div className="text-sm text-muted-foreground">
                            {selectedIds.length} products selected
                        </div>
                    )}
                </div>

                <DialogFooter>
                    <Button type="button" variant="outline" onClick={handleClose}>
                        Cancel
                    </Button>
                    <Button onClick={handleSubmit} disabled={selectedIds.length === 0 || isPending}>
                        Assign {selectedIds.length > 0 ? `${selectedIds.length} ` : ""}Products
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import { useState, useMemo } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogDescription,
    DialogFooter,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { 
    generateCodePreview, 
    estimateUniqueCodeCount,
    type GenerateCodesOptions,
} from "@/features/discounts/voucher-code-generator";

export interface GenerateCodesFormData {
    quantity: number;
    prefix: string;
    suffix: string;
    length: number;
    charset: "alphanumeric" | "alphabetic" | "numeric";
}

interface VoucherCodesGenerateDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSubmit: (data: GenerateCodesFormData) => void;
    existingCodesCount?: number;
}

const MAX_CODES = 100;
const DEFAULT_LENGTH = 8;

export function VoucherCodesGenerateDialog({
    open,
    onOpenChange,
    onSubmit,
    existingCodesCount = 0,
}: VoucherCodesGenerateDialogProps) {
    const [quantity, setQuantity] = useState("10");
    const [prefix, setPrefix] = useState("");
    const [suffix, setSuffix] = useState("");
    const [length, setLength] = useState(DEFAULT_LENGTH.toString());
    const [charset, setCharset] = useState<"alphanumeric" | "alphabetic" | "numeric">("alphanumeric");

    // Generate preview code
    const previewCode = useMemo(() => {
        return generateCodePreview({
            prefix: prefix || undefined,
            suffix: suffix || undefined,
            length: parseInt(length) || DEFAULT_LENGTH,
            charset,
            separator: "-",
        });
    }, [prefix, suffix, length, charset]);

    // Estimate unique codes possible
    const uniqueCodesEstimate = useMemo(() => {
        return estimateUniqueCodeCount({
            length: parseInt(length) || DEFAULT_LENGTH,
            charset,
        });
    }, [length, charset]);

    const handleQuantityChange = (value: string) => {
        const num = parseInt(value);
        if (value === "" || (num >= 0 && num <= MAX_CODES)) {
            setQuantity(value);
        }
    };

    const handleLengthChange = (value: string) => {
        const num = parseInt(value);
        if (value === "" || (num >= 4 && num <= 16)) {
            setLength(value);
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const qty = parseInt(quantity);
        if (qty > 0 && qty <= MAX_CODES) {
            onSubmit({
                quantity: qty,
                prefix,
                suffix,
                length: parseInt(length) || DEFAULT_LENGTH,
                charset,
            });
            resetForm();
        }
    };

    const resetForm = () => {
        setQuantity("10");
        setPrefix("");
        setSuffix("");
        setLength(DEFAULT_LENGTH.toString());
        setCharset("alphanumeric");
    };

    const handleClose = () => {
        onOpenChange(false);
        resetForm();
    };

    const qty = parseInt(quantity) || 0;
    const isValid = qty > 0 && qty <= MAX_CODES;

    return (
        <Dialog open={open} onOpenChange={handleClose}>
            <DialogContent className="sm:max-w-lg">
                <DialogHeader>
                    <DialogTitle>Generate Voucher Codes</DialogTitle>
                    <DialogDescription>
                        Generate multiple unique voucher codes at once. Codes are automatically 
                        generated to avoid duplicates.
                    </DialogDescription>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-5">
                    {/* Quantity */}
                    <div className="space-y-2">
                        <Label htmlFor="quantity">
                            Number of codes
                        </Label>
                        <Input
                            id="quantity"
                            type="number"
                            placeholder="10"
                            value={quantity}
                            onChange={(e) => handleQuantityChange(e.target.value)}
                            min={1}
                            max={MAX_CODES}
                            required
                        />
                        <p className="text-xs text-muted-foreground">
                            Maximum {MAX_CODES} codes per batch. You have {existingCodesCount} existing codes.
                        </p>
                    </div>

                    {/* Prefix and Suffix */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="prefix">Prefix (optional)</Label>
                            <Input
                                id="prefix"
                                placeholder="SUMMER"
                                value={prefix}
                                onChange={(e) => setPrefix(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, ""))}
                                maxLength={10}
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="suffix">Suffix (optional)</Label>
                            <Input
                                id="suffix"
                                placeholder="2024"
                                value={suffix}
                                onChange={(e) => setSuffix(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, ""))}
                                maxLength={10}
                            />
                        </div>
                    </div>

                    {/* Code Length and Charset */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label htmlFor="length">Code length</Label>
                            <Input
                                id="length"
                                type="number"
                                value={length}
                                onChange={(e) => handleLengthChange(e.target.value)}
                                min={4}
                                max={16}
                            />
                            <p className="text-xs text-muted-foreground">
                                4-16 characters
                            </p>
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="charset">Character set</Label>
                            <Select value={charset} onValueChange={(v) => setCharset(v as typeof charset)}>
                                <SelectTrigger>
                                    <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="alphanumeric">Letters & Numbers</SelectItem>
                                    <SelectItem value="alphabetic">Letters Only</SelectItem>
                                    <SelectItem value="numeric">Numbers Only</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </div>

                    {/* Preview */}
                    <div className="rounded-lg border bg-muted/30 p-4 space-y-2">
                        <div className="flex items-center justify-between">
                            <span className="text-sm font-medium">Preview</span>
                            <Badge variant="secondary" className="text-xs">
                                ~{uniqueCodesEstimate.toLocaleString()} unique codes possible
                            </Badge>
                        </div>
                        <code className="block font-mono text-lg bg-background px-3 py-2 rounded border">
                            {previewCode}
                        </code>
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={handleClose}>
                            Cancel
                        </Button>
                        <Button type="submit" disabled={!isValid}>
                            Generate {qty} code{qty !== 1 ? "s" : ""}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import React, { useState, useCallback, useRef, type CSSProperties, type ReactNode } from "react";
import { useEditor } from "../core/provider";
import { useDocumentStore } from "../core/document-store";
import { useEditorStore } from "../core/editor-store";
import ElementWrapper from "./element-wrapper";
import { makeElInContext } from "../core/registry";
import { cn } from "@/shared/utils";
import type { El } from "../core/types";
import { resolveStyles } from "../core/types";
import Recursive from "./recursive";

/** Split styles: layout props go to wrapRef, visual props go to ElementWrapper */
function splitStyles(styles: CSSProperties) {
  const { display, flexDirection, gap, flexWrap, alignItems, justifyContent, gridTemplateColumns, gridTemplateRows, ...visual } = styles as Record<string, unknown>;
  const layout = { display, flexDirection, gap, flexWrap, alignItems, justifyContent, gridTemplateColumns, gridTemplateRows } as CSSProperties;
  return { layout, visual: visual as CSSProperties };
}

export default function ContainerElement({ element }: { element: El }): ReactNode {
  const { dispatch } = useEditor();
  const preview = useEditorStore(s => s.preview);
  const dropTarget = useEditorStore(s => s.dropTarget);
  const device = useEditorStore(s => s.device);
  const isSel = useEditorStore(s => s.selected?.id === element.id);
  const resolved = resolveStyles(element, device);
  const { layout, visual } = splitStyles(resolved);
  const children = Array.isArray(element.content) ? element.content : [];
  const isEmpty = children.length === 0;
  const isBody = element.type === "__body";
  const isActive = dropTarget === element.id;
  const [dropIdx, setDropIdx] = useState<number>(-1);
  const wrapRef = useRef<HTMLDivElement>(null);

  const isRow = resolved.flexDirection === "row" || resolved.flexDirection === "row-reverse";

  const calcDropIdx = useCallback((e: React.DragEvent) => {
    if (!wrapRef.current) return children.length;
    const els = wrapRef.current.querySelectorAll(":scope > [data-el-id], :scope > [data-wrapper]");
    // Find closest edge between children
    let bestIdx = children.length;
    let bestDist = Infinity;
    for (let i = 0; i <= els.length; i++) {
      let edge: number;
      if (i === 0) {
        const r = els[0]?.getBoundingClientRect();
        edge = r ? (isRow ? r.left : r.top) : 0;
      } else if (i === els.length) {
        const r = els[els.length - 1]?.getBoundingClientRect();
        edge = r ? (isRow ? r.right : r.bottom) : 0;
      } else {
        const prev = els[i - 1].getBoundingClientRect();
        const next = els[i].getBoundingClientRect();
        edge = isRow ? (prev.right + next.left) / 2 : (prev.bottom + next.top) / 2;
      }
      const cursor = isRow ? e.clientX : e.clientY;
      const dist = Math.abs(cursor - edge);
      if (dist < bestDist) { bestDist = dist; bestIdx = i; }
    }
    return bestIdx;
  }, [children.length, isRow]);

  function handleDragOver(e: React.DragEvent) {
    e.preventDefault();
    e.stopPropagation();
    if (dropTarget !== element.id) dispatch({ type: "SET_DROP_TARGET", payload: { id: element.id } });
    setDropIdx(calcDropIdx(e));
  }

  function handleDragLeave(e: React.DragEvent) {
    e.stopPropagation();
    const related = e.relatedTarget as Node | null;
    if (wrapRef.current && related && wrapRef.current.contains(related)) return;
    setDropIdx(-1);
    if (dropTarget === element.id) dispatch({ type: "SET_DROP_TARGET", payload: { id: null } });
  }

  function handleDrop(e: React.DragEvent) {
    e.preventDefault();
    e.stopPropagation();
    const idx = dropIdx >= 0 ? dropIdx : children.length;
    setDropIdx(-1);
    dispatch({ type: "SET_DROP_TARGET", payload: { id: null } });

    const type = e.dataTransfer.getData("componentType");
    const moveId = e.dataTransfer.getData("moveElementId");

    if (type === "__saved") {
      const raw = e.dataTransfer.getData("savedElement");
      if (raw) { try { const el = JSON.parse(raw) as El; dispatch({ type: "ADD_ELEMENT", payload: { containerId: element.id, element: el, index: idx } }); } catch { /* skip */ } }
    } else if (type) {
      const newEl = makeElInContext(type, element);
      if (newEl) dispatch({ type: "ADD_ELEMENT", payload: { containerId: element.id, element: newEl, index: idx } });
    } else if (moveId && moveId !== element.id) {
      dispatch({ type: "MOVE_ELEMENT", payload: { elId: moveId, targetContainerId: element.id, index: idx } });
    }
  }

  const indicator = (
    <div className={cn(
      "shrink-0 rounded-full bg-primary transition-opacity",
      isRow ? "w-[3px] self-stretch min-h-[20px]" : "h-[3px] w-full"
    )} />
  );

  return (
    <ElementWrapper element={element} style={visual} containerEl>
      <div
        ref={wrapRef}
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        className={cn(
          "min-h-[40px]",
          isActive && !isEmpty && "bg-primary/[0.02]"
        )}
        style={isBody ? { ...layout, display: 'flex', flexDirection: 'column' as const, gap: layout.gap ?? 0 } : layout}
      >
        {children.map((child, i) => isBody ? (
          <React.Fragment key={child.id}>
            {isActive && dropIdx === i && indicator}
            <Recursive element={child} />
          </React.Fragment>
        ) : (
          <div key={child.id} data-el-id={child.id} className="min-w-0 relative break-words">
            {isActive && dropIdx === i && indicator}
            <Recursive element={child} />
          </div>
        ))}
        {isActive && dropIdx === children.length && !isEmpty && indicator}
        {isEmpty && !preview && (
          <div className={cn(
            "flex items-center justify-center border-2 border-dashed rounded-md text-xs transition-colors flex-1",
            isBody ? "min-h-[calc(100vh-56px)]" : "min-h-[48px] min-w-[48px]",
            isActive
              ? "border-primary/40 text-primary/70 bg-primary/[0.02]"
              : "border-border/30 text-muted-foreground/40"
          )}>
            {isBody ? "Drag a component here to start" : "Drop here"}
          </div>
        )}
      </div>
    </ElementWrapper>
  );
}

'use client';

import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';

type DragInfo = { label: string; x: number; y: number } | null;

const DragOverlayContext = createContext<{
  start: (label: string, e: React.DragEvent) => void;
}>({ start: () => {} });

export function useDragOverlay() { return useContext(DragOverlayContext); }

// 1x1 transparent image to hide native ghost
let emptyImg: HTMLImageElement | null = null;
function getEmptyImg() {
  if (!emptyImg) {
    emptyImg = new Image();
    emptyImg.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
  }
  return emptyImg;
}

export function DragOverlayProvider({ children }: { children: ReactNode }) {
  const [info, setInfo] = useState<DragInfo>(null);

  const start = useCallback((label: string, e: React.DragEvent) => {
    e.dataTransfer.setDragImage(getEmptyImg(), 0, 0);
    setInfo({ label, x: e.clientX, y: e.clientY });
  }, []);

  useEffect(() => {
    if (!info) return;
    const onDrag = (e: DragEvent) => {
      // dragover fires on document with coordinates
      if (e.clientX === 0 && e.clientY === 0) return; // browser sends 0,0 at end
      setInfo(prev => prev ? { ...prev, x: e.clientX, y: e.clientY } : null);
    };
    const onEnd = () => setInfo(null);
    document.addEventListener('dragover', onDrag);
    document.addEventListener('dragend', onEnd);
    document.addEventListener('drop', onEnd);
    return () => {
      document.removeEventListener('dragover', onDrag);
      document.removeEventListener('dragend', onEnd);
      document.removeEventListener('drop', onEnd);
    };
  }, [!!info]);

  return (
    <DragOverlayContext.Provider value={{ start }}>
      {children}
      {info && createPortal(
        <div
          className="pointer-events-none fixed z-[9999]"
          style={{ left: info.x + 12, top: info.y - 12 }}
        >
          <div className="rounded-lg border border-primary/30 bg-background px-3 py-2 text-xs font-medium shadow-lg whitespace-nowrap animate-in fade-in-0 zoom-in-95 duration-150">
            {info.label}
          </div>
        </div>,
        document.body
      )}
    </DragOverlayContext.Provider>
  );
}

'use client';

import { useRef, type CSSProperties, type ReactNode } from 'react';
import { useDocumentStore } from '../core/document-store';
import { useEditorStore } from '../core/editor-store';
import { useEditor } from '../core/provider';
import { ContextMenu, ContextMenuTrigger } from '@/components/ui/context-menu';
import { cn } from '@/shared/utils';
import type { El } from '../core/types';
import { resolveStyles } from '../core/types';
import { findParentId } from '../core/tree-helpers';
import { isContainer } from '../core/registry';
import { splitContentStyles } from './interactions/use-style-split';
import { BoxHandlesOverlay } from './interactions/box-handles-overlay';
import { ElementContextMenu } from './interactions/context-menu';
import { ResizeHandles } from './handles/resize-handles';
import { FontSizeHandle } from './handles/font-size-handle';
import { DimensionsBadge } from './handles/dimensions-badge';

import { MotionWrapper } from './motion-wrapper';

const TEXT_TYPES = new Set(['text', 'heading', 'subheading', 'quote', 'code', 'badge', 'list']);

type Props = { element: El; children: ReactNode; className?: string; style?: CSSProperties; containerEl?: boolean };

export default function ElementWrapper({ element, children, className, style, containerEl }: Props) {
  const { dispatch } = useEditor();
  const selected = useEditorStore(s => s.selected);
  const preview = useEditorStore(s => s.preview);
  const hovered = useEditorStore(s => s.hovered);
  const dropTarget = useEditorStore(s => s.dropTarget);
  const device = useEditorStore(s => s.device);
  const editingState = useEditorStore(s => s.editingState);
  const elements = useDocumentStore(s => s.elements);
  const wrapperRef = useRef<HTMLDivElement>(null);

  const isBody = element.type === '__body';
  const isSel = selected?.id === element.id;
  const isHov = hovered === element.id && !isSel;
  const isDrop = dropTarget === element.id && containerEl;
  const parentId = findParentId(elements, element.id);

  let resolved = style ?? resolveStyles(element, device);
  if (isSel && editingState === 'hover' && element.hoverStyles) {
    resolved = { ...resolved, ...element.hoverStyles };
  }

  const { wrapperStyles, contentStyles, hasContentStyles } = splitContentStyles(resolved);

  if (element.hidden && preview) return null;
  if (element.hidden && !preview) return <div className={`relative opacity-40 pointer-events-none el-${element.id}`} style={resolved}>{children}</div>;
  if (preview) {
    return (
      <MotionWrapper animations={element.animations} style={resolved} className={cn(`el-${element.id}`, className)}>
        {children}
      </MotionWrapper>
    );
  }

  return (
    <ContextMenu>
    <ContextMenuTrigger disabled={isBody} asChild>
    <MotionWrapper
      ref={wrapperRef}
      animations={element.animations}
      disableAnimations={!preview}
      data-wrapper
      data-el-id={element.id}
      draggable={!isBody && !element.locked}
      onDragStart={(e: any) => {
        if (isBody || element.locked) { e.preventDefault(); return; }
        e.dataTransfer.setData('moveElementId', element.id);
        e.dataTransfer.effectAllowed = 'move';
        e.stopPropagation();
      }}
      className={cn(
        `el-${element.id}`,
        'relative group/el min-w-0',
        isSel && !isBody && 'outline outline-2 outline-blue-500 -outline-offset-1',
        isHov && !isBody && 'outline outline-1 outline-blue-400/40 -outline-offset-1 cursor-pointer',
        isDrop && 'outline outline-2 outline-emerald-500/60 -outline-offset-1 bg-emerald-500/[0.04] cursor-copy',
        isBody && 'min-h-full',
        !isBody && element.locked && 'cursor-not-allowed opacity-90',
        className,
      )}
      style={wrapperStyles as CSSProperties}
      onClick={(e: any) => { e.stopPropagation(); dispatch({ type: 'CHANGE_CLICKED_ELEMENT', payload: { element } }); }}
      onDragOver={(e: any) => { e.preventDefault(); }}
      onMouseEnter={() => dispatch({ type: 'SET_HOVERED', payload: { id: element.id } })}
      onMouseLeave={() => { if (hovered === element.id) dispatch({ type: 'SET_HOVERED', payload: { id: null } }); }}
    >
      {!isBody && <BoxHandlesOverlay element={element} isSel={isSel} isHov={isHov} dispatch={dispatch} />}

      {isSel && !isBody && !element.locked && (<>
        {!isContainer(element.type) && <ResizeHandles element={element} wrapperRef={wrapperRef} dispatch={dispatch} />}
        {TEXT_TYPES.has(element.type) && <FontSizeHandle element={element} dispatch={dispatch} />}
        <DimensionsBadge wrapperRef={wrapperRef} isSelected={isSel} />
      </>)}

      {hasContentStyles ? <div style={contentStyles as CSSProperties}>{children}</div> : children}
    </MotionWrapper>
    </ContextMenuTrigger>
    {!isBody && <ElementContextMenu element={element} parentId={parentId} dispatch={dispatch} />}
    </ContextMenu>
  );
}

