import React, { useState, useEffect, useRef, useCallback } from "react";

export type CanvasTransform = { x: number; y: number; z: number };

const MIN_ZOOM = 0.1;
const MAX_ZOOM = 3;
const ZOOM_SPEED = 0.002;

export function useCanvas() {
  const [canvasEl, setCanvasEl] = useState<HTMLDivElement | null>(null);
  const canvasRefObj = useRef<HTMLDivElement | null>(null);
  const canvasRef = useCallback((node: HTMLDivElement | null) => { canvasRefObj.current = node; setCanvasEl(node); }, []);
  const [transform, setTransform] = useState<CanvasTransform>({ x: 0, y: 0, z: 1 });
  const [panning, setPanning] = useState(false);
  const [altHeld, setAltHeld] = useState(false);
  const spaceRef = useRef(false);
  const tRef = useRef(transform);
  tRef.current = transform;

  // ── Zoom to cursor (pinch + Cmd+scroll) + free scroll ──
  useEffect(() => {
    const el = canvasEl;
    if (!el) return;

    // Auto-fit on mount
    requestAnimationFrame(() => {
      const rect = el.getBoundingClientRect();
      const canvas = el.querySelector("[data-canvas]");
      const cw = canvas ? canvas.scrollWidth : 800;
      const pad = 40;
      const z = Math.min((rect.width - pad * 2) / cw, 1);
      setTransform({ x: (rect.width - cw * z) / 2, y: pad, z });
    });

    const onWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const rect = el.getBoundingClientRect();
        const cx = e.clientX - rect.left;
        const cy = e.clientY - rect.top;
        const t = tRef.current;
        const factor = Math.exp(-e.deltaY * ZOOM_SPEED);
        const nz = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, t.z * factor));
        const nx = cx - (cx - t.x) * (nz / t.z);
        const ny = cy - (cy - t.y) * (nz / t.z);
        setTransform({ x: nx, y: ny, z: nz });
        return;
      }
      e.preventDefault();
      const t = tRef.current;
      setTransform({ x: t.x - e.deltaX, y: t.y - e.deltaY, z: t.z });
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => el.removeEventListener("wheel", onWheel);
  }, [canvasEl]);

  // ── Space/Alt key tracking ──
  useEffect(() => {
    const onDown = (e: KeyboardEvent) => {
      if (e.code === "Space" && !(e.target as HTMLElement).matches("input,textarea,[contenteditable]")) { e.preventDefault(); spaceRef.current = true; setPanning(true); }
      if (e.key === "Alt") setAltHeld(true);
    };
    const onUp = (e: KeyboardEvent) => {
      if (e.code === "Space") { spaceRef.current = false; setPanning(false); }
      if (e.key === "Alt") setAltHeld(false);
    };
    window.addEventListener("keydown", onDown);
    window.addEventListener("keyup", onUp);
    return () => { window.removeEventListener("keydown", onDown); window.removeEventListener("keyup", onUp); };
  }, []);

  // ── Space+drag / middle-click pan ──
  const onCanvasPointerDown = useCallback((e: React.PointerEvent) => {
    const shouldPan = spaceRef.current || e.button === 1;
    if (!shouldPan) return;
    e.preventDefault();
    const sx = e.clientX, sy = e.clientY;
    const st = tRef.current;
    const onMove = (ev: PointerEvent) => {
      setTransform({ x: st.x + (ev.clientX - sx), y: st.y + (ev.clientY - sy), z: st.z });
    };
    const onUp = () => { document.removeEventListener("pointermove", onMove); document.removeEventListener("pointerup", onUp); };
    document.addEventListener("pointermove", onMove);
    document.addEventListener("pointerup", onUp);
  }, []);

  // ── Zoom helpers ──
  const zoomTo = useCallback((newZ: number) => {
    if (!canvasEl) return;
    const rect = canvasEl.getBoundingClientRect();
    const cx = rect.width / 2, cy = rect.height / 2;
    const t = tRef.current;
    const nz = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, newZ));
    setTransform({ x: cx - (cx - t.x) * (nz / t.z), y: cy - (cy - t.y) * (nz / t.z), z: nz });
  }, [canvasEl]);

  const zoomIn = useCallback(() => zoomTo(tRef.current.z * 1.2), [zoomTo]);
  const zoomOut = useCallback(() => zoomTo(tRef.current.z / 1.2), [zoomTo]);
  const zoomReset = useCallback(() => {
    if (!canvasEl) return;
    const rect = canvasEl.getBoundingClientRect();
    const canvas = canvasEl.querySelector("[data-canvas]");
    const cw = canvas ? canvas.scrollWidth : 800;
    const ch = canvas ? canvas.scrollHeight : 600;
    const pad = 40;
    const z = Math.min((rect.width - pad * 2) / cw, 1);
    setTransform({ x: (rect.width - cw * z) / 2, y: pad, z });
  }, [canvasEl]);

  const zoomToFit = useCallback((contentWidth: number, contentHeight: number) => {
    if (!canvasEl) return;
    const rect = canvasEl.getBoundingClientRect();
    const pad = 60;
    const nz = Math.min((rect.width - pad * 2) / contentWidth, (rect.height - pad * 2) / contentHeight, MAX_ZOOM);
    setTransform({ x: (rect.width - contentWidth * nz) / 2, y: pad, z: nz });
  }, [canvasEl]);

  const zoomToRect = useCallback((elRect: { x: number; y: number; w: number; h: number }) => {
    if (!canvasEl) return;
    const rect = canvasEl.getBoundingClientRect();
    const pad = 80;
    const nz = Math.min((rect.width - pad * 2) / elRect.w, (rect.height - pad * 2) / elRect.h, MAX_ZOOM);
    setTransform({
      x: (rect.width - elRect.w * nz) / 2 - elRect.x * nz,
      y: (rect.height - elRect.h * nz) / 2 - elRect.y * nz,
      z: nz,
    });
  }, [canvasEl]);

  const transformCSS = `translate(${transform.x}px, ${transform.y}px) scale(${transform.z})`;
  const cursor = panning ? "cursor-grab active:cursor-grabbing" : altHeld ? "cursor-copy" : "";

  const zoom = Math.round(transform.z * 100);
  const setZoom: React.Dispatch<React.SetStateAction<number>> = useCallback((action) => {
    const current = Math.round(tRef.current.z * 100);
    const newPct = typeof action === "function" ? action(current) : action;
    zoomTo(newPct / 100);
  }, [zoomTo]);

  return {
    canvasRef, canvasRefObj, transform, setTransform, transformCSS,
    zoom, setZoom, zoomIn, zoomOut, zoomReset, zoomToFit, zoomToRect,
    panning, altHeld, spaceRef, onCanvasPointerDown, cursor,
  };
}

'use client';

import React, { createContext, useContext, useEffect, useCallback, useMemo } from 'react';
import type { El, Device, EditorProps } from './types';
import { useDocumentStore } from './document-store';
import { useEditorStore } from './editor-store';
import { findEl } from './tree-helpers';

// ─── Legacy action type (for compatibility) ─────────────────

type EditorAction =
  | { type: 'ADD_ELEMENT'; payload: { containerId: string; element: El; index?: number } }
  | { type: 'UPDATE_ELEMENT'; payload: { element: El } }
  | { type: 'UPDATE_ELEMENT_LIVE'; payload: { element: El } }
  | { type: 'COMMIT_HISTORY' }
  | { type: 'DELETE_ELEMENT'; payload: { id: string } }
  | { type: 'MOVE_ELEMENT'; payload: { elId: string; targetContainerId: string; index?: number } }
  | { type: 'REORDER_ELEMENT'; payload: { elId: string; direction: 'up' | 'down' } }
  | { type: 'DUPLICATE_ELEMENT'; payload: { elId: string; containerId: string } }
  | { type: 'CHANGE_CLICKED_ELEMENT'; payload: { element: El | null } }
  | { type: 'CHANGE_DEVICE'; payload: { device: Device } }
  | { type: 'TOGGLE_PREVIEW' }
  | { type: 'SET_HOVERED'; payload: { id: string | null } }
  | { type: 'SET_DROP_TARGET'; payload: { id: string | null } }
  | { type: 'SET_EDITING_STATE'; payload: 'default' | 'hover' }
  | { type: 'LOAD_DATA'; payload: { elements: El[] } }
  | { type: 'SET_ELEMENTS'; payload: { elements: El[] } }
  | { type: 'UNDO' }
  | { type: 'REDO' };

export type { EditorAction };

// ─── Legacy state shape (for compatibility) ─────────────────

type EditorState = {
  elements: El[];
  selected: El | null;
  device: Device;
  preview: boolean;
  hovered: string | null;
  dropTarget: string | null;
  dirty: boolean;
  clipboard: El | null;
  zoom: number;
  editingState: 'default' | 'hover';
};

type HistoryState = { patchCount: number; currentIndex: number };
type EditorStore = { editor: EditorState; history: HistoryState };
export type { EditorState, HistoryState, EditorStore };

// ─── Context (page-level props only) ────────────────────────

type EditorContextValue = {
  pageId: string;
  pageName: string;
  tenantId: string;
  userId: string;
  activePageId: string | null;
  activePageName: string;
  activePageSlug: string;
  activePageSeoTitle: string | null;
  activePageSeoDescription: string | null;
  activePageOgImage: string | null;
  themeConfig: Record<string, string> | null;
  currency: string;
  sampleProduct?: { id: string; name: string; price: number; compareAtPrice?: number | null; description?: string | null; slug: string; images: { url: string; alt: string }[] };
};

const EditorContext = createContext<EditorContextValue | null>(null);

// ─── Compatibility hook — maps Zustand to old API ───────────

export function useEditor() {
  const ctx = useContext(EditorContext);
  if (!ctx) throw new Error('useEditor must be used inside EditorProvider');

  const elements = useDocumentStore(s => s.elements);
  const dirty = useDocumentStore(s => s.dirty);
  const patchCount = useDocumentStore(s => s.patches.length);
  const currentIndex = useDocumentStore(s => s.currentIndex);

  const selected = useEditorStore(s => s.selected);
  const hovered = useEditorStore(s => s.hovered);
  const dropTarget = useEditorStore(s => s.dropTarget);
  const device = useEditorStore(s => s.device);
  const preview = useEditorStore(s => s.preview);
  const zoom = useEditorStore(s => s.zoom);
  const editingState = useEditorStore(s => s.editingState);

  const doc = useDocumentStore.getState();
  const ui = useEditorStore.getState();

  const dispatch = useCallback((action: EditorAction) => {
    switch (action.type) {
      case 'ADD_ELEMENT': doc.addElement(action.payload.containerId, action.payload.element, action.payload.index); break;
      case 'UPDATE_ELEMENT': doc.updateElement(action.payload.element); break;
      case 'UPDATE_ELEMENT_LIVE': doc.updateElementLive(action.payload.element); break;
      case 'COMMIT_HISTORY': doc.commitHistory(); break;
      case 'DELETE_ELEMENT': doc.deleteElement(action.payload.id); break;
      case 'MOVE_ELEMENT': doc.moveElement(action.payload.elId, action.payload.targetContainerId, action.payload.index); break;
      case 'REORDER_ELEMENT': doc.reorderElement(action.payload.elId, action.payload.direction); break;
      case 'DUPLICATE_ELEMENT': doc.duplicateElement(action.payload.elId, action.payload.containerId); break;
      case 'CHANGE_CLICKED_ELEMENT': ui.select(action.payload.element); break;
      case 'CHANGE_DEVICE': ui.setDevice(action.payload.device); break;
      case 'TOGGLE_PREVIEW': ui.togglePreview(); break;
      case 'SET_HOVERED': ui.hover(action.payload.id); break;
      case 'SET_DROP_TARGET': ui.setDropTarget(action.payload.id); break;
      case 'SET_EDITING_STATE': ui.setEditingState(action.payload); break;
      case 'LOAD_DATA': doc.loadData(action.payload.elements); break;
      case 'SET_ELEMENTS': doc.setElements(action.payload.elements); break;
      case 'UNDO': {
        doc.undo();
        const el = useEditorStore.getState().selected;
        if (el) { const found = findEl(useDocumentStore.getState().elements, el.id); ui.select(found ?? null); }
        break;
      }
      case 'REDO': {
        doc.redo();
        const el = useEditorStore.getState().selected;
        if (el) { const found = findEl(useDocumentStore.getState().elements, el.id); ui.select(found ?? null); }
        break;
      }
    }
  }, [doc, ui]);

  const state: EditorStore = useMemo(() => ({
    editor: { elements, selected, device, preview, hovered, dropTarget, dirty, clipboard: null, zoom, editingState },
    history: { patchCount, currentIndex },
  }), [elements, selected, device, preview, hovered, dropTarget, dirty, zoom, editingState, patchCount, currentIndex]);

  return { state, dispatch, ...ctx };
}

// ─── Provider ───────────────────────────────────────────────

type EditorProviderProps = EditorProps & { children: React.ReactNode; sampleProduct?: any };

export function EditorProvider({ children, pageId, pageName, tenantId, userId, initialContent, activePageId, activePageName, activePageSlug, activePageSeoTitle, activePageSeoDescription, activePageOgImage, themeConfig, initialServerRevision = 0, currency = "NPR", sampleProduct }: EditorProviderProps) {
  useEffect(() => {
    if (initialContent) {
      try {
        const parsed = JSON.parse(initialContent);
        if (Array.isArray(parsed) && parsed.length > 0) {
          const root = parsed[0];
          if (root && typeof root.id === 'string' && typeof root.type === 'string' && root.styles) {
            useDocumentStore.getState().loadData(parsed as El[], initialServerRevision);
            return;
          }
        } else if (parsed?.schemaVersion === 2 && Array.isArray(parsed.root) && parsed.root.length > 0) {
          useDocumentStore.getState().loadData(parsed.root as El[], initialServerRevision);
          return;
        }
      } catch { /* invalid JSON */ }
    }
    // No valid content — create default body
    const body: El = {
      id: '__body',
      type: '__body',
      name: 'Body',
      styles: { display: 'flex', flexDirection: 'column', minHeight: '100vh', width: '100%', fontFamily: 'Inter, system-ui, sans-serif' },
      content: [],
    };
    useDocumentStore.getState().loadData([body], initialServerRevision);
  }, [initialContent, initialServerRevision]);

  // Initialize currentPageId in store
  useEffect(() => {
    useEditorStore.getState().setCurrentPageId(activePageId ?? null);
  }, [activePageId]);

  const ctx = useMemo(() => ({ pageId, pageName, tenantId, userId, activePageId: activePageId ?? null, activePageName: activePageName ?? 'Home', activePageSlug: activePageSlug ?? '', activePageSeoTitle: activePageSeoTitle ?? null, activePageSeoDescription: activePageSeoDescription ?? null, activePageOgImage: activePageOgImage ?? null, themeConfig: themeConfig ?? null, currency, sampleProduct }), [pageId, pageName, tenantId, userId, activePageId, activePageName, activePageSlug, activePageSeoTitle, activePageSeoDescription, activePageOgImage, themeConfig, currency, sampleProduct]);

  return <EditorContext.Provider value={ctx}>{children}</EditorContext.Provider>;
}

import React from "react";
import { register } from "../types";
import { type El } from "../../types";
import { Code } from "lucide-react";

register({
  type: "embed",
  name: "HTML Embed",
  icon: Code as any,
  color: "text-rose-500",
  group: "Interactive",
  isContainer: false,
  factory: () => ({
    id: crypto.randomUUID(),
    type: "embed",
    name: "HTML Embed",
    styles: {
      width: "100%",
    },
    content: {
      code: "<!-- Paste your custom HTML/JS/CSS here -->\n<div style=\"padding: 20px; background: #f3f4f6; text-align: center; border-radius: 8px;\">\n  <h3>Custom Code Block</h3>\n</div>",
    },
  }),
  render: ({ element }) => {
    const content = element.content as Record<string, string>;
    const code = content?.code || "";

    return (
      <div 
        style={element.styles as React.CSSProperties} 
        className="w-full relative"
      >
        {/* We render dangerouslySetInnerHTML. To be safe in the editor, we pointer-events-none it so the user can still select it without child elements capturing clicks */}
        <div 
          className="pointer-events-none" 
          dangerouslySetInnerHTML={{ __html: code }} 
        />
      </div>
    );
  },
  exportHTML: (el: El) => {
    const content = el.content as Record<string, string>;
    const code = content?.code || "";
    // Export raw code (the user is responsible for ensuring it's valid and safe)
    return `
      <div style="width: ${el.styles.width || '100%'}">
        ${code}
      </div>
    `;
  }
});

