import { useCallback, type CSSProperties } from "react";
import type { El } from "./types";
import type { EditorAction } from "./provider";
import { cloneEl, findParentId, findEl as findElInTree } from "./tree-helpers";
import { toast } from "sonner";

type ShortcutDeps = {
  selected: El | null;
  elements: El[];
  clipboard: El | null;
  setClipboard: (el: El | null) => void;
  styleClipboard: CSSProperties | null;
  setStyleClipboard: (s: CSSProperties | null) => void;
  dispatch: React.Dispatch<EditorAction>;
  setDirty: (v: boolean) => void;
  setZoom: React.Dispatch<React.SetStateAction<number>>;
  handleSave: () => void;
  zoomReset?: () => void;
  zoomToFit?: (w: number, h: number) => void;
  zoomToRect?: (r: { x: number; y: number; w: number; h: number }) => void;
};

export function useShortcuts(deps: ShortcutDeps) {
  const { selected, elements, clipboard, setClipboard, styleClipboard, setStyleClipboard, dispatch, setDirty, setZoom, handleSave, zoomReset, zoomToFit, zoomToRect } = deps;

  return useCallback((e: React.KeyboardEvent) => {
    const mod = e.metaKey || e.ctrlKey;
    const tag = (e.target as HTMLElement).tagName;
    const isInput = tag === "INPUT" || tag === "TEXTAREA" || (e.target as HTMLElement).isContentEditable;

    if (mod && e.key === "z") { e.preventDefault(); e.shiftKey ? dispatch({ type: "REDO" }) : dispatch({ type: "UNDO" }); }
    if (mod && e.key === "s") { e.preventDefault(); handleSave(); }
    if (mod && e.key === "d" && selected && selected.type !== "__body") {
      e.preventDefault();
      const pid = findParentId(elements, selected.id);
      if (pid) { dispatch({ type: "DUPLICATE_ELEMENT", payload: { elId: selected.id, containerId: pid } }); setDirty(true); }
    }
    if (mod && !e.altKey && e.key === "c" && selected && selected.type !== "__body") { e.preventDefault(); setClipboard(selected); toast.success("Copied"); }
    if (mod && e.altKey && e.key === "c" && selected) { e.preventDefault(); setStyleClipboard(selected.styles); toast.success("Styles copied"); }
    if (mod && e.altKey && e.key === "v" && selected && styleClipboard) {
      e.preventDefault();
      dispatch({ type: "UPDATE_ELEMENT", payload: { element: { ...selected, styles: { ...selected.styles, ...styleClipboard } } } });
      setDirty(true); toast.success("Styles pasted");
    }
    if (mod && !e.altKey && e.key === "v" && clipboard) {
      e.preventDefault();
      const target = selected && Array.isArray(selected.content) ? selected.id : "__body";
      dispatch({ type: "ADD_ELEMENT", payload: { containerId: target, element: cloneEl(clipboard) } });
      setDirty(true);
    }
    if ((e.key === "Delete" || e.key === "Backspace") && selected && selected.type !== "__body" && !isInput) {
      dispatch({ type: "DELETE_ELEMENT", payload: { id: selected.id } }); setDirty(true);
    }
    if (e.key === "Escape") {
      if (selected && selected.type !== "__body") {
        const pid = findParentId(elements, selected.id);
        if (pid && pid !== "__body") { dispatch({ type: "CHANGE_CLICKED_ELEMENT", payload: { element: findElInTree(elements, pid) } }); }
        else dispatch({ type: "CHANGE_CLICKED_ELEMENT", payload: { element: null } });
      } else dispatch({ type: "CHANGE_CLICKED_ELEMENT", payload: { element: null } });
    }
    if (mod && e.key === "ArrowUp" && selected && selected.type !== "__body") { e.preventDefault(); dispatch({ type: "REORDER_ELEMENT", payload: { elId: selected.id, direction: "up" } }); setDirty(true); }
    if (mod && e.key === "ArrowDown" && selected && selected.type !== "__body") { e.preventDefault(); dispatch({ type: "REORDER_ELEMENT", payload: { elId: selected.id, direction: "down" } }); setDirty(true); }
    // ⌘[ / ⌘] — send backward / forward
    if (mod && e.key === "[" && selected && selected.type !== "__body") { e.preventDefault(); dispatch({ type: "REORDER_ELEMENT", payload: { elId: selected.id, direction: "up" } }); setDirty(true); }
    if (mod && e.key === "]" && selected && selected.type !== "__body") { e.preventDefault(); dispatch({ type: "REORDER_ELEMENT", payload: { elId: selected.id, direction: "down" } }); setDirty(true); }
    // ⌘⇧L — lock/unlock
    if (mod && e.shiftKey && e.key === "L" && selected && selected.type !== "__body") {
      e.preventDefault();
      dispatch({ type: "UPDATE_ELEMENT", payload: { element: { ...selected, locked: !selected.locked } } });
      toast.success(selected.locked ? "Unlocked" : "Locked");
    }
    // ⌘⇧H — hide/show
    if (mod && e.shiftKey && e.key === "H" && selected && selected.type !== "__body") {
      e.preventDefault();
      dispatch({ type: "UPDATE_ELEMENT", payload: { element: { ...selected, hidden: !selected.hidden } } });
      toast.success(selected.hidden ? "Shown" : "Hidden");
    }
    if (mod && e.key === "=") { e.preventDefault(); setZoom((z) => Math.min(200, z + 10)); }
    if (mod && e.key === "-") { e.preventDefault(); setZoom((z) => Math.max(25, z - 10)); }
    if (mod && e.key === "0") { e.preventDefault(); if (zoomReset) zoomReset(); else setZoom(100); }
    if (mod && e.key === "1") {
      e.preventDefault();
      if (zoomToFit) {
        const canvas = document.querySelector("[data-canvas]");
        if (canvas) zoomToFit(canvas.scrollWidth, canvas.scrollHeight);
      }
    }
    if (mod && e.key === "2") {
      e.preventDefault();
      if (zoomToRect && selected) {
        const dom = document.querySelector(`[data-el-id="${selected.id}"]`);
        const canvas = document.querySelector("[data-canvas]");
        if (dom && canvas) {
          const cr = canvas.getBoundingClientRect();
          const dr = dom.getBoundingClientRect();
          const z = parseFloat(getComputedStyle(canvas).getPropertyValue("--zoom") || "1");
          zoomToRect({ x: (dr.left - cr.left) / z, y: (dr.top - cr.top) / z, w: dr.width / z, h: dr.height / z });
        }
      }
    }
    if (mod && e.key === "a") { e.preventDefault(); dispatch({ type: "CHANGE_CLICKED_ELEMENT", payload: { element: elements[0] } }); }
  }, [selected, clipboard, styleClipboard, elements, dispatch, setDirty, setZoom, handleSave, setClipboard, setStyleClipboard]);
}

import type { El } from '../core/types';
import { getDef } from '../core/registry';
import { parseCsv, parseItems, parseNumber } from '../lib/content-utils';
import { safeUrl } from '@/shared/utils/safe-url';
import type { ExportRendererType } from '../core/registry/renderer-manifests';

/** Escape HTML entities to prevent XSS */
function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function cssify(styles: Record<string, unknown>): string {
  const UNSAFE_CSS = /expression|javascript:|url\s*\(|behavior:|\\-moz\\-binding|@import|@charset/i;
  return Object.entries(styles).filter(([, v]) => v !== undefined && v !== '').filter(([, v]) => !UNSAFE_CSS.test(String(v))).map(([k, v]) => `${k.replace(/([A-Z])/g, '-$1').toLowerCase()}:${String(v).replace(/[;\"<>{}\\]/g, '')}`).join(';');
}

const LAYOUT_KEYS = new Set(['display', 'flexDirection', 'gap', 'rowGap', 'columnGap', 'flexWrap', 'alignItems', 'justifyContent', 'justifyItems', 'gridTemplateColumns', 'gridTemplateRows']);

function splitContainerStyles(styles: Record<string, unknown>): { outer: Record<string, unknown>; inner: Record<string, unknown>; needsSplit: boolean } {
  const outer: Record<string, unknown> = {};
  const inner: Record<string, unknown> = {};
  let hasLayout = false;
  let hasVisual = false;
  for (const [k, v] of Object.entries(styles)) {
    if (v === undefined || v === '') continue;
    if (LAYOUT_KEYS.has(k)) { inner[k] = v; hasLayout = true; }
    else { outer[k] = v; if (['padding','paddingTop','paddingRight','paddingBottom','paddingLeft','background','backgroundColor','border','borderRadius'].includes(k)) hasVisual = true; }
  }
  return { outer, inner, needsSplit: hasLayout && hasVisual };
}

function containerHtml(el: El, fonts: Set<string>, did: string, tag: string, children: string): string {
  const style = cssify(el.styles as Record<string, unknown>);
  const { outer, inner, needsSplit } = splitContainerStyles(el.styles as Record<string, unknown>);
  return needsSplit
    ? `<${tag}${did} style="${cssify(outer)}"><div style="${cssify(inner)}">${children}</div></${tag}>`
    : `<${tag}${did} style="${style}">${children}</${tag}>`;
}

// ─── Per-type static export renderers ───────────────────────
// Shared with the storefront/canvas coverage test. def.exportHTML takes
// precedence when present; this map is the fallback for built-in types.

const EXPORT_RENDERERS: Record<ExportRendererType, (el: El, fonts: Set<string>) => string> = {
  text: (el, _f) => `<p data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</p>`,
  heading: (el, _f) => `<h1 data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</h1>`,
  subheading: (el, _f) => `<h2 data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</h2>`,
  link: (el, _f) => { const href = safeUrl((el.content as Record<string,string>)?.href) ?? '#'; return `<a data-id="${el.id}" href="${esc(href)}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</a>`; },
  button: (el, _f) => { const href = safeUrl((el.content as Record<string,string>)?.href) ?? '#'; return `<a data-id="${el.id}" href="${esc(href)}" style="${cssify(el.styles as Record<string, unknown>)};display:inline-block;text-decoration:none">${esc((el.content as Record<string,string>)?.innerText || '')}</a>`; },
  image: (el, _f) => { const src = safeUrl((el.content as Record<string,string>)?.src) ?? ''; return `<img data-id="${el.id}" src="${esc(src)}" alt="${esc((el.content as Record<string,string>)?.alt || '')}" style="${cssify(el.styles as Record<string, unknown>)}" />`; },
  video: (el, _f) => { const src = safeUrl((el.content as Record<string,string>)?.src) ?? ''; return `<iframe data-id="${el.id}" src="${esc(src)}" style="${cssify(el.styles as Record<string, unknown>)};border:0" allowfullscreen></iframe>`; },
  divider: (el, _f) => `<hr data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}" />`,
  spacer: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}"></div>`,
  icon: (el, _f) => `<span data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '★')}</span>`,
  badge: (el, _f) => `<span data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</span>`,
  quote: (el, _f) => `<blockquote data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${esc((el.content as Record<string,string>)?.innerText || '')}</blockquote>`,
  list: (el, _f) => `<ul data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${parseCsv((el.content as Record<string,string>)?.innerText).map(li => `<li>${esc(li)}</li>`).join('')}</ul>`,
  code: (el, _f) => `<pre data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}"><code>${esc((el.content as Record<string,string>)?.innerText || '')}</code></pre>`,
  embed: (el, _f) => `<div data-id="${el.id}" style="width:${el.styles.width || '100%'}">${esc((el.content as Record<string,string>)?.code || '')}</div>`,
  map: (el, _f) => `<iframe data-id="${el.id}" src="https://maps.google.com/maps?q=${encodeURIComponent((el.content as Record<string,string>)?.address || '')}&z=${(el.content as Record<string,string>)?.zoom || '13'}&output=embed" style="${cssify(el.styles as Record<string, unknown>)};border:0" loading="lazy"></iframe>`,
  gallery: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${parseCsv((el.content as Record<string,string>)?.images).map(src => `<img src="${esc(src)}" style="width:100%;object-fit:cover" />`).join('')}</div>`,
  socialIcons: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${parseCsv((el.content as Record<string,string>)?.platforms).map(p => `<a href="#" style="opacity:0.7">${esc(p)}</a>`).join('')}</div>`,
  accordion: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${parseItems((el.content as Record<string,string>)?.items).map(i => `<details><summary style="cursor:pointer;padding:12px 0;font-weight:600">${esc(i.title)}</summary><p style="padding:0 0 12px">${esc(i.body)}</p></details>`).join('')}</div>`,
  tabs: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${parseItems((el.content as Record<string,string>)?.items).map((t, i) => `<div style="padding:16px${i > 0 ? ';display:none' : ''}"><h4>${esc(t.title)}</h4><p>${esc(t.body)}</p></div>`).join('')}</div>`,
  countdown: (el, _f) => `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">Countdown to ${esc((el.content as Record<string,string>)?.targetDate || '')}</div>`,
  starRating: (el, _f) => { const r = parseNumber((el.content as Record<string,string>)?.rating, 5); return `<div data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${'★'.repeat(Math.floor(r))}${'☆'.repeat(5 - Math.floor(r))} <span style="opacity:0.6">(${esc((el.content as Record<string,string>)?.reviews || '0')})</span></div>`; },
  cartButton: (el, _f) => `<button data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">🛒 ${esc((el.content as Record<string,string>)?.innerText || 'Add to Cart')}</button>`,
  // Container elements with semantic tags
  navbar: (el, fonts) => { if (Array.isArray(el.content)) { const ch = el.content.map(child => renderEl(child, fonts)).join(''); return containerHtml(el, fonts, ` data-id="${el.id}"`, 'nav', ch); } return ''; },
  header: (el, fonts) => { if (Array.isArray(el.content)) { const ch = el.content.map(child => renderEl(child, fonts)).join(''); return containerHtml(el, fonts, ` data-id="${el.id}"`, 'header', ch); } return ''; },
  footer: (el, fonts) => { if (Array.isArray(el.content)) { const ch = el.content.map(child => renderEl(child, fonts)).join(''); return containerHtml(el, fonts, ` data-id="${el.id}"`, 'footer', ch); } return ''; },
  section: (el, fonts) => { if (Array.isArray(el.content)) { const ch = el.content.map(child => renderEl(child, fonts)).join(''); return containerHtml(el, fonts, ` data-id="${el.id}"`, 'section', ch); } return ''; },
  contactForm: (el, fonts) => { if (Array.isArray(el.content)) return `<form data-id="${el.id}" style="${cssify(el.styles as Record<string, unknown>)}">${el.content.map(child => renderEl(child, fonts)).join('')}</form>`; return ''; },
};

/** Types that render via def.exportHTML only (they need custom output). */
const DEF_EXPORT_ONLY = new Set(["embed"]);

function renderEl(el: El, fonts: Set<string>): string {
  if (el.styles.fontFamily) fonts.add(String(el.styles.fontFamily).split(',')[0].trim().replace(/['"]/g, ''));
  const did = ` data-id="${el.id}"`;
  const style = cssify(el.styles as Record<string, unknown>);

  // Element-provided export (e.g. plugins, embed).
  const def = getDef(el.type);
  if (def?.exportHTML) return def.exportHTML(el);

  // Per-type renderer.
  const renderer = (EXPORT_RENDERERS as Record<string, ((el: El, fonts: Set<string>) => string) | undefined>)[el.type];
  if (renderer) return renderer(el, fonts);

  // Container fallback — split visual/layout like canvas does.
  if (Array.isArray(el.content)) {
    const children = el.content.map(child => renderEl(child, fonts)).join('');
    const { outer, inner, needsSplit } = splitContainerStyles(el.styles as Record<string, unknown>);
    if (needsSplit) return `<div${did} style="${cssify(outer)}"><div style="${cssify(inner)}">${children}</div></div>`;
    return `<div${did} style="${style}">${children}</div>`;
  }
  return `<div${did} style="${style}">${esc((el.content as Record<string, string>)?.innerText || '')}</div>`;
}

/** All leaf types handled by this export (for the coverage test). */
export function getExportHandledTypes(): string[] {
  return Object.keys(EXPORT_RENDERERS);
}

export function generateHTML(elements: El[], options: { title: string; description?: string; ogImage?: string }): string {
  const body = elements[0];
  if (!body) return '';
  const fonts = new Set<string>();
  const bodyHTML = renderEl(body, fonts);

  // Responsive styles
  const responsiveCSS: string[] = [];
  const collectResponsive = (el: El) => {
    if (el.responsiveStyles) {
      for (const [device, styles] of Object.entries(el.responsiveStyles)) {
        const bp = device === 'tablet' ? 768 : device === 'mobile' ? 420 : 0;
        if (bp && styles && Object.keys(styles).length) {
          responsiveCSS.push(`@media(max-width:${bp}px){[data-id="${el.id}"]{${cssify(styles as Record<string, unknown>)}}}`);
        }
      }
    }
    if (Array.isArray(el.content)) el.content.forEach(collectResponsive);
  };
  collectResponsive(body);

  const fontLinks = [...fonts].filter(f => f && f !== 'Inter' && f !== 'system-ui')
    .map(f => `<link href="https://fonts.googleapis.com/css2?family=${encodeURIComponent(f)}:wght@400;500;600;700;800&display=swap" rel="stylesheet">`).join('');

  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(options.title)}</title>${options.description ? `<meta name="description" content="${esc(options.description)}">` : ''}${options.ogImage ? `<meta property="og:image" content="${esc(options.ogImage)}">` : ''}${fontLinks}<style>*{box-sizing:border-box;margin:0}img{max-width:100%;height:auto}p,h1,h2,h3,h4,li,blockquote{word-break:break-word}@media(max-width:768px){h1{font-size:clamp(28px,5vw,48px)!important}h2{font-size:clamp(22px,4vw,36px)!important}}${responsiveCSS.join('')}</style></head><body style="margin:0;font-family:Inter,system-ui,sans-serif">${bodyHTML}</body></html>`;
}

export function downloadHTML(elements: El[], options: { title: string; description?: string; ogImage?: string }) {
  const html = generateHTML(elements, options);
  const blob = new Blob([html], { type: 'text/html' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${options.title.replace(/\s+/g, '-').toLowerCase()}.html`;
  a.click();
  URL.revokeObjectURL(url);
}

'use server';

import { authorizedAction, requireTenantUser } from '@/lib/auth';
import { editorProjects } from '@/db/schema/editor-projects';
import { editorPages } from '@/db/schema/editor-pages';
import { editorReusableComponents } from '@/db/schema/editor-reusable-components';
import { pageTemplates } from '@/db/schema/layouts';
import { products } from '@/db/schema/products';
import { collectionProducts, collections } from '@/db/schema/collections';
import { plans, subscriptions } from '@/db/schema/billing';
import { eq, and, asc, desc, sql, count } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';
import { uniquePageSlug } from '@/lib/page-utils';

function safeJsonParse(str: string, fallback: unknown = []): unknown {
  try { return JSON.parse(str); } catch { return fallback; }
}

export async function savePageTemplate(template: {
  name: string;
  content: string;
  userId: string;
}) {
  const user = await requireTenantUser();
  return authorizedAction(async (tx, tenantId) => {
    const [created] = await tx.insert(pageTemplates)
      .values({ tenantId, name: template.name, data: safeJsonParse(template.content), createdAt: new Date() })
      .returning();
    return { ...created, userId: user.id };
  });
}

export async function getPageTemplates() {
  return authorizedAction(async (tx, tenantId) => {
    const all = await tx.select().from(pageTemplates).where(eq(pageTemplates.tenantId, tenantId));
    return all.map(t => ({ id: t.id, name: t.name, content: JSON.stringify(t.data) }));
  });
}

export async function deletePageTemplate(id: string) {
  await authorizedAction(async (tx, tenantId) => {
    await tx.delete(pageTemplates).where(and(eq(pageTemplates.id, id), eq(pageTemplates.tenantId, tenantId)));
  });
}

// ─── Multi-Page CRUD ────────────────────────────────────

export async function getProjectPages(projectId: string) {
  return authorizedAction(async (tx, tenantId) => tx.select().from(editorPages)
    .where(and(eq(editorPages.projectId, projectId), eq(editorPages.tenantId, tenantId)))
    .orderBy(asc(editorPages.order)));
}

export async function updatePage(pageId: string, data: { name?: string; slug?: string; data?: string }) {
  return authorizedAction(async (tx, tenantId) => {
    const [page] = await tx.select({ projectId: editorPages.projectId }).from(editorPages)
      .where(and(eq(editorPages.id, pageId), eq(editorPages.tenantId, tenantId))).limit(1);
    if (!page) return null;

    const updates: Record<string, unknown> = { updatedAt: new Date() };

    if (data.name) {
      updates.name = data.name;
      if (!data.slug) {
        const slugify = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
        updates.slug = await uniquePageSlug(page.projectId, tenantId, slugify(data.name), pageId);
      }
    }
    if (data.slug) {
      updates.slug = await uniquePageSlug(page.projectId, tenantId, data.slug, pageId);
    }

    if (data.data) updates.data = safeJsonParse(data.data);
    const [updated] = await tx.update(editorPages).set(updates)
      .where(and(eq(editorPages.id, pageId), eq(editorPages.tenantId, tenantId))).returning();
    revalidatePath('/dashboard/pages');
    return updated ?? null;
  });
}

export async function setHomepage(projectId: string, pageId: string) {
  await authorizedAction(async (tx, tenantId) => {
    const owned = and(eq(editorPages.projectId, projectId), eq(editorPages.tenantId, tenantId));
    await tx.update(editorPages).set({ isHomepage: false }).where(owned);
    await tx.update(editorPages).set({ isHomepage: true, slug: '', updatedAt: new Date() })
      .where(and(eq(editorPages.id, pageId), owned));
    revalidatePath('/dashboard/pages');
  });
}

export async function setPageVisibility(pageId: string, visible: boolean) {
  await authorizedAction(async (tx, tenantId) => {
    await tx.update(editorPages).set({ visible, updatedAt: new Date() })
      .where(and(eq(editorPages.id, pageId), eq(editorPages.tenantId, tenantId)));
  });
}

export async function reorderProjectPages(projectId: string, orderedPageIds: string[]) {
  await authorizedAction(async (tx, tenantId) => {
    const ownedPages = await tx.select({ id: editorPages.id }).from(editorPages).where(and(
      eq(editorPages.projectId, projectId),
      eq(editorPages.tenantId, tenantId),
    ));
    const ownedIds = new Set(ownedPages.map((page) => page.id));
    if (orderedPageIds.length !== ownedIds.size || orderedPageIds.some((id) => !ownedIds.has(id))) {
      throw new Error("Invalid page order");
    }
    for (const [order, id] of orderedPageIds.entries()) {
      await tx.update(editorPages).set({ order, updatedAt: new Date() }).where(and(
        eq(editorPages.id, id),
        eq(editorPages.tenantId, tenantId),
      ));
    }
  });
}

// ─── SEO + Navigation ───────────────────────────────────

export async function updatePageSeo(pageId: string, seo: { seoTitle?: string; seoDescription?: string; ogImage?: string }) {
  await authorizedAction(async (tx, tenantId) => {
    await tx.update(editorPages).set({ ...seo, updatedAt: new Date() })
      .where(and(eq(editorPages.id, pageId), eq(editorPages.tenantId, tenantId)));
  });
}

export type NavItem = { id: string; label: string; pageId?: string; href?: string; children?: NavItem[] };

export async function saveNavConfig(projectId: string, navConfig: NavItem[]) {
  await authorizedAction(async (tx, tenantId) => {
    await tx.update(editorProjects).set({ navConfig, updatedAt: new Date() })
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId)));
  });
}

export async function getNavConfig(projectId: string): Promise<NavItem[]> {
  return authorizedAction(async (tx, tenantId) => {
    const [project] = await tx.select({ navConfig: editorProjects.navConfig }).from(editorProjects)
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId))).limit(1);
    return (project?.navConfig as NavItem[] | null) ?? [];
  });
}

// ─── Theme / Design Tokens ──────────────────────────────

import { type ThemeConfig, defaultThemeConfig } from "./theme-utils";

export async function getThemeConfig(projectId: string): Promise<ThemeConfig> {
  return authorizedAction(async (tx, tenantId) => {
    const [project] = await tx.select({ themeConfig: editorProjects.themeConfig }).from(editorProjects)
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId))).limit(1);
    return { ...defaultThemeConfig, ...(project?.themeConfig as Partial<ThemeConfig> | null) };
  });
}

export async function saveThemeConfig(projectId: string, theme: Partial<ThemeConfig>) {
  await authorizedAction(async (tx, tenantId) => {
    const [project] = await tx.select({ themeConfig: editorProjects.themeConfig }).from(editorProjects)
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId))).limit(1);
    const current = { ...defaultThemeConfig, ...(project?.themeConfig as Partial<ThemeConfig> | null) };
    await tx.update(editorProjects).set({ themeConfig: { ...current, ...theme }, updatedAt: new Date() })
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId)));
  });
}

// ─── Global Header / Footer ─────────────────────────────

export async function saveHeaderFooter(projectId: string, which: 'header' | 'footer', data: string) {
  await authorizedAction(async (tx, tenantId) => {
    const field = which === 'header' ? { headerData: safeJsonParse(data) } : { footerData: safeJsonParse(data) };
    await tx.update(editorProjects).set({ ...field, updatedAt: new Date() })
      .where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId)));
  });
}

export async function getHeaderFooter(projectId: string): Promise<{ header: unknown[] | null; footer: unknown[] | null }> {
  return authorizedAction(async (tx, tenantId) => {
    const [project] = await tx.select({ headerData: editorProjects.headerData, footerData: editorProjects.footerData })
      .from(editorProjects).where(and(eq(editorProjects.id, projectId), eq(editorProjects.tenantId, tenantId))).limit(1);
    return { header: project?.headerData as unknown[] | null, footer: project?.footerData as unknown[] | null };
  });
}

export async function getProjectVersions(projectId: string) {
  return authorizedAction(async (tx, tenantId) => {
    const { editorProjectVersions } = await import("@/db/schema/editor-project-versions");
    const { desc } = await import("drizzle-orm");
    return tx.select({
      id: editorProjectVersions.id,
      version: editorProjectVersions.version,
      label: editorProjectVersions.label,
      createdAt: editorProjectVersions.createdAt,
    })
      .from(editorProjectVersions)
      .where(and(eq(editorProjectVersions.projectId, projectId), eq(editorProjectVersions.tenantId, tenantId)))
      .orderBy(desc(editorProjectVersions.version));
  });
}

export async function saveComponent(data: { name: string; element: string }) {
  const user = await requireTenantUser();
  return authorizedAction(async (tx, tenantId) => {
    const [created] = await tx.insert(editorReusableComponents)
      .values({ tenantId, name: data.name, data: safeJsonParse(data.element), createdBy: user.id })
      .returning();
    return created;
  });
}

export async function getSavedComponents() {
  return authorizedAction(async (tx, tenantId) => {
    const all = await tx.select().from(editorReusableComponents)
      .where(eq(editorReusableComponents.tenantId, tenantId)).orderBy(desc(editorReusableComponents.updatedAt));
    return all.map(t => ({ id: t.id, name: t.name, element: JSON.stringify(t.data) }));
  });
}

export async function deleteSavedComponent(id: string) {
  await authorizedAction(async (tx, tenantId) => {
    await tx.delete(editorReusableComponents).where(and(eq(editorReusableComponents.id, id), eq(editorReusableComponents.tenantId, tenantId)));
  });
}

// ─── Product Data for Editor Binding ─────────────────────

export async function getEditorProducts(opts?: { collectionId?: string; limit?: number; search?: string }) {
  return authorizedAction(async (tx, tenantId) => {
    const conditions = [eq(products.tenantId, tenantId)];
    if (opts?.search) conditions.push(sql`${products.name} ILIKE ${'%' + opts.search + '%'}`);
    const selection = {
      id: products.id, name: products.name, slug: products.slug,
      price: products.price, compareAtPrice: products.compareAtPrice,
      description: products.description, images: products.images,
    };
    if (opts?.collectionId) {
      return tx.select(selection).from(products)
        .innerJoin(collectionProducts, and(eq(collectionProducts.productId, products.id), eq(collectionProducts.tenantId, tenantId)))
        .where(and(...conditions, eq(collectionProducts.collectionId, opts.collectionId))).limit(opts.limit ?? 50);
    }
    return tx.select(selection).from(products).where(and(...conditions)).limit(opts?.limit ?? 50);
  });
}

export async function getEditorCollections() {
  return authorizedAction(async (tx, tenantId) => tx.select({ id: collections.id, name: collections.name, slug: collections.slug })
    .from(collections).where(eq(collections.tenantId, tenantId)).limit(50));
}

export async function getEditorCollectionProducts() {
  return authorizedAction(async (tx, tenantId) => tx.select({
    collectionId: collectionProducts.collectionId,
    productId: collectionProducts.productId,
  }).from(collectionProducts).where(eq(collectionProducts.tenantId, tenantId)));
}

"use client"

import { useCallback, useEffect, useState } from "react"
import { Input } from "@/components/ui/input"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/shared/utils"
import { useEditor } from "../../core/provider"
import { useEditorStore } from "../../core/editor-store"
import {
  getProjectPages,
  reorderProjectPages,
  setHomepage,
  setPageVisibility,
  updatePage,
} from "../../lib/queries"
import { createPage, deletePage } from "@/app/dashboard/pages/actions"
import { MIcon } from "../../ui/m-icon"

type PageItem = Awaited<ReturnType<typeof getProjectPages>>[number]

type LeftPanelProps = {
  onPageChange?: (page: { id: string; name: string; slug?: string; data: string | null; serverRevision?: number }) => void
  onAddSection?: () => void
}

function IconButton({ label, icon, onClick, disabled }: { label: string; icon: string; onClick: () => void; disabled?: boolean }) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button type="button" aria-label={label} disabled={disabled} onClick={onClick} className="flex size-8 shrink-0 items-center justify-center rounded-md text-muted-foreground hover:bg-sidebar-accent hover:text-foreground disabled:opacity-30">
          <MIcon name={icon} size={14} />
        </button>
      </TooltipTrigger>
      <TooltipContent side="right">{label}</TooltipContent>
    </Tooltip>
  )
}

export default function LeftPanel({ onPageChange, onAddSection }: LeftPanelProps) {
  const { pageId, state, dispatch } = useEditor()
  const activePageId = useEditorStore((store) => store.currentPageId)
  const [pages, setPages] = useState<PageItem[]>([])
  const [creating, setCreating] = useState(false)
  const [newPageName, setNewPageName] = useState("")
  const [settingsId, setSettingsId] = useState<string | null>(null)
  const body = state.editor.elements[0]
  const sections = body && Array.isArray(body.content) ? body.content : []

  const handleGlobalSection = (type: "header" | "footer") => {
    // Placeholder for global section selection
  };

  const loadPages = useCallback(async () => {
    setPages(await getProjectPages(pageId))
  }, [pageId])

  useEffect(() => {
    let cancelled = false
    getProjectPages(pageId).then((result) => {
      if (!cancelled) setPages(result)
    })
    return () => { cancelled = true }
  }, [pageId])

  const selectPage = (page: PageItem) => {
    onPageChange?.({
      id: page.id,
      name: page.name,
      slug: page.slug,
      data: JSON.stringify(page.data),
      serverRevision: page.serverRevision,
    })
  }

  const addPage = async () => {
    const name = newPageName.trim()
    if (!name) return
    const result = await createPage(pageId, name)
    if (!result.success || !result.page) return
    setNewPageName("")
    setCreating(false)
    await loadPages()
    selectPage(result.page)
  }

  const movePage = async (index: number, direction: -1 | 1) => {
    const nextIndex = index + direction
    if (nextIndex < 0 || nextIndex >= pages.length) return
    const next = [...pages]
    ;[next[index], next[nextIndex]] = [next[nextIndex], next[index]]
    setPages(next)
    await reorderProjectPages(pageId, next.map((page) => page.id))
  }

  const updateVisibility = async (page: PageItem) => {
    const visible = !page.visible
    setPages((current) => current.map((item) => item.id === page.id ? { ...item, visible } : item))
    await setPageVisibility(page.id, visible)
  }

  return (
    <aside className="flex h-full w-72 shrink-0 flex-col border-r border-sidebar-border bg-sidebar text-sidebar-foreground max-lg:w-64" aria-label="Site navigator">
      <div className="flex h-11 items-center justify-between border-b border-sidebar-border px-3">
        <h2 className="text-sm font-semibold">Site</h2>
        <IconButton label="Create page" icon="add" onClick={() => setCreating(true)} />
      </div>

      <div className="flex-1 overflow-y-auto p-2">
        <div className="mb-1 px-2 py-1 text-xs font-medium text-muted-foreground">Global sections</div>
        <button type="button" onClick={() => handleGlobalSection("header")} className={cn("flex h-9 w-full items-center gap-2 rounded-md px-2 text-left text-sm hover:bg-sidebar-accent", activePageId === "header" && "bg-sidebar-accent text-sidebar-accent-foreground")}>
          <MIcon name="web_asset" size={15} className="text-muted-foreground" />
          <span className="flex-1">Header</span>
          <span className="text-xs text-muted-foreground">Global</span>
        </button>

        <div className="mt-4 flex items-center justify-between px-2 py-1">
          <span className="text-xs font-medium text-muted-foreground">Pages</span>
          <span className="text-xs tabular-nums text-muted-foreground">{pages.length}</span>
        </div>
        {creating && (
          <form className="mb-2 flex gap-1 px-1" onSubmit={(event) => { event.preventDefault(); void addPage() }}>
            <Input autoFocus value={newPageName} onChange={(event) => setNewPageName(event.target.value)} placeholder="Page name" className="h-8 text-xs" />
            <IconButton label="Add page" icon="check" onClick={() => void addPage()} disabled={!newPageName.trim()} />
          </form>
        )}
        <div className="space-y-0.5">
          {pages.map((page, index) => (
            <div key={page.id}>
              <div className={cn("group flex min-h-9 items-center rounded-md", activePageId === page.id && "bg-sidebar-accent text-sidebar-accent-foreground")}>
                <button type="button" onClick={() => selectPage(page)} className="flex min-w-0 flex-1 items-center gap-2 px-2 py-2 text-left text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
                  <MIcon name={page.isHomepage ? "home" : "description"} size={14} className="shrink-0 text-muted-foreground" />
                  <span className="truncate">{page.name}</span>
                </button>
                <button type="button" aria-label={page.visible ? `Hide ${page.name}` : `Show ${page.name}`} onClick={() => void updateVisibility(page)} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted">
                  <MIcon name={page.visible ? "visibility" : "visibility_off"} size={13} />
                </button>
                <button type="button" aria-label={`Settings for ${page.name}`} onClick={() => setSettingsId(settingsId === page.id ? null : page.id)} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted">
                  <MIcon name="more_horiz" size={14} />
                </button>
              </div>
              {settingsId === page.id && (
                <div className="mb-2 ml-6 space-y-2 border-l pl-3 pr-1 py-2">
                  <label className="block text-xs text-muted-foreground">
                    Page name
                    <Input defaultValue={page.name} onBlur={(event) => {
                      const name = event.target.value.trim()
                      if (name && name !== page.name) void updatePage(page.id, { name }).then(loadPages)
                    }} className="mt-1 h-8 text-xs" />
                  </label>
                  <div className="flex items-center gap-1">
                    <IconButton label="Move page up" icon="arrow_upward" onClick={() => void movePage(index, -1)} disabled={index === 0} />
                    <IconButton label="Move page down" icon="arrow_downward" onClick={() => void movePage(index, 1)} disabled={index === pages.length - 1} />
                    {!page.isHomepage && <button type="button" onClick={() => void setHomepage(pageId, page.id).then(loadPages)} className="h-8 rounded-md px-2 text-xs hover:bg-sidebar-accent">Set home</button>}
                    {pages.length > 1 && <IconButton label={`Delete ${page.name}`} icon="delete" onClick={() => void deletePage(page.id).then(loadPages)} />}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="mt-4 flex items-center justify-between px-2 py-1">
          <span className="text-xs font-medium text-muted-foreground">Sections on this page</span>
          <span className="text-xs tabular-nums text-muted-foreground">{sections.length}</span>
        </div>
        <div className="space-y-0.5">
          {sections.map((section, index) => (
            <div key={section.id} className={cn("group flex min-h-9 items-center rounded-md", state.editor.selected?.id === section.id && "bg-sidebar-accent text-sidebar-accent-foreground")}>
              <button type="button" onClick={() => dispatch({ type: "CHANGE_CLICKED_ELEMENT", payload: { element: section } })} className="flex min-w-0 flex-1 items-center gap-2 px-2 py-2 text-left text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
                <MIcon name="drag_indicator" size={14} className="text-muted-foreground" />
                <span className="truncate">{section.name}</span>
              </button>
              <button type="button" aria-label={section.hidden ? `Show ${section.name}` : `Hide ${section.name}`} onClick={() => dispatch({ type: "UPDATE_ELEMENT", payload: { element: { ...section, hidden: !section.hidden } } })} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted">
                <MIcon name={section.hidden ? "visibility_off" : "visibility"} size={13} />
              </button>
              <button type="button" aria-label={`Move ${section.name} up`} disabled={index === 0} onClick={() => dispatch({ type: "REORDER_ELEMENT", payload: { elId: section.id, direction: "up" } })} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted disabled:opacity-20">
                <MIcon name="arrow_upward" size={13} />
              </button>
              <button type="button" aria-label={`Move ${section.name} down`} disabled={index === sections.length - 1} onClick={() => dispatch({ type: "REORDER_ELEMENT", payload: { elId: section.id, direction: "down" } })} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:bg-muted disabled:opacity-20">
                <MIcon name="arrow_downward" size={13} />
              </button>
            </div>
          ))}
          {sections.length === 0 && <p className="px-2 py-3 text-xs text-muted-foreground">This page has no sections yet.</p>}
        </div>
        <button type="button" onClick={onAddSection} className="mt-2 flex h-9 w-full items-center justify-center gap-2 rounded-md border border-dashed text-sm font-medium hover:border-primary/50 hover:bg-sidebar-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
          <MIcon name="add" size={15} /> Add section
        </button>

        <button type="button" onClick={() => handleGlobalSection("footer")} className={cn("mt-4 flex h-9 w-full items-center gap-2 rounded-md px-2 text-left text-sm hover:bg-sidebar-accent", activePageId === "footer" && "bg-sidebar-accent text-sidebar-accent-foreground")}>
          <MIcon name="call_to_action" size={15} className="text-muted-foreground" />
          <span className="flex-1">Footer</span>
          <span className="text-xs text-muted-foreground">Global</span>
        </button>
      </div>
    </aside>
  )
}

