"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { MIcon } from "../../ui/m-icon";
import { cn } from "@/shared/utils";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { useEditor } from "../../core/provider";
import { useEditorStore } from "../../core/editor-store";
import {
  getProjectPages,
  updatePage, updatePageSeo, setHomepage,
} from "../../lib/queries";
import { createPage, deletePage } from "@/app/dashboard/pages/actions";
import { pageTemplates } from "../../lib/page-templates";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Label } from "@/components/ui/label";

const templateIconMap: Record<string, string> = {
  File: "file", Users: "people", Mail: "contact_mail", Briefcase: "work", HelpCircle: "help",
  MessageSquare: "chat", CreditCard: "credit_card", Image: "image", Rocket: "rocket_launch", ShoppingBag: "shopping_bag",
};

interface PageItem {
  id: string;
  name: string;
  slug: string;
  isHomepage: boolean;
  published: boolean;
  seoTitle: string;
  seoDescription: string;
  ogImage: string;
}

type View = "list" | "templates" | "settings";

export default function PagesTab({ onPageChange }: { onPageChange: (page: { id: string; name: string; slug?: string; data: string | null; serverRevision?: number }) => void }) {
  const { pageId, activePageId: _initialPageId } = useEditor();
  const activePageId = useEditorStore(s => s.currentPageId) ?? _initialPageId;
  const [pages, setPages] = useState<PageItem[]>([]);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [creating, setCreating] = useState(false);
  const [view, setView] = useState<View>("list");
  const [settingsPage, setSettingsPage] = useState<PageItem | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined);

  const load = useCallback(async () => {
    const result = await getProjectPages(pageId);
    setPages(result.map(p => ({
      id: p.id, name: p.name, slug: p.slug,
      isHomepage: p.isHomepage ?? false, published: p.published ?? false,
      seoTitle: p.seoTitle ?? "", seoDescription: p.seoDescription ?? "", ogImage: p.ogImage ?? "",
    })));
  }, [pageId]);

  useEffect(() => { load(); }, [load]);

  const handleSelect = async (page: PageItem) => {
    const all = await getProjectPages(pageId);
    const found = all.find(p => p.id === page.id);
    onPageChange({ id: page.id, name: page.name, slug: page.slug, data: found ? JSON.stringify(found.data) : null, serverRevision: found?.serverRevision ?? 0 });
  };

  const handleCreateFromTemplate = async (templateId: string) => {
    setCreating(true);
    const template = pageTemplates.find(t => t.id === templateId);
    if (!template) { setCreating(false); return; }

    const name = template.id === "blank" ? `Page ${pages.length + 1}` : template.name;
    const result = await createPage(pageId, name);
    if (result.success && result.page) {
      const page = result.page;
      const elements = template.factory();
      if (elements.length > 0) {
        await updatePage(page.id, { data: JSON.stringify(elements) });
      }
      await load();
      onPageChange({ id: page.id, name: page.name, slug: page.slug, data: elements.length > 0 ? JSON.stringify(elements) : null, serverRevision: page.serverRevision });
    }
    setCreating(false);
    setView("list");
  };

  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);

  const handleDelete = async (id: string) => {
    if (pages.length <= 1) return;
    setDeleteTarget(id);
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    await deletePage(deleteTarget);
    await load();
    if (deleteTarget === activePageId) {
      const remaining = pages.filter(p => p.id !== deleteTarget);
      if (remaining[0]) handleSelect(remaining[0]);
    }
    setDeleteTarget(null);
  };

  const commitRename = async () => {
    if (!editingId || !editName.trim()) { setEditingId(null); return; }
    await updatePage(editingId, { name: editName.trim() });
    const slug = editName.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    setPages(prev => prev.map(p => p.id === editingId ? { ...p, name: editName.trim(), slug } : p));
    // Don't call onPageChange — rename should NOT reload canvas
    setEditingId(null);
  };

  const debouncedSave = (fn: () => Promise<void>) => {
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(fn, 500);
  };

  const updateSettingsField = (field: keyof PageItem, value: string | boolean) => {
    if (!settingsPage) return;
    const updated = { ...settingsPage, [field]: value };
    if (field === "name" && !settingsPage.isHomepage) {
      updated.slug = (value as string).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    }
    setSettingsPage(updated);
    setPages(prev => prev.map(p => p.id === updated.id ? updated : p));

    debouncedSave(async () => {
      if (field === "name") {
        await updatePage(updated.id, { name: value as string });
      } else if (field === "seoTitle" || field === "seoDescription" || field === "ogImage") {
        await updatePageSeo(updated.id, { [field]: value as string });
      }
    });
  };

  const handleSetHomepage = async (checked: boolean) => {
    if (!settingsPage || !checked) return;
    await setHomepage(pageId, settingsPage.id);
    setSettingsPage({ ...settingsPage, isHomepage: true, slug: "" });
    await load();
  };

  // ─── Template Picker ──────────────────────────────────
  if (view === "templates") {
    return (
      <div className="flex-1 overflow-y-auto">
        <div className="flex items-center gap-2 px-2 py-2 border-b">
          <button onClick={() => setView("list")} className="p-1 rounded-md hover:bg-muted">
            <MIcon name="chevron_left" size={14} />
          </button>
          <span className="text-xs font-medium">Choose a Template</span>
        </div>
        <div className="grid grid-cols-2 gap-2 p-2">
          {pageTemplates.map(tmpl => {
            const iconName = templateIconMap[tmpl.icon] ?? "description";
            return (
              <button
                key={tmpl.id}
                disabled={creating}
                onClick={() => handleCreateFromTemplate(tmpl.id)}
                className="flex flex-col items-center gap-2 rounded-lg border border-transparent p-3 text-center hover:bg-muted hover:border-border transition-colors"
              >
                <MIcon name={iconName} size={20} className="text-muted-foreground" />
                <span className="text-xs font-medium leading-tight">{tmpl.name}</span>
                <span className="text-[10px] text-muted-foreground leading-tight">{tmpl.description}</span>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // ─── Page Settings ────────────────────────────────────
  if (view === "settings" && settingsPage) {
    return (
      <div className="flex-1 overflow-y-auto">
        <div className="flex items-center gap-2 px-2 py-2 border-b">
          <button onClick={() => { setView("list"); setSettingsPage(null); }} className="p-1 rounded-md hover:bg-muted">
            <MIcon name="chevron_left" size={14} />
          </button>
          <span className="text-xs font-medium truncate">{settingsPage.name}</span>
        </div>
        <Tabs defaultValue="info" className="px-2 pt-2">
          <TabsList className="w-full h-7 p-0.5">
            <TabsTrigger value="info" className="text-[10px] h-7 flex-1">Info</TabsTrigger>
            <TabsTrigger value="seo" className="text-[10px] h-7 flex-1">SEO</TabsTrigger>
            <TabsTrigger value="social" className="text-[10px] h-7 flex-1">Social</TabsTrigger>
          </TabsList>

          <TabsContent value="info" className="space-y-3 mt-3">
            <div className="space-y-1">
              <Label className="text-[10px] text-muted-foreground">Page Name</Label>
              <Input
                value={settingsPage.name}
                onChange={e => updateSettingsField("name", e.target.value)}
                className="h-7 text-xs"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-[10px] text-muted-foreground">Slug</Label>
              <div className="flex items-center h-7 rounded-md border bg-muted/50 px-2 text-xs text-muted-foreground font-mono">
                /{settingsPage.isHomepage ? "" : settingsPage.slug}
              </div>
            </div>
            <div className="flex items-center justify-between py-1">
              <Label className="text-[10px] text-muted-foreground">Homepage</Label>
              <Switch
                checked={settingsPage.isHomepage}
                onCheckedChange={handleSetHomepage}
                className="scale-75 origin-right"
              />
            </div>
          </TabsContent>

          <TabsContent value="seo" className="space-y-3 mt-3">
            <div className="space-y-1">
              <Label className="text-[10px] text-muted-foreground">SEO Title</Label>
              <Input
                value={settingsPage.seoTitle}
                onChange={e => updateSettingsField("seoTitle", e.target.value)}
                placeholder={settingsPage.name}
                className="h-7 text-xs"
              />
              <p className="text-[10px] text-muted-foreground">{settingsPage.seoTitle.length}/60</p>
            </div>
            <div className="space-y-1">
              <Label className="text-[10px] text-muted-foreground">Meta Description</Label>
              <Textarea
                value={settingsPage.seoDescription}
                onChange={e => updateSettingsField("seoDescription", e.target.value)}
                placeholder="Describe this page for search engines..."
                className="text-xs min-h-[60px] resize-none"
              />
              <p className="text-[10px] text-muted-foreground">{settingsPage.seoDescription.length}/160</p>
            </div>
          </TabsContent>

          <TabsContent value="social" className="space-y-3 mt-3">
            <div className="space-y-1">
              <Label className="text-[10px] text-muted-foreground">OG Image URL</Label>
              <Input
                value={settingsPage.ogImage}
                onChange={e => updateSettingsField("ogImage", e.target.value)}
                placeholder="https://example.com/og.png"
                className="h-7 text-xs"
              />
              <p className="text-[10px] text-muted-foreground">Recommended: 1200×630px</p>
            </div>
            {settingsPage.ogImage && (
              <div className="rounded-md border overflow-hidden">
                <img
                  src={settingsPage.ogImage}
                  alt="OG preview"
                  className="w-full h-auto object-cover"
                  onError={e => { (e.target as HTMLImageElement).style.display = "none"; }}
                />
              </div>
            )}
          </TabsContent>
        </Tabs>
      </div>
    );
  }

  // ─── Page List ────────────────────────────────────────
  return (
    <div className="flex-1 overflow-y-auto p-2">
      {pages.map(page => (
        <button
          key={page.id}
          onClick={() => handleSelect(page)}
          className={cn(
            "flex items-center gap-2 w-full rounded-md px-2 py-2 text-xs transition-colors group mb-0.5",
            page.id === activePageId ? "bg-primary/10 text-primary" : "hover:bg-muted"
          )}
        >
          <MIcon name="drag_indicator" size={12} className="text-muted-foreground/40 shrink-0" />
          {page.isHomepage ? <MIcon name="home" size={14} className="shrink-0" /> : <MIcon name="description" size={14} className="shrink-0" />}

          {editingId === page.id ? (
            <input
              autoFocus
              value={editName}
              onChange={e => setEditName(e.target.value)}
              onBlur={commitRename}
              onKeyDown={e => { if (e.key === "Enter") commitRename(); if (e.key === "Escape") setEditingId(null); }}
              onClick={e => e.stopPropagation()}
              className="flex-1 min-w-0 h-5 bg-transparent border-b border-primary text-xs outline-none"
            />
          ) : (
            <span
              className="flex-1 truncate text-left"
              onDoubleClick={e => { e.stopPropagation(); setEditingId(page.id); setEditName(page.name); }}
            >
              {page.name}
            </span>
          )}

          <span className="text-[10px] text-muted-foreground/40 font-mono">/{page.slug}</span>

          {page.published ? (
            <MIcon name="visibility" size={12} className="text-emerald-500/50 shrink-0" />
          ) : (
            <MIcon name="visibility_off" size={12} className="text-muted-foreground/40 shrink-0" />
          )}

          <span
            className="shrink-0 opacity-0 group-hover:opacity-40 hover:!opacity-100 transition-opacity"
            onClick={e => { e.stopPropagation(); setSettingsPage(page); setView("settings"); }}
          >
            <MIcon name="settings" size={12} />
          </span>

          {!page.isHomepage && (
            <span
              className="shrink-0 opacity-0 group-hover:opacity-40 hover:!opacity-100 hover:text-destructive transition-opacity"
              onClick={e => { e.stopPropagation(); handleDelete(page.id); }}
            >
              <MIcon name="delete" size={12} />
            </span>
          )}
        </button>
      ))}

      <button
        onClick={() => setView("templates")}
        disabled={creating}
        className="flex items-center gap-2 w-full rounded-md px-2 py-2 mt-1 text-xs text-muted-foreground hover:text-foreground hover:bg-muted transition-colors border border-dashed border-transparent hover:border-border"
      >
        <MIcon name="add" size={14} />
        {creating ? "Creating..." : "Add Page"}
      </button>

      {/* Delete confirmation */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(open) => !open && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete page?</AlertDialogTitle>
            <AlertDialogDescription>This will permanently delete this page and its content. This action cannot be undone.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={confirmDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">Delete</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useEditorStore } from "../../core/editor-store";
import { useDocumentStore } from "../../core/document-store";
import { useEditor } from "../../core/provider";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import type { ElementAnimation } from "../../core/types";

export function AnimationSettings() {
  const { dispatch } = useEditor();
  const selectedId = useEditorStore(s => s.selected?.id);
  const selectedElement = useDocumentStore(s =>
    selectedId ? s.elements.find(e => e.id === selectedId) : null
  );

  if (!selectedElement) return null;

  const animations: ElementAnimation = selectedElement.animations || {
    preset: 'none',
    duration: 0.5,
    delay: 0,
    trigger: 'on-load',
  };

  const updateAnimation = (updates: Partial<ElementAnimation>) => {
    dispatch({
      type: "UPDATE_ELEMENT_LIVE",
      payload: {
        element: {
          ...selectedElement,
          animations: { ...animations, ...updates },
        },
      },
    });
    // For animations, we can immediately commit to history since they are simple dropdown/slider changes
    dispatch({ type: "COMMIT_HISTORY" });
  };

  return (
    <div className="space-y-6">
      {/* Preset */}
      <div className="space-y-2.5">
        <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Animation Preset</Label>
        <Select
          value={animations.preset || "none"}
          onValueChange={(val: any) => updateAnimation({ preset: val })}
        >
          <SelectTrigger className="w-full">
            <SelectValue placeholder="Select preset" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="none">None</SelectItem>
            <SelectItem value="fade">Fade In</SelectItem>
            <SelectItem value="slide-up">Slide Up</SelectItem>
            <SelectItem value="slide-down">Slide Down</SelectItem>
            <SelectItem value="zoom-in">Zoom In</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {animations.preset && animations.preset !== 'none' && (
        <>
          {/* Trigger */}
          <div className="space-y-2.5">
            <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Trigger</Label>
            <Select
              value={animations.trigger || "on-load"}
              onValueChange={(val: any) => updateAnimation({ trigger: val })}
            >
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Select trigger" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="on-load">On Load</SelectItem>
                <SelectItem value="on-scroll">On Scroll</SelectItem>
                <SelectItem value="hover">On Hover</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Duration */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Duration</Label>
              <span className="text-xs tabular-nums">{animations.duration}s</span>
            </div>
            <Slider
              value={[animations.duration ?? 0.5]}
              min={0.1}
              max={3}
              step={0.1}
              onValueChange={(vals) => updateAnimation({ duration: vals[0] })}
            />
          </div>

          {/* Delay */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Delay</Label>
              <span className="text-xs tabular-nums">{animations.delay}s</span>
            </div>
            <Slider
              value={[animations.delay ?? 0]}
              min={0}
              max={5}
              step={0.1}
              onValueChange={(vals) => updateAnimation({ delay: vals[0] })}
            />
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { MIcon } from "../../../ui/m-icon";
import type { El } from "../../../core/types";
import { getEditorProducts } from "../../../lib/queries";

const PRODUCT_FIELDS = [
  { value: "name", label: "Product Name" },
  { value: "price", label: "Price" },
  { value: "compareAtPrice", label: "Compare Price" },
  { value: "description", label: "Description" },
  { value: "images[0]", label: "Main Image" },
  { value: "slug", label: "Slug" },
];

const COLLECTION_FIELDS = [
  { value: "name", label: "Collection Name" },
  { value: "description", label: "Description" },
];

export function BindingSection({ selected, onUpdate }: { selected: El; onUpdate: (el: El) => void }) {
  const [products, setProducts] = useState<{ id: string; name: string; price: string }[]>([]);
  const [loading, setLoading] = useState(false);
  const binding = selected.binding;

  const loadProducts = async () => {
    if (products.length > 0) return;
    setLoading(true);
    const data = await getEditorProducts({ limit: 20 });
    setProducts(data.map(p => ({ id: p.id, name: p.name, price: p.price })));
    setLoading(false);
  };

  const setBindingSource = (source: "product" | "collection") => {
    onUpdate({ ...selected, binding: { source, field: "name", resourceId: undefined } });
  };

  const setBindingField = (field: string) => {
    if (!binding) return;
    onUpdate({ ...selected, binding: { source: binding.source, field, resourceId: (binding as any).resourceId } as any });
  };

  const setProductId = (id: string) => {
    if (binding?.source !== "product") return;
    onUpdate({ ...selected, binding: { source: 'product', field: binding.field || 'name', resourceId: id || undefined } });
  };

  const clearBinding = () => {
    const el = { ...selected };
    delete el.binding;
    onUpdate(el);
  };

  return (
    <div className="px-3 py-2 border-b border-sidebar-border">
      <div className="flex items-center justify-between mb-1">
        <span className="text-[10px] font-semibold text-muted-foreground/40 uppercase tracking-wider">Data Binding</span>
        {binding && <button onClick={clearBinding} className="text-[10px] text-destructive hover:underline">Remove</button>}
      </div>
      {binding ? (
        <div className="space-y-1">
          <div className="flex items-center gap-1 h-6 px-2 rounded-md bg-primary/10 text-primary text-[10px] font-medium">
            <MIcon name="link" size={11} />
            <span>{binding.source}.{binding.field}</span>
          </div>

          <select value={binding.source} onChange={(e) => setBindingSource(e.target.value as "product" | "collection")} className="w-full h-6 rounded-md border border-sidebar-border bg-sidebar text-[10px] px-1">
            <option value="product">Product Data</option>
            <option value="collection">Collection Data</option>
          </select>

          <select value={binding.field} onChange={(e) => setBindingField(e.target.value)} className="w-full h-6 rounded-md border border-sidebar-border bg-sidebar text-[10px] px-1">
            {(binding.source === "collection" ? COLLECTION_FIELDS : PRODUCT_FIELDS).map(f => (
              <option key={f.value} value={f.value}>{f.label}</option>
            ))}
          </select>

          {binding.source === "product" && (
            <select value={binding.resourceId || ''} onChange={(e) => setProductId(e.target.value)} onFocus={loadProducts} className="w-full h-8 rounded-md border border-sidebar-border bg-sidebar text-xs px-2">
              <option value="">All products (dynamic)</option>
              {loading && <option disabled>Loading...</option>}
              {products.map(p => <option key={p.id} value={p.id}>{p.name} — ${p.price}</option>)}
            </select>
          )}
        </div>
      ) : (
        <div className="flex gap-1">
          <button onClick={() => setBindingSource('product')} className="flex-1 flex items-center justify-center gap-1 h-6 rounded-md border border-dashed border-sidebar-border text-[10px] text-muted-foreground/40 hover:text-foreground hover:border-primary/40 transition-colors">
            <MIcon name="link" size={11} /> Product
          </button>
          <button onClick={() => setBindingSource('collection')} className="flex-1 flex items-center justify-center gap-1 h-6 rounded-md border border-dashed border-sidebar-border text-[10px] text-muted-foreground/40 hover:text-foreground hover:border-primary/40 transition-colors">
            <MIcon name="link" size={11} /> Collection
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useRef } from "react";
import { MIcon } from "../../../ui/m-icon";
import { Input } from "@/components/ui/input";
import { cn } from "@/shared/utils";
import { uploadEditorAsset } from "../../../lib/upload";
import { MediaPicker } from "@/features/media/components/media-picker";
import { toast } from "sonner";

export function ImageField({ value, onChange }: { value: string; onChange: (v: string) => void }) {
  const ref = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [pickerOpen, setPickerOpen] = useState(false);

  const handleUpload = async (file: File) => {
    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    const res = await uploadEditorAsset(fd);
    setUploading(false);
    if ('url' in res) onChange(res.url);
    else toast.error('error' in res ? res.error : 'Upload failed');
  };

  return (
    <div className="space-y-2">
      {value ? (
        <div className="relative group rounded-lg border border-sidebar-border overflow-hidden">
          <img src={value} alt="" className="w-full h-28 object-cover" onError={(e) => { (e.target as HTMLImageElement).src = ''; }} />
          <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
            <button onClick={() => ref.current?.click()} className="size-8 rounded-full bg-white/20 backdrop-blur flex items-center justify-center text-white hover:bg-white/30 transition-colors">
              <MIcon name="cloud_upload" size={14} />
            </button>
            <button onClick={() => setPickerOpen(true)} className="size-8 rounded-full bg-white/20 backdrop-blur flex items-center justify-center text-white hover:bg-white/30 transition-colors">
              <MIcon name="image" size={14} />
            </button>
            <button onClick={() => onChange('')} className="size-8 rounded-full bg-white/20 backdrop-blur flex items-center justify-center text-white hover:bg-red-500/50 transition-colors">
              <MIcon name="delete" size={14} />
            </button>
          </div>
        </div>
      ) : (
        <div className="space-y-1">
          <div
            onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={(e) => { e.preventDefault(); setDragOver(false); const f = e.dataTransfer.files[0]; if (f) handleUpload(f); }}
            onClick={() => ref.current?.click()}
            className={cn("flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed py-6 cursor-pointer transition-colors",
              dragOver ? "border-primary bg-primary/5" : "border-sidebar-border/50 hover:border-primary/30 hover:bg-muted/30",
              uploading && "opacity-50 pointer-events-none"
            )}>
            <MIcon name={uploading ? "hourglass_empty" : "cloud_upload"} size={20} className={cn("text-muted-foreground/40", uploading && "animate-spin")} />
            <p className="text-[10px] text-muted-foreground/40">{uploading ? "Uploading..." : "Drop image or click to upload"}</p>
          </div>
          <button onClick={() => setPickerOpen(true)} className="flex w-full items-center justify-center gap-1 h-7 rounded-md border border-sidebar-border text-[10px] text-muted-foreground/70 hover:text-foreground hover:bg-sidebar-accent transition-colors">
            <MIcon name="image" size={12} /> Browse Media Library
          </button>
        </div>
      )}
      <Input ref={ref as unknown as React.Ref<HTMLInputElement>} type="file" accept="image/*,video/mp4" className="hidden"
        onChange={(e) => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) handleUpload(f); }} />
      <Input value={value} onChange={(e) => onChange(e.target.value)} className="h-7 text-[10px] font-mono text-muted-foreground" placeholder="or paste URL..." />
      <MediaPicker open={pickerOpen} onOpenChange={setPickerOpen} onSelect={(assets) => { if (assets[0]?.cdnUrl) onChange(assets[0].cdnUrl); setPickerOpen(false); }} />
    </div>
  );
}

"use client";

import { useState, useRef, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Section, ColorField, SelectField, selectOptions, Tip, type StyleProps } from "../shared";
import { MIcon } from "../../../ui/m-icon";
import { cn } from "@/shared/utils";

type Stop = { color: string; pos: number };

// ─── Gradient parsing ───────────────────────────────────────

function parseGradient(val: string): { type: 'linear' | 'radial'; angle: number; stops: Stop[] } | null {
  const linear = val.match(/^linear-gradient\((\d+)deg,\s*(.+)\)$/);
  if (linear) return { type: 'linear', angle: +linear[1], stops: parseStops(linear[2]) };
  const radial = val.match(/^radial-gradient\(circle,\s*(.+)\)$/);
  if (radial) return { type: 'radial', angle: 0, stops: parseStops(radial[1]) };
  return null;
}

function parseStops(raw: string): Stop[] {
  const parts: string[] = [];
  let depth = 0, cur = '';
  for (const ch of raw) {
    if (ch === '(') depth++;
    else if (ch === ')') depth--;
    else if (ch === ',' && depth === 0) { parts.push(cur.trim()); cur = ''; continue; }
    cur += ch;
  }
  if (cur.trim()) parts.push(cur.trim());
  return parts.map((p, i, arr) => {
    const m = p.match(/^(.+?)\s+(\d+)%$/);
    return m ? { color: m[1], pos: +m[2] } : { color: p, pos: Math.round((i / Math.max(1, arr.length - 1)) * 100) };
  });
}

function build(type: 'linear' | 'radial', angle: number, stops: Stop[]): string {
  const s = stops.map(st => `${st.color} ${st.pos}%`).join(', ');
  return type === 'linear' ? `linear-gradient(${angle}deg, ${s})` : `radial-gradient(circle, ${s})`;
}

// ─── Draggable stop bar ─────────────────────────────────────

function StopBar({ stops, gradient, activeStop, onSelect, onMove, onAdd }: {
  stops: Stop[]; gradient: string; activeStop: number;
  onSelect: (i: number) => void; onMove: (i: number, pos: number) => void; onAdd: (pos: number) => void;
}) {
  const barRef = useRef<HTMLDivElement>(null);

  const getPos = useCallback((e: React.PointerEvent | PointerEvent) => {
    const r = barRef.current?.getBoundingClientRect();
    return r ? Math.round(Math.max(0, Math.min(100, ((e.clientX - r.left) / r.width) * 100))) : 0;
  }, []);

  const onStopDown = (i: number, e: React.PointerEvent) => {
    e.stopPropagation();
    onSelect(i);
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);
    const move = (ev: PointerEvent) => onMove(i, getPos(ev));
    const up = () => { el.removeEventListener('pointermove', move); el.removeEventListener('pointerup', up); };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
  };

  return (
    <div ref={barRef} className="relative h-5 rounded-md border border-sidebar-border cursor-crosshair" style={{ background: gradient }}
      onClick={(e) => { if ((e.target as HTMLElement) === barRef.current) onAdd(getPos(e as unknown as React.PointerEvent)); }}>
      {/* Checkerboard for transparency */}
      <div className="absolute inset-0 rounded-md -z-10" style={{ background: 'repeating-conic-gradient(#d4d4d4 0% 25%, transparent 0% 50%) 0 0 / 8px 8px' }} />
      {stops.map((s, i) => (
        <div key={i} onPointerDown={(e) => onStopDown(i, e)}
          className={cn("absolute top-1/2 -translate-x-1/2 -translate-y-1/2 size-3.5 rounded-full border-2 cursor-grab active:cursor-grabbing transition-shadow",
            i === activeStop ? "border-white shadow-[0_0_0_1px_rgba(0,0,0,0.3),0_2px_4px_rgba(0,0,0,0.3)] z-10" : "border-white/70 shadow-sm"
          )}
          style={{ left: `${s.pos}%`, background: s.color }}
        />
      ))}
    </div>
  );
}

// ─── Angle dial ─────────────────────────────────────────────

function AngleDial({ angle, onChange }: { angle: number; onChange: (a: number) => void }) {
  const ref = useRef<HTMLDivElement>(null);
  const calcAngle = (e: PointerEvent | React.PointerEvent) => {
    const r = ref.current?.getBoundingClientRect();
    if (!r) return angle;
    const x = e.clientX - r.left - r.width / 2;
    const y = e.clientY - r.top - r.height / 2;
    return Math.round(((Math.atan2(y, x) * 180) / Math.PI + 90 + 360) % 360);
  };

  const onDown = (e: React.PointerEvent) => {
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);
    onChange(calcAngle(e));
    const move = (ev: PointerEvent) => onChange(calcAngle(ev));
    const up = () => { el.removeEventListener('pointermove', move); el.removeEventListener('pointerup', up); };
    el.addEventListener('pointermove', move);
    el.addEventListener('pointerup', up);
  };

  return (
    <div ref={ref} onPointerDown={onDown}
      className="size-6 rounded-full border border-sidebar-border bg-sidebar cursor-pointer shrink-0 relative"
      title={`${angle}°`}>
      <div className="absolute top-1/2 left-1/2 w-px h-2.5 bg-primary origin-bottom" style={{ transform: `translate(-50%, -100%) rotate(${angle}deg)` }} />
      <div className="absolute top-1/2 left-1/2 size-1 rounded-full bg-muted-foreground/30 -translate-x-1/2 -translate-y-1/2" />
    </div>
  );
}

// ─── Fill Menu ──────────────────────────────────────────────

export function FillMenu({ get, set }: StyleProps) {
  const bgColor = get("backgroundColor");
  const bgImage = get("backgroundImage");
  const gradient = parseGradient(bgImage);
  const detectedMode = gradient ? gradient.type : bgImage && !bgImage.includes("gradient") && bgImage ? "image" : "solid";
  const [modeOverride, setModeOverride] = useState<string | null>(null);
  const mode = modeOverride ?? detectedMode;
  const [enabled, setEnabled] = useState(!!bgColor || !!bgImage);
  const [activeStop, setActiveStop] = useState(0);

  const setMode = (m: 'solid' | 'linear' | 'radial' | 'image') => {
    setEnabled(true);
    setModeOverride(m);
    if (m === 'solid') set("backgroundImage", "");
    else if (m === 'linear') set("backgroundImage", build('linear', 180, [{ color: bgColor || "#6366f1", pos: 0 }, { color: "#000000", pos: 100 }]));
    else if (m === 'radial') set("backgroundImage", build('radial', 0, [{ color: bgColor || "#6366f1", pos: 0 }, { color: "#000000", pos: 100 }]));
    else if (m === 'image') set("backgroundImage", "");
  };

  const toggleFill = () => {
    if (enabled) { set("backgroundColor", "transparent"); set("backgroundImage", ""); setEnabled(false); }
    else { set("backgroundColor", bgColor || "#ffffff"); setEnabled(true); }
  };

  const updateStop = (i: number, patch: Partial<Stop>) => {
    if (!gradient) return;
    const stops = gradient.stops.map((s, j) => j === i ? { ...s, ...patch } : s);
    set("backgroundImage", build(gradient.type, gradient.angle, stops));
  };
  const addStopAt = (pos: number) => {
    if (!gradient) return;
    const stops = [...gradient.stops, { color: "#888888", pos }].sort((a, b) => a.pos - b.pos);
    const newIdx = stops.findIndex(s => s.pos === pos && s.color === "#888888");
    setActiveStop(newIdx >= 0 ? newIdx : stops.length - 1);
    set("backgroundImage", build(gradient.type, gradient.angle, stops));
  };
  const removeStop = (i: number) => {
    if (!gradient || gradient.stops.length <= 2) return;
    const stops = gradient.stops.filter((_, j) => j !== i);
    setActiveStop(Math.min(activeStop, stops.length - 1));
    set("backgroundImage", build(gradient.type, gradient.angle, stops));
  };
  const swapStops = () => {
    if (!gradient) return;
    const stops = gradient.stops.map(s => ({ ...s, pos: 100 - s.pos })).reverse();
    set("backgroundImage", build(gradient.type, gradient.angle, stops));
  };

  const active = gradient?.stops[activeStop];

  return (
    <Section title="Fill" icon="format_color_fill" action={
      <button onClick={toggleFill} className={cn("size-4 flex items-center justify-center rounded-md transition-colors", enabled ? "text-primary" : "text-muted-foreground/40")}>
        <MIcon name={enabled ? "visibility" : "visibility_off"} size={11} />
      </button>
    }>
      <div className="space-y-2">
        {/* Mode tabs */}
        <div className="flex gap-1 rounded-md border border-sidebar-border p-0.5">
          {(["solid", "linear", "radial", "image"] as const).map((t) => (
            <button key={t} onClick={() => setMode(t)} className={cn("flex-1 h-5 rounded-md text-[10px] font-medium capitalize transition-colors", mode === t ? "bg-primary text-primary-foreground" : "text-muted-foreground/70 hover:text-foreground")}>{t}</button>
          ))}
        </div>

        {/* Solid */}
        {mode === "solid" && (
          <ColorField label="" value={bgColor} onChange={(v) => set("backgroundColor", v)} />
        )}

        {/* Gradient */}
        {gradient && (
          <div className="space-y-2">
            {/* Draggable stop bar */}
            <StopBar stops={gradient.stops} gradient={bgImage} activeStop={activeStop}
              onSelect={setActiveStop}
              onMove={(i, pos) => updateStop(i, { pos })}
              onAdd={addStopAt}
            />

            {/* Active stop controls */}
            {active && (
              <div className="flex items-center gap-1">
                <ColorField label="" value={active.color} onChange={(v) => updateStop(activeStop, { color: v })} />
                <Input className="h-5 text-[10px] w-12 shrink-0" type="number" min={0} max={100} value={active.pos} onChange={(e) => updateStop(activeStop, { pos: +e.target.value })} />
                <span className="text-[10px] text-muted-foreground/40 shrink-0">%</span>
                {gradient.stops.length > 2 && (
                  <button onClick={() => removeStop(activeStop)} className="size-4 flex items-center justify-center text-muted-foreground/40 hover:text-destructive shrink-0">
                    <MIcon name="close" size={10} />
                  </button>
                )}
              </div>
            )}

            {/* Angle + swap */}
            <div className="flex items-center gap-1">
              {gradient.type === 'linear' && (
                <>
                  <AngleDial angle={gradient.angle} onChange={(a) => set("backgroundImage", build('linear', a, gradient.stops))} />
                  <Input className="h-5 text-[10px] w-12" type="number" value={gradient.angle} onChange={(e) => set("backgroundImage", build('linear', +e.target.value, gradient.stops))} />
                  <span className="text-[10px] text-muted-foreground/40">°</span>
                </>
              )}
              <div className="flex-1" />
              <Tip label="Reverse gradient"><button onClick={swapStops} className="flex items-center gap-1 text-[10px] text-muted-foreground/40 hover:text-foreground transition-colors">
                <MIcon name="swap_horiz" size={12} />
              </button></Tip>
            </div>
          </div>
        )}

        {/* Image */}
        {mode === "image" && (
          <div className="space-y-2">
            {/* Preview / Drop zone */}
            {bgImage && bgImage.startsWith("url(") ? (
              <div className="relative group/img rounded-md border border-sidebar-border overflow-hidden">
                <img src={bgImage.replace(/^url\(["']?|["']?\)$/g, '')} alt="" className="w-full h-20 object-cover" />
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover/img:opacity-100 transition-opacity flex items-center justify-center gap-2">
                  <button onClick={() => set("backgroundImage", "")} className="size-6 rounded-full bg-white/20 flex items-center justify-center text-white hover:bg-white/30">
                    <MIcon name="delete" size={12} />
                  </button>
                </div>
              </div>
            ) : (
              <label className="flex flex-col items-center justify-center h-20 rounded-md border border-dashed border-sidebar-border/60 bg-sidebar hover:border-primary/40 hover:bg-primary/5 transition-colors cursor-pointer">
                <MIcon name="add_photo_alternate" size={20} className="text-muted-foreground/40" />
                <span className="text-[10px] text-muted-foreground/40 mt-1">Paste image URL below</span>
              </label>
            )}

            {/* URL input */}
            <div className="relative">
              <MIcon name="link" size={10} className="absolute left-2 top-1/2 -translate-y-1/2 text-muted-foreground/40" />
              <Input value={bgImage?.startsWith("url(") ? bgImage.replace(/^url\(["']?|["']?\)$/g, '') : bgImage} onChange={(e) => { const v = e.target.value; set("backgroundImage", v && !v.startsWith("url(") ? `url(${v})` : v); }} className="h-7 text-[10px] pl-6" placeholder="https://..." />
            </div>

            {/* Size + Position row */}
            <div className="grid grid-cols-2 gap-1">
              <div>
                <span className="text-[10px] text-muted-foreground/40 mb-0.5 block">Size</span>
                <SelectField label="" value={get("backgroundSize") || "cover"} options={selectOptions.backgroundSize} onChange={(v) => set("backgroundSize", v)} />
              </div>
              <div>
                <span className="text-[10px] text-muted-foreground/40 mb-0.5 block">Position</span>
                <SelectField label="" value={get("backgroundPosition") || "center"} options={["center","top","bottom","left","right"]} onChange={(v) => set("backgroundPosition", v)} />
              </div>
            </div>

            {/* Repeat */}
            <div>
              <span className="text-[10px] text-muted-foreground/40 mb-0.5 block">Repeat</span>
              <div className="flex gap-1 rounded-md border border-sidebar-border p-0.5">
                {(["no-repeat","repeat","repeat-x","repeat-y"] as const).map((r) => (
                  <button key={r} onClick={() => set("backgroundRepeat", r)} className={cn("flex-1 h-5 rounded-md text-[10px] font-medium transition-colors", (get("backgroundRepeat") || "no-repeat") === r ? "bg-primary text-primary-foreground" : "text-muted-foreground/40 hover:text-foreground")}>
                    {r === "no-repeat" ? "None" : r === "repeat" ? "Both" : r === "repeat-x" ? "X" : "Y"}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </Section>
  );
}

"use client";

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Section, ColorField, IconToggle, textAlignOpts, fontStyleOpts, textDecoOpts, type StyleProps } from "../shared";
import { MIcon } from "../../../ui/m-icon";
import { N } from "./measures-menu";
import { cn } from "@/shared/utils";

const fonts = ["Inter", "Roboto", "Open Sans", "Lato", "Montserrat", "Poppins", "Raleway", "Nunito", "Playfair Display", "Merriweather", "Source Code Pro", "Fira Code", "DM Sans", "Space Grotesk", "Outfit", "Geist"];

const weights = [
  { value: "100", label: "Thin" }, { value: "200", label: "Extra Light" },
  { value: "300", label: "Light" }, { value: "400", label: "Regular" },
  { value: "500", label: "Medium" }, { value: "600", label: "Semi Bold" },
  { value: "700", label: "Bold" }, { value: "800", label: "Extra Bold" },
  { value: "900", label: "Black" },
];

const loadedFonts = new Set<string>();
function loadFont(family: string) {
  if (loadedFonts.has(family)) return;
  loadedFonts.add(family);
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = `https://fonts.googleapis.com/css2?family=${family.replace(/ /g, "+")}&display=swap`;
  document.head.appendChild(link);
}

export function TypographyMenu({ get, set }: StyleProps) {
  return (
    <Section title="Typography" icon="text_fields">
      <div className="space-y-2">
        {/* Font family */}
        <Select value={get("fontFamily") || "Inter"} onValueChange={(v) => { set("fontFamily", v); loadFont(v); }}>
          <SelectTrigger className="h-5 text-[10px]"><SelectValue /></SelectTrigger>
          <SelectContent>{fonts.map((f) => <SelectItem key={f} value={f} className="text-xs" style={{ fontFamily: f }}>{f}</SelectItem>)}</SelectContent>
        </Select>

        {/* Size + Weight */}
        <div className="grid grid-cols-2 gap-1">
          <N icon="Sz" value={get("fontSize")?.replace("px", "")} onChange={(v) => set("fontSize", /^\d+$/.test(v) ? `${v}px` : v)} placeholder="16" tip="Font size" />
          <Select value={get("fontWeight") || "400"} onValueChange={(v) => set("fontWeight", v)}>
            <SelectTrigger className="h-5 text-[10px]"><SelectValue /></SelectTrigger>
            <SelectContent>{weights.map((w) => <SelectItem key={w.value} value={w.value} className="text-xs"><span className="font-mono text-[10px] text-muted-foreground/40 mr-1">{w.value}</span>{w.label}</SelectItem>)}</SelectContent>
          </Select>
        </div>

        {/* Line height + Letter spacing */}
        <div className="grid grid-cols-2 gap-1">
          <N icon="Lh" value={get("lineHeight")} onChange={(v) => set("lineHeight", v)} placeholder="1.5" tip="Line height" />
          <N icon="Ls" value={get("letterSpacing")?.replace("px", "")} onChange={(v) => set("letterSpacing", /^\d+$/.test(v) ? `${v}px` : v)} placeholder="0" tip="Letter spacing" />
        </div>

        {/* Color */}
        <div>
          <span className="text-[10px] text-muted-foreground/40 mb-0.5 block">Color</span>
          <ColorField label="" value={get("color")} onChange={(v) => set("color", v)} />
        </div>

        {/* Align */}
        <IconToggle value={get("textAlign")} options={textAlignOpts} onChange={(v) => set("textAlign", v)} />

        {/* Style + Decoration */}
        <div className="grid grid-cols-2 gap-1">
          <IconToggle value={get("fontStyle")} options={fontStyleOpts} onChange={(v) => set("fontStyle", v)} />
          <IconToggle value={get("textDecoration")} options={textDecoOpts} onChange={(v) => set("textDecoration", v)} />
        </div>

        {/* Text transform */}
        <div>
          <span className="text-[10px] text-muted-foreground/40 mb-0.5 block">Transform</span>
          <div className="flex gap-1 rounded-md border border-sidebar-border p-0.5">
            {([["none", "—"], ["uppercase", "AA"], ["lowercase", "aa"], ["capitalize", "Aa"]] as const).map(([val, label]) => (
              <button key={val} onClick={() => set("textTransform", val)} className={cn("flex-1 h-5 rounded-md text-[10px] font-medium transition-colors", (get("textTransform") || "none") === val ? "bg-primary text-primary-foreground" : "text-muted-foreground/70 hover:text-foreground")}>{label}</button>
            ))}
          </div>
        </div>
      </div>
    </Section>
  );
}

"use client";

import { useState, type CSSProperties } from "react";
import { MIcon } from "../../ui/m-icon";
import type { El } from "../../core/types";
import { cn } from "@/shared/utils";
import { useEditor } from "../../core/provider";
import { findParentId } from "../../core/tree-helpers";
import DesignTab from "./design-tab";
import ContentTab from "./content-tab";

export default function SettingsTab() {
  const { state, dispatch } = useEditor();
  const [tab, setTab] = useState<"content" | "layout" | "style" | "advanced">("content");
  const selected = state.editor.selected;
  if (!selected) return null;

  const editingState = state.editor.editingState;
  const device = state.editor.device;
  let resolved: any;
  if (editingState === "hover") {
    resolved = selected.hoverStyles ?? {};
  } else {
    resolved = device === "desktop" ? selected.styles : { ...selected.styles, ...selected.responsiveStyles?.[device] };
  }

  const s = resolved as Record<string, unknown>;
  const get = (p: string) => String(s[p] ?? "");
  const set = (p: string, v: string) => {
    if (editingState === "hover") {
      dispatch({ type: "UPDATE_ELEMENT_LIVE", payload: { element: { ...selected, hoverStyles: { ...(selected.hoverStyles || {}), [p]: v } as CSSProperties } } });
    } else if (device === "desktop") {
      dispatch({ type: "UPDATE_ELEMENT_LIVE", payload: { element: { ...selected, styles: { ...selected.styles, [p]: v } as CSSProperties } } });
    } else {
      const prev = selected.responsiveStyles ?? {};
      dispatch({ type: "UPDATE_ELEMENT_LIVE", payload: { element: { ...selected, responsiveStyles: { ...prev, [device]: { ...prev[device], [p]: v } } } } });
    }
  };
  const onUpdate = (el: El) => dispatch({ type: "UPDATE_ELEMENT", payload: { element: el } });
  const parentId = findParentId(state.editor.elements, selected.id);
  const isBody = selected.type === "__body";

  return (
    <div className="flex flex-1 flex-col min-h-0 overflow-hidden">
      {/* Actions + name */}
      <div className="flex items-center gap-1 px-3 h-8 border-b border-sidebar-border shrink-0">
        <input aria-label="Selected element name" className="h-8 min-w-0 flex-1 rounded-md bg-transparent px-2 text-xs outline-none border border-transparent hover:border-sidebar-border focus:border-primary transition-all" value={selected.name} onChange={(e) => onUpdate({ ...selected, name: e.target.value })} />
        {device !== "desktop" && <span className="shrink-0 px-1.5 text-xs h-5 flex items-center rounded-md bg-primary/10 text-primary font-medium capitalize">{device}</span>}
        {parentId && <button aria-label="Duplicate element" className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:text-foreground hover:bg-sidebar-accent transition-colors" onClick={() => dispatch({ type: "DUPLICATE_ELEMENT", payload: { elId: selected.id, containerId: parentId } })}><MIcon name="content_copy" size={13} /></button>}
        <button aria-label={selected.locked ? "Unlock element" : "Lock element"} className={cn("flex size-8 items-center justify-center rounded-md transition-colors", selected.locked ? "text-warning" : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent")} onClick={() => onUpdate({ ...selected, locked: !selected.locked })}><MIcon name={selected.locked ? "lock" : "lock_open"} size={13} /></button>
        <button aria-label={selected.hidden ? "Show element" : "Hide element"} className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:text-foreground hover:bg-sidebar-accent transition-colors" onClick={() => onUpdate({ ...selected, hidden: !selected.hidden })}><MIcon name={selected.hidden ? "visibility_off" : "visibility"} size={13} /></button>
        {!isBody && <button aria-label="Delete element" className="flex size-8 items-center justify-center rounded-md text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors" onClick={() => dispatch({ type: "DELETE_ELEMENT", payload: { id: selected.id } })}><MIcon name="delete" size={13} /></button>}
      </div>

      {/* State Toggle (Default / Hover) */}
      {tab !== "content" && !isBody && (
        <div className="px-3 py-2 border-b border-sidebar-border bg-sidebar shrink-0">
          <div className="flex bg-sidebar-accent/50 p-0.5 rounded-lg border border-sidebar-border/30">
            <button 
              onClick={() => dispatch({ type: "SET_EDITING_STATE", payload: "default" } as any)} 
              className={cn("flex-1 text-[10px] font-medium h-6 rounded-md transition-all", editingState === "default" ? "bg-sidebar shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground")}
            >
              Default
            </button>
            <button 
              onClick={() => dispatch({ type: "SET_EDITING_STATE", payload: "hover" } as any)} 
              className={cn("flex-1 text-[10px] font-medium h-6 rounded-md transition-all flex items-center justify-center gap-1", editingState === "hover" ? "bg-sidebar shadow-sm text-foreground" : "text-muted-foreground hover:text-foreground")}
            >
              Hover
              {editingState === "hover" && <span className="size-1.5 rounded-full bg-primary" />}
            </button>
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex border-b border-sidebar-border shrink-0">
        {(["content", "layout", "style", "advanced"] as const).map((t) => (
          <button key={t} onClick={() => setTab(t)} className={cn(
            "min-w-0 flex-1 h-9 px-1 text-xs font-medium capitalize transition-colors",
            tab === t ? "text-foreground border-b-2 border-primary" : "text-muted-foreground hover:text-foreground",
            t !== "content" && "hidden xl:block"
          )}>{t}</button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto min-h-0">
        <div className={cn(tab !== "content" && "xl:hidden")}>
          <ContentTab selected={selected} onUpdate={onUpdate} />
        </div>
        <div className={cn("hidden", tab === "content" && "hidden", tab === "layout" && "xl:block")}>
          {tab === "layout" && <DesignTab mode="layout" get={get} set={set} selected={selected} onUpdate={onUpdate} />}
        </div>
        <div className={cn("hidden", tab === "content" && "hidden", tab === "style" && "xl:block")}>
          {tab === "style" && <DesignTab mode="style" get={get} set={set} selected={selected} onUpdate={onUpdate} />}
        </div>
        <div className={cn("hidden", tab === "content" && "hidden", tab === "advanced" && "xl:block")}>
          {tab === "advanced" && <DesignTab mode="advanced" get={get} set={set} selected={selected} onUpdate={onUpdate} />}
        </div>
      </div>
    </div>
  );
}

