interface AssetListItemProps {
  asset: MediaAsset;
  index: number;
  isSelected: boolean;
  onSelect: (e?: React.MouseEvent) => void;
  onDelete: () => void;
  onClick: () => void;
  onDragStart: (e: React.DragEvent) => void;
}

export const AssetListItem = memo(function AssetListItem({
  asset, isSelected, onSelect, onDelete, onClick, onDragStart,
}: AssetListItemProps) {
  const fileType = getFileTypeCategory(asset.mimeType);
  const [imgLoaded, setImgLoaded] = useState(false);
  const [imgError, setImgError] = useState(false);

  useEffect(() => { setImgLoaded(false); setImgError(false); }, [asset.id]);

  return (
    <div
      draggable onDragStart={onDragStart}
      className={cn(
        "group flex items-center gap-3 px-3 py-2 cursor-pointer transition-colors",
        isSelected ? "bg-accent" : "hover:bg-accent/50"
      )}
      onClick={onClick}
    >
      {/* Checkbox */}
      <div className={cn("transition-opacity", isSelected ? "opacity-100" : "opacity-0 group-hover:opacity-100")} onClick={e => e.stopPropagation()}>
        <Checkbox checked={isSelected} onCheckedChange={() => onSelect()} className="size-4" />
      </div>

      {/* Thumbnail */}
      <div className="size-10 rounded-md bg-muted flex items-center justify-center shrink-0 overflow-hidden">
        {fileType === "image" && !imgError ? (
          <img
            src={asset.thumbnailUrl || asset.cdnUrl}
            alt={asset.altText || asset.filename}
            className={cn("size-full object-cover", !imgLoaded && "opacity-0")}
            onLoad={() => setImgLoaded(true)}
            onError={() => setImgError(true)}
            loading="lazy"
          />
        ) : fileType === "video" ? (
          <Video className="size-4 text-muted-foreground" />
        ) : (
          <File className="size-4 text-muted-foreground" />
        )}
      </div>

      {/* Info */}
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{asset.filename}</p>
        <p className="text-xs text-muted-foreground">
          {formatFileSize(asset.sizeBytes)}
          {asset.width && asset.height && <span> · {asset.width}×{asset.height}</span>}
        </p>
      </div>

      {/* Type */}
      <span className="text-[10px] text-muted-foreground capitalize shrink-0">{fileType}</span>

      {/* Actions */}
      <div className={cn("transition-opacity", isSelected ? "opacity-100" : "opacity-0 group-hover:opacity-100")} onClick={e => e.stopPropagation()}>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="size-7">
              <MoreVertical className="size-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-36">
            <DropdownMenuItem onClick={() => navigator.clipboard.writeText(asset.cdnUrl)} className="text-xs gap-2">
              <Copy className="size-3.5" /> Copy URL
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => { const a = document.createElement("a"); a.href = asset.cdnUrl; a.download = asset.originalFilename; a.click(); }} className="text-xs gap-2">
              <Download className="size-3.5" /> Download
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={onDelete} className="text-xs gap-2 text-destructive focus:text-destructive">
              <Trash2 className="size-3.5" /> Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
});

"use client";

import { useState, useCallback, useEffect, useMemo, useRef } from "react";
import { createPortal } from "react-dom";
import { File, ArrowLeft, ArrowRight, X, Download, ExternalLink } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/shared/utils";
import type { MediaAsset } from "@/features/media/types";
import { formatFileSize, getFileTypeCategory } from "@/features/media/types";
import { ImagePreview } from "./image-preview";
import { VideoPreview } from "./video-preview";
import { AssetInfoPanel } from "./asset-info-panel";

function Portal({ children }: { children: React.ReactNode }) {
  if (typeof document === "undefined") return null;
  return createPortal(children, document.body);
}

interface AssetViewerProps {
  asset: MediaAsset | null;
  assets?: MediaAsset[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDeleted?: () => void;
  onUpdated?: (asset: MediaAsset) => void;
  onNavigate?: (direction: "prev" | "next") => void;
  canNavigatePrev?: boolean;
  canNavigateNext?: boolean;
}

export function AssetViewer({
  asset, assets = [], open, onOpenChange,
  onDeleted, onUpdated, onNavigate,
  canNavigatePrev = false, canNavigateNext = false,
}: AssetViewerProps) {
  const [isMounted, setIsMounted] = useState(false);
  const [showInfoPanel, setShowInfoPanel] = useState(true);

  const fileType = useMemo(
    () => (asset ? getFileTypeCategory(asset.mimeType) : "unknown"),
    [asset],
  );

  useEffect(() => { setIsMounted(true); }, []);
  useEffect(() => { if (open) setShowInfoPanel(true); }, [open]);

  // Scroll lock
  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => { document.body.style.overflow = ""; };
  }, [open]);

  // Keyboard shortcuts
  useEffect(() => {
    if (!open) return;
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
      switch (e.key) {
        case "Escape": onOpenChange(false); break;
        case "ArrowLeft": if (fileType !== "video" && canNavigatePrev) onNavigate?.("prev"); break;
        case "ArrowRight": if (fileType !== "video" && canNavigateNext) onNavigate?.("next"); break;
        case "i": setShowInfoPanel(s => !s); break;
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [open, fileType, canNavigatePrev, canNavigateNext, onNavigate, onOpenChange]);

  const handleDownload = useCallback(() => {
    if (!asset) return;
    const link = document.createElement("a");
    link.href = asset.cdnUrl;
    link.download = asset.originalFilename;
    link.click();
  }, [asset]);

  if (!asset || !isMounted || !open) return null;

  return (
    <Portal>
      <div className="fixed inset-0 z-50 bg-foreground/80 flex items-center justify-center p-4 md:p-8" onClick={() => onOpenChange(false)}>
        <div
          className="relative w-full max-w-[95vw] h-[90vh] bg-background border rounded-lg overflow-hidden flex"
          onClick={e => e.stopPropagation()}
        >
          {/* Preview column */}
          <div className="flex-1 relative h-full bg-muted/30 flex items-center justify-center overflow-hidden group">
            {/* Nav arrows */}
            {canNavigatePrev && (
              <Button variant="ghost" size="icon" className="absolute left-3 z-20 size-10 rounded-full bg-foreground/20 hover:bg-foreground/40 text-primary-foreground opacity-0 group-hover:opacity-100 transition-opacity" onClick={() => onNavigate?.("prev")}>
                <ArrowLeft className="size-4" />
              </Button>
            )}
            {canNavigateNext && (
              <Button variant="ghost" size="icon" className="absolute right-3 z-20 size-10 rounded-full bg-foreground/20 hover:bg-foreground/40 text-primary-foreground opacity-0 group-hover:opacity-100 transition-opacity" onClick={() => onNavigate?.("next")}>
                <ArrowRight className="size-4" />
              </Button>
            )}

            {fileType === "image" && <ImagePreview asset={asset} isFullscreen showControls />}
            {fileType === "video" && <VideoPreview asset={asset} isFullscreen showControls />}
            {(fileType === "document" || fileType === "unknown") && (
              <div className="flex flex-col items-center justify-center gap-3 text-center p-8">
                <div className="size-16 rounded-lg bg-muted flex items-center justify-center">
                  <File className="size-6 text-muted-foreground" />
                </div>
                <div className="space-y-1">
                  <p className="text-sm font-medium">{asset.filename}</p>
                  <p className="text-xs text-muted-foreground">{asset.mimeType} · {formatFileSize(asset.sizeBytes)}</p>
                </div>
                <div className="flex gap-2 mt-1">
                  <Button size="sm" onClick={() => window.open(asset.cdnUrl, "_blank")}>
                    <ExternalLink className="size-3.5" /> Open
                  </Button>
                  <Button size="sm" variant="outline" onClick={handleDownload}>
                    <Download className="size-3.5" /> Download
                  </Button>
                </div>
              </div>
            )}
          </div>

          {/* Info panel */}
          {showInfoPanel && (
            <AssetInfoPanel asset={asset} onDeleted={onDeleted} onUpdated={onUpdated} onClose={() => onOpenChange(false)} />
          )}
          {!showInfoPanel && (
            <Button variant="ghost" size="icon" className="absolute top-3 right-3 z-30 size-8 rounded-full bg-foreground/20 hover:bg-foreground/40 text-primary-foreground" onClick={() => onOpenChange(false)}>
              <X className="size-4" />
            </Button>
          )}
        </div>
      </div>
    </Portal>
  );
}

"use client";

import { memo } from "react";
import { Folder, Image } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { cn } from "@/shared/utils";

interface FolderDialogProps {
  open: boolean;
  mode: "create" | "rename";
  folderName: string;
  parentFolderName?: string | null; // Name of parent folder, null means root
  onOpenChange: (open: boolean) => void;
  onFolderNameChange: (name: string) => void;
  onSubmit: () => void;
}

export const FolderDialog = memo(function FolderDialog({
  open,
  mode,
  folderName,
  parentFolderName,
  onOpenChange,
  onFolderNameChange,
  onSubmit,
}: FolderDialogProps) {
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && folderName.trim()) {
      onSubmit();
    }
  };

  const isRoot = parentFolderName === null || parentFolderName === undefined;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {mode === "create" ? "Create Folder" : "Rename Folder"}
          </DialogTitle>
          {mode === "create" && (
            <DialogDescription className="flex items-center gap-2 pt-1">
              <span className="text-muted-foreground">Location:</span>
              <span className={cn(
                "inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-xs font-medium",
                "bg-muted text-foreground"
              )}>
                {isRoot ? (
                  <Image className="size-3.5" />
                ) : (
                  <Folder className="size-3.5" />
                )}
                {isRoot ? "All Files (Root)" : parentFolderName}
              </span>
            </DialogDescription>
          )}
        </DialogHeader>
        <Input
          placeholder="Folder name"
          value={folderName}
          onChange={(e) => onFolderNameChange(e.target.value)}
          onKeyDown={handleKeyDown}
          autoFocus
          className="mt-2"
        />
        <DialogFooter className="mt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={onSubmit} disabled={!folderName.trim()}>
            {mode === "create" ? "Create" : "Rename"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
});

"use client";

import { memo, useState, useEffect, useMemo } from "react";
import {
  FolderPlus,
  Image,
  Folder,
  FolderOpen,
  PenLine,
  Trash2,
  HardDrive,
  X,
  ChevronRight,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from "@/components/ui/context-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Collapsible,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { cn } from "@/shared/utils";
import type { MediaFolder, StorageUsage } from "@/features/media/types";
import { formatFileSize } from "@/features/media/types";

// Extended folder type with optional asset count
interface FolderWithCount extends MediaFolder {
  assetCount?: number;
}

interface FolderSidebarProps {
  folders: FolderWithCount[];
  currentFolderId: string | null;
  storageUsage: StorageUsage;
  dragOverFolderId: string | null;
  totalAssetCount?: number;
  onFolderClick: (folderId: string | null) => void;
  onFolderDragOver: (e: React.DragEvent, folderId: string | null) => void;
  onFolderDrop: (e: React.DragEvent, folderId: string | null) => void;
  onCreateFolder: () => void;
  onRenameFolder: (folder: FolderWithCount) => void;
  onDeleteFolder: (folder: FolderWithCount) => void;
}

// Recursive folder item component with drag animations
function FolderItem({
  folder,
  folders,
  currentFolderId,
  dragOverFolderId,
  depth = 0,
  onFolderClick,
  onFolderDragOver,
  onFolderDrop,
  onRenameFolder,
  onDeleteFolder,
}: {
  folder: FolderWithCount;
  folders: FolderWithCount[];
  currentFolderId: string | null;
  dragOverFolderId: string | null;
  depth?: number;
  onFolderClick: (folderId: string | null) => void;
  onFolderDragOver: (e: React.DragEvent, folderId: string | null) => void;
  onFolderDrop: (e: React.DragEvent, folderId: string | null) => void;
  onRenameFolder: (folder: FolderWithCount) => void;
  onDeleteFolder: (folder: FolderWithCount) => void;
}) {
  const childFolders = folders.filter((f) => f.parentFolderId === folder.id);
  const hasChildren = childFolders.length > 0;
  const [isOpen, setIsOpen] = useState(true);
  const isActive = currentFolderId === folder.id;
  const isDragOver = dragOverFolderId === folder.id && !isActive;

  return (
    <div className="animate-in fade-in slide-in-from-left-1 duration-200">
      <ContextMenu>
        <ContextMenuTrigger asChild>
          <div className="flex items-center">
            {hasChildren && (
              <Collapsible open={isOpen} onOpenChange={setIsOpen}>
                <CollapsibleTrigger asChild>
                  <button
                    className={cn(
                      "size-5 flex items-center justify-center rounded hover:bg-muted shrink-0",
                      depth > 0 && "ml-1"
                    )}
                    onClick={(e) => {
                      e.stopPropagation();
                      setIsOpen(!isOpen);
                    }}
                  >
                    <ChevronRight className={cn("size-3.5 text-muted-foreground transition-transform duration-200", isOpen && "rotate-90")} />
                  </button>
                </CollapsibleTrigger>
              </Collapsible>
            )}
            <button
              onClick={() => onFolderClick(folder.id)}
              onDragOver={(e) => onFolderDragOver(e, folder.id)}
              onDragLeave={(e) => {
                e.preventDefault();
                e.stopPropagation();
              }}
              onDrop={(e) => onFolderDrop(e, folder.id)}
              className={cn(
                "flex-1 text-left px-3 py-2 rounded-lg text-sm flex items-center gap-3 transition-colors outline-none group",
                "focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
                !hasChildren && depth > 0 && "ml-7",
                isActive
                  ? "bg-primary/10 text-primary font-medium"
                  : "text-muted-foreground hover:bg-muted hover:text-foreground",
                isDragOver && "bg-primary/15 ring-2 ring-primary/40"
              )}
              style={{ paddingLeft: hasChildren ? undefined : `${depth * 12 + 12}px` }}
            >
              {/* Folder icon */}
              <div className="transition-transform duration-200">
                {isDragOver ? (
                  <FolderOpen
                    className={cn(
                      "size-4 shrink-0 transition-colors",
                      "text-primary"
                    )}
                  />
                ) : (
                  <Folder
                    className={cn(
                      "size-4 shrink-0 transition-colors",
                      isActive 
                        ? "text-primary" 
                        : "text-muted-foreground/50 group-hover:text-foreground"
                    )}
                  />
                )}
              </div>
              <span className="truncate flex-1">{folder.name}</span>

              {/* Drop indicator badge */}
              {isDragOver && (
                  <span
                    className="text-[10px] font-semibold px-1.5 py-0.5 rounded bg-primary text-primary-foreground animate-in fade-in zoom-in-95 duration-150"
                  >
                    Drop
                  </span>
              )}

              {folder.assetCount !== undefined && folder.assetCount > 0 && !isDragOver && (
                <span className={cn(
                  "text-xs tabular-nums px-2 py-0.5 rounded-md",
                  isActive
                    ? "bg-primary/20 text-primary"
                    : "bg-muted text-muted-foreground group-hover:bg-border"
                )}>
                  {folder.assetCount}
                </span>
              )}
            </button>
          </div>
        </ContextMenuTrigger>
        <ContextMenuContent>
          <ContextMenuItem onClick={() => onRenameFolder(folder)}>
            <PenLine className="size-3.5" />
            Rename
          </ContextMenuItem>
          <ContextMenuItem
            onClick={() => onDeleteFolder(folder)}
            className="text-destructive focus:text-destructive"
          >
            <Trash2 className="size-3.5" />
            Delete
          </ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>

      {/* Child folders */}
      {hasChildren && isOpen && (
          <div
            className="ml-3 border-l border-border/50 pl-1 mt-0.5 space-y-0.5 overflow-hidden animate-in fade-in slide-in-from-top-1 duration-200"
          >
            {childFolders.map((child) => (
              <FolderItem
                key={child.id}
                folder={child}
                folders={folders}
                currentFolderId={currentFolderId}
                dragOverFolderId={dragOverFolderId}
                depth={depth + 1}
                onFolderClick={onFolderClick}
                onFolderDragOver={onFolderDragOver}
                onFolderDrop={onFolderDrop}
                onRenameFolder={onRenameFolder}
                onDeleteFolder={onDeleteFolder}
              />
            ))}
          </div>
      )}
    </div>
  );
}

export const FolderSidebar = memo(function FolderSidebar({
  folders,
  currentFolderId,
  storageUsage,
  dragOverFolderId,
  totalAssetCount = 0,
  onFolderClick,
  onFolderDragOver,
  onFolderDrop,
  onCreateFolder,
  onRenameFolder,
  onDeleteFolder,
}: FolderSidebarProps) {
  const rootFolders = useMemo(() => folders.filter((f) => !f.parentFolderId), [folders]);
  const [isMobileOpen, setIsMobileOpen] = useState(false);

  // Close mobile sidebar on escape
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isMobileOpen) {
        setIsMobileOpen(false);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isMobileOpen]);

  // Close mobile sidebar when folder is selected
  const handleFolderClick = (folderId: string | null) => {
    onFolderClick(folderId);
    setIsMobileOpen(false);
  };

  return (
    <>
      {/* Mobile toggle button */}
      <Button
        variant="outline"
        size="icon"
        className="fixed bottom-4 left-4 z-40 lg:hidden size-12 rounded-full"
        onClick={() => setIsMobileOpen(true)}
        aria-label="Open folders"
      >
        <Folder className="size-4" />
      </Button>

      {/* Mobile backdrop */}
      {isMobileOpen && (
        <div
          className="fixed inset-0 z-40 bg-foreground/50 lg:hidden animate-in fade-in duration-200"
          onClick={() => setIsMobileOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Sidebar */}
      <div
        className={cn(
          "w-60 border-r bg-sidebar flex flex-col shrink-0",
          "fixed inset-y-0 left-0 z-50 transform transition-transform duration-300 ease-out lg:relative lg:translate-x-0",
          isMobileOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        {/* Header */}
        <div className="h-14 px-4 border-b flex items-center justify-between bg-sidebar">
          <span className="text-sm font-semibold tracking-tight">Folders</span>
          <div className="flex items-center gap-1">
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"

                  className="size-8 p-0"
                  onClick={onCreateFolder}
                  aria-label="Create folder"
                >
                  <FolderPlus className="size-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Create folder</TooltipContent>
            </Tooltip>
            <Button
              variant="ghost"

              className="size-8 p-0 lg:hidden"
              onClick={() => setIsMobileOpen(false)}
              aria-label="Close folders"
            >
              <X className="size-4" />
            </Button>
          </div>
        </div>

        <div className="flex-1 overflow-auto p-3 space-y-1">
          {/* All Files */}
          <button
            onClick={() => handleFolderClick(null)}
            onDragOver={(e) => onFolderDragOver(e, null)}
            onDragLeave={(e) => {
              e.preventDefault();
              e.stopPropagation();
            }}
            onDrop={(e) => onFolderDrop(e, null)}
            className={cn(
              "w-full text-left px-3 py-2.5 rounded-lg text-sm flex items-center gap-3 transition-colors outline-none group",
              "focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
              currentFolderId === null
                ? "bg-primary/10 text-primary font-medium"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
              dragOverFolderId === null && currentFolderId !== null && "bg-primary/15 ring-2 ring-primary/40"
            )}
          >
            <div>
              <Image className="size-4 shrink-0" />
            </div>
            <span className="flex-1">All Files</span>

            {/* Drop indicator for All Files */}
            {dragOverFolderId === null && currentFolderId !== null && (
                <span
                  className="text-[10px] font-semibold px-1.5 py-0.5 rounded bg-primary text-primary-foreground animate-in fade-in zoom-in-95 duration-150"
                >
                  Drop
                </span>
            )}

            {totalAssetCount > 0 && !(dragOverFolderId === null && currentFolderId !== null) && (
              <span className={cn(
                "text-xs tabular-nums px-2 py-0.5 rounded-md",
                currentFolderId === null
                  ? "bg-primary/20 text-primary"
                  : "bg-muted text-muted-foreground group-hover:bg-border"
              )}>
                {totalAssetCount}
              </span>
            )}
          </button>

          {/* Folders section */}
          {folders.length > 0 && (
            <div className="px-3 pt-4 pb-2">
              <span className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground/50">
                Folders
              </span>
            </div>
          )}

          {/* Folder tree */}
          <div className="space-y-0.5">
            {rootFolders.map((folder) => (
              <FolderItem
                key={folder.id}
                folder={folder}
                folders={folders}
                currentFolderId={currentFolderId}
                dragOverFolderId={dragOverFolderId}
                onFolderClick={handleFolderClick}
                onFolderDragOver={onFolderDragOver}
                onFolderDrop={onFolderDrop}
                onRenameFolder={onRenameFolder}
                onDeleteFolder={onDeleteFolder}
              />
            ))}
          </div>

          {/* Empty state */}
          {folders.length === 0 && (
            <div className="px-3 py-8 text-center">
              <Folder className="size-8 mx-auto text-border" />
              <p className="text-xs text-muted-foreground mt-3">No folders created yet</p>
              <Button
                variant="ghost"

                className="mt-3 h-8 text-xs font-medium"
                onClick={onCreateFolder}
              >
                Create new folder
              </Button>
            </div>
          )}
        </div>

        {/* Storage Usage */}
        <div className="p-3 border-t bg-muted">
          <div className="flex items-center gap-2 mb-2">
            <HardDrive className="size-4 text-muted-foreground" />
            <span className="text-xs font-medium">Storage</span>
          </div>
          <Progress
            value={storageUsage.percentUsed}
            className={cn(
              "h-1.5",
              storageUsage.percentUsed >= 90 && "[&>div]:bg-destructive",
              storageUsage.percentUsed >= 80 && storageUsage.percentUsed < 90 && "[&>div]:bg-warning"
            )}
          />
          <div className="mt-2 flex items-center justify-between text-xs text-muted-foreground">
            <span>{formatFileSize(storageUsage.usedBytes)} used</span>
            <span>{formatFileSize(storageUsage.quotaBytes - storageUsage.usedBytes)} free</span>
          </div>
          {storageUsage.percentUsed >= 80 && (
            <p className={cn(
              "text-xs mt-2 font-medium",
              storageUsage.percentUsed >= 90 ? "text-destructive" : "text-warning"
            )}>
              {storageUsage.percentUsed >= 90 ? "Storage almost full!" : "Storage running low"}
            </p>
          )}
        </div>
      </div>
    </>
  );
});

"use client";

import { useState } from "react";
import Image from "next/image";
import { Loader2, ImageOff } from "lucide-react";
import { cn } from "@/shared/utils";
import type { MediaAsset } from "@/features/media/types";

interface ImagePreviewProps {
  asset: MediaAsset;
  isFullscreen: boolean;
  showControls: boolean;
}

export function ImagePreview({ asset, isFullscreen }: ImagePreviewProps) {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center gap-2 p-8 text-muted-foreground">
        <ImageOff className="size-8" />
        <p className="text-sm">Failed to load image</p>
      </div>
    );
  }

  return (
    <div className="relative flex items-center justify-center w-full h-full p-4">
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center">
          <Loader2 className="size-6 animate-spin text-muted-foreground" />
        </div>
      )}
      <Image
        src={asset.cdnUrl}
        alt={asset.altText || asset.filename}
        width={asset.width || 800}
        height={asset.height || 600}
        className={cn("max-w-full max-h-full object-contain rounded-md", loading && "opacity-0")}
        onLoad={() => setLoading(false)}
        onError={() => { setLoading(false); setError(true); }}
        unoptimized
        priority
      />
    </div>
  );
}

