function getFileIcon(mimeType: string) {
  if (mimeType.startsWith("image/")) return Image;
  if (mimeType.startsWith("video/")) return Video;
  return File;
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) return "0 B";
  const k = 1024;
  const sizes = ["B", "KB", "MB", "GB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}

export const UploadPanel = memo(function UploadPanel() {
  const files = useUploadStore((s) => s.files);
  const isUploading = useUploadStore((s) => s.isUploading);
  const cancelUpload = useUploadStore((s) => s.cancelUpload);
  const clearCompleted = useUploadStore((s) => s.clearCompleted);
  const retryUpload = useUploadStore((s) => s.retryUpload);
  const currentFolderId = useMediaStore((s) => s.currentFolderId);

  const [isExpanded, setIsExpanded] = useState(true);

  const stats = useMemo(() => {
    const active = files.filter(
      (u) => u.status === "uploading" || u.status === "pending"
    );
    const completed = files.filter((u) => u.status === "complete");
    const errors = files.filter((u) => u.status === "error");

    let overallProgress = 0;
    if (active.length > 0) {
      const activeProgress = active.reduce((sum, u) => sum + u.progress, 0);
      overallProgress = Math.round(activeProgress / active.length);
    } else if (completed.length > 0) {
      overallProgress = 100;
    }

    const totalSize = active.reduce((sum, u) => sum + u.file.size, 0);
    const uploadedSize = active.reduce((sum, u) => sum + (u.file.size * u.progress / 100), 0);

    return {
      activeCount: active.length,
      completedCount: completed.length,
      errorCount: errors.length,
      overallProgress,
      totalSize,
      uploadedSize,
      remainingSize: totalSize - uploadedSize,
      isUploading: active.length > 0,
    };
  }, [files]);

  if (files.length === 0) return null;

  return (
    <div
        className="fixed bottom-6 right-6 z-50 w-[380px] max-w-[calc(100vw-3rem)] animate-in fade-in slide-in-from-bottom-2 duration-200"
      >
        <div className="bg-background border rounded-lg overflow-hidden">
          {/* Header */}
          <div
            className={cn(
              "px-4 py-3 flex items-center gap-3 cursor-pointer transition-colors",
              stats.isUploading ? "bg-primary/5" : stats.errorCount > 0 ? "bg-destructive/10" : "bg-success/10"
            )}
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {/* Upload Icon with Animation */}
            <div className={cn(
              "size-9 rounded-full flex items-center justify-center shrink-0",
              stats.isUploading ? "bg-primary/10" : stats.errorCount > 0 ? "bg-destructive/15" : "bg-success/15"
            )}>
              {stats.isUploading ? (
                <div className="animate-bounce">
                  <UploadCloud className="size-4.5 text-primary" />
                </div>
              ) : stats.errorCount > 0 ? (
                <AlertCircle className="size-4.5 text-destructive" />
              ) : (
                <CheckCircle2 className="size-4.5 text-success" />
              )}
            </div>

            {/* Status Text */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <span className="text-sm font-semibold">
                  {stats.isUploading 
                    ? `Uploading ${stats.activeCount} file${stats.activeCount > 1 ? "s" : ""}` 
                    : stats.errorCount > 0 
                      ? "Upload incomplete"
                      : "Upload complete"
                  }
                </span>
                {stats.isUploading && (
                  <span className="text-xs text-muted-foreground tabular-nums">
                    {stats.overallProgress}%
                  </span>
                )}
              </div>
              <div className="flex items-center gap-2 text-xs text-muted-foreground mt-0.5">
                {stats.completedCount > 0 && (
                  <span className="flex items-center gap-1 text-success">
                    <CheckCircle2 className="size-3.5" />
                    {stats.completedCount}
                  </span>
                )}
                {stats.errorCount > 0 && (
                  <span className="flex items-center gap-1 text-destructive">
                    <AlertCircle className="size-3.5" />
                    {stats.errorCount}
                  </span>
                )}
                {stats.isUploading && stats.remainingSize > 0 && (
                  <span>{formatFileSize(stats.remainingSize)} remaining</span>
                )}
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-1 shrink-0">
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button 
                    variant="ghost" 
                    size="icon" 
                    className="size-7"
                    onClick={(e) => {
                      e.stopPropagation();
                      setIsExpanded(!isExpanded);
                    }}
                  >
                    {isExpanded ? (
                      <ChevronDown className="size-4" />
                    ) : (
                      <ChevronUp className="size-4" />
                    )}
                  </Button>
                </TooltipTrigger>
                <TooltipContent>{isExpanded ? "Collapse" : "Expand"}</TooltipContent>
              </Tooltip>
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button 
                    variant="ghost" 
                    size="icon" 
                    className="size-7"
                    onClick={(e) => {
                      e.stopPropagation();
                      clearCompleted();
                    }}
                  >
                    <X className="size-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Clear all</TooltipContent>
              </Tooltip>
            </div>
          </div>

          {/* Overall Progress Bar */}
          {stats.isUploading && (
            <div className="h-1 bg-muted">
              <div
                className="h-full bg-primary transition-[width] duration-300 ease-out"
                style={{ width: `${stats.overallProgress}%` }}
              />
            </div>
          )}

          {/* File List */}
          {isExpanded && (
              <div
                className="overflow-hidden animate-in fade-in slide-in-from-top-1 duration-200"
              >
                <div className="max-h-64 overflow-auto">
                  {files.map((upload) => (
                    <div
                      key={upload.id}
                      className={cn(
                        "flex items-center gap-3 px-4 py-2.5 border-t transition-colors animate-in fade-in slide-in-from-left-1 duration-200",
                        upload.status === "error" && "bg-destructive/10",
                        upload.status === "complete" && "bg-success/10"
                      )}
                    >
                      {/* File Type Icon */}
                      <div className={cn(
                        "size-8 rounded-lg flex items-center justify-center shrink-0",
                        upload.status === "error" ? "bg-destructive/15" :
                        upload.status === "complete" ? "bg-success/15" : "bg-muted"
                      )}>
                        {(() => {
                          const FileIcon = getFileIcon(upload.file.type);
                          return (
                            <FileIcon 
                              className={cn(
                                "size-4",
                                upload.status === "error" ? "text-destructive" :
                                upload.status === "complete" ? "text-success" : "text-muted-foreground"
                              )} 
                            />
                          );
                        })()}
                      </div>

                      {/* File Info */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm truncate font-medium">{upload.file.name}</span>
                        </div>
                        <div className="flex items-center gap-2 mt-0.5">
                          {upload.status === "error" ? (
                            <span className="text-xs text-destructive truncate">{upload.error}</span>
                          ) : upload.status === "complete" ? (
                            <span className="text-xs text-success">Uploaded</span>
                          ) : (
                            <>
                              <span className="text-xs text-muted-foreground">
                                {formatFileSize(upload.file.size)}
                              </span>
                              <span className="text-xs text-muted-foreground">•</span>
                              <span className="text-xs text-primary font-medium tabular-nums">
                                {upload.progress}%
                              </span>
                            </>
                          )}
                        </div>
                        {(upload.status === "uploading" || upload.status === "pending") && (
                          <div className="mt-1.5 h-1 bg-muted rounded-full overflow-hidden">
                            <div
                              className="h-full bg-primary rounded-full transition-[width] duration-300 ease-out"
                              style={{ width: `${upload.progress}%` }}
                            />
                          </div>
                        )}
                      </div>

                      {/* Status/Actions */}
                      <div className="flex items-center gap-1 shrink-0">
                        {upload.status === "uploading" && (
                          <div className="size-4 rounded-full border-2 border-primary border-t-transparent animate-spin" />
                        )}
                        {upload.status === "complete" && (
                          <CheckCircle2 className="size-4 text-success" />
                        )}
                        {upload.status === "error" && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-5"
                                onClick={() => retryUpload(upload.id, currentFolderId)}
                              >
                                <RefreshCw className="size-3.5" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Retry</TooltipContent>
                          </Tooltip>
                        )}
                        {(upload.status === "uploading" || upload.status === "pending") && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-5"
                                onClick={() => cancelUpload(upload.id)}
                              >
                                <X className="size-3.5" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Cancel</TooltipContent>
                          </Tooltip>
                        )}
                        {(upload.status === "complete" || upload.status === "error") && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-5 opacity-50 hover:opacity-100"
                                onClick={() => cancelUpload(upload.id)}
                              >
                                <X className="size-3.5" />
                              </Button>
                            </TooltipTrigger>
                            <TooltipContent>Dismiss</TooltipContent>
                          </Tooltip>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
        </div>
      </div>
  );
});

import { create } from "zustand";
import type { UploadingFile, UploadStatus } from "@/features/media/types";
import { validateFile } from "@/features/media/types";
import { uploadAsset } from "@/app/dashboard/media/actions";
import { useMediaStore } from "./media-store";

interface UploadState {
  files: UploadingFile[];
  isUploading: boolean;
  isDragging: boolean;

  addFiles: (files: File[], folderId: string | null) => void;
  cancelUpload: (id: string) => void;
  retryUpload: (id: string, folderId: string | null) => void;
  clearCompleted: () => void;
  setDragging: (v: boolean) => void;
}

let idCounter = 0;

export const useUploadStore = create<UploadState>((set, get) => ({
  files: [],
  isUploading: false,
  isDragging: false,

  addFiles: (rawFiles, folderId) => {
    const entries: UploadingFile[] = [];
    for (const file of rawFiles) {
      const validation = validateFile(file);
      const id = `upload-${++idCounter}`;
      entries.push({
        id,
        file,
        progress: 0,
        status: validation.valid ? "pending" : "error",
        error: validation.error,
      });
    }

    set((s) => ({ files: [...entries, ...s.files], isUploading: true }));

    // Start uploading valid files
    for (const entry of entries) {
      if (entry.status === "pending") {
        processUpload(entry.id, entry.file, folderId);
      }
    }
  },

  cancelUpload: (id) => {
    set((s) => ({
      files: s.files.filter((f) => f.id !== id),
      isUploading: s.files.some((f) => f.id !== id && f.status === "uploading"),
    }));
  },

  retryUpload: (id, folderId) => {
    const file = get().files.find((f) => f.id === id);
    if (!file) return;
    updateFile(id, { status: "uploading", progress: 0, error: undefined });
    processUpload(id, file.file, folderId);
  },

  clearCompleted: () => {
    set((s) => ({
      files: s.files.filter((f) => f.status !== "complete" && f.status !== "error"),
    }));
  },

  setDragging: (v) => set({ isDragging: v }),
}));

function updateFile(id: string, updates: Partial<UploadingFile>) {
  useUploadStore.setState((s) => ({
    files: s.files.map((f) => (f.id === id ? { ...f, ...updates } : f)),
    isUploading: s.files.some(
      (f) => (f.id === id ? (updates.status ?? f.status) : f.status) === "uploading"
    ),
  }));
}

async function processUpload(id: string, file: File, folderId: string | null) {
  updateFile(id, { status: "uploading", progress: 10 });

  try {
    const formData = new FormData();
    formData.append("file", file);
    if (folderId) formData.append("folderId", folderId);

    updateFile(id, { progress: 40 });
    const result = await uploadAsset(formData);
    updateFile(id, { progress: 80 });

    if (!result.success || !result.asset) {
      updateFile(id, { status: "error", error: result.error ?? "Upload failed", progress: 0 });
      return;
    }

    updateFile(id, { status: "complete", progress: 100, asset: result.asset });

    // Add to media store
    useMediaStore.getState().addAsset(result.asset);
  } catch (err) {
    updateFile(id, {
      status: "error",
      error: err instanceof Error ? err.message : "Upload failed",
      progress: 0,
    });
  }
}

import "server-only";
import { 
  notificationPreferences, 
  quietHoursSettings,
  type NotificationCategory,
  type NotificationChannel,
  type NotificationFrequency,
  type NotificationPreference,
  type QuietHoursSetting,
} from "@/db/schema/notification-preferences";
import { eq, and } from "drizzle-orm";
import { withTenant } from "@/infrastructure/db";

/**
 * Notification Preferences Repository
 * 
 * Manages user notification preferences with tenant isolation.
 * 
 * @see IMPLEMENTATION-PLAN.md Section 4.1
 * @see SYSTEM-ARCHITECTURE.md Section 5.2 (Multitenancy Safeguards)
 */

// Input types
export interface NotificationPreferenceInput {
  category: NotificationCategory;
  channel: NotificationChannel;
  enabled: boolean;
  frequency: NotificationFrequency;
}

export interface QuietHoursInput {
  enabled: boolean;
  startTime: string;
  endTime: string;
  timezone: string;
}

export interface UserNotificationPreferences {
  preferences: NotificationPreference[];
  quietHours: QuietHoursSetting | null;
}

// Default preferences for new users
const ALL_CATEGORIES: NotificationCategory[] = ["orders", "inventory", "system", "mentions"];
const ALL_CHANNELS: NotificationChannel[] = ["in_app", "email", "push", "whatsapp", "sms"];

export class NotificationPreferencesRepository {
  /**
   * Get all notification preferences for a user
   */
  async findByUser(tenantId: string, userId: string): Promise<UserNotificationPreferences> {
    return withTenant(tenantId, async (tx) => {
      const preferences = await tx
        .select()
        .from(notificationPreferences)
        .where(and(eq(notificationPreferences.tenantId, tenantId), eq(notificationPreferences.userId, userId)));

      const [quietHours] = await tx
        .select()
        .from(quietHoursSettings)
        .where(and(eq(quietHoursSettings.tenantId, tenantId), eq(quietHoursSettings.userId, userId)))
        .limit(1);

      return {
        preferences,
        quietHours: quietHours || null,
      };
    });
  }

  /**
   * Get a specific preference
   */
  async findPreference(
    tenantId: string, 
    userId: string, 
    category: NotificationCategory, 
    channel: NotificationChannel
  ): Promise<NotificationPreference | null> {
    return withTenant(tenantId, async (tx) => {
      const [result] = await tx
        .select()
        .from(notificationPreferences)
        .where(
          and(
            eq(notificationPreferences.tenantId, tenantId),
            eq(notificationPreferences.userId, userId),
            eq(notificationPreferences.category, category),
            eq(notificationPreferences.channel, channel)
          )
        )
        .limit(1);

      return result || null;
    });
  }

  /**
   * Upsert a notification preference
   */
  async upsertPreference(
    tenantId: string,
    userId: string,
    input: NotificationPreferenceInput
  ): Promise<NotificationPreference> {
    return withTenant(tenantId, async (tx) => {
      // Check if preference exists
      const [existing] = await tx
        .select()
        .from(notificationPreferences)
        .where(
          and(
            eq(notificationPreferences.tenantId, tenantId),
            eq(notificationPreferences.userId, userId),
            eq(notificationPreferences.category, input.category),
            eq(notificationPreferences.channel, input.channel)
          )
        )
        .limit(1);

      if (existing) {
        // Update existing
        const [updated] = await tx
          .update(notificationPreferences)
          .set({
            enabled: input.enabled,
            frequency: input.frequency,
            updatedAt: new Date(),
          })
          .where(eq(notificationPreferences.id, existing.id))
          .returning();

        return updated;
      } else {
        // Create new
        const [created] = await tx
          .insert(notificationPreferences)
          .values({
            tenantId,
            userId,
            category: input.category,
            channel: input.channel,
            enabled: input.enabled,
            frequency: input.frequency,
          })
          .returning();

        return created;
      }
    });
  }

  /**
   * Bulk upsert notification preferences
   */
  async bulkUpsertPreferences(
    tenantId: string,
    userId: string,
    inputs: NotificationPreferenceInput[]
  ): Promise<NotificationPreference[]> {
    const results: NotificationPreference[] = [];

    for (const input of inputs) {
      const result = await this.upsertPreference(tenantId, userId, input);
      results.push(result);
    }

    return results;
  }

  /**
   * Get or create quiet hours settings for a user
   */
  async getQuietHours(tenantId: string, userId: string): Promise<QuietHoursSetting | null> {
    return withTenant(tenantId, async (tx) => {
      const [result] = await tx
        .select()
        .from(quietHoursSettings)
        .where(and(eq(quietHoursSettings.tenantId, tenantId), eq(quietHoursSettings.userId, userId)))
        .limit(1);

      return result || null;
    });
  }

  /**
   * Upsert quiet hours settings
   */
  async upsertQuietHours(
    tenantId: string,
    userId: string,
    input: QuietHoursInput
  ): Promise<QuietHoursSetting> {
    return withTenant(tenantId, async (tx) => {
      // Check if settings exist
      const [existing] = await tx
        .select()
        .from(quietHoursSettings)
        .where(and(eq(quietHoursSettings.tenantId, tenantId), eq(quietHoursSettings.userId, userId)))
        .limit(1);

      if (existing) {
        // Update existing
        const [updated] = await tx
          .update(quietHoursSettings)
          .set({
            enabled: input.enabled,
            startTime: input.startTime,
            endTime: input.endTime,
            timezone: input.timezone,
            updatedAt: new Date(),
          })
          .where(eq(quietHoursSettings.id, existing.id))
          .returning();

        return updated;
      } else {
        // Create new
        const [created] = await tx
          .insert(quietHoursSettings)
          .values({
            tenantId,
            userId,
            enabled: input.enabled,
            startTime: input.startTime,
            endTime: input.endTime,
            timezone: input.timezone,
          })
          .returning();

        return created;
      }
    });
  }

  /**
   * Initialize default preferences for a new user
   */
  async initializeDefaults(tenantId: string, userId: string): Promise<void> {
    await withTenant(tenantId, async (tx) => {
      // Create default preferences for all category/channel combinations
      const defaultPrefs = ALL_CATEGORIES.flatMap(category =>
        ALL_CHANNELS.map(channel => ({
          tenantId,
          userId,
          category,
          channel,
          enabled: channel !== "push", // Push disabled by default (future feature)
          frequency: "realtime" as NotificationFrequency,
        }))
      );

      // Insert all defaults (ignore conflicts)
      for (const pref of defaultPrefs) {
        await tx
          .insert(notificationPreferences)
          .values(pref)
          .onConflictDoNothing();
      }

      // Create default quiet hours (disabled)
      await tx
        .insert(quietHoursSettings)
        .values({
          tenantId,
          userId,
          enabled: false,
          startTime: "22:00",
          endTime: "08:00",
          timezone: "UTC",
        })
        .onConflictDoNothing();
    });
  }

  /**
   * Check if notifications should be delivered for a user/category/channel
   */
  async shouldDeliver(
    tenantId: string,
    userId: string,
    category: NotificationCategory,
    channel: NotificationChannel
  ): Promise<{ deliver: boolean; frequency: NotificationFrequency }> {
    const pref = await this.findPreference(tenantId, userId, category, channel);

    if (!pref || !pref.enabled) {
      return { deliver: false, frequency: "realtime" };
    }

    return { deliver: true, frequency: pref.frequency || "realtime" };
  }

  /**
   * Delete all preferences for a user (for account deletion)
   */
  async deleteUserPreferences(tenantId: string, userId: string): Promise<void> {
    await withTenant(tenantId, async (tx) => {
      await tx
        .delete(notificationPreferences)
        .where(and(eq(notificationPreferences.tenantId, tenantId), eq(notificationPreferences.userId, userId)));

      await tx
        .delete(quietHoursSettings)
        .where(and(eq(quietHoursSettings.tenantId, tenantId), eq(quietHoursSettings.userId, userId)));
    });
  }
}

