"use client";

import { useState, useEffect } from "react";

const KEY = "cookie-consent";

export function CookieConsent({ text, enabled }: { text: string; enabled: boolean }) {
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (enabled && !localStorage.getItem(KEY)) setShow(true);
  }, [enabled]);

  if (!show) return null;

  const dismiss = (accept: boolean) => {
    if (accept) localStorage.setItem(KEY, "1");
    setShow(false);
  };

  return (
    <div className="fixed bottom-4 left-4 right-4 z-50 mx-auto flex max-w-xl items-center gap-4 rounded-lg border bg-popover px-5 py-3 text-sm text-popover-foreground shadow-lg">
      <p className="flex-1">{text}</p>
      <button onClick={() => dismiss(true)} className="rounded-md bg-primary px-3 py-1 text-sm font-medium text-primary-foreground hover:bg-primary/90">Accept</button>
      <button onClick={() => dismiss(false)} className="rounded-md border border-border px-3 py-1 text-sm hover:bg-muted">Decline</button>
    </div>
  );
}

/**
 * Server-side cart data layer
 * Uses Drizzle ORM for type-safe database interactions
 * 
 * @deprecated Use cartRepository from @/lib/repositories instead
 * This file is kept for backward compatibility with existing code
 */
"use server"

import { revalidateTag } from "next/cache"
import { getCartId, setCartId, removeCartId, getCacheTag } from "@/features/store/data/cookies"
import { db } from "@/infrastructure/db"
import { carts, cartItems, orders, orderItems, products, users, tenants } from "@/db/schema"
import { eq, and, sql } from "drizzle-orm"
import { sendOrderConfirmationEmail, sendOrderNotificationEmail } from "@/infrastructure/services/email/actions"
import { createLogger } from "@/lib/logger";
const log = createLogger("features:store-cart");

// Cache profile for cart revalidation (short-lived, user-specific)
const CART_CACHE_PROFILE = "seconds"

// Types
export interface CartItem {
  id: string
  productId: string | null
  variantId: string | null
  productName: string
  productSku: string | null
  productImage: string | null
  unitPrice: number
  compareAtPrice: number | null
  quantity: number
  subtotal: number
}

export interface Cart {
  id: string
  tenantId: string
  customerId: string | null
  email: string | null
  items: CartItem[]
  subtotal: number
  discountTotal: number
  shippingTotal: number
  taxTotal: number
  total: number
  currency: string
  shippingAddress: string | null
  billingAddress: string | null
  status: "active" | "completed" | "abandoned"
  createdAt: string
  updatedAt: string
}

/**
 * Retrieve cart by ID with items
 */
export async function retrieveCart(tenantId: string, cartId?: string): Promise<Cart | null> {
  const id = cartId || (await getCartId())

  if (!id) {
    return null
  }

  try {
    const [cartData] = await db.select().from(carts).where(and(eq(carts.id, id), eq(carts.tenantId, tenantId), eq(carts.status, "active"))).limit(1);

    if (!cartData) {
      return null
    }

    const itemsData = await db.select().from(cartItems).where(eq(cartItems.cartId, id)).orderBy(cartItems.createdAt);

    const items: CartItem[] = itemsData.map((item) => ({
      id: item.id,
      productId: item.productId,
      variantId: item.variantId,
      productName: item.productName,
      productSku: item.productSku,
      productImage: item.productImage,
      unitPrice: Number(item.unitPrice),
      compareAtPrice: item.compareAtPrice ? Number(item.compareAtPrice) : null,
      quantity: item.quantity,
      subtotal: Number(item.unitPrice) * item.quantity,
    }))

    return {
      id: cartData.id,
      tenantId: cartData.tenantId,
      customerId: cartData.customerId,
      email: cartData.email,
      items,
      subtotal: Number(cartData.subtotal || 0),
      discountTotal: Number(cartData.discountTotal || 0),
      shippingTotal: Number(cartData.shippingTotal || 0),
      taxTotal: Number(cartData.taxTotal || 0),
      total: Number(cartData.total || 0),
      currency: cartData.currency || "USD",
      shippingAddress: cartData.shippingAddress,
      billingAddress: cartData.billingAddress,
      status: cartData.status as "active" | "completed" | "abandoned",
      createdAt: cartData.createdAt.toISOString(),
      updatedAt: cartData.updatedAt.toISOString(),
    }
  } catch (error) {
    log.error("Error retrieving cart:", error)
    return null
  }
}

/**
 * Get or create cart for tenant
 */
export async function getOrCreateCart(tenantId: string, currency = "USD"): Promise<Cart> {
  // Try to get existing cart
  let cart = await retrieveCart(tenantId)

  if (cart) {
    return cart
  }

  // Create new cart
  const [newCart] = await db.insert(carts).values({
    tenantId,
    currency,
    status: "active",
  }).returning();

  if (!newCart) {
    throw new Error("Failed to create cart")
  }

  await setCartId(newCart.id)

  // Revalidate cache
  const cacheTag = await getCacheTag("carts", tenantId)
  revalidateTag(cacheTag, CART_CACHE_PROFILE)

  return {
    id: newCart.id,
    tenantId,
    customerId: null,
    email: null,
    items: [],
    subtotal: 0,
    discountTotal: 0,
    shippingTotal: 0,
    taxTotal: 0,
    total: 0,
    currency,
    shippingAddress: null,
    billingAddress: null,
    status: "active",
    createdAt: newCart.createdAt.toISOString(),
    updatedAt: newCart.updatedAt.toISOString(),
  }
}

/**
 * Add item to cart
 */
export async function addToCart(
  tenantId: string,
  productId: string,
  quantity: number,
  options?: {
    variantId?: string
    productName: string
    productSku?: string
    productImage?: string
    unitPrice: number
    compareAtPrice?: number
  }
): Promise<{ success: boolean; error?: string }> {
  if (!options) {
    return { success: false, error: "Product details required" }
  }

  try {
    const cart = await getOrCreateCart(tenantId)

    // Check if item already exists
    const [existing] = await db.select().from(cartItems)
      .where(
        and(
          eq(cartItems.cartId, cart.id),
          eq(cartItems.productId, productId),
          options.variantId ? eq(cartItems.variantId, options.variantId) : sql`${cartItems.variantId} IS NULL`
        )
      )
      .limit(1);

    if (existing) {
      // Atomic increment — no read-then-write race
      await db.update(cartItems)
        .set({
          quantity: sql`${cartItems.quantity} + ${quantity}`,
          updatedAt: new Date()
        })
        .where(and(eq(cartItems.id, existing.id), eq(cartItems.tenantId, tenantId)));
    } else {
      // Insert new item
      await db.insert(cartItems).values({
        tenantId,
        cartId: cart.id,
        productId,
        variantId: options.variantId || null,
        productName: options.productName,
        productSku: options.productSku || null,
        productImage: options.productImage || null,
        unitPrice: String(options.unitPrice),
        compareAtPrice: options.compareAtPrice ? String(options.compareAtPrice) : null,
        quantity,
      });
    }

    // Update cart totals
    await recalculateCartTotals(cart.id, tenantId)

    // Revalidate cache
    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error adding to cart:", error)
    return { success: false, error: "Failed to add item to cart" }
  }
}

/**
 * Recalculate cart totals
 */
async function recalculateCartTotals(cartId: string, tenantId: string): Promise<void> {
  // Get cart with discount info
  const [cart] = await db.select({
    discountTotal: carts.discountTotal,
    shippingTotal: carts.shippingTotal,
    taxTotal: carts.taxTotal
  }).from(carts).where(eq(carts.id, cartId)).limit(1);

  // Get all items
  const items = await db.select({
    unitPrice: cartItems.unitPrice,
    quantity: cartItems.quantity
  }).from(cartItems).where(eq(cartItems.cartId, cartId));

  const subtotal = (items || []).reduce(
    (sum, item) => sum + Number(item.unitPrice) * item.quantity,
    0
  )

  const discountTotal = Number(cart?.discountTotal || 0)
  const shippingTotal = Number(cart?.shippingTotal || 0)
  const taxTotal = Number(cart?.taxTotal || 0)
  const total = subtotal - discountTotal + shippingTotal + taxTotal

  // Update cart
  await db.update(carts)
    .set({
      subtotal: String(subtotal),
      total: String(Math.max(0, total)),
      updatedAt: new Date(),
    })
    .where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));
}

/**
 * Update cart item quantity
 */
export async function updateCartItem(
  tenantId: string,
  itemId: string,
  quantity: number
): Promise<{ success: boolean; error?: string }> {
  try {
    // Verify item belongs to a cart owned by this tenant
    const [item] = await db.select({ cartId: cartItems.cartId })
      .from(cartItems)
      .innerJoin(carts, eq(carts.id, cartItems.cartId))
      .where(and(eq(cartItems.id, itemId), eq(carts.tenantId, tenantId)))
      .limit(1);

    if (!item) {
      return { success: false, error: "Item not found" }
    }

    if (quantity <= 0) {
      await db.delete(cartItems).where(and(eq(cartItems.id, itemId), eq(cartItems.cartId, item.cartId), eq(cartItems.tenantId, tenantId)));
    } else {
      await db.update(cartItems)
        .set({ quantity, updatedAt: new Date() })
        .where(and(eq(cartItems.id, itemId), eq(cartItems.cartId, item.cartId), eq(cartItems.tenantId, tenantId)));
    }

    // Recalculate totals
    await recalculateCartTotals(item.cartId, tenantId)

    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error updating cart item:", error)
    return { success: false, error: "Failed to update cart item" }
  }
}

/**
 * Remove item from cart
 */
export async function removeFromCart(
  tenantId: string,
  itemId: string
): Promise<{ success: boolean; error?: string }> {
  return updateCartItem(tenantId, itemId, 0)
}

/**
 * Update cart (addresses, email, etc.)
 */
export async function updateCart(
  tenantId: string,
  data: {
    email?: string
    shippingAddress?: string
    billingAddress?: string
    shippingMethodId?: string
  }
): Promise<{ success: boolean; error?: string }> {
  const cartId = await getCartId()
  if (!cartId) {
    return { success: false, error: "No cart found" }
  }

  try {
    const updateData: Record<string, unknown> = {
      updatedAt: new Date(),
    }

    if (data.email !== undefined) {
      updateData.email = data.email
    }
    if (data.shippingAddress !== undefined) {
      updateData.shippingAddress = data.shippingAddress
    }
    if (data.billingAddress !== undefined) {
      updateData.billingAddress = data.billingAddress
    }

    await db.update(carts).set(updateData).where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));

    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error updating cart:", error)
    return { success: false, error: "Failed to update cart" }
  }
}

/**
 * Clear cart (remove all items)
 */
export async function clearCart(tenantId: string): Promise<{ success: boolean; error?: string }> {
  const cartId = await getCartId()
  if (!cartId) {
    return { success: true } // No cart to clear
  }

  try {
    await db.delete(cartItems).where(and(eq(cartItems.cartId, cartId), eq(cartItems.tenantId, tenantId)));

    // Reset totals
    await db.update(carts)
      .set({
        subtotal: "0",
        total: "0",
        updatedAt: new Date(),
      })
      .where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));

    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error clearing cart:", error)
    return { success: false, error: "Failed to clear cart" }
  }
}

/**
 * Complete cart (convert to order)
 * 
 * @deprecated Use checkout API route instead which handles Stripe integration
 */
export async function completeCart(
  tenantId: string,
  _storeSlug: string
): Promise<{ success: boolean; orderId?: string; orderNumber?: string; error?: string }> {
  const cartId = await getCartId()
  if (!cartId) {
    return { success: false, error: "No cart found" }
  }

  try {
    // Get cart with items
    const cart = await retrieveCart(tenantId, cartId)

    if (!cart || cart.items.length === 0) {
      return { success: false, error: "Cart is empty" }
    }

    // Generate order number
    const orderNumber = `ORD-${Date.now().toString(36).toUpperCase()}`

    // Create order using Drizzle
    const [order] = await db.insert(orders).values({
      tenantId,
      orderNumber,
      status: "pending",
      paymentStatus: "pending",
      subtotal: String(cart.subtotal),
      total: String(cart.total),
      customerEmail: cart.email,
    }).returning();

    // Create order items
    for (const item of cart.items) {
      await db.insert(orderItems).values({
        orderId: order.id,
        tenantId,
        productId: item.productId,
        variantId: item.variantId,
        productName: item.productName,
        productSku: item.productSku,
        productImage: item.productImage,
        quantity: item.quantity,
        unitPrice: String(item.unitPrice),
        totalPrice: String(item.subtotal),
      });
    }

    // Mark cart as completed
    await db.update(carts)
      .set({
        status: "completed",
        updatedAt: new Date(),
      })
      .where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));

    // Remove cart cookie
    await removeCartId()

    // --- Post-order side effects (fire-and-forget) ---

    // 1. Decrement stock for each item
    for (const item of cart.items) {
      if (item.productId) {
        db.update(products)
          .set({ quantity: sql`GREATEST(0, ${products.quantity} - ${item.quantity})` })
          .where(and(eq(products.id, item.productId), eq(products.tenantId, tenantId)))
          .catch(err => log.error("Stock decrement failed:", err))
      }
    }

    // 2. Send order confirmation email to customer
    if (cart.email) {
      const orderDetails = {
        orderId: order.id,
        orderNumber,
        customerEmail: cart.email,
        items: cart.items.map(i => ({ productName: i.productName, quantity: i.quantity, unitPrice: String(i.unitPrice), totalPrice: String(i.subtotal), productImage: i.productImage ?? undefined })),
        subtotal: String(cart.subtotal),
        total: String(cart.total),
        currency: "NPR",
        createdAt: new Date(),
      }
      const [tenant] = await db.select({ name: tenants.name, slug: tenants.slug }).from(tenants).where(eq(tenants.id, tenantId))
      const storeInfo = { name: tenant?.name ?? "Store", slug: tenant?.slug ?? "" }
      sendOrderConfirmationEmail(cart.email, orderDetails, storeInfo)
        .catch(err => log.error("Order confirmation email failed:", err))

      // 3. Notify merchant
      const [owner] = await db.select({ email: users.email }).from(users).where(and(eq(users.tenantId, tenantId), eq(users.role, "owner")))
      if (owner?.email) {
        sendOrderNotificationEmail(owner.email, orderDetails, storeInfo)
          .catch(err => log.error("Merchant notification email failed:", err))
      }
    }

    // Revalidate caches
    const cartCacheTag = await getCacheTag("carts", tenantId)
    const orderCacheTag = await getCacheTag("orders", tenantId)
    revalidateTag(cartCacheTag, CART_CACHE_PROFILE)
    revalidateTag(orderCacheTag, CART_CACHE_PROFILE)

    return { success: true, orderId: order.id, orderNumber }
  } catch (error) {
    log.error("Error completing cart:", error)
    return { success: false, error: error instanceof Error ? error.message : "Failed to complete order" }
  }
}

/**
 * Apply voucher to cart data
 */
export async function applyVoucherToCartData(
  tenantId: string,
  discountId: string,
  voucherCodeId: string,
  voucherCode: string,
  discountAmount: number
): Promise<{ success: boolean; error?: string }> {
  const cartId = await getCartId()
  if (!cartId) {
    return { success: false, error: "No cart found" }
  }

  try {
    await db.update(carts)
      .set({
        discountId,
        voucherCodeId,
        voucherCode,
        discountTotal: String(discountAmount),
        updatedAt: new Date(),
      })
      .where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));

    // Recalculate totals
    await recalculateCartTotals(cartId, tenantId)

    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error applying voucher to cart:", error)
    return { success: false, error: "Failed to apply voucher" }
  }
}

/**
 * Remove voucher from cart
 */
export async function removeVoucherFromCart(
  tenantId: string
): Promise<{ success: boolean; error?: string }> {
  const cartId = await getCartId()
  if (!cartId) {
    return { success: false, error: "No cart found" }
  }

  try {
    await db.update(carts)
      .set({
        discountId: null,
        voucherCodeId: null,
        voucherCode: null,
        discountTotal: "0",
        updatedAt: new Date(),
      })
      .where(and(eq(carts.id, cartId), eq(carts.tenantId, tenantId)));

    // Recalculate totals
    await recalculateCartTotals(cartId, tenantId)

    const cacheTag = await getCacheTag("carts", tenantId)
    revalidateTag(cacheTag, CART_CACHE_PROFILE)

    return { success: true }
  } catch (error) {
    log.error("Error removing voucher from cart:", error)
    return { success: false, error: "Failed to remove voucher" }
  }
}

/**
 * Server-side category data layer for storefront — Drizzle + withTenant
 */
import "server-only"

import { withTenant } from "@/infrastructure/db"
import { categories, products } from "@/db/schema/products"
import { eq, and, isNull, asc, count, sql } from "drizzle-orm"
import { revalidateTag, updateTag } from "next/cache"
import { tagTenantCache, getTenantCacheTag, CACHE_PROFILES } from "@/features/store/data/cache"
import { createLogger } from "@/lib/logger"
const log = createLogger("features:store-categories")

export interface StoreCategory {
  id: string
  name: string
  slug: string
  description: string | null
  imageUrl: string | null
  parentId: string | null
  productCount: number
}

/**
 * List all categories for a tenant (cached, RLS enforced)
 */
export async function listCategories(tenantId: string): Promise<StoreCategory[]> {
  "use cache"
  CACHE_PROFILES.categories()
  tagTenantCache("categories", tenantId)

  try {
    return await withTenant(tenantId, async (tx) => {
      const rows = await tx
        .select({
          id: categories.id, name: categories.name, slug: categories.slug,
          description: categories.description, imageUrl: categories.imageUrl,
          parentId: categories.parentId,
          productCount: sql<number>`(SELECT count(*) FROM products WHERE products.category_id = ${categories.id} AND products.status = 'active')`.as("product_count"),
        })
