import { getCollectionProducts, getLatestProducts, getProduct } from "./product-data"
import type { StorefrontProduct } from "./product-data"

/**
 * Walk the serialized Craft.js JSON and inject live product data
 * into ProductGridBlock and FeaturedProductBlock nodes.
 *
 * This runs server-side before passing JSON to the client renderer.
 */
export async function hydrateCraftJson(
  craftJson: string,
  tenantId: string
): Promise<string> {
  let tree: Record<string, any>
  try {
    tree = JSON.parse(craftJson)
  } catch {
    return craftJson
  }

  // Strip padding/margin from root Container so storefront is edge-to-edge
  const rootNode = tree["ROOT"]
  if (rootNode) {
    const rootChildId = rootNode.nodes?.[0] ?? Object.values(rootNode.linkedNodes ?? {})[0]
    const rootChild = rootChildId ? tree[rootChildId] : null
    if (rootChild?.type?.resolvedName === "Container" && rootChild.props) {
      rootChild.props.padding = 0
      rootChild.props.background = "transparent"
    }
  }

  const promises: Promise<void>[] = []

  for (const [nodeId, node] of Object.entries(tree)) {
    const name = node?.type?.resolvedName
    const props = node?.props

    if (name === "ProductGridBlock" && props) {
      const limit = (props.columns ?? 3) * (props.rows ?? 2)
      promises.push(
        (props.collectionId
          ? getCollectionProducts(tenantId, props.collectionId, limit)
          : getLatestProducts(tenantId, limit)
        ).then((products) => {
          tree[nodeId].props._products = products
        })
      )
    }

    if (name === "FeaturedProductBlock" && props?.productId) {
      promises.push(
        getProduct(tenantId, props.productId).then((product) => {
          if (product) {
            tree[nodeId].props.productName = product.name
            tree[nodeId].props.price = `Rs. ${(product.price / 100).toLocaleString()}`
            tree[nodeId].props.imageUrl = product.images?.[0]?.url ?? props.imageUrl
          }
        })
      )
    }
  }

  if (promises.length === 0) return craftJson

  await Promise.all(promises)
  return JSON.stringify(tree)
}

import { createClient } from "@/infrastructure/supabase/server"

export interface StorefrontProduct {
  id: string
  name: string
  slug: string
  price: number
  images: { url: string }[] | null
  status: string
}

/** Fetch products for a collection (storefront rendering) */
export async function getCollectionProducts(
  tenantId: string,
  collectionId: string,
  limit: number = 12
): Promise<StorefrontProduct[]> {
  const supabase = await createClient()

  const { data } = await supabase
    .from("collection_products")
    .select("product:products(id, name, slug, price, images, status)")
    .eq("collection_id", collectionId)
    .eq("products.tenant_id", tenantId)
    .eq("products.status", "active")
    .limit(limit)

  if (!data) return []
  return data
    .map((row: any) => row.product)
    .filter(Boolean) as StorefrontProduct[]
}

/** Fetch a single product by ID (storefront rendering) */
export async function getProduct(
  tenantId: string,
  productId: string
): Promise<StorefrontProduct | null> {
  const supabase = await createClient()

  const { data } = await supabase
    .from("products")
    .select("id, name, slug, price, images, status")
    .eq("id", productId)
    .eq("tenant_id", tenantId)
    .eq("status", "active")
    .single()

  return data as StorefrontProduct | null
}

/** Fetch latest products for a tenant (fallback when no collection selected) */
export async function getLatestProducts(
  tenantId: string,
  limit: number = 12
): Promise<StorefrontProduct[]> {
  const supabase = await createClient()

  const { data } = await supabase
    .from("products")
    .select("id, name, slug, price, images, status")
    .eq("tenant_id", tenantId)
    .eq("status", "active")
    .order("created_at", { ascending: false })
    .limit(limit)

  return (data ?? []) as StorefrontProduct[]
}

