/**
 * Event Bus - Core communication layer for modular services
 * Enables services to communicate asynchronously while remaining decoupled
 */

import { createLogger } from "@/lib/logger";

const log = createLogger("infra:event-bus");

// Event type definitions
export type EventType =
    // Order events
    | 'order.created'
    | 'order.confirmed'
    | 'order.processing'
    | 'order.shipped'
    | 'order.delivered'
    | 'order.completed'
    | 'order.cancelled'
    | 'order.returned'
    | 'order.refunded'
    // Payment events
    | 'payment.initiated'
    | 'payment.completed'
    | 'payment.failed'
    | 'refund.initiated'
    | 'refund.completed'
    // Product events
    | 'product.created'
    | 'product.updated'
    | 'product.deleted'
    | 'product.archived'
    | 'stock.updated'
    | 'stock.low'
    | 'stock.out'
    | 'stock.reserved'
    | 'stock.released'
    // Variant events
    | 'variant.created'
    | 'variant.updated'
    | 'variant.deleted'
    // Collection events
    | 'collection.created'
    | 'collection.updated'
    | 'collection.deleted'
    // Customer events
    | 'customer.created'
    | 'customer.updated'
    | 'customer.deleted'
    // User events
    | 'user.created'
    | 'user.verified'
    | 'user.login';

// Event payload types
export interface EventPayload {
    tenantId: string;
    timestamp: Date;
    data: Record<string, unknown>;
}

// Event handler type
export type EventHandler = (payload: EventPayload) => Promise<void>;

/**
 * EventBus class - singleton pattern for in-process event handling
 */
class EventBus {
    private handlers: Map<EventType, EventHandler[]> = new Map();
    private eventLog: Array<{ event: EventType; payload: EventPayload; timestamp: Date }> = [];

    /**
     * Subscribe to an event
     */
    on(event: EventType, handler: EventHandler): () => void {
        if (!this.handlers.has(event)) {
            this.handlers.set(event, []);
        }
        this.handlers.get(event)!.push(handler);

        // Return unsubscribe function
        return () => {
            const handlers = this.handlers.get(event);
            if (handlers) {
                const index = handlers.indexOf(handler);
                if (index > -1) handlers.splice(index, 1);
            }
        };
    }

    /**
     * Emit an event to all subscribers
     */
    async emit(event: EventType, payload: EventPayload): Promise<void> {
        // Log the event
        this.eventLog.push({ event, payload, timestamp: new Date() });
        if (this.eventLog.length > 1000) this.eventLog = this.eventLog.slice(-500);

        // Get handlers
        const handlers = this.handlers.get(event) || [];

        // Execute all handlers (fire and forget for now)
        const results = await Promise.allSettled(
            handlers.map(handler => handler(payload))
        );

        // Log any failures
        results.forEach((result, index) => {
            if (result.status === 'rejected') {
                log.error(`Event handler failed for ${event}:`, result.reason);
            }
        });
    }

    /**
     * Get recent events (for debugging)
     */
    getRecentEvents(limit = 10) {
        return this.eventLog.slice(-limit);
    }

    /**
     * Clear event log
     */
    clearLog() {
        this.eventLog = [];
    }
}

// Export singleton instance
export const eventBus = new EventBus();

/**
 * Helper to create typed event payloads
 */
export function createEventPayload(
    tenantId: string,
    data: Record<string, unknown>
): EventPayload {
    return {
        tenantId,
        timestamp: new Date(),
        data,
    };
}

import { createLogger } from "@/lib/logger";
import { db } from "@/infrastructure/db";
import { notificationPreferences } from "@/db/schema/notification-preferences";
import { eq, and } from "drizzle-orm";

const log = createLogger("services:notification-delivery");

type Channel = "email" | "whatsapp" | "push";
type DeliveryResult = { success: boolean; channel: Channel; error?: string; notificationId?: string };

interface DeliverInput {
  tenantId: string;
  userId?: string;
  recipientEmail?: string;
  recipientPhone?: string;
  type: "order_confirmation" | "order_shipped" | "order_delivered" | "low_stock" | "team_invite" | "payment_received";
  subject: string;
  body: string;
  htmlBody?: string;
  channels?: Channel[];
  metadata?: Record<string, unknown>;
}

export async function deliverNotification(input: DeliverInput): Promise<{
  delivered: boolean;
  results: DeliveryResult[];
  skippedChannels: string[];
}> {
  const results: DeliveryResult[] = [];
  const skippedChannels: string[] = [];
  const channels = input.channels || ["email"];

  for (const channel of channels) {
    try {
      switch (channel) {
        case "email": {
          if (!input.recipientEmail) { skippedChannels.push("email"); break; }
          const { Resend } = await import("resend");
          const resend = new Resend(process.env.RESEND_API_KEY);
          const { error } = await resend.emails.send({
            from: process.env.EMAIL_FROM || "Indigo <noreply@indigo.store>",
            to: input.recipientEmail,
            subject: input.subject,
            html: input.htmlBody || `<p>${input.body}</p>`,
          });
          results.push({ success: !error, channel: "email", error: error?.message });
          break;
        }

        case "whatsapp": {
          if (!input.recipientPhone) { skippedChannels.push("whatsapp"); break; }
          try {
            const { sendWhatsAppMessage } = await import("@/infrastructure/services/whatsapp");
            await sendWhatsAppMessage({ to: input.recipientPhone, message: input.body, config: {} as any });
            results.push({ success: true, channel: "whatsapp" });
          } catch (err) {
            results.push({ success: false, channel: "whatsapp", error: err instanceof Error ? err.message : "WhatsApp send failed" });
          }
          break;
        }

        case "push":
          // Push notifications not yet implemented
          skippedChannels.push("push");
          break;

        default:
          skippedChannels.push(channel);
      }
    } catch (err) {
      log.error(`Failed to deliver via ${channel}:`, err);
      results.push({ success: false, channel, error: err instanceof Error ? err.message : "Unknown error" });
    }
  }

  const delivered = results.some(r => r.success);
  log.info(`Notification delivered=${delivered}, channels=${channels.join(",")}, type=${input.type}`);
  return { delivered, results, skippedChannels };
}

/**
 * Local Storage Provider
 * 
 * Implements StorageProvider interface using local filesystem
 * Useful for development, testing, and fallback scenarios
 */

import { promises as fs } from 'fs';
import path from 'path';
import type { StorageProvider, UploadOptions, UploadResult, StorageObject } from './types';

export class LocalStorageProvider implements StorageProvider {
  private baseDir: string;
  private baseUrl: string;

  constructor(options?: { baseDir?: string; baseUrl?: string }) {
    this.baseDir = options?.baseDir || path.join(process.cwd(), 'public', 'uploads');
    this.baseUrl = options?.baseUrl || '/uploads';
  }

  /**
   * Upload file to local filesystem
   */
  async upload(file: Buffer | Uint8Array, options: UploadOptions): Promise<UploadResult> {
    try {
      // Generate key
      const key = this.generateKey(options.tenantId, options.filename, options.folder);
      const filePath = path.join(this.baseDir, key);

      // Ensure directory exists
      await fs.mkdir(path.dirname(filePath), { recursive: true });

      // Write file
      await fs.writeFile(filePath, file);

      // Write metadata
      const metadataPath = `${filePath}.meta.json`;
      await fs.writeFile(
        metadataPath,
        JSON.stringify({
          tenantId: options.tenantId,
          filename: options.filename,
          contentType: options.contentType,
          folder: options.folder,
          metadata: options.metadata,
          uploadedAt: new Date().toISOString(),
        })
      );

      return {
        success: true,
        key,
        url: this.getUrl(key),
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Upload failed',
      };
    }
  }

  /**
   * Delete file from local filesystem
   */
  async delete(key: string): Promise<void> {
    const filePath = path.join(this.baseDir, key);
    const metadataPath = `${filePath}.meta.json`;

    try {
      // Delete file
      await fs.unlink(filePath);

      // Delete metadata (ignore if doesn't exist)
      try {
        await fs.unlink(metadataPath);
      } catch {
        // Metadata file might not exist
      }
    } catch (error) {
      throw new Error(error instanceof Error ? error.message : 'Delete failed');
    }
  }

  /**
   * Get public URL for a file
   */
  getUrl(key: string): string {
    return `${this.baseUrl}/${key}`;
  }

  /**
   * Get presigned URL (for local storage, just return regular URL)
   */
  async getPresignedUrl(key: string, expiresIn?: number): Promise<string> {
    // For local storage, we don't have presigned URLs
    // Just return the regular URL
    return this.getUrl(key);
  }

  /**
   * Check if file exists
   */
  async exists(key: string): Promise<boolean> {
    const filePath = path.join(this.baseDir, key);

    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * List files with prefix
   */
  async list(prefix: string, maxKeys: number = 100): Promise<StorageObject[]> {
    const dirPath = path.join(this.baseDir, prefix);
    const files: StorageObject[] = [];

    try {
      const entries = await fs.readdir(dirPath, { withFileTypes: true });

      for (const entry of entries) {
        if (files.length >= maxKeys) break;

        // Skip metadata files
        if (entry.name.endsWith('.meta.json')) continue;

        if (entry.isFile()) {
          const filePath = path.join(dirPath, entry.name);
          const stats = await fs.stat(filePath);
          const key = path.join(prefix, entry.name);

          // Try to read metadata
          let contentType: string | undefined;
          try {
            const metadataPath = `${filePath}.meta.json`;
            const metadataContent = await fs.readFile(metadataPath, 'utf-8');
            const metadata = JSON.parse(metadataContent);
            contentType = metadata.contentType;
          } catch {
            // Metadata not available
          }

          files.push({
            key,
            size: stats.size,
            lastModified: stats.mtime,
            contentType,
          });
        }
      }

      return files;
    } catch (error) {
      // Directory doesn't exist or other error
      return [];
    }
  }

  /**
   * Generate storage key
   */
  private generateKey(tenantId: string, filename: string, folder?: string): string {
    const sanitizedFilename = filename.replace(/[^a-zA-Z0-9.-]/g, '_');
    const timestamp = Date.now();
    const randomSuffix = Math.random().toString(36).substring(2, 8);
    const uniqueFilename = `${timestamp}-${randomSuffix}-${sanitizedFilename}`;

    return folder
      ? `tenants/${tenantId}/${folder}/${uniqueFilename}`
      : `tenants/${tenantId}/${uniqueFilename}`;
  }
}

