import React from "react";
import { type ElementDef, register as registerElement } from "@/features/editor/core/registry/types";
import { type El } from "@/features/editor/core/types";
import { Plug } from "lucide-react";
import { safeUrl } from "@/shared/utils/safe-url";

/**
 * Definition of a custom property that will be exposed in the editor UI.
 */
export type PluginPropType = "string" | "number" | "boolean" | "color" | "select";

export interface PluginPropDef {
  type: PluginPropType;
  label: string;
  defaultValue: any;
  options?: string[]; // For 'select' type
}

export interface PluginConfig {
  /** A unique identifier for the plugin (e.g., 'acme_reviews') */
  id: string;
  /** The display name of the plugin in the elements panel */
  name: string;
  /** The icon to display. Defaults to a plug icon. */
  icon?: any;
  /** The default CSS properties for the plugin container */
  defaultStyles?: Record<string, string>;
  /** The properties that the user can configure in the right sidebar */
  props?: Record<string, PluginPropDef>;
  /** The React component to render */
  component: React.FC<{ props: Record<string, any>; styles: React.CSSProperties }>;
  /** A function that returns raw HTML string for the published site */
  exportHTML: (props: Record<string, any>, styles: Record<string, string>) => string;
}

/**
 * Factory function to create a new Plugin definition compatible with Indigo.
 */
export function createPlugin(config: PluginConfig): ElementDef {
  const defaultContent: Record<string, any> = {};

  if (config.props) {
    for (const [key, def] of Object.entries(config.props)) {
      defaultContent[key] = def.defaultValue;
    }
  }

  return {
    type: config.id,
    name: config.name,
    icon: config.icon || Plug,
    color: "text-indigo-500",
    group: "Plugins",
    isContainer: false,
    pluginProps: config.props,
    factory: () => ({
      id: crypto.randomUUID(),
      type: config.id,
      name: config.name,
      styles: config.defaultStyles || { width: "100%", display: "block" },
      content: { ...defaultContent },
    }),
    render: ({ element }) => {
      const content = element.content as Record<string, any>;
      return (
        <config.component 
          props={content} 
          styles={element.styles as React.CSSProperties} 
        />
      );
    },
    /**
     * Default live-storefront renderer (server-safe, no hooks).
     * Renders a simple form: the first safe http(s) prop becomes the action,
     * string props become inputs, and a submit button labels itself from a
     * `buttonText` prop when present. Plugins that need exact markup should
     * provide their own `storefrontRender` (see mailchimp.tsx).
     */
    storefrontRender: ({ element }) => {
      const content = element.content as Record<string, any>;
      const styles = element.styles as React.CSSProperties;
      const entries = Object.entries(content).filter(([, v]) => typeof v === "string" && v !== "");
      const action = entries.find(([, v]) => safeUrl(v))?.[1] ?? undefined;
      return (
        <form action={action} method="POST" style={styles}>
          {entries
            .filter(([key, value]) => key !== "buttonText" && safeUrl(value) !== value)
            .map(([key, value]) => (
              <input key={key} name={key} defaultValue={value} placeholder={value} style={{ display: "block", width: "100%", marginBottom: 8, padding: "8px 12px", borderRadius: 4, border: "1px solid #d4d4d8", boxSizing: "border-box" }} />
            ))}
          <button type="submit" style={{ backgroundColor: "#18181b", color: "#fff", padding: "8px 16px", borderRadius: 4, fontWeight: 500, border: "none", cursor: "pointer" }}>
            {content.buttonText || "Submit"}
          </button>
        </form>
      );
    },
    exportHTML: (el: El) => {
      const content = el.content as Record<string, any>;
      return config.exportHTML(content, el.styles as Record<string, string>);
    }
  };
}

/**
 * Register a created plugin with the editor registry.
 */
export function registerPlugin(plugin: ElementDef) {
  registerElement(plugin);
}

import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";

const PUBLIC_ROUTES = ["/", "/login", "/signup", "/forgot-password", "/reset-password", "/auth/callback", "/invite", "/suspended", "/coming-soon", "/api/health", "/api/revalidate", "/api/inngest"];
const STORE_PREFIX = "/store/";
const API_STORE_PREFIX = "/api/store/";

/** Routes that require owner or admin role */
const ADMIN_ROUTES = ["/dashboard/settings"];

/** Routes that require platform_admin role */
const PLATFORM_ADMIN_ROUTES = ["/admin"];

const DEV_SCRIPT_POLICY = process.env.NODE_ENV === "development" ? " 'unsafe-eval'" : "";

const CSP_HEADER = [
  "default-src 'self'",
  `script-src 'self' 'unsafe-inline'${DEV_SCRIPT_POLICY} https://js.stripe.com https://www.googletagmanager.com https://va.vercel-scripts.com`,
  "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
  "font-src 'self' https://fonts.gstatic.com",
  "img-src 'self' data: blob: https:",
  "worker-src 'self' blob:",
  "connect-src 'self' https://*.supabase.co https://esewa.com.np https://khalti.com https://api.pathao.com https://va.vercel-scripts.com https://*.vercel-insights.com wss://*.supabase.co",
  "frame-src 'self' https://js.stripe.com https://esewa.com.np https://khalti.com",
].join("; ");

export async function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const hostname = request.headers.get("host")?.split(":")[0] || "";
  const platformDomain = process.env.NEXT_PUBLIC_PLATFORM_DOMAIN || "localhost";

  // Custom domain routing — resolve to store page
  if (hostname !== platformDomain && hostname !== "localhost" && !hostname.endsWith(`.${platformDomain}`) && !hostname.endsWith(".vercel.app")) {
    const storeUrl = request.nextUrl.clone();
    // Rewrite custom domain requests to /store/_custom?domain=xxx&path=yyy
    storeUrl.pathname = `/store/_custom`;
    storeUrl.searchParams.set("domain", hostname);
    storeUrl.searchParams.set("path", pathname === "/" ? "" : pathname);
    return NextResponse.rewrite(storeUrl);
  }

  // Tenant subdomain routing — e.g., mystore.indigo.com.np → /store/mystore
  if (hostname.endsWith(`.${platformDomain}`) && hostname !== platformDomain) {
    const subdomain = hostname.replace(`.${platformDomain}`, "");
    // Skip platform subdomains (www, api, admin, etc.)
    const reserved = ["www", "api", "admin", "app", "dashboard", "mail", "smtp", "ftp"];
    if (!reserved.includes(subdomain)) {
      const storeUrl = request.nextUrl.clone();
      storeUrl.pathname = `/store/${subdomain}${pathname === "/" ? "" : pathname}`;
      return NextResponse.rewrite(storeUrl);
    }
  }

  // CI-1: editor-v3 routes REMOVED from public skip list — require auth
  const isPublic =
    PUBLIC_ROUTES.some((r) => pathname === r) ||
    pathname.startsWith("/blog") ||
    pathname.startsWith(STORE_PREFIX) ||
    pathname.startsWith(API_STORE_PREFIX) ||
    pathname.startsWith("/p/") ||
    pathname.startsWith("/api/public/") ||
    pathname.startsWith("/api/contact") ||
    pathname.startsWith("/api/newsletter") ||
    pathname.startsWith("/api/checkout") ||
    pathname.startsWith("/_next/") ||
    pathname.startsWith("/_vercel/") ||
    pathname === "/manifest.webmanifest" ||
    pathname === "/sw.js" ||
    pathname === "/robots.txt" ||
    pathname === "/sitemap.xml";

  // Create Supabase client that can refresh the session
  let response = NextResponse.next({ request });

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll: (cookies) => {
          cookies.forEach(({ name, value, options }) => {
            request.cookies.set(name, value);
            response.cookies.set(name, value, options);
          });
        },
      },
    }
  );

  // Always call getUser to refresh session cookies
  const { data: { user } } = await supabase.auth.getUser();

  // Redirect unauthenticated users away from dashboard/editor
  if (!isPublic && !user) {
    const loginUrl = new URL("/login", request.url);
    loginUrl.searchParams.set("next", pathname);
    return NextResponse.redirect(loginUrl);
  }

  // CI-5: RBAC enforcement — gate routes by role
  if (user && !isPublic) {
    // Read role from DB (not user_metadata which is client-writable)
    const { data: dbUser } = await supabase
      .from("users")
      .select("role, tenant_id, platform_role")
      .eq("id", user.id)
      .single();
    const role = dbUser?.role ?? "owner";
    const hasPlatformAccess = role === "platform_admin" || !!dbUser?.platform_role;

    // Platform-only users (no tenant) can't access merchant dashboard
    if (!dbUser?.tenant_id && pathname.startsWith("/dashboard") && hasPlatformAccess) {
      return NextResponse.redirect(new URL("/admin", request.url));
    }

    // Check if merchant is suspended (block dashboard access — even if they have platform access)
    if (dbUser?.tenant_id && pathname.startsWith("/dashboard")) {
      const { data: tenant } = await supabase
        .from("tenants")
        .select("settings")
        .eq("id", dbUser.tenant_id)
        .single();
      if ((tenant?.settings as Record<string, unknown>)?.suspended) {
        const suspendedUrl = new URL("/suspended", request.url);
        return NextResponse.redirect(suspendedUrl);
      }
    }

    // Admin-only routes require owner or admin role
    if (ADMIN_ROUTES.some((r) => pathname.startsWith(r))) {
      if (role !== "owner" && role !== "admin") {
        return NextResponse.redirect(new URL("/dashboard", request.url));
      }
    }

    // Platform admin routes require platform_admin role OR platform_role
    if (PLATFORM_ADMIN_ROUTES.some((r) => pathname.startsWith(r))) {
      if (!hasPlatformAccess) {
        return NextResponse.redirect(new URL("/dashboard", request.url));
      }
    }

    // Redirect authenticated users away from auth pages (role-based routing)
    if (pathname === "/login" || pathname === "/signup") {
      // If user has platform access AND a tenant, default to admin (they can navigate to dashboard)
      // If user has platform access but no tenant, go to admin
      // If user has no platform access, go to dashboard
      const destination = hasPlatformAccess ? "/admin" : "/dashboard";
      return NextResponse.redirect(new URL(destination, request.url));
    }
  }

  // Security headers
  response.headers.set("X-Content-Type-Options", "nosniff");
  response.headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  response.headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");

  // Stricter CSP for published editor pages — no JS execution allowed
  if (pathname.startsWith("/p/")) {
    response.headers.set("Content-Security-Policy", "default-src 'self'; script-src 'none'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob: https:; frame-ancestors 'self'");
    response.headers.set("X-Frame-Options", "SAMEORIGIN");
  } else {
    response.headers.set("Content-Security-Policy", CSP_HEADER);
  }

  return response;
}

